window.CY = {"meta":{"city":"南投縣","slug":"nantou-county","updated":"2026-11-01","designer":"Allan Lo","designerSite":"https://www.123hi.org","designed":"2026年11月","ai":"Claude Opus 5.5"},"config":{"slug":"nantou-county","name":"南投縣","short":"南投","center":[23.86,120.86],"zoom":10,"minZoom":8,"detailZoom":16,"timeZoom":10,"fitSites":true,"categories":["國定古蹟","縣定古蹟","歷史建築","紀念建築","考古遺址","文化景觀"],"towns":["草屯鎮","南投市","中寮鄉","名間鄉","集集鎮","竹山鎮","鹿谷鄉","水里鄉","國姓鄉","埔里鎮","魚池鄉","仁愛鄉","信義鄉"],"ubikeAreas":[],"wiki":{"title":"維基百科「南投縣文化資產」","url":"https://zh.wikipedia.org/zh-tw/%E5%8D%97%E6%8A%95%E7%B8%A3%E6%96%87%E5%8C%96%E8%B3%87%E7%94%A2"},"introTitle":"歡迎來到南投","quizTitle":"南投文資通","eraLabels":{"dutch":"原住民族社會（荷西時期）","zheng":"明鄭時期（林圮埔開墾）"},"board":{"name":"山城擲骰大冒險","start":"出發：南投市區","train":"集集線小火車","food":"意麵補給站"},"planner":{"speeds":{"car":35,"scooter":28,"bike":13,"walk":4.5,"ubike":13},"hints":{"car":"南投縣是臺灣唯一不靠海的縣，景點分散在南投市、草屯、竹山、集集、日月潭、埔里與仁愛、信義山區，開車最方便。山區道路彎多，台14甲線、台21線、中橫公路等颱風或豪雨後常有坍方管制，出發前請先查詢公路局最新路況。每站已預留約 8 分鐘停車時間。","scooter":"南投市、草屯、竹山、集集市區騎機車很方便；上山到日月潭、埔里、霧社坡長彎多，請注意大型車、午後雷陣雨與落石，國道不能騎機車。","bike":"集集綠色隧道、日月潭環湖自行車道與中興新村一帶適合騎單車；日月潭有私人業者的自行車租借，不是 YouBike。單段超過 12 公里或要爬坡上山時，會建議改開車或搭車。","walk":"南投市藍田書院、武德殿一帶，中興新村，草屯老街，竹山、集集市區的景點彼此不遠，可以步行串遊；單段超過 3 公里會建議改搭車。","ubike":"南投縣目前沒有 YouBike 站點，建議開車、騎機車，或搭臺鐵集集線、南投客運、豐榮客運與日月潭、埔里方向的國道客運。"},"defaultMode":"car","lunchNote":"南投在地小吃：南投意麵、草屯肉圓、竹山番薯與竹筍料理、集集香蕉與山蕉冰、埔里米粉與紹興料理、日月潭總統魚與阿薩姆紅茶","eveningNote":"晚上可以逛南投市的南投夜市、草屯的夜市（營業日以現場公告為準），或住日月潭、埔里，隔天一早看湖景","walkMaxKm":3,"bikeMaxKm":12,"ubikeStationMaxKm":1.2,"farKm":60},"eras":{"dutch":{"layers":[],"paper":true,"end":1662,"note":"荷西時期南投仍是原住民族的家園，沒有實測地圖，底圖改成古紙風格，標示的是推定位置。"},"zheng":{"layers":[],"paper":true,"end":1683,"note":"明鄭時期沒有南投的實測地圖，底圖改成古紙風格，標示的是推定位置。"},"qing":{"layers":["1904"],"end":1895,"note":"1904 年的臺灣堡圖是日治初期實測，記錄了清末南投、草鞋墩、林圮埔、集集、埔里社等街庄。霧社以東的深山不在這張圖的範圍內。"},"japan":{"layers":["1921","1916"],"end":1945,"note":"1921 年地形圖涵蓋南投、草屯、竹山、集集與日月潭；埔里、霧社與信義山區要切換 1916 年蕃地地形圖。1944 年的地形圖沒有涵蓋南投。"},"early-roc":{"layers":["1950"],"end":1960,"note":"1950 年的地形圖：戰後初期的南投縣，只涵蓋西半部，埔里與東邊山區沒有圖。"},"roc60":{"layers":["1966","corona"],"end":1981,"note":"1957–1969 年的二萬五千分之一地形圖，也可以切換 1966 年的 Corona 衛星影像，看中興新村成為省府所在地後的南投。"},"now":{"layers":["photo","1989"],"end":2026,"opacity":0,"note":"今天的南投縣。可疊上正射影像或 1989 年的地形圖做對照。"}}},"categories":["國定古蹟","縣定古蹟","歷史建築","紀念建築","考古遺址","文化景觀"],"sites":[{"id":"zhushan-batongguangudao","name":"八通關古道","short":"八通關古道","category":"國定古蹟","level":"國定古蹟","town":"竹山鎮","types":["碑碣"],"lat":23.726265,"lng":120.796338,"address":"南投縣竹山鎮至花蓮縣玉里鎮（清光緒元年所開闢之古道）","announced":"1987-04-17","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19870417000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/37604/photo/96b0b3c4-2efd-4817-afeb-67c7479a3efa.jpg","year":1875,"yearText":"1875年（光緒元年）","era":"qing","themes":["清代開山","碑碣古道","原住民族文化"],"yearUnknown":false,"summary":"清代開山撫番的中路，西段從竹山出發","intro":"八通關古道是清代開山撫番的「中路」，1987年指定為一級古蹟，今為南投縣唯一國定古蹟。1874年牡丹社事件後，清廷為鞏固後山、開發東部，1875年由總兵吳光亮率兵開闢，西起林圯埔（今竹山），經大坪頂（今鹿谷）、鳳凰山、東埔、八通關，越中央山脈至璞石閣（今花蓮玉里），全長約152公里。西段沿途留有「萬年亨衢」「開闢鴻荒」等石碣。對布農族、鄒族等族人而言，這是軍隊與墾民進入傳統領域、衝突與土地流失的開始。古道不久便荒廢；今天從東埔上山走的多是日治1919至1921年另闢的八通關越嶺道，兩者細部很少重疊。東端見花蓮縣篇。","highlights":["鹿谷鳳凰谷鳥園內吳光亮親題的「萬年亨衢」石碣","集集林尾濁水溪畔的「開闢鴻荒」石碣","鹿谷新寮福安宮旁的撤禁告示碑與德遍山陬碑"],"funFact":"「山通大海」碣1959年八七水災被沖失，1988年重刻，又在2001年桃芝風災被土石流吞沒。","photoSpot":"在萬年亨衢石碣前拍行書與巨石","visitMin":60,"openNote":"古道是一條長路線，地圖點標在鹿谷鄉鳳凰谷鳥園內的「萬年亨衢」石碣，入園時間與票價以鳥園公告為準；集集鎮林尾里濁水溪畔還可看到「開闢鴻荒」石碣。清代古道大多已湮沒，山區段多在信義鄉、玉山國家公園內，進入須依規定申請入園證，山地管制區另須申請入山證；出發前請查詢玉山國家公園管理處的步道開放與路況公告，以及公路局最新路況。","dialogue":[{"who":"R","text":"Allan，八通關古道不是在花蓮嗎？怎麼南投也有？"},{"who":"A","text":"它是一條長路！清代從竹山翻過中央山脈到花蓮玉里，東端請看花蓮縣篇，今天我們走西段。"},{"who":"R","text":"為什麼清朝要在高山上開這麼長的路？"},{"who":"A","text":"1874年牡丹社事件後，清廷想鞏固後山、開發東部，1875年派總兵吳光亮從林圯埔往東開路。"},{"who":"R","text":"可是那些高山裡本來就有人住吧？"},{"who":"A","text":"對，那是布農族、鄒族等族人的傳統領域。對族人來說，軍隊和墾民進來，帶來衝突和失去土地。"},{"who":"R","text":"同一條路，兩邊的感受差好多。那現在還能走嗎？"},{"who":"A","text":"清代古道大多已湮沒，今天從東埔上山多走日治時期另闢的越嶺道，還得申請入園和入山。"},{"who":"R","text":"那我們先去鹿谷鳳凰谷鳥園，找吳光亮題的萬年亨衢，看看旁邊是不是還有兩道空框！"}],"clues":["我身上的題字散落在鹿谷與集集的巨石上","我是清代開山撫番北、中、南三路裡的中路","我從今天的竹山出發，翻過中央山脈到花蓮玉里"],"quiz":[{"q":"這條清代開山道路由哪位將領率兵開闢？","options":["沈葆楨","劉銘傳","羅大春","吳光亮"],"answer":3,"explain":"1875年由總兵吳光亮率兵開闢中路。"},{"q":"今天登山客從東埔走的路線，多半是哪個時期開闢的？","options":["清代光緒年間","日治1919至1921年","戰後1950年代","明鄭時期"],"answer":1,"explain":"多為日治時期另闢的八通關越嶺道。"}],"images":[{"file":"國家一級古蹟開闢鴻荒(整修後).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/%E5%9C%8B%E5%AE%B6%E4%B8%80%E7%B4%9A%E5%8F%A4%E8%B9%9F%E9%96%8B%E9%97%A2%E9%B4%BB%E8%8D%92%28%E6%95%B4%E4%BF%AE%E5%BE%8C%29.jpg/960px-%E5%9C%8B%E5%AE%B6%E4%B8%80%E7%B4%9A%E5%8F%A4%E8%B9%9F%E9%96%8B%E9%97%A2%E9%B4%BB%E8%8D%92%28%E6%95%B4%E4%BF%AE%E5%BE%8C%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%9C%8B%E5%AE%B6%E4%B8%80%E7%B4%9A%E5%8F%A4%E8%B9%9F%E9%96%8B%E9%97%A2%E9%B4%BB%E8%8D%92(%E6%95%B4%E4%BF%AE%E5%BE%8C).jpg","artist":"林振宇","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/zhushan-batongguangudao-0.webp","small":"img/zhushan-batongguangudao-0-s.webp"}]},{"id":"zhushan-lianxinggong","name":"竹山連興宮","short":"竹山連興宮","category":"縣定古蹟","level":"縣(市)定古蹟","town":"竹山鎮","types":["寺廟"],"lat":23.756274,"lng":120.685168,"address":"南投縣竹山鎮竹山里下橫街28號","announced":"2000-08-09","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20190426000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-19/ad14fdba-f20d-4881-807c-ec763f972c37/竹山連興宮.jpg","year":1742,"yearText":"1742年或1756年（乾隆年間，兩說）","era":"qing","themes":["宗教信仰"],"yearUnknown":false,"summary":"南投歷史最悠久的媽祖廟，供奉黑面媽祖","intro":"竹山連興宮位於竹山鎮竹山里下橫街，奉祀湄洲媽祖，是竹山、鹿谷地區民眾主要的信仰中心，也是南投縣歷史最悠久的媽祖廟。創建年代有乾隆7年（1742）與乾隆21年（1756）兩說，名稱取「水沙連興旺」之意，歷經1856年、1907年與1972年三次大修。廟內黑面媽祖原安座於社寮媽祖宮，1912年因整修暫駐於此後不願回駕，於是每年媽祖誕辰前十天，以神轎迎回社寮「娘家」。廟內古物眾多，如「德佈山海」古匾、1778年立的「正堂馬示」石碑，以及福州匠師溥明所作的千里眼、順風耳神像。","highlights":["四肢以榫接、可拆解組合的黑面媽祖","921震後與另半截接合的「正堂馬示」碑","福州匠師溥明的千里眼、順風耳像"],"funFact":"黑面媽祖腳纏裹腳布、穿繡花鞋、戴耳環，這樣的神像在臺灣十分罕見。","photoSpot":"在下橫街廟埕拍前殿燕尾與石獅","visitMin":30,"openNote":"位於竹山鎮竹山里下橫街，官方資料記載開放時間8:00至21:00。參拜時請保持莊重，拍攝神像前先詢問廟方。可搭客運到竹山。","dialogue":[{"who":"A","text":"來竹山先拜媽祖！連興宮是南投縣歷史最悠久的媽祖廟，名字取水沙連興旺的意思。"},{"who":"R","text":"Allan，聽說這裡的黑面媽祖有個不想回家的故事？"},{"who":"A","text":"對呀！黑面媽祖原本住社寮媽祖宮，1912年那邊整修，暫時住到這裡，結果就不願回駕了。"},{"who":"R","text":"媽祖也會住到不想走，這裡一定很舒服。"},{"who":"A","text":"所以每年媽祖誕辰前十天，信眾會用神轎把她迎回社寮娘家，這個習俗延續了八十多年。"},{"who":"R","text":"好像嫁出去的女兒回娘家！神像本身有什麼特別嗎？"},{"who":"A","text":"她的四肢關節用榫接，可以拆開再組合，腳上還纏裹腳布、穿繡花鞋，在臺灣很少見。"},{"who":"R","text":"那廟裡還藏了什麼值得看的寶物？"},{"who":"A","text":"很多！請妳到右側入口，找那塊921震後只剩半截、後來和另半截接回去的正堂馬示石碑。"}],"clues":["我有一尊來暫住卻不願回去的黑面媽祖","我的名字取自水沙連興旺的意思","我是竹山街上南投縣歷史最悠久的媽祖廟"],"quiz":[{"q":"連興宮的黑面媽祖原本安座在哪裡？","options":["鹿港天后宮","北港朝天宮","社寮媽祖宮","大甲鎮瀾宮"],"answer":2,"explain":"原安座社寮媽祖宮，1912年暫駐後不願回駕。"},{"q":"連興宮的名稱取什麼寓意？","options":["連年興盛","連結兩岸","興建連城","水沙連興旺"],"answer":3,"explain":"取「水沙連興旺」之意命名。"}],"images":[{"file":"Zhushan Lianxing Temple 20120302.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/53/Zhushan_Lianxing_Temple_20120302.jpg/960px-Zhushan_Lianxing_Temple_20120302.jpg","page":"https://commons.wikimedia.org/wiki/File:Zhushan_Lianxing_Temple_20120302.jpg","artist":"Shxpeng","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/zhushan-lianxinggong-0.webp","small":"img/zhushan-lianxinggong-0-s.webp"}]},{"id":"caotun-yuemeicuolongde","name":"月眉厝龍德廟","short":"月眉厝龍德廟","category":"縣定古蹟","level":"縣(市)定古蹟","town":"草屯鎮","types":["寺廟"],"lat":23.971298,"lng":120.650419,"address":"南投縣草屯鎮碧峰里碧山路1158號","announced":"1985-11-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20190501000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-15/8cdd09b8-56e7-409a-ad04-aabf19292be0/月眉厝龍德廟.jpg","year":1793,"yearText":"1793年（清乾隆58年）","era":"qing","themes":["宗教信仰","宅第家族"],"yearUnknown":false,"summary":"林姓宗族守護的保生大帝廟與救命老榕","intro":"月眉厝龍德廟位於草屯鎮碧峰里碧山路，貓羅溪東岸的月眉厝。清代林姓先民從漳州府南靖縣攜保生大帝香火來臺，入墾草屯後成為四大姓之一，1793年在現址建成龍德廟，是草屯林姓宗族的主要寺廟，也是庄民信仰與自治中心，地方事務由「六腳頭」共商。廟為單進兩護龍帶拜亭的樸實格局，斗座直接承桁的作法可看出清代中部匠師手法。1864年臺灣兵備道丁曰健途經此地祈勝，亂平後獻「刑期無刑」匾。1985年指定為古蹟。","highlights":["清同治3年丁曰健所獻「刑期無刑」匾","廟埕老榕樹與泰山石敢當","清咸豐元年「真元壽世」古匾"],"funFact":"1959年八七水災時，許多庄民爬上廟前老榕樹逃過一劫；後來拓寬馬路要砍樹，里民陳情護樹，終於保住。","photoSpot":"在廟埕老榕樹下，把樹與廟一起入鏡","visitMin":25,"openNote":"位於草屯鎮碧峰里碧山路，依官方資料全天開放，參拜請保持安靜、尊重廟方規範。可搭客運到草屯市區後轉乘或開車前往。","dialogue":[{"who":"A","text":"阿拉蕾，如果淹大水，妳第一個會往哪裡跑？"},{"who":"R","text":"當然往高處跑啊！Allan 不要嚇我，這跟廟有什麼關係？"},{"who":"A","text":"1959年八七水災，貓羅溪潰堤，月眉厝的庄民就是爬上龍德廟前的老榕樹逃命的。"},{"who":"R","text":"哇，這棵樹根本是救命恩人！它後來還在嗎？"},{"who":"A","text":"還在。1981年拓寬碧山路本來要砍，里民陳情護樹到底，最後連廟的南廂也一起保住。"},{"who":"R","text":"那這間廟是誰蓋的？主神是哪一位？"},{"who":"A","text":"林姓先民從福建南靖帶來保生大帝香火，1793年在這裡建廟，地方大小事都在廟裡商量。"},{"who":"R","text":"所以它是廟，也是以前的里民活動中心兼議事廳！"},{"who":"A","text":"沒錯。到現場先拜拜，再到榕樹下的小祠看看，跟這位老樹爺爺說聲謝謝吧！"}],"clues":["我廟裡有一塊清代兵備道所獻的「刑期無刑」匾","水災時，庄民爬上我門前的老榕樹逃過一劫","我在草屯碧峰里，主祀保生大帝，由林姓宗族所建"],"quiz":[{"q":"龍德廟主祀哪一位神明？","options":["天上聖母","關聖帝君","保生大帝","清水祖師"],"answer":2,"explain":"林姓先民攜保生大帝香火來臺，龍德廟主祀保生大帝。"},{"q":"八七水災時，庄民靠什麼逃過一劫？","options":["躲進廟的正殿","跑上附近山坡","搭竹筏渡過溪","爬上廟前老榕樹"],"answer":3,"explain":"許多庄民攀上廟前古榕樹而倖免於難。"}],"images":[{"file":"月眉厝龍德廟.gif","thumb":"https://upload.wikimedia.org/wikipedia/commons/4/47/%E6%9C%88%E7%9C%89%E5%8E%9D%E9%BE%8D%E5%BE%B7%E5%BB%9F.gif","page":"https://commons.wikimedia.org/wiki/File:%E6%9C%88%E7%9C%89%E5%8E%9D%E9%BE%8D%E5%BE%B7%E5%BB%9F.gif","artist":"Outlookxp","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0"}]},{"id":"zhushan-longenzhensuiqu","name":"竹山隆恩圳隧渠","short":"隆恩圳隧渠","category":"縣定古蹟","level":"縣(市)定古蹟","town":"竹山鎮","types":["產業"],"lat":23.816103,"lng":120.761956,"address":"南投縣竹山鎮富州里(吊橋頭集集攔河埯南端)","announced":"2006-07-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20060711000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-15/a69eb07b-41f0-4650-8215-f9537a28e3a4/竹山隆恩圳隧渠.jpg","year":1794,"yearText":"1794年（乾隆59年）","era":"qing","themes":["水利設施"],"yearUnknown":false,"summary":"清代人工鑿山取水，落差僅84公分","intro":"竹山隆恩圳隧渠位於竹山鎮富州里，集集攔河堰南端。隆恩圳開鑿於1794年，由社寮地區墾戶張天球、陳佛照、陳同升、曾石等人開鑿，灌溉社寮附近數百甲農田，全長約一公里。取水口以人工鑿出數百公尺的隧道穿山而過，進出水口水位落差只有84公分，在缺乏精密儀器的年代相當不易；另設二十多處與大圳相通的「水窗」，又稱橫坑，大水時分散水勢，枯水期又能攔截溪水入圳。2001年集集攔河堰完工取代原隧渠，仍保留取水口隧渠172公尺，成為新舊水利工程並置的文化資產保存案例。","highlights":["保留下來的172公尺取水口隧渠","能分散水勢也能攔水的「水窗」設計","與集集攔河堰新舊並置的景觀"],"funFact":"隧道進出水口水位只差84公分，大約一張書桌高，在沒有精密儀器的年代很不容易。","photoSpot":"在攔河堰南端拍隧渠與堰堤同框","visitMin":20,"openNote":"位於竹山鎮富州里，集集攔河堰南端，戶外全天可參觀。水利設施周邊請勿下水或攀越護欄，颱風豪雨期間請勿靠近溪畔。","dialogue":[{"who":"R","text":"Allan，山壁上這個洞口，是古代的祕密通道嗎？"},{"who":"A","text":"算是水的祕密通道！這是隆恩圳的隧渠，1794年社寮的墾戶們開鑿，引濁水溪水灌溉。"},{"who":"R","text":"1794年就會挖隧道？那時候又沒有怪手。"},{"who":"A","text":"全靠人工鑿山，隧道有數百公尺長，而且進出水口的水位只差84公分。"},{"who":"R","text":"84公分？差不多是一張書桌的高度，這也太精準了吧！"},{"who":"A","text":"還有更聰明的，他們做了二十多處水窗，大水時分散水勢，枯水期又能攔水入圳。"},{"who":"R","text":"會自己調節的水圳，古人的腦袋好厲害。"},{"who":"A","text":"2001年集集攔河堰完工後取代了它，但仍留下172公尺取水口隧渠，新舊並排很有看頭。"},{"who":"R","text":"我的任務是站在旁邊拍一張，讓清代隧渠和現代攔河堰同框！"}],"clues":["我的進水口和出水口，水位只差84公分","我身上有二十多扇叫水窗的橫坑","我是社寮墾戶在乾隆年間鑿穿山壁的取水隧道"],"quiz":[{"q":"這條清代隧渠進出水口的水位落差約多少？","options":["8公分","84公分","8公尺","84公尺"],"answer":1,"explain":"進出水口水位落差只有84公分。"},{"q":"這條隧渠的功能後來被哪項工程取代？","options":["集集攔河堰","日月潭發電廠","霧社水庫","明潭抽蓄電廠"],"answer":0,"explain":"2001年集集攔河堰取代原隧渠。"}],"images":[{"file":"竹山隆恩圳隧渠正面照.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/%E7%AB%B9%E5%B1%B1%E9%9A%86%E6%81%A9%E5%9C%B3%E9%9A%A7%E6%B8%A0%E6%AD%A3%E9%9D%A2%E7%85%A7.jpg/960px-%E7%AB%B9%E5%B1%B1%E9%9A%86%E6%81%A9%E5%9C%B3%E9%9A%A7%E6%B8%A0%E6%AD%A3%E9%9D%A2%E7%85%A7.jpg","page":"https://commons.wikimedia.org/wiki/File:%E7%AB%B9%E5%B1%B1%E9%9A%86%E6%81%A9%E5%9C%B3%E9%9A%A7%E6%B8%A0%E6%AD%A3%E9%9D%A2%E7%85%A7.jpg","artist":"林振宇","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/zhushan-longenzhensuiqu-0.webp","small":"img/zhushan-longenzhensuiqu-0-s.webp"}]},{"id":"caotun-chaoyanggong","name":"草屯朝陽宮","short":"草屯朝陽宮","category":"縣定古蹟","level":"縣(市)定古蹟","town":"草屯鎮","types":["寺廟"],"lat":23.983499,"lng":120.663974,"address":"南投縣草屯鎮史館路239號","announced":"2021-08-17","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20211104000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-08/eb6ad99e-c200-47b9-ac2a-c75951e45b08/草屯朝陽宮.jpg","year":1797,"yearText":"1797年（清嘉慶2年）","era":"qing","themes":["宗教信仰"],"yearUnknown":false,"summary":"草屯四大姓共同興建的最早媽祖廟","intro":"草屯朝陽宮位於草屯鎮北投里史館路，1797年由洪、李、林、簡四大姓聚資延聘名匠興建，是草屯地區最早的媽祖廟，奉祀「湄洲聖二媽」，祭祀圈跨越各姓，也是清代北投堡四大姓總理的行政中心。清代草屯是鹿港、臺中進入南投與埔里的交通樞紐，朝陽宮見證了地方開發。正殿雕刻保留1797至1806年間鑿花匠的手法，有「憨番挑角」「憨番挑樑」雕塑。2009年登錄歷史建築，2021年公告為縣定古蹟，2019年完成大規模修復。","highlights":["正殿「憨番挑角」「憨番挑樑」雕塑","神龕上方「水德配天」等古匾","虎爺石香爐與磨石子神桌"],"funFact":"朝陽宮由洪、李、林、簡四大姓一起蓋，平常各姓各有宗祠，拜媽祖時大家就是一家人。","photoSpot":"在廟埕正面拍三川殿燕尾脊","visitMin":30,"openNote":"位於草屯鎮史館路，依官方資料每日07:00至21:00開放參拜，由廟方管理委員會管理。可搭客運到草屯市區後轉乘前往。","dialogue":[{"who":"A","text":"阿拉蕾，來到草屯先考妳一題：草屯四大姓是哪四個？"},{"who":"R","text":"這我知道，洪、李、林、簡！最近一直聽你講，耳朵都快長繭了。"},{"who":"A","text":"很好！這四大姓平常各拜各的祖先，可是1797年他們一起出錢，蓋了朝陽宮。"},{"who":"R","text":"四個家族合作蓋廟，不會吵架嗎？"},{"who":"A","text":"有媽祖在，大家都很客氣。這裡是草屯最早的媽祖廟，清代也是四大姓總理辦公的地方。"},{"who":"R","text":"那廟裡最特別的寶貝是什麼？是金牌還是古匾？"},{"who":"A","text":"正殿有「憨番挑角」和「憨番挑樑」，憨番蹲在屋角扛重量，表情又苦又可愛。"},{"who":"R","text":"好像我每天幫 Allan 扛行李、扛便當，還要扛他冷笑話的樣子！"},{"who":"A","text":"那妳到現場抬頭找找憨番，看他跟妳誰比較辛苦，拍下來比一比。"}],"clues":["我的正殿屋角有憨番在扛重量","清代我是北投堡四大姓總理辦事的地方","我是草屯最早的媽祖廟，由洪李林簡四姓合建"],"quiz":[{"q":"朝陽宮由草屯哪幾個大姓共同興建？","options":["陳林黃張","王李張劉","洪李林簡","洪林莊吳"],"answer":2,"explain":"朝陽宮由洪、李、林、簡四大姓聚資興建。"},{"q":"朝陽宮主要奉祀哪一位神明？","options":["保生大帝","開漳聖王","三山國王","媽祖"],"answer":3,"explain":"朝陽宮奉祀湄洲聖二媽，是草屯最早的媽祖廟。"}],"images":[{"file":"草屯朝陽宮.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b3/%E8%8D%89%E5%B1%AF%E6%9C%9D%E9%99%BD%E5%AE%AE.JPG/960px-%E8%8D%89%E5%B1%AF%E6%9C%9D%E9%99%BD%E5%AE%AE.JPG","page":"https://commons.wikimedia.org/wiki/File:%E8%8D%89%E5%B1%AF%E6%9C%9D%E9%99%BD%E5%AE%AE.JPG","artist":"Pbdragonwang","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/caotun-chaoyanggong-0.webp","small":"img/caotun-chaoyanggong-0-s.webp"}]},{"id":"caotun-dunluntang","name":"草屯燉倫堂","short":"草屯燉倫堂","category":"縣定古蹟","level":"縣(市)定古蹟","town":"草屯鎮","types":["祠堂"],"lat":24.000986,"lng":120.655069,"address":"南投縣草屯鎮加老里加老路269-1號","announced":"1993-02-05","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19930205000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-07-17/76c516b7-76d1-49bf-a91d-52d969d4b999/草屯燉倫堂.jpg","year":1830,"yearText":"1830年（清道光10年）","era":"qing","themes":["宗祠公廳","震災重建"],"yearUnknown":false,"summary":"洪姓宗祠中最古樸、少改動的一座","intro":"燉倫堂位於草屯鎮加老里頂茄荖聚落，是洪姓移民入墾草屯後建立的宗祠之一。1810年洪秉正率家族從漳州府漳浦縣渡臺，落腳頂茄荖一帶開墾，並開圳引水灌溉。1830年創建敦樸派下的宗祠燉倫堂。建築為坐東朝西的兩進式小型祠廟，以土埆、木材、薄瓦構成，少用繁複剪黏，屋脊平直，風格古樸。在草屯洪姓四座祠堂中，燉倫堂沒有大規模改建紀錄，最能保持早期樣貌，1993年指定為古蹟。921大地震造成龜裂與木柱移位，2001年修復完成。","highlights":["屋脊平直、只在翼角微揚的燕尾脊","門柱兼作前點金柱的凹壽前殿","「百世衣冠長濟美」等祠內對聯"],"funFact":"依族人說法，燉倫堂的座向是面向大陸祖祠，表達永懷遠祖之意。","photoSpot":"在祠前廣場拍兩進式屋脊與門廳","visitMin":20,"openNote":"位於草屯鎮加老里的宗祠，依官方資料08:00至17:00開放，開放情形以管理單位為準；這是宗族祭祀空間，請保持安靜、勿擅入內室。","dialogue":[{"who":"R","text":"Allan，這間祠堂好樸素，沒有五顏六色的剪黏耶。"},{"who":"A","text":"這就是燉倫堂的個性。它是1830年洪姓族人蓋的宗祠，走的是低調古樸路線。"},{"who":"R","text":"低調到我差點以為是一般老房子。"},{"who":"A","text":"草屯洪姓蓋了四座祠堂，只有它沒有大改建的紀錄，土埆、木頭和薄瓦都還保留原味。"},{"who":"R","text":"那921大地震的時候，它還好嗎？"},{"who":"A","text":"正殿後兩側龜裂、木柱移位，修復後2001年完工。老房子跟老人家一樣，要好好照顧。"},{"who":"R","text":"聽說它坐東朝西的座向，有特別的意思？"},{"who":"A","text":"族人說它面向大陸祖祠，表示不忘根本。洪家祖先如果有導航，應該設定成「回老家」。"},{"who":"R","text":"到現場我要找找屋脊，看看它是不是真的只在角落微微翹起來！"}],"clues":["我只在屋角輕輕翹起，屋脊比一般廟宇平直","族人說我面向祖籍地，表示永懷遠祖","我是草屯頂茄荖洪姓族人在1830年建的宗祠"],"quiz":[{"q":"燉倫堂是草屯哪一姓的宗祠？","options":["洪姓","簡姓","林姓","李姓"],"answer":0,"explain":"燉倫堂是洪姓敦樸派下的宗祠。"},{"q":"燉倫堂在洪姓祠堂中的特色是什麼？","options":["規模最大","最少改建、最古樸","裝飾最華麗","年代最晚"],"answer":1,"explain":"因無大事重修紀錄，仍維持早期古樸風貌。"}],"images":[{"file":"草屯燉倫堂, 南投縣, 台灣 - 20120913.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/eb/%E8%8D%89%E5%B1%AF%E7%87%89%E5%80%AB%E5%A0%82%2C_%E5%8D%97%E6%8A%95%E7%B8%A3%2C_%E5%8F%B0%E7%81%A3_-_20120913.jpg/960px-%E8%8D%89%E5%B1%AF%E7%87%89%E5%80%AB%E5%A0%82%2C_%E5%8D%97%E6%8A%95%E7%B8%A3%2C_%E5%8F%B0%E7%81%A3_-_20120913.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%8D%89%E5%B1%AF%E7%87%89%E5%80%AB%E5%A0%82,_%E5%8D%97%E6%8A%95%E7%B8%A3,_%E5%8F%B0%E7%81%A3_-_20120913.jpg","artist":"Pbdragonwang","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/caotun-dunluntang-0.webp","small":"img/caotun-dunluntang-0-s.webp"}]},{"id":"nantou-lantianshuyuan","name":"藍田書院","short":"藍田書院","category":"縣定古蹟","level":"縣(市)定古蹟","town":"南投市","types":["書院"],"lat":23.907231,"lng":120.684732,"address":"南投縣南投市南投市崇文里文昌街140號","announced":"1985-11-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20190501000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-02-17/cad06896-f400-4db4-b8c5-ae969c218854/藍田書院.jpg","year":1831,"yearText":"1831年（清道光11年）","era":"qing","themes":["書院儒學","宗教信仰"],"yearUnknown":false,"summary":"南投縣第一所正式書院","intro":"藍田書院位於南投市崇文里文昌街。1831年南投縣丞朱懋邀集南北投及水沙連兩堡士紳議建，1833年竣工，是南投縣第一所正式書院，取「種玉藍田」之意，期望學子青出於藍。書院歷經多次重修與遷建，日治時期因市區改正，於1915年以原貌遷建方式改築到現址，1957年再次修建成今貌。現為單進兩廂格局，前殿主祀文昌帝君，後殿為鸞堂濟化堂與供奉孔子的大成殿，俗稱「孔子廟」。殿內保存「天上文衡」「奏凱崇文」等清代古匾。","highlights":["清代古匾「天上文衡」「奏凱崇文」","前殿半月池「鯉躍龍門」與旗杆座","東南牆角的「奇賢門」入口"],"funFact":"「藍田」取自種玉的典故，把教育人才比喻成種玉，希望學生青出於藍。","photoSpot":"在半月池旁拍三川殿與鯉躍龍門","visitMin":30,"openNote":"位於南投市崇文里文昌街，依官方資料08:30至17:00開放，由書院管理委員會管理。可搭客運到南投市區後步行前往，附近可順遊武德殿、旗杆厝外觀。","dialogue":[{"who":"A","text":"阿拉蕾，南投第一所正式書院，妳猜叫什麼名字？"},{"who":"R","text":"看門口的招牌就知道，藍田書院！Allan 這題太簡單了啦。"},{"who":"A","text":"那加分題來了：為什麼這間書院要叫藍田？"},{"who":"R","text":"呃，因為以前這裡的田都種藍色的植物？"},{"who":"A","text":"差很多！藍田有種玉的典故，把教育人才比喻成種玉，希望學生青出於藍、更勝於藍。"},{"who":"R","text":"好有學問的名字，比我的名字有深度多了。它一直都在這裡嗎？"},{"who":"A","text":"1833年蓋好，後來搬過家。日治時期1915年因市區改正，以原貌遷建到現在的文昌街。"},{"who":"R","text":"那現在裡面除了文昌帝君，還拜誰？"},{"who":"A","text":"後殿有鸞堂濟化堂和供奉孔子的大成殿。到現場先找半月池裡的鯉躍龍門，祝妳考運亨通！"}],"clues":["我的名字取自種玉的典故","1915年我因市區改正以原貌遷建","我是南投縣第一所正式書院，在南投市文昌街"],"quiz":[{"q":"藍田書院是哪一位官員邀集士紳籌建的？","options":["臺灣兵備道丁曰健","彰化知縣周璽","南投縣丞朱懋","巡撫劉銘傳"],"answer":2,"explain":"1831年南投縣丞朱懋邀集士紳議建書院。"},{"q":"藍田書院前殿半月池的雕塑寓意是什麼？","options":["五穀豐收","延年益壽","海晏河清","鯉躍龍門考試順利"],"answer":3,"explain":"半月池中的鯉躍龍門，祈求考試順利。"}],"images":[{"file":"藍田書院.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4c/%E8%97%8D%E7%94%B0%E6%9B%B8%E9%99%A2.JPG/960px-%E8%97%8D%E7%94%B0%E6%9B%B8%E9%99%A2.JPG","page":"https://commons.wikimedia.org/wiki/File:%E8%97%8D%E7%94%B0%E6%9B%B8%E9%99%A2.JPG","artist":"Pbdragonwang","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/nantou-lantianshuyuan-0.webp","small":"img/nantou-lantianshuyuan-0-s.webp"}]},{"id":"caotun-dengyingshuyuan","name":"登瀛書院","short":"登瀛書院","category":"縣定古蹟","level":"縣(市)定古蹟","town":"草屯鎮","types":["書院"],"lat":23.988759,"lng":120.667479,"address":"南投縣草屯鎮新庄里史館路文昌巷30號","announced":"1985-11-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19851127000032","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-16/5d850b23-818d-4e8d-b412-9170e5af5070/登瀛書院.jpg","year":1847,"yearText":"1847年（清道光27年）","era":"qing","themes":["書院儒學","震災重建"],"yearUnknown":false,"summary":"臺灣保存原貌最完整的書院之一","intro":"登瀛書院位於草屯鎮新庄里史館路文昌巷。清道光年間北投堡已有士紳組成「登瀛社」，因藍田書院遠在南投，1847年由莊文蔚、洪濟純等人募款創建，1848年竣工，主祀文昌帝君，清代培育舉人簡化成等19名功名人才。格局為單進兩翼齋舍的三合院，正前有三脊燕尾照壁，右前方有惜字亭。書院歷經多次大修都依原貌修繕，兩排齋舍不增不減、土埆牆也未改成磚，被評為書院類最完整者之一。921大地震造成嚴重傾斜塌陷，2002年依原貌修復完成。","highlights":["正前方長13公尺的三脊燕尾照壁","正殿右前方焚燒字紙的惜字亭","古匾「學教敦倫」與拜殿枋梁彩繪"],"funFact":"書院四次大修都照原貌，連兩排齋舍都沒多蓋或少蓋一間，土埆牆也一直沒換成紅磚。","photoSpot":"在照壁旁斜拍正殿燕尾與兩側齋舍","visitMin":30,"openNote":"位於草屯鎮新庄里，依官方資料08:30至17:00開放，現由書院管理委員會管理，開放民眾參拜。可搭客運到草屯市區後轉乘前往。","dialogue":[{"who":"R","text":"Allan，書院是古代的學校吧？那草屯的學生以前都去哪裡讀書？"},{"who":"A","text":"本來要跑到南投的藍田書院，太遠了，所以1847年北投堡的士紳自己募款蓋了登瀛書院。"},{"who":"R","text":"自己的書院自己蓋，好有行動力！那它跟其他書院有什麼不一樣？"},{"who":"A","text":"它是臺灣原貌保存最完整的書院之一，大修好幾次，兩排齋舍一間都沒多也沒少。"},{"who":"R","text":"連牆壁也是原本的材料嗎？還是偷偷換成水泥了？"},{"who":"A","text":"對，還是土埆牆，沒有換成紅磚。不過921大地震讓它嚴重傾斜，後來依原貌修好了。"},{"who":"R","text":"那我要拜文昌帝君保佑考試，有沒有什麼祕訣？"},{"who":"A","text":"祕訣就是拜完要回家讀書。我拜了三十年，發現文昌帝君最怕不讀書的人。"},{"who":"R","text":"好啦好啦！到現場我要去右前方找惜字亭，看古人怎麼尊敬寫過字的紙。"}],"clues":["我的齋舍兩排，修了好幾次一間都沒增減","我的正前方有一道三脊燕尾照壁，右前方有惜字亭","我是草屯北投堡士紳在1847年募款創建的書院"],"quiz":[{"q":"登瀛書院修復時，牆體用的是什麼材料？","options":["土埆","鋼筋混凝土","紅磚","石板"],"answer":0,"explain":"書院大修都依原貌，土埆牆未更換為磚塊。"},{"q":"書院正殿右前方有什麼設施？","options":["鐘鼓樓","惜字亭","半月池","旗杆座"],"answer":1,"explain":"登瀛書院正殿右前方有惜字亭。"}],"images":[{"file":"登瀛書院.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3d/%E7%99%BB%E7%80%9B%E6%9B%B8%E9%99%A2.JPG/960px-%E7%99%BB%E7%80%9B%E6%9B%B8%E9%99%A2.JPG","page":"https://commons.wikimedia.org/wiki/File:%E7%99%BB%E7%80%9B%E6%9B%B8%E9%99%A2.JPG","artist":"Pbdragonwang","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/caotun-dengyingshuyuan-0.webp","small":"img/caotun-dengyingshuyuan-0-s.webp"}]},{"id":"zhushan-sheliaojingsheng","name":"竹山社寮敬聖亭","short":"社寮敬聖亭","category":"縣定古蹟","level":"縣(市)定古蹟","town":"竹山鎮","types":["其他設施"],"lat":23.814456,"lng":120.722279,"address":"南投縣竹山鎮社寮里集山路1段1738號","announced":"2006-07-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20190425000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-12/7e81dd0d-830e-4591-9352-6d74d252958d/竹山社寮敬聖亭.jpg","year":1861,"yearText":"1861年（咸豐11年）","era":"qing","themes":["書院儒學","震災重建"],"yearUnknown":false,"summary":"砂岩雕成、震後重修的清代惜字亭","intro":"竹山社寮敬聖亭位於竹山鎮社寮里，竹山往集集的公路旁，又稱聖蹟亭、惜字亭，是古人焚化寫過字的紙張、表達敬惜文字之心的建築。1861年由陳凌雲捐資創建，1879年童生陳大成捐建重修。亭高兩層，以當地砂岩雕鑿砌成，屋頂雕成筒瓦與板瓦樣式；正面圓拱門洞上刻「敬聖亭」，門聯「有能付丙者，便是識丁人」巧妙嵌入天干丙、丁。二層四面浮雕葫蘆、麒麟、鹿、竹等吉祥圖案。1999年921大地震時整座倒毀，2001年9月修復完成，是南投縣僅存的兩座清代聖蹟亭之一。","highlights":["門聯「有能付丙者，便是識丁人」","正面造形簡潔的葫蘆浮雕","背側形象飽滿的麒麟浮雕"],"funFact":"門聯的「付丙」是火化、「識丁」是識字，丙丁在五行屬火，把燒字紙說得很文雅。","photoSpot":"站在亭前拍圓拱門洞與門聯","visitMin":15,"openNote":"位於竹山鎮社寮里集山路一段旁，戶外全天可參觀，附近有紫南宮、社寮穀倉與永濟義渡碑，可一起走訪。路邊車多，拍照請注意安全。","dialogue":[{"who":"R","text":"Allan，這座石頭小塔是給誰住的？土地公嗎？"},{"who":"A","text":"不是喔，它叫敬聖亭，是專門燒寫過字的紙的小爐子，古人覺得文字很神聖，不能亂丟。"},{"who":"R","text":"那我考不好的考卷，是不是也可以送來燒？"},{"who":"A","text":"考卷燒了成績還是在啦！這座亭1861年由陳凌雲捐資創建，1879年又重修過。"},{"who":"R","text":"那門口石頭上刻的對聯寫了什麼呢？"},{"who":"A","text":"有能付丙者，便是識丁人。丙丁在五行屬火，付丙就是燒掉，識丁就是識字。"},{"who":"R","text":"好文雅的標語！可是石頭亭子遇到地震不會倒嗎？"},{"who":"A","text":"921大地震時它真的整座倒了，2001年9月才修好，現在是南投僅存兩座清代聖蹟亭之一。"},{"who":"R","text":"我的任務是繞到亭子後面，找到那隻胖胖的麒麟浮雕！"}],"clues":["我的門聯偷偷藏了兩個天干的字","我用當地砂岩雕成，大地震時曾整座倒下","我是社寮路邊專門焚化字紙的清代小亭"],"quiz":[{"q":"這類亭子的主要功能是什麼？","options":["焚化字紙","祭拜土地公","存放稻穀","瞭望守衛"],"answer":0,"explain":"敬聖亭是焚化字紙、敬惜文字的建築。"},{"q":"門聯中的「付丙」是什麼意思？","options":["讀書","火化","寫字","祭拜"],"answer":1,"explain":"丙在五行屬火，付丙就是火化。"}],"images":[{"file":"竹山社寮敬聖亭.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/77/%E7%AB%B9%E5%B1%B1%E7%A4%BE%E5%AF%AE%E6%95%AC%E8%81%96%E4%BA%AD.JPG/960px-%E7%AB%B9%E5%B1%B1%E7%A4%BE%E5%AF%AE%E6%95%AC%E8%81%96%E4%BA%AD.JPG","page":"https://commons.wikimedia.org/wiki/File:%E7%AB%B9%E5%B1%B1%E7%A4%BE%E5%AF%AE%E6%95%AC%E8%81%96%E4%BA%AD.JPG","artist":"Shxpeng","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/zhushan-sheliaojingsheng-0.webp","small":"img/zhushan-sheliaojingsheng-0-s.webp"}]},{"id":"lugu-linfengchijurenmu","name":"林鳳池舉人墓","short":"林鳳池舉人墓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"鹿谷鄉","types":["墓葬"],"lat":23.768926,"lng":120.738024,"address":"南投縣鹿谷鄉鹿谷鄉初鄉村中村巷23號","announced":"1985-11-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19851127000034","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-05-05/2cf58ece-39b2-4a54-97fb-f14baffbfd98/林鳳池舉人墓.jpg","year":1870,"yearText":"1870年（清同治9年）歸葬","era":"qing","themes":["墓葬碑碣","茶業農業"],"yearUnknown":false,"summary":"茶園環抱的沙連保唯一舉人墓園","intro":"位於鹿谷鄉初鄉村的山坡茶園中。林鳳池（1819–1867）是彰化縣沙連保粗坑莊（今初鄉村）人，1855年中乙卯科舉人，是沙連保唯一的舉人，福建巡撫為他立「文魁」匾，後獲內閣中書加侍讀銜。返鄉後與地方人士勸捐重修連興宮；1862年戴潮春事件時設保全局、聯莊防守。1867年赴京途中病逝廣東，1870年歸葬故里。墓座東南朝西北，左右三伸手環抱，石刻構件為砂岩，墓前有風化的石獅，柱身刻有堪輿楹聯，不遠處另立神道碑。1985年公告為縣定古蹟。","highlights":["三伸手環抱的墓園與墓前石獅","柱身堪輿楹聯「水九曲而神應，山四迴而氣生」","墓道入口的神道碑"],"funFact":"他是沙連保唯一的舉人，福建巡撫呂全孫還為他立了「文魁」匾額。","photoSpot":"站在墓前俯瞰周圍茶園","visitMin":25,"openNote":"官方資料開放時間為上午8:30至下午4:00，位於鹿谷鄉初鄉村茶園山坡，產業道路狹窄請小心會車，勿踩踏茶園。","dialogue":[{"who":"R","text":"Allan，我們爬上這片茶園，是要來喝凍頂烏龍茶嗎？"},{"who":"A","text":"茶等一下再喝，先來拜訪一位清代大人物，沙連保唯一的舉人林鳳池。"},{"who":"R","text":"唯一？那他考上的時候，全村應該放鞭炮放到天亮吧！"},{"who":"A","text":"差不多，1855年他中了舉人，福建巡撫還送他文魁匾額，後來得到內閣中書加侍讀的頭銜。"},{"who":"R","text":"那他後來有沒有到北京去當大官呢？"},{"who":"A","text":"他先回鄉重修連興宮，戴潮春事件時還設保全局聯莊防守。可惜1867年赴京途中病逝廣東。"},{"who":"R","text":"好可惜，那這座墓是後來才建的嗎？"},{"who":"A","text":"對，1870年歸葬故里。墓有三層伸手環抱，前面有石獅，柱子上還刻著看風水的對聯。"},{"who":"A","text":"到了墓前，找找水九曲而神應，山四迴而氣生這句對聯，再看看四周的山勢像不像。"}],"clues":["我在鹿谷茶園的山坡上，周圍一片綠油油","我的主人1855年中舉，是沙連保唯一的一位","我是清代舉人病逝廣東後歸葬故里的墓園"],"quiz":[{"q":"林鳳池在哪一年考中舉人？","options":["1838年","1874年","1855年","1887年"],"answer":2,"explain":"清咸豐5年，即1855年中乙卯科舉人。"},{"q":"墓園柱身所刻的楹聯內容主要和什麼有關？","options":["堪輿風水","科舉試題","農作節氣","戰功事蹟"],"answer":0,"explain":"柱身刻有與堪輿相關的楹聯字句。"}],"images":[{"file":"南投縣縣定古蹟林鳳池舉人墓.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/73/%E5%8D%97%E6%8A%95%E7%B8%A3%E7%B8%A3%E5%AE%9A%E5%8F%A4%E8%B9%9F%E6%9E%97%E9%B3%B3%E6%B1%A0%E8%88%89%E4%BA%BA%E5%A2%93.jpg/960px-%E5%8D%97%E6%8A%95%E7%B8%A3%E7%B8%A3%E5%AE%9A%E5%8F%A4%E8%B9%9F%E6%9E%97%E9%B3%B3%E6%B1%A0%E8%88%89%E4%BA%BA%E5%A2%93.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%8D%97%E6%8A%95%E7%B8%A3%E7%B8%A3%E5%AE%9A%E5%8F%A4%E8%B9%9F%E6%9E%97%E9%B3%B3%E6%B1%A0%E8%88%89%E4%BA%BA%E5%A2%93.jpg","artist":"Kobe8833","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/lugu-linfengchijurenmu-0.webp","small":"img/lugu-linfengchijurenmu-0-s.webp"}]},{"id":"lugu-shengjiting","name":"鹿谷聖蹟亭","short":"鹿谷聖蹟亭","category":"縣定古蹟","level":"縣(市)定古蹟","town":"鹿谷鄉","types":["其他設施"],"lat":23.751406,"lng":120.748709,"address":"南投縣鹿谷鄉鹿谷鄉鹿谷村中正路164-1號","announced":"2006-07-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20060711000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-09-19/dd8ce113-8aea-458b-a5c8-622097c42b3b/鹿谷聖蹟亭.jpg","year":1871,"yearText":"1871年（清同治10年）","era":"qing","themes":["書院儒學","震災重建"],"yearUnknown":false,"summary":"敬惜字紙的焚字亭，歷經傾倒撞毀再重生","intro":"位於鹿谷鄉鹿谷村中正路旁。1871年，新寮街的文人社團「彬彬社」提倡興建，由童生黃時中負責施工，專門焚燒寫過字的紙張，表達敬惜字紙的傳統。日治時期科舉廢除，敬惜字紙風氣漸淡，1931年亭子一度傾圮，已改為詩社的彬彬社再募款重修。1990年因開闢外環道路，聖蹟亭位在計畫道路上，準備遷移時又遭車輛撞毀，殘件移到鹿谷鄉圖書館保存多年。1999年921大地震後，2001年與竹山社寮敬聖亭一起修復，鹿谷聖蹟亭在原址重建，周邊以竹編與石頭美化。2006年公告為縣定古蹟。","highlights":["焚燒字紙的亭身與爐口","周邊竹編與石頭布置的小景觀","與竹山社寮敬聖亭同年修復的歷史"],"funFact":"1990年準備拆遷時竟被車撞毀，殘件在圖書館裡待了好多年，2001年才回到原址。","photoSpot":"從路旁拍亭身與竹編、石頭造景","visitMin":10,"openNote":"官方資料標示24小時，位於鹿谷鄉鹿谷村中正路旁，路邊停車請注意來車。","dialogue":[{"who":"A","text":"阿拉蕾，如果你寫壞一張作業紙，你會怎麼處理？"},{"who":"R","text":"揉成一團，投籃丟進垃圾桶，咻一聲三分球！我的準度可是很有名的。"},{"who":"A","text":"清代的讀書人看了會昏倒。他們敬惜字紙，寫過字的紙要收集起來，送到這種聖蹟亭裡焚燒。"},{"who":"R","text":"原來紙也有隆重的告別式。那這座是誰蓋的？"},{"who":"A","text":"1871年新寮街的文人社團彬彬社提倡，由童生黃時中負責興建，算是當年文青的公益專案。"},{"who":"R","text":"那它一路上都平平安安地活到現在嗎？"},{"who":"A","text":"命運多舛喔！1931年傾倒過，1990年要拆遷時又被車撞毀，殘件只好暫放在圖書館。"},{"who":"R","text":"古蹟住進圖書館，也算是很有書香氣息的避難方式。"},{"who":"A","text":"2001年才回原址修復。到現場找找焚燒字紙的爐口，順便把自己的垃圾帶走喔。"}],"clues":["我是清代文人社團彬彬社倡建的","我曾被車撞毀，殘件在圖書館裡待了好幾年","我是鹿谷專門焚燒字紙的小亭"],"quiz":[{"q":"聖蹟亭在清代的主要用途是什麼？","options":["祭拜土地公","存放稻穀","守望治安","焚燒寫過字的紙張"],"answer":3,"explain":"昔日有字的紙須送到聖蹟亭焚燒，以示崇敬。"},{"q":"1990年鹿谷聖蹟亭遭遇了什麼事？","options":["遭颱風吹倒","準備遷移時被車撞毀","被大火燒毀","被改建成涼亭"],"answer":1,"explain":"因開闢外環道路須遷移，又遭車輛撞毀。"}],"images":[{"file":"鹿谷聖蹟亭.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/82/%E9%B9%BF%E8%B0%B7%E8%81%96%E8%B9%9F%E4%BA%AD.jpg/960px-%E9%B9%BF%E8%B0%B7%E8%81%96%E8%B9%9F%E4%BA%AD.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%B9%BF%E8%B0%B7%E8%81%96%E8%B9%9F%E4%BA%AD.jpg","artist":"Pbdragonwang","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/lugu-shengjiting-0.webp","small":"img/lugu-shengjiting-0-s.webp"}]},{"id":"mingjian-xiandinggujiyongji","name":"縣定古蹟永濟義渡碑(名間鄉)","short":"永濟義渡碑北岸","category":"縣定古蹟","level":"縣(市)定古蹟","town":"名間鄉","types":["碑碣"],"lat":23.830728,"lng":120.712014,"address":"南投縣名間鄉名間鄉濁水村福興宮左側","announced":"2006-07-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20190116000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-09-19/28a49904-db4e-4bd9-81ab-c4706707fc1b/永濟義渡碑(名間鄉).jpg","year":1879,"yearText":"1879年（光緒5年）","era":"qing","themes":["碑碣古道"],"yearUnknown":false,"summary":"濁水溪北岸記錄免費渡船的石碑","intro":"位於名間鄉濁水村福興宮左側。早年濁水溪兩岸沒有橋，名間濁水與竹山社寮之間靠渡船往來，民渡常有勒索，百姓負擔沉重。濁水莊的董郁文倡議設立免費撐渡的「義渡」，他在1863年去世後，兒子董榮華於1865年起繼承遺志，與吳朝陽等人勸捐，共得銀2800元，買田十段，以每年約四百石租穀支付船夫工資與修船費用。光緒5年正式立碑，由舉人簡化成撰文。碑為花崗石，高185公分、寬88公分，南北兩岸各立一座、內容相同。1931年義渡財產出售，所得作為架設集集吊橋的經費，義渡從此走入歷史。","highlights":["高185公分的花崗石碑","簡化成撰寫、詳列捐款與章程的碑文","與對岸竹山社寮那座碑隔溪相望"],"funFact":"碑文形容濁水溪「濁水之勢與黃河等」，可見當年渡河有多驚險。","photoSpot":"在福興宮旁拍石碑與廟宇同框","visitMin":15,"openNote":"位於名間鄉濁水村福興宮左側，戶外全天可參觀。可搭臺鐵集集線到濁水站再步行前往；參觀時請尊重廟方與信眾。","dialogue":[{"who":"A","text":"阿拉蕾，如果過一次河就要被船夫敲竹槓，妳會怎麼辦？"},{"who":"R","text":"我會自己游過去！啊不對，這條是濁水溪，我應該會被沖走吧。"},{"who":"A","text":"對，碑文就說濁水溪的水勢跟黃河一樣猛。所以清代這裡的人決定辦免費的義渡。"},{"who":"R","text":"免費搭船？那船夫的薪水誰來付？"},{"who":"A","text":"地方人士捐了2800元買田，用每年大約四百石的租穀付船夫工資和修船費。"},{"who":"R","text":"用稻田養一艘船，這個經營模式也太佛心了！"},{"who":"A","text":"發起人董郁文過世後，兒子董榮華接手完成，光緒5年立碑，南北兩岸各立一座。"},{"who":"R","text":"那現在濁水溪上還有免費的義渡嗎？"},{"who":"A","text":"1931年財產賣掉，錢拿去蓋集集吊橋，渡船就退休了。到現場找找碑文裡的黃河兩個字吧！"}],"clues":["我的雙胞胎兄弟站在濁水溪對岸","我記錄一群人捐錢買田，讓大家免費過河","我立在名間濁水村的媽祖廟旁"],"quiz":[{"q":"這座碑記錄的義渡用什麼支付船夫工資？","options":["官府渡稅","買田收租","向乘客收費","廟宇香油錢"],"answer":1,"explain":"捐款買田十段，以租穀支付工資與修船。"},{"q":"日治時期義渡財產出售後，所得用於什麼？","options":["興建學校","修建福興宮","開闢鐵路","架設集集吊橋"],"answer":3,"explain":"1931年出售，所得作為集集吊橋經費。"}],"images":[{"file":"永濟義渡碑 (福興宮).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/38/%E6%B0%B8%E6%BF%9F%E7%BE%A9%E6%B8%A1%E7%A2%91_%28%E7%A6%8F%E8%88%88%E5%AE%AE%29.jpg/960px-%E6%B0%B8%E6%BF%9F%E7%BE%A9%E6%B8%A1%E7%A2%91_%28%E7%A6%8F%E8%88%88%E5%AE%AE%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%B0%B8%E6%BF%9F%E7%BE%A9%E6%B8%A1%E7%A2%91_(%E7%A6%8F%E8%88%88%E5%AE%AE).jpg","artist":"Outlookxp","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/mingjian-xiandinggujiyongji-0.webp","small":"img/mingjian-xiandinggujiyongji-0-s.webp"}]},{"id":"zhushan-xiandinggujiyongji","name":"縣定古蹟永濟義渡碑(竹山鎮)","short":"永濟義渡碑南岸","category":"縣定古蹟","level":"縣(市)定古蹟","town":"竹山鎮","types":["碑碣"],"lat":23.816965,"lng":120.722855,"address":"南投縣竹山鎮竹山鎮社寮紫南宮前廣場","announced":"2006-07-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20190123000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-04-17/1d66e113-00dd-43ea-be56-f4f7033152df/竹山永濟義渡碑及周邊環境.jpg","year":1879,"yearText":"1879年（光緒5年）","era":"qing","themes":["碑碣古道"],"yearUnknown":false,"summary":"紫南宮前與北岸遙對的義渡石碑","intro":"這座永濟義渡碑位於竹山鎮社寮里紫南宮前廣場，與濁水溪北岸名間鄉濁水村福興宮旁的碑隔溪相望，兩碑高寬、碑文與材質都相同，附近正是當年的渡船頭。清代社寮與濁水之間沒有橋樑，民渡負擔重且常有勒索，地方於是籌設免費撐渡的「永濟義渡」，前後歷經十多年勸捐，買田收租支付船夫工資與修船費用，光緒5年立碑，由舉人簡化成撰文，碑上詳列捐款名錄、田產與章程。日治時期改為財團法人，1931年財產出售，作為架設集集吊橋的經費，1934年吊橋完成後義渡走入歷史。","highlights":["高185公分、寬88公分的花崗石碑","碑文「一水橫流，萬人病涉」的描寫","與北岸名間那座碑內容相同的雙碑設計"],"funFact":"碑文說濁水溪「溜急似箭、浪湧如飛」，舵工稍一鬆手就可能翻船觸石。","photoSpot":"在紫南宮廣場拍石碑全景","visitMin":15,"openNote":"位於竹山鎮社寮里紫南宮前廣場，戶外全天可參觀，由紫南宮管理委員會管理維護。假日香客多，請注意停車與人潮；可與社寮敬聖亭、社寮穀倉一起走訪。","dialogue":[{"who":"R","text":"Allan，紫南宮前面好熱鬧，你怎麼一直盯著旁邊那塊石碑？"},{"who":"A","text":"因為這塊碑記錄了一件很佛心的事：免費渡船！它叫永濟義渡碑。"},{"who":"R","text":"免費？那不就是穩賠不賺的生意嗎？船夫要喝西北風喔？"},{"who":"A","text":"清代地方人士捐錢買田，用田租付船夫工資和修船費，乘客一毛都不用出。"},{"who":"R","text":"原來是用稻米發薪水的公益航線，古人的點子真多！"},{"who":"A","text":"碑文還說濁水溪溜急似箭、浪湧如飛，舵工一鬆手就可能翻船，過河可是在拚命。"},{"who":"R","text":"那濁水溪對岸也有一塊一樣的碑嗎？"},{"who":"A","text":"有！名間濁水村福興宮旁那塊，高寬碑文都一樣，兩塊碑隔著濁水溪對望。"},{"who":"R","text":"我的任務是在碑文裡找出撰文者簡化成的名字，再想像對岸那塊碑在哪裡！"}],"clues":["我和北岸的兄弟長得一模一樣，隔著大溪對望","我身上刻著捐款名錄、田產和渡船章程","我站在社寮一座香火鼎盛的土地公廟前"],"quiz":[{"q":"竹山這座義渡碑立在哪座廟前？","options":["連興宮","福興宮","紫南宮","明新書院"],"answer":2,"explain":"竹山這座碑位於社寮紫南宮前廣場。"},{"q":"這座義渡碑的碑文由誰撰寫？","options":["簡化成","吳光亮","董郁文","沈葆楨"],"answer":0,"explain":"碑文由舉人簡化成撰寫。"}],"images":[{"file":"永濟義渡碑 (紫南宮).JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cd/%E6%B0%B8%E6%BF%9F%E7%BE%A9%E6%B8%A1%E7%A2%91_%28%E7%B4%AB%E5%8D%97%E5%AE%AE%29.JPG/960px-%E6%B0%B8%E6%BF%9F%E7%BE%A9%E6%B8%A1%E7%A2%91_%28%E7%B4%AB%E5%8D%97%E5%AE%AE%29.JPG","page":"https://commons.wikimedia.org/wiki/File:%E6%B0%B8%E6%BF%9F%E7%BE%A9%E6%B8%A1%E7%A2%91_(%E7%B4%AB%E5%8D%97%E5%AE%AE).JPG","artist":"Pbdragonwang","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/zhushan-xiandinggujiyongji-0.webp","small":"img/zhushan-xiandinggujiyongji-0-s.webp"}]},{"id":"jiji-mingxinshuyuan","name":"明新書院","short":"明新書院","category":"縣定古蹟","level":"縣(市)定古蹟","town":"集集鎮","types":["書院"],"lat":23.827566,"lng":120.799518,"address":"南投縣集集鎮永昌里東昌巷4號","announced":"1985-11-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19851127000033","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-05-09/c2d54e00-5eed-43a1-917d-b1fa65f18b5a/明新書院.jpg","year":1885,"yearText":"1885年（光緒11年）","era":"qing","themes":["書院儒學","震災重建"],"yearUnknown":false,"summary":"集集文風所繫、震後依原貌修復的書院","intro":"明新書院位於集集鎮永昌里。集集自古是進入水沙連內山與埔里盆地的孔道，清光緒初年樟腦業興起後街市繁榮，地方仕紳組成「濟濟社」，在柴橋頭庄建明新書院提倡文風。後來為遷入集集街，利用1883年濁水溪氾濫沖下的木料並募款改建，1885年完工，奉祀文昌帝君、制字先師與紫陽夫子。1902年書院田產與廟地捐給集集公學校建校，1908年鄉民再集資遷回柴橋頭現址，改稱「崇德堂」。1953年永昌國校設立後，形成書院與學校並存的樣貌。1985年指定為三級古蹟；1999年921大地震嚴重損毀，2002年依原貌修復完成。","highlights":["單進三合院格局與三開間正殿","本地砂岩石板鋪成的大埕","書院西側的惜字亭"],"funFact":"1883年濁水溪氾濫沖下大批木料，地方雇工收集起來，拿來蓋書院。","photoSpot":"從大埕拍正殿與原木簷柱","visitMin":30,"openNote":"位於集集鎮永昌里，與永昌國小相鄰，官方資料記載開放時間8:00至17:00。可搭臺鐵集集線到集集站，再步行或騎單車前往；書院旁為校園，上課時間請勿進入校區。","dialogue":[{"who":"A","text":"集集除了火車站，還藏著一間樸素的書院，就是這座明新書院。"},{"who":"R","text":"Allan，為什麼要在山腳下的小鎮蓋書院？"},{"who":"A","text":"清光緒年間樟腦業興起，集集街越來越熱鬧，仕紳組了濟濟社，蓋書院來提倡文風。"},{"who":"R","text":"賺了錢就想讀書，很有上進心嘛！"},{"who":"A","text":"更妙的是，1883年濁水溪氾濫沖下很多木料，地方就收集來當建材，1885年完工。"},{"who":"R","text":"大水送來的建材，這算是天上掉下來的禮物嗎？"},{"who":"A","text":"可以這麼說。可惜1999年921大地震讓書院嚴重損毀，2002年才依原貌修復完成。"},{"who":"R","text":"書院旁邊就是國小，讀書的香火真的延續下來了。"},{"who":"A","text":"沒錯！最後請妳到書院西邊，找出那座專門燒字紙的惜字亭。"}],"clues":["我曾被改稱崇德堂，至今和一所國小當鄰居","蓋我的木料，有一部分是大水從山裡沖下來的","我是集集仕紳組成濟濟社後興建的書院"],"quiz":[{"q":"明新書院主要奉祀哪一位神祇？","options":["媽祖","關聖帝君","福德正神","文昌帝君"],"answer":3,"explain":"書院奉祀文昌帝君、制字先師與紫陽夫子。"},{"q":"明新書院在哪一次災害中嚴重損毀？","options":["八七水災","桃芝颱風","921大地震","莫拉克颱風"],"answer":2,"explain":"921大地震嚴重損毀，2002年依原貌修復。"}],"images":[{"file":"明新書院.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/38/%E6%98%8E%E6%96%B0%E6%9B%B8%E9%99%A2.JPG/960px-%E6%98%8E%E6%96%B0%E6%9B%B8%E9%99%A2.JPG","page":"https://commons.wikimedia.org/wiki/File:%E6%98%8E%E6%96%B0%E6%9B%B8%E9%99%A2.JPG","artist":"SSR2000","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/jiji-mingxinshuyuan-0.webp","small":"img/jiji-mingxinshuyuan-0-s.webp"}]},{"id":"xinyi-nanzaijiaomanshe","name":"楠仔腳蔓社學堂遺蹟","short":"楠仔腳蔓社學堂","category":"縣定古蹟","level":"縣(市)定古蹟","town":"信義鄉","types":["其他設施"],"lat":23.61797,"lng":120.884199,"address":"南投縣信義鄉望美村部落","announced":"1988-02-26","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19880226000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-29/184a2ed1-d897-45f6-8260-d2657978168a/楠仔腳蔓社學堂遺蹟.jpg","year":1887,"yearText":"1887年（清光緒13年）","era":"qing","themes":["教育設施","原住民族文化","碑碣古道"],"yearUnknown":false,"summary":"清末撫番政策下的番學堂與萬興關古碑","intro":"位於信義鄉望美村久美部落一帶，社名楠仔腳蔓（Namakaban）出自鄒族語「肥沃平原」。1887年，劉銘傳推動「開山撫番」，雲林撫墾局委員陳世烈在社外仿書院規模設立番學堂，招收原住民孩童二十餘名，教授漢文與三字經，並在入口立「萬興關」石碑。對清廷而言，這是推行漢化的教化措施；但教學不顧孩童的語言與文化，還有呵責體罰，孩童紛紛逃避，不到一年學堂就荒廢。石碑一度失落，1926年日本警察草野豐吉發現，經森丑之助鑑定才確認這段歷史，成為原住民教育史的佐證。今址有1981年所立紀念碑與五角亭，嵌有原碑。1988年公告為古蹟。","highlights":["嵌著光緒13年原碑的「萬興關」紀念碑","1981年所立碑記略與五角亭","清代撫番與原住民教育的歷史脈絡"],"funFact":"學堂荒廢後古碑一度失落，1926年才被日本警察偶然發現，經森丑之助鑑定才解開身世。","photoSpot":"在五角亭旁拍嵌著原碑的紀念碑","visitMin":15,"openNote":"官方資料標示24小時開放，位於信義鄉望美村久美部落一帶，進入部落請尊重族人，拍照前先徵得同意。山區道路颱風、豪雨後常有坍方管制，出發前查詢公路局最新路況。","dialogue":[{"who":"R","text":"Allan，這裡只有一座小亭子和石碑，以前真的是學校嗎？"},{"who":"A","text":"是清代的番學堂。1887年雲林撫墾局委員陳世烈在這裡設學，入口還立了萬興關石碑。"},{"who":"R","text":"清朝在深山開學校，是真心想讓孩子讀書嗎？"},{"who":"A","text":"背後是劉銘傳開山撫番的政策，想用漢文和三字經讓族人漢化，教化也是治理的一部分。"},{"who":"R","text":"那時候的孩子們，喜歡去上學嗎？"},{"who":"A","text":"不太喜歡。老師不懂孩子的語言文化，還會呵責體罰，孩子一被拉來就逃，不到一年學堂就荒廢了。"},{"who":"R","text":"換作是我也會逃，這根本是恐怖補習班！"},{"who":"A","text":"所以要兩面看：對官方是把教育推向山區，對族人卻是被迫改變文化。古碑後來失落，1926年才被找回。"},{"who":"A","text":"原碑就嵌在紀念碑上，請找找碑上陳世烈的名字，再想想當年那些孩子的心情。"}],"clues":["我在清光緒年間由撫墾局設立，招收原住民孩童","我門口的古碑刻著萬興關三個大字","我是信義鄉久美部落一帶的清代番學堂遺址"],"quiz":[{"q":"學堂入口石碑上刻的是哪三個字？","options":["開山路","萬年亨","萬興關","文開堂"],"answer":2,"explain":"陳世烈在學堂入口立碑，題「萬興關」三字。"},{"q":"學堂為什麼不到一年就荒廢？","options":["教法不當又體罰，孩童紛紛逃避","遭颱風沖毀無法上課","經費被撫墾局挪用","改設為日本公學校"],"answer":0,"explain":"教學不因材施教且體罰，孩童避學，未及週年荒廢。"}],"images":[]},{"id":"guoxing-xiangbeigangxishi","name":"國姓鄉北港溪石橋(糯米橋)","short":"北港溪糯米橋","category":"縣定古蹟","level":"縣(市)定古蹟","town":"國姓鄉","types":["橋樑"],"lat":24.058474,"lng":120.90646,"address":"南投縣國姓鄉北港村第10鄰","announced":"1994-08-18","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19940818000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-11-20/6bf34ecf-8daf-43ea-8e1d-0cfb78d11efa/國姓鄉北港溪石橋(糯米橋).jpg","year":1940,"yearText":"1940年動工、1941年完工（日治昭和15至16年）","era":"japan","themes":["公共建築","軍事遺構"],"yearUnknown":false,"summary":"用糯米、紅糖和石灰黏合的四孔石拱橋","intro":"位於國姓鄉北港村，橫跨北港溪。這裡原本只有簡陋木橋，大水時常淹過橋面。日治時期為縮短東勢與埔里兩地軍用機場間的運補，興建這座戰備石橋，由臺中州的日本商社承造，石拱部分轉包給在地人施工；石料取自北港村西南郊山區，人工鑿好、編號，再用牛車運到現場組合，幾乎全村居民都應徵參與。1940年枯水期動工，隔年完工，成為埔里通往臺中新社一帶的捷徑。1987年臺21線拓寬及下游新橋完成後功成身退。以石灰、糯米、紅糖為黏結材的四孔拱橋在臺灣極少見，1994年指定為三級古蹟，今為縣定古蹟，近年多次復建並穩固河床。","highlights":["四孔石拱的優美造型","糯米、紅糖、石灰調成的傳統黏結材","人工鑿製、編號組砌的在地石材"],"funFact":"造橋的石塊先在山上鑿好、編號，再由牛車一塊塊運到溪邊組合。","photoSpot":"在溪岸拍四孔石拱與溪水","visitMin":20,"openNote":"官方資料標示24小時開放，位於國姓鄉北港村北港溪上，鄉公所管理。溪水暴漲時請勿下溪。山區道路颱風、豪雨後常有坍方管制，出發前查詢公路局最新路況。","dialogue":[{"who":"A","text":"阿拉蕾，如果我說有一座橋是用糯米蓋的，你相信嗎？"},{"who":"R","text":"糯米？那下雨的時候，會不會變成一條超長的米糕？"},{"who":"A","text":"哈，不會啦！糯米是和紅糖、石灰調在一起當黏著劑，把石塊黏得牢牢的。"},{"who":"R","text":"原來是古早味的水泥！那這座橋是誰蓋的？"},{"who":"A","text":"日治時期為了東勢和埔里兩座軍用機場之間的運補，1940年動工，隔年完工。"},{"who":"R","text":"那這些石頭是從哪裡搬來的？總不會是從溪裡隨便撿的吧？"},{"who":"A","text":"從村子附近山區人工鑿好、編上號碼，再用牛車一塊一塊運來，幾乎全村的人都來幫忙。"},{"who":"R","text":"先編號再組裝，根本是超大型的樂高積木。"},{"who":"A","text":"它1987年才功成身退。到了溪邊，請數一數橋有幾個拱孔，再找找石塊上有沒有留下鑿痕。"}],"clues":["我是戰備工程，為了兩座軍用機場間的運補而建","我的石塊先編號，再用牛車運到溪邊組合","我是國姓鄉用米食當黏著劑的四孔石拱橋"],"quiz":[{"q":"這座石橋用哪些材料當作黏結材？","options":["水泥、鋼筋、砂石","黏土、稻草、牛糞","瀝青、碎石、樹脂","糯米、紅糖、石灰"],"answer":3,"explain":"以石灰、糯米、紅糖等傳統材料黏結石塊。"},{"q":"北港溪糯米橋共有幾個拱孔？","options":["2個","4個","3個","6個"],"answer":1,"explain":"這是一座以傳統方式建成的四孔型石橋。"}],"images":[{"file":"Old Beigang River Bridge.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/Old_Beigang_River_Bridge.jpg/960px-Old_Beigang_River_Bridge.jpg","page":"https://commons.wikimedia.org/wiki/File:Old_Beigang_River_Bridge.jpg","artist":"Yoxem (talk)","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","local":"img/guoxing-xiangbeigangxishi-0.webp","small":"img/guoxing-xiangbeigangxishi-0-s.webp"}]},{"id":"nantou-taiwanshengzhengfu","name":"臺灣省政府","short":"臺灣省政府","category":"縣定古蹟","level":"縣(市)定古蹟","town":"南投市","types":["衙署"],"lat":23.958323,"lng":120.687279,"address":"南投縣南投市中興新村省府路1號","announced":"2011-04-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20110513000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-11/7fabe3f0-9048-4a85-9cd4-9301ac9567c5/臺灣省政府.jpg","year":1957,"yearText":"1957年（民國46年）","era":"postwar","themes":["省府中興新村","公共建築"],"yearUnknown":false,"summary":"中興新村花園城市的第1號辦公廳","intro":"臺灣省政府大樓位於南投市中興新村省府路1號。1950年代因疏遷政策，政府在原稱「營盤口」的地方規劃中興新村，參考英國新市鎮、花園城市理念，辦公與住宅合一，街道多採囊底路設計。1957年省政府遷駐，大樓是第一期第1號辦公廳，為類國際式樣的現代建築，正面三層、左右兩層，呈ㄇ字形對稱，外牆洗石子。1998年起推動精省，省府組織逐步精簡，2018年業務與人員移交國家發展委員會。大樓2011年公告為縣定古蹟，2021年進行耐震補強。","highlights":["ㄇ字形左右對稱的白色立面","正前方三角形草皮公園與銅像","後方林木茂盛的梅園"],"funFact":"中興新村舊名「營盤口」，因清代這裡有駐軍營地而得名，後來才改名中興新村。","photoSpot":"從正前方三角草皮公園拍大樓全景","visitMin":30,"openNote":"位於南投市中興新村省府路，目前為機關辦公使用，請在外觀參觀，開放情形以國家發展委員會等管理機關公告為準。可從南投市區或臺中搭客運到中興新村。","dialogue":[{"who":"R","text":"Allan，這棟白色大樓看起來好端正，一點都不花俏。"},{"who":"A","text":"四平八穩，正是它的風格。這是臺灣省政府大樓，1957年省府遷到中興新村的第1號辦公廳。"},{"who":"R","text":"為什麼省政府要從臺北搬到南投？"},{"who":"A","text":"1950年代的疏遷政策，把機關分散到中部。這裡原本叫營盤口，後來規劃成中興新村。"},{"who":"R","text":"那中興新村怎麼看起來像一座大公園？"},{"who":"A","text":"它參考英國新市鎮的花園城市理念，辦公住宅合一，綠地很多，巷子多是囊底路。"},{"who":"R","text":"囊底路是什麼？聽起來像口袋，難道是放東西的地方？"},{"who":"A","text":"就是死巷，車子少，鄰居容易認識。不過在這裡迷路，繞一圈還是回到原點。"},{"who":"R","text":"那我到現場，要站在前面的三角形草皮，數數看大樓正面有幾層！"}],"clues":["我是中興新村的第1號辦公廳，正面三層、左右兩層","我的正前方有三角形草皮公園，後方有梅園","我在南投市省府路1號，1957年迎來省府遷駐"],"quiz":[{"q":"中興新村在規劃前原本叫什麼地名？","options":["營盤口","草鞋墩","林圮埔","番仔田"],"answer":0,"explain":"當地原稱營盤口，得名自清代駐軍營地。"},{"q":"中興新村的規劃參考了哪一種理念？","options":["日式町屋街區","英國新市鎮花園城市","美國摩天樓都市","中國傳統城池"],"answer":1,"explain":"參考英國新市鎮、花園城市理念，辦公住宅合一。"}],"images":[{"file":"臺灣省政府大樓.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f1/%E8%87%BA%E7%81%A3%E7%9C%81%E6%94%BF%E5%BA%9C%E5%A4%A7%E6%A8%93.jpg/960px-%E8%87%BA%E7%81%A3%E7%9C%81%E6%94%BF%E5%BA%9C%E5%A4%A7%E6%A8%93.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%87%BA%E7%81%A3%E7%9C%81%E6%94%BF%E5%BA%9C%E5%A4%A7%E6%A8%93.jpg","artist":"Fcuk1203","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/nantou-taiwanshengzhengfu-0.webp","small":"img/nantou-taiwanshengzhengfu-0-s.webp"}]},{"id":"caotun-shougongyepinchen","name":"原手工業品陳列館","short":"手工業品陳列館","category":"縣定古蹟","level":"縣(市)定古蹟","town":"草屯鎮","types":["其他設施"],"lat":23.980042,"lng":120.69217,"address":"南投縣草屯鎮中正路573號","announced":"2022-02-09","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20220223000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-12-07/7b8a1de3-7a4e-4de6-b288-e7e413b1b9fe/原手工業品陳列館(北向外觀照).jpg","year":1977,"yearText":"1977年（民國66年）啟用","era":"postwar","themes":["產業遺產","公共建築","震災重建"],"yearUnknown":false,"summary":"楊英風與貝聿銘團隊合作的白色工藝殿堂","intro":"原手工業品陳列館位於草屯鎮中正路，今國立臺灣工藝研究發展中心園區內。1970年代臺灣省政府推動「客廳即工場」等政策，成立臺灣省手工業研究所，聘雕塑家楊英風擔任總設計師，再邀貝聿銘建築團隊的彭蔭宣、程儀賢兩位建築師共同設計，1974年動工，1977年6月啟用，是當時國內唯一對公眾開放的大型全國工藝品展場。建築以「雙十」與經緯交織為圖案，下窄上大、逐層外擴，是國內最早運用格子梁結構的大型公共建築之一，經歷921大地震仍完好，2022年公告為縣定古蹟。","highlights":["正面「雙十」圖案，象徵經緯編織","下窄上大、逐層外擴的白色量體","中央挑空環形展場與格子梁天花"],"funFact":"這是雕塑家楊英風唯一的建築規劃設計案例；頭重腳輕的造型，靠電腦模擬地震驗算，921時安然無恙。","photoSpot":"站在前方大草坪，拍白色館體與草地","visitMin":60,"openNote":"位於草屯鎮中正路國立臺灣工藝研究發展中心園區內，依官方資料09:00至17:00開放，週一休館，遇假日照常開放，園區免費參觀，工藝體驗另收費，10人以上團體請提前預約。可從高鐵臺中站或臺中市區搭客運到草屯。","dialogue":[{"who":"R","text":"Allan，這棟白色大樓上面寬下面窄，看起來好像隨時會往前倒耶！"},{"who":"A","text":"放心，它站得比我還穩。這是1977年啟用的手工業品陳列館，921大地震都沒事。"},{"who":"R","text":"那是誰設計的？造型這麼大膽，一般建築師應該不敢這樣蓋吧。"},{"who":"A","text":"雕塑家楊英風當總設計師，再找貝聿銘團隊的兩位建築師一起完成，算是夢幻組合。"},{"who":"R","text":"正面那些格子是裝飾嗎？看起來像在織布。"},{"who":"A","text":"答對一半！那是「雙十」圖案，代表經緯交織，裡面還用了當時很新的格子梁結構。"},{"who":"R","text":"當年為什麼要蓋這麼大的工藝展館？"},{"who":"A","text":"那時政府推「客廳即工場」，家家戶戶做手工藝外銷，這裡就是全國的工藝櫥窗。"},{"who":"R","text":"那我們到現場，先站在大草坪上，數數看正面有幾個雙十格子吧！"}],"clues":["我是雕塑家楊英風唯一的建築設計作品","我的造型下窄上大，正面滿是雙十格紋","我在草屯中正路的工藝中心園區裡，前面有大草坪"],"quiz":[{"q":"陳列館正面的格子圖案以什麼為主題？","options":["雙十與經緯交織","梅花與竹節","八卦與太極","稻穗與齒輪"],"answer":0,"explain":"正面以「雙十」為圖案，表現經緯交織的編織意象。"},{"q":"擔任這座陳列館總設計師的是哪一位藝術家？","options":["朱銘","楊英風","李梅樹","顏水龍"],"answer":1,"explain":"臺灣省手工業研究所聘請雕塑家楊英風擔任總設計師。"}],"images":[]},{"id":"zhushan-ganquanjingjishi","name":"甘泉井及石頭公","short":"甘泉井","category":"歷史建築","level":"","town":"竹山鎮","types":["其他設施"],"lat":23.805437,"lng":120.72737,"address":"南投縣竹山鎮山崇里第二鄰頂溝巷38-39號對面","announced":"2004-12-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20060623000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-08-30/0d3bc2a3-3181-47d4-a166-724ff173d549/甘泉井及石頭公.jpg","year":1788,"yearText":"約1788年（乾隆末年，推測）","era":"qing","themes":["清代開山","宗教信仰"],"yearUnknown":false,"summary":"吳光亮開路時飲後命名的清代古井","intro":"甘泉井及石頭公位於竹山鎮山崇里頂溝巷旁，社寮頂埔（後溝坑）一帶。依《雲林縣采訪冊》記載推測，此井可能是乾隆末年福康安圍剿林爽文時，在駐兵大營旁開鑿供汲水之用。1875年總兵吳光亮開闢八通關中路時經過此地，飲用井水覺得甘甜，便以「甘泉」為井命名，並召集工匠以石環砌井壁。井水終年不涸、水質清澈，曾是當地重要水源，今加上半圓形水泥蓋，附近居民仍抽取灌溉。井旁石砌的土地公「石頭公」年代不可考，推測與井年代相當。921大地震後井一度沒入荒草，經地主同意由社寮義工整理保存。","highlights":["以石環砌的古井井壁","造型如神像的石頭公","與八通關中路開路故事相連的井名"],"funFact":"井名「甘泉」是吳光亮1875年開八通關中路經過時，喝了覺得甘甜才取的。","photoSpot":"拍古井與一旁石頭公同框","visitMin":15,"openNote":"位於竹山鎮山崇里頂溝巷旁的山坡下，戶外可參觀，官方資料記載8:00至17:00。位在馬路邊，請注意來車；井水仍供居民灌溉，請勿丟入雜物。","dialogue":[{"who":"R","text":"Allan，這口井看起來小小的，為什麼也是文化資產？"},{"who":"A","text":"別小看它！依記載推測，它可能是乾隆末年福康安的軍隊駐紮時挖的，到現在還有水。"},{"who":"R","text":"兩百多年還沒乾，這口井的體力也太好了。"},{"who":"A","text":"而且1875年吳光亮開八通關中路經過這裡，喝了一口覺得好甜，就取名甘泉井。"},{"who":"R","text":"原來是用喝的評分，吳總兵根本是第一代美食評論家吧！"},{"who":"A","text":"哈哈，他還找工匠用石頭把井壁砌起來。旁邊那尊石頭公，就是守護這口井的土地公。"},{"who":"R","text":"喝水不忘挖井人，還要謝謝土地公。"},{"who":"A","text":"921大地震後井一度淹沒在荒草裡，是社寮的義工整理好，我們今天才看得到。"},{"who":"R","text":"我的任務是仔細看看石頭公，猜猜它的造型像不像一尊神像！"}],"clues":["一位清代總兵喝了我的水，覺得很甜","我身旁有一尊石頭砌的土地公陪伴","我是社寮頂埔一口以甘甜為名的古井"],"quiz":[{"q":"這口古井的名字是誰取的？","options":["吳光亮","福康安","林爽文","沈葆楨"],"answer":0,"explain":"1875年吳光亮開路經過，飲而甘之，以甘泉為名。"},{"q":"井旁的石頭公是什麼神明？","options":["土地公","媽祖","文昌帝君","關聖帝君"],"answer":0,"explain":"石頭公是井旁石砌的土地公。"}],"images":[{"file":"福泉宮與甘泉井.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/%E7%A6%8F%E6%B3%89%E5%AE%AE%E8%88%87%E7%94%98%E6%B3%89%E4%BA%95.jpg/960px-%E7%A6%8F%E6%B3%89%E5%AE%AE%E8%88%87%E7%94%98%E6%B3%89%E4%BA%95.jpg","page":"https://commons.wikimedia.org/wiki/File:%E7%A6%8F%E6%B3%89%E5%AE%AE%E8%88%87%E7%94%98%E6%B3%89%E4%BA%95.jpg","artist":"Outlookxp","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","local":"img/zhushan-ganquanjingjishi-0.webp","small":"img/zhushan-ganquanjingjishi-0-s.webp"}]},{"id":"jiji-linweichenzhaiyong","name":"集集林尾陳宅永福堂","short":"永福堂","category":"歷史建築","level":"","town":"集集鎮","types":["宅第"],"lat":23.823609,"lng":120.770137,"address":"南投縣集集鎮集集鎮林尾路566號","announced":"2004-12-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20041221000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-11/a5eb7db3-e511-4184-b9ea-6af12d798b49/集集林尾陳宅永福堂.jpg","year":1840,"yearText":"1840年（道光20年）","era":"qing","themes":["宅第家族"],"yearUnknown":false,"summary":"集集現存最古老的閩南式三合院民宅","intro":"集集林尾陳宅永福堂位於集集鎮林尾里，古稱「林仔尾陳宅」。陳氏祖先在清乾隆年間從福建漳州府海澄縣渡海來臺，在此定居開墾；永福堂由第14世陳朝聘與其子陳仲璉於1840年興建，是閩南式三合院木構建築，也是集集鎮目前歷史最悠久的民宅。正身為木構造，金形瓜筒、步口通、吊筒、員光與壁堵上都有精美彩繪，堂號下方雕有作工細膩的「金玉滿堂」。屋頂今已改以紅色隔熱浪板覆蓋。2004年登錄為歷史建築。","highlights":["瓜筒、步口通、吊筒等木構件上的彩繪","堂號下方的「金玉滿堂」雕刻","集集現存最老民宅的三合院格局"],"funFact":"屋頂雖然換成了紅色隔熱浪板，屋內木構件仍保留精美的彩繪。","photoSpot":"在巷口遠拍三合院外觀","visitMin":15,"openNote":"位於集集鎮林尾里，私人宅第，請在外觀參觀，勿擅自進入；如需參觀，請事先向南投縣政府文化局洽詢預約。","dialogue":[{"who":"A","text":"走到集集林尾里，我們來拜訪集集鎮目前最老的民宅，永福堂。"},{"who":"R","text":"最老是多老？比集集火車站還老嗎？"},{"who":"A","text":"老多了！1840年就蓋好了，是陳家第14世陳朝聘和兒子陳仲璉興建的。"},{"who":"R","text":"1840年，那時候連火車都還沒來，大家都走路吧。"},{"who":"A","text":"對啊！陳家祖先在乾隆年間從福建漳州海澄渡海來臺，就在這裡開墾定居。"},{"who":"R","text":"那這間老屋子裡藏了什麼寶貝呢？我好好奇。"},{"who":"A","text":"木構件上有很多彩繪，堂號下方還雕了金玉滿堂，看了會覺得錢包都變胖了。"},{"who":"R","text":"可是這是陳家的私人住宅，我們不能隨便走進去吧？"},{"who":"A","text":"沒錯，這裡是私人宅第，要預約才行。在外面請先找找看，屋頂是不是換成了紅色的隔熱浪板。"}],"clues":["我的堂號下方雕著四個吉祥字","我古稱林仔尾陳宅，是陳家第14世建的","我是集集鎮目前歷史最悠久的民宅"],"quiz":[{"q":"永福堂建於哪一年？","options":["1768年","1840年","1885年","1918年"],"answer":1,"explain":"1840年由陳朝聘與其子陳仲璉興建。"},{"q":"永福堂堂號下方雕有哪四個字？","options":["金玉滿堂","福壽雙全","五穀豐登","文風鼎盛"],"answer":0,"explain":"堂號下方雕有細膩的金玉滿堂。"}],"images":[{"file":"集集林尾陳宅永福堂.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/%E9%9B%86%E9%9B%86%E6%9E%97%E5%B0%BE%E9%99%B3%E5%AE%85%E6%B0%B8%E7%A6%8F%E5%A0%82.JPG/960px-%E9%9B%86%E9%9B%86%E6%9E%97%E5%B0%BE%E9%99%B3%E5%AE%85%E6%B0%B8%E7%A6%8F%E5%A0%82.JPG","page":"https://commons.wikimedia.org/wiki/File:%E9%9B%86%E9%9B%86%E6%9E%97%E5%B0%BE%E9%99%B3%E5%AE%85%E6%B0%B8%E7%A6%8F%E5%A0%82.JPG","artist":"SSR2000","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/jiji-linweichenzhaiyong-0.webp","small":"img/jiji-linweichenzhaiyong-0-s.webp"}]},{"id":"nantou-jisigongyezhang","name":"祭祀公業張琯溪公宗祠","short":"張琯溪公宗祠","category":"歷史建築","level":"","town":"南投市","types":["祠堂"],"lat":23.91396,"lng":120.688108,"address":"南投縣南投市平和里南陽路196 巷20 號","announced":"2002-01-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020129000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-09-19/8c078b02-1349-4443-aac9-36132e9ad0aa/祭祀公業張琯溪公宗祠.jpg","year":1849,"yearText":"1849年（清道光29年）創建，1912年遷建現址","era":"qing","themes":["宗祠公廳"],"yearUnknown":false,"summary":"山牆刻著「琯」「溪」二字的張氏宗祠","intro":"祭祀公業張琯溪公宗祠位於南投市平和里。南投市張姓有琯溪、南坑、大宗三大派下，琯溪派來自福建漳州府平和縣琯溪；大宗派因未建宗祠，張良公神位暫祀於此。宗祠創建於1849年，1880年重修，1897至1899年間曾被日軍徵用為南投陸軍分遣隊兵舍。1911年遭颱風吹毀，族人協議由祭祀公業出資，遷建於昔日的包尾庄現址，1912年竣工。宗祠為兩進一護龍的合院格局，大木構件間距富韻律感，護龍山牆以洗石子幾何裝飾，並飾有「琯」「溪」二字。","highlights":["護龍山牆上的「琯」「溪」二字","洗石子幾何裝飾的山牆","三通五瓜的穿斗木構架"],"funFact":"1897至1899年間，這座宗祠曾被日軍徵用，當作南投陸軍分遣隊的兵舍。","photoSpot":"在祠前拍護龍山牆上的琯溪二字","visitMin":15,"openNote":"位於南投市平和里的宗祠，依官方資料08:00至17:00開放，開放情形以祭祀公業管理委員會為準；請尊重宗族祭祀空間，保持安靜。","dialogue":[{"who":"R","text":"Allan，宗祠山牆上寫著「琯」和「溪」，這是什麼意思？"},{"who":"A","text":"琯溪是福建平和縣的地名，也是這支張姓族人的祖籍。把老家名字寫在牆上，誰都忘不了。"},{"who":"R","text":"好像我把家裡地址繡在書包上。那這座宗祠蓋多久了？"},{"who":"A","text":"1849年創建，日治初期還被日軍徵用當兵舍，住進一群阿兵哥。"},{"who":"R","text":"祖先們應該很錯愕吧！那後來呢？"},{"who":"A","text":"1911年被颱風吹毀，族人出錢搬到現址重建，1912年完工，就是今天看到的樣子。"},{"who":"R","text":"所以它同時有清代的身世和日治的外表？"},{"who":"A","text":"對，格局是傳統合院，護龍山牆卻有日治流行的洗石子幾何裝飾，混搭得很有味道。"},{"who":"R","text":"到現場我要找出左右護龍上的琯和溪，兩個字都拍下來！"}],"clues":["我的護龍山牆上分別有琯和溪兩個字","日治初期我曾被日軍徵用當兵舍","我是南投市張姓族人的宗祠，1912年遷建現址"],"quiz":[{"q":"琯溪派張姓族人的祖籍在哪裡？","options":["泉州府安溪縣","汀州府永定縣","漳州府平和縣","潮州府饒平縣"],"answer":2,"explain":"琯溪派下來自福建省漳州府平和縣琯溪。"},{"q":"宗祠在1911年為什麼要遷建？","options":["地震倒塌","日軍強制拆除","道路拓寬","遭颱風吹毀"],"answer":3,"explain":"1911年遭颱風吹毀，族人協議遷建於現址。"}],"images":[{"file":"南投張琯溪公宗祠.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/%E5%8D%97%E6%8A%95%E5%BC%B5%E7%90%AF%E6%BA%AA%E5%85%AC%E5%AE%97%E7%A5%A0.JPG/960px-%E5%8D%97%E6%8A%95%E5%BC%B5%E7%90%AF%E6%BA%AA%E5%85%AC%E5%AE%97%E7%A5%A0.JPG","page":"https://commons.wikimedia.org/wiki/File:%E5%8D%97%E6%8A%95%E5%BC%B5%E7%90%AF%E6%BA%AA%E5%85%AC%E5%AE%97%E7%A5%A0.JPG","artist":"Pbdragonwang","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/nantou-jisigongyezhang-0.webp","small":"img/nantou-jisigongyezhang-0-s.webp"}]},{"id":"zhushan-chenjiagucuo","name":"陳家古厝（武秀才陳獻瑞家宅）","short":"陳家古厝","category":"歷史建築","level":"","town":"竹山鎮","types":["宅第"],"lat":23.812852,"lng":120.731969,"address":"南投縣竹山鎮中央里集山路1 段1135 巷42 號","announced":"2002-01-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020129000009","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-05-21/6f37e84f-e9ab-4038-b2c3-16f45870bfcd/陳家古厝(武秀才陳獻瑞家宅).jpg","year":1860,"yearText":"清代，確切年代不詳","era":"qing","themes":["宅第家族"],"yearUnknown":true,"summary":"後埔仔第一位武秀才的五開間三合院","intro":"位於竹山鎮中央里集山路一段旁，與陳善述老宅在同一條巷子。陳家祖先陳寄於乾隆年間來臺，在羌子寮（今富州里）開墾；第三房玄孫陳喦遷居後埔仔（今中央里）建了這座宅第，成為社寮地區的富戶，地方俗諺說「有陳喦富，無陳喦厝；有陳喦厝，無陳喦富」。陳喦之孫陳獻瑞生於1873年，1889年考取彰化縣武秀才，是後埔仔第一位武秀才。宅第為五開間三合院，懸山式屋頂、穿斗式木構，編竹夾泥牆與磚、木混合構造，門樓有磚砌鏤空牆面與雕花石材，是竹山少數完整保存的閩南三合院。近年翻修改用水泥瓦。2002年登錄為歷史建築。","highlights":["門樓的磚砌鏤空牆面與雕花石材","五開間三合院與懸山式屋頂","編竹夾泥牆與磚木混合構造"],"funFact":"地方俗諺「有陳喦富，無陳喦厝；有陳喦厝，無陳喦富」，形容這座宅第的豪華。","photoSpot":"在宅外拍門樓的鏤空磚牆","visitMin":15,"openNote":"私人宅第，位於竹山鎮中央里集山路一段旁，部分空間仍有人使用。官方未載開放資訊，請在外觀參觀，勿擅自進入。","dialogue":[{"who":"R","text":"Allan，聽說竹山有句俗諺，什麼有錢沒房、有房沒錢的，到底在講誰？"},{"who":"A","text":"講的是清代後埔仔的富戶陳喦，有陳喦富，無陳喦厝，意思是他家房子豪華到別人比不上。"},{"who":"R","text":"這句話好像繞口令，我的舌頭快要打結了。"},{"who":"A","text":"更厲害的是他的孫子陳獻瑞，1889年考上彰化縣武秀才，是後埔仔第一位武秀才。"},{"who":"R","text":"武秀才要考什麼？該不會是比誰的拳頭比較硬吧？"},{"who":"A","text":"要考騎射、拉弓、舉石頭這些武藝，家族到現在還留著他練武用的練武石呢。"},{"who":"R","text":"那這座豪宅三合院，到底長什麼樣子？"},{"who":"A","text":"五開間加左右護龍，懸山式屋頂，門樓有磚砌鏤空牆和雕花石材，是竹山少數完整的閩南三合院。"},{"who":"A","text":"這裡是私人宅第，請在門外欣賞。看看門樓的鏤空磚牆，排出了什麼樣的圖案。"}],"clues":["我的主人家族出了後埔仔第一位武秀才","地方俗諺誇我的豪華，說有錢也蓋不出來","我是竹山中央里有鏤空磚牆門樓的五開間三合院"],"quiz":[{"q":"陳獻瑞在哪一年考取彰化縣武秀才？","options":["1874年","1895年","1889年","1901年"],"answer":2,"explain":"陳獻瑞於清光緒15年，即1889年考取武秀才。"},{"q":"陳家古厝屬於哪一種建築格局？","options":["五開間三合院","二進四合院","單伸手街屋","二層洋樓"],"answer":0,"explain":"為五開間三合院，含正身及左右護龍。"}],"images":[]},{"id":"nantou-qigancuo","name":"旗杆厝","short":"旗杆厝","category":"歷史建築","level":"","town":"南投市","types":["其他設施"],"lat":23.910554,"lng":120.685724,"address":"南投縣南投市復興路321 號","announced":"2002-01-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020129000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-11-23/a9faf607-9902-4b2b-aae3-97a02e983699/旗杆厝.jpg","year":1871,"yearText":"1871年（清同治10年）","era":"qing","themes":["宅第家族"],"yearUnknown":false,"summary":"南投秀才張春華的功名宅第","intro":"旗杆厝位於南投市復興路旁，1871年由張春華創建，原名「選青堂張家祖宅」。張春華於1849年考取彰化縣學歲貢生榜首，當時當地只有張家獲得科舉功名，得以在屋前左右立兩座旗杆掛旗祭祖，成為地標，因而俗稱「旗杆厝」。宅第原為二進雙護龍，因開闢馬路拆除左護龍與左側旗杆座，今存正廳、右護龍、部分門廳與門樓，以及右側旗杆座，座上立有兩塊泉州白花崗石夾杆石。正身為穿斗式木構架，明間保有匠師林江漢的彩繪。","highlights":["右護龍前僅存的旗杆座與夾杆石","正身明間署名林江漢的彩繪","土埆、竹編夾泥牆混合構造"],"funFact":"清代只有考取功名的人家，才能在屋前立旗杆，所以旗杆就是當年的「金榜題名招牌」。","photoSpot":"在路旁拍門樓與右側旗杆座","visitMin":10,"openNote":"位於南投市復興路旁，官方資料標示為居住空間。私人宅第，請在外觀參觀，勿擅自進入。附近可順遊藍田書院、武德殿。","dialogue":[{"who":"A","text":"阿拉蕾，清代有人考上功名，家門口會多出什麼東西？"},{"who":"R","text":"鞭炮和紅布條？還是一堆突然冒出來借錢的親戚？"},{"who":"A","text":"哈哈，親戚可能也有，但最正式的是旗杆。張春華考上歲貢生榜首，家門口就能立旗杆。"},{"who":"R","text":"所以旗杆厝的名字就是這樣來的！好直白的取名法。"},{"who":"A","text":"對，原名選青堂張家祖宅。當時當地只有張家有功名，兩支旗杆一立，大家都認得。"},{"who":"R","text":"那現在門口兩支旗杆座都還在嗎？"},{"who":"A","text":"開路時拆了左護龍和左邊的旗杆座，只剩右邊一座，上面有泉州白花崗石夾杆石。"},{"who":"R","text":"那屋子裡面還有什麼值得看的寶貝？"},{"who":"A","text":"正廳有匠師林江漢的彩繪。不過這裡有人住，在外面找找那座旗杆座和夾杆石，拍張照就好。"}],"clues":["我門前只剩一座夾杆石旗杆座","我原名選青堂，主人是清代歲貢生榜首","我在南投市復興路旁，因旗杆而得名"],"quiz":[{"q":"旗杆厝的創建人是誰？","options":["曾作雲","朱懋","張春華","林江漢"],"answer":2,"explain":"旗杆厝1871年由張春華創建。"},{"q":"旗杆厝目前還保留幾座旗杆座？","options":["0座","1座","2座","4座"],"answer":1,"explain":"左側旗杆座因開路拆除，只剩右側一座。"}],"images":[{"file":"南投旗杆厝.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/39/%E5%8D%97%E6%8A%95%E6%97%97%E6%9D%86%E5%8E%9D.jpg/960px-%E5%8D%97%E6%8A%95%E6%97%97%E6%9D%86%E5%8E%9D.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%8D%97%E6%8A%95%E6%97%97%E6%9D%86%E5%8E%9D.jpg","artist":"Pbdragonwang","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/nantou-qigancuo-0.webp","small":"img/nantou-qigancuo-0-s.webp"}]},{"id":"puli-nancunyiminci","name":"埔里南村義民祠","short":"埔里南村義民祠","category":"歷史建築","level":"","town":"埔里鎮","types":["寺廟"],"lat":23.963823,"lng":120.944578,"address":"南投縣埔里鎮南村里南村路8-1號","announced":"2021-08-04","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20210908000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-08-18/4a4335dc-fb06-4c1f-855d-95a41ba4ca9b/埔里南村義民祠.jpg","year":1879,"yearText":"1879年（清光緒5年）","era":"qing","themes":["宗教信仰"],"yearUnknown":false,"summary":"從新埔褒忠義民廟分香的埔里客家信仰中心","intro":"位於埔里鎮南村里南村路。1879年由客家移民從新竹縣新埔鎮枋寮褒忠義民廟分香建廟，1888年、1930年與2001年曾經重修，但仍維持清代閩式建築風格，正身古色古香，屋架、屋面與柱樑保有傳統工法和材質，具地區特色。廟內供奉「褒忠粵東義民老爺尊神之位」牌位，祭祀清乾隆年間林爽文事件中協助清軍而陣亡的客家先民，是當地居民的信仰中心，也見證客家移民進入埔里盆地的歷史。2021年登錄為歷史建築。","highlights":["清代閩式風格的正身建築","「褒忠粵東義民老爺尊神之位」牌位","保有傳統工法的屋架與柱樑"],"funFact":"廟裡供奉的是一面寫著「褒忠粵東義民老爺尊神之位」的牌位。","photoSpot":"在廟埕拍正身屋架與屋面","visitMin":15,"openNote":"官方資料開放時間為上午8時至下午5時，位於埔里鎮南村里，參拜請保持莊重。可搭客運到埔里再轉乘。","dialogue":[{"who":"A","text":"埔里這座小廟有一個遠房祖廟，在新竹新埔，叫做枋寮褒忠義民廟。"},{"who":"R","text":"從新竹到埔里？那分香的時候，應該走了好遠的山路。"},{"who":"A","text":"是啊，1879年客家移民把義民爺的香火帶到這裡，蓋了這座祠。"},{"who":"R","text":"義民爺是哪一位神明啊？我好像沒聽過。"},{"who":"A","text":"祭祀的是清乾隆年間林爽文事件時，協助清軍作戰而陣亡的客家先民，廟裡供奉的是牌位。"},{"who":"R","text":"原來是紀念先人。那這座廟還是古早的樣子嗎？"},{"who":"A","text":"雖然1888年、1930年和2001年都修過，但仍保持清代閩式風格，屋架和柱樑都是傳統工法。"},{"who":"R","text":"修了三次還保有原味，就像老店換了裝潢，招牌滷汁沒變。"},{"who":"A","text":"參拜時請保持莊重，找找牌位上粵東兩個字，想想這些先民是從哪裡來的。"}],"clues":["我的香火來自新竹新埔枋寮","我祭祀林爽文事件中陣亡的客家先民","我是埔里南村里的清代客家廟宇"],"quiz":[{"q":"這座祠的香火是從哪一座廟分香而來？","options":["鹿港天后宮","北港朝天宮","新埔枋寮褒忠義民廟","竹山連興宮"],"answer":2,"explain":"由客家移民自新埔枋寮褒忠義民廟分香建廟。"},{"q":"埔里南村義民祠創建於哪一年？","options":["1879年","1823年","1895年","1930年"],"answer":0,"explain":"創建於清光緒5年，即1879年。"}],"images":[]},{"id":"mingjian-chenxingzongqinhui","name":"南投縣陳姓宗親會西水祠","short":"陳姓西水祠","category":"歷史建築","level":"","town":"名間鄉","types":["祠堂"],"lat":23.876634,"lng":120.694477,"address":"南投縣名間鄉新街村客庄巷1 號","announced":"2002-01-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020129000007","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-09-15/2cfa337a-6a64-4945-a71b-3627edc6226b/南投縣陳姓宗親會西水祠.jpg","year":1882,"yearText":"1882年（光緒8年）創建，1918年遷建","era":"qing","themes":["宗祠公廳","震災重建"],"yearUnknown":false,"summary":"燕尾翹脊的兩進式陳氏家廟","intro":"南投縣陳姓宗親會西水祠位於名間鄉新街村客庄巷。西水祠創建於1882年，原址在井仔頭（今名間鄉赤水村），1918年由陳芳輝等23人首倡集資，遷建到新街村現址，改稱「陳氏家廟」。建築為兩進式小型祠廟，前殿採凹壽式正面，簷柱以龍柱支撐，兩側牆面有龍虎堵相互輝映，屋頂覆臺灣瓦及筒瓦，採燕尾翹脊兩坡式，閩南風格濃厚。1953年由族人再度重修。1999年921大地震時，廂廊簷柱嚴重傾斜、正身屋架與背牆接合處嚴重裂開，屋頂剪粘與泥塑多處掉落，之後已修復完成。目前仍是家族祭祀場所。","highlights":["前殿凹壽式正面與龍柱","左右對望的龍虎堵","燕尾翹脊的兩坡屋頂"],"funFact":"西水祠原本不在新街村，而是在今赤水村的井仔頭，1918年才由族人集資搬到現址。","photoSpot":"在祠前拍燕尾翹脊的屋頂線條","visitMin":20,"openNote":"位於名間鄉新街村客庄巷，為家族祭祀場所，參觀須事先向南投縣政府文化局洽詢預約，開放時間以管理單位南投縣陳姓宗親會為準；請保持安靜，勿擅自進入。","dialogue":[{"who":"R","text":"Allan，這座建築屋頂兩端翹得好高，好像燕子的尾巴！"},{"who":"A","text":"那就叫燕尾翹脊！這裡是南投縣陳姓宗親會的西水祠，也叫陳氏家廟。"},{"who":"R","text":"它從一開始就住在名間新街村嗎？"},{"who":"A","text":"不是喔，1882年創建時在井仔頭，就是今天的赤水村，1918年才由族人集資搬到這裡。"},{"who":"R","text":"祠堂也會搬家，那時候的搬家工程一定很浩大。"},{"who":"A","text":"是族人出錢出力完成的！前殿是凹壽式，簷下有龍柱撐著，兩側牆面還有龍虎堵。"},{"who":"R","text":"那921大地震時，它有沒有受傷？"},{"who":"A","text":"傷得不輕，簷柱傾斜、屋架裂開，剪粘也掉了不少，後來才修復完成。"},{"who":"R","text":"這裡是家族祭祀的地方，要預約參觀。我的任務是分辨左右兩邊哪一邊是龍、哪一邊是虎！"}],"clues":["我原本住在井仔頭，後來被族人搬到新街村","我前殿的龍柱旁，兩側牆面有龍與虎對望","我是名間鄉一座燕尾翹脊的陳氏家廟"],"quiz":[{"q":"西水祠最早創建時位於哪裡？","options":["井仔頭","竹山社寮","名間濁水","集集林尾"],"answer":0,"explain":"原址在井仔頭，即今名間鄉赤水村。"},{"q":"西水祠屋頂採用哪一種形式？","options":["燕尾翹脊兩坡式","日式黑瓦切妻","鋼浪板平頂","圓形穹頂"],"answer":0,"explain":"屋頂覆臺灣瓦與筒瓦，採燕尾翹脊。"}],"images":[]},{"id":"shuili-linquguanlichushui","name":"南投林區管理處水里工作站所轄木造辦公廳舍","short":"水里林業木造廳舍","category":"歷史建築","level":"","town":"水里鄉","types":["辦公廳舍"],"lat":23.812646,"lng":120.856407,"address":"南投縣水里鄉民生路140巷5號","announced":"2023-03-03","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20230428000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-02-24/c1f17fbf-c959-44ea-a341-2e1279848fcf/南投林區管理處水里工作站所轄木造辦公廳舍.jpg","year":1905,"yearText":"1905年（日治明治38年）","era":"japan","themes":["林業樟腦","日式建築"],"yearUnknown":false,"summary":"見證巒大山伐木歲月的日式木造辦公廳舍","intro":"位於水里鄉民生路巷內的高地上。原為巒大山林場的建物，林場在日治時期先由鹿島組經營，1909年轉由日商櫻井組，伐木範圍在望鄉山、郡坑山一帶。1960年巒大山林場與臺中山林管理所合併為巒大林區管理處，此棟曾是管理處辦公廳，1968年至1993年為水里工作站辦公廳舍，之後供保安警察與林務單位員工使用。建築坐東朝西，雙斜屋頂、西式桁架、雨淋板外牆與編竹夾泥內牆，並利用水里坑高地砌出三層石牆台地與洗石子彎手台階，是水里、丹大、人倫一帶伐木史的見證。2023年登錄為歷史建築。","highlights":["三層台地砌石牆與洗石子彎手台階","雨淋板外牆、山牆博風與簷廊","見證巒大山、丹大林區的伐木歲月"],"funFact":"這棟老辦公室從林場、林區管理處、工作站到警察宿舍，換過好幾任「房客」。","photoSpot":"在台階下仰拍石牆台地與木造廳舍","visitMin":15,"openNote":"官方資料標示修復中，不開放參觀；目前為機關辦公與宿舍使用，請在外觀參觀。位於水里鄉市區，可搭臺鐵集集線到水里站。山區道路颱風、豪雨後常有坍方管制，出發前查詢公路局最新路況。","dialogue":[{"who":"R","text":"Allan，水里街上這棟木頭房子好有氣質，是新開的咖啡廳嗎？"},{"who":"A","text":"可惜不是，它是一百多年前林場的辦公室，後來當過巒大林區管理處和水里工作站的辦公廳。"},{"who":"R","text":"一百多年？那它一定看過很多大樹被運下山，簡直是森林的送行者囉？"},{"who":"A","text":"沒錯，日治時期鹿島組、櫻井組在望鄉山、郡坑山一帶伐木，水里就是林業的重要據點。"},{"who":"R","text":"那房子本身有什麼看頭？總不會只是因為年紀大吧？"},{"who":"A","text":"看它的雨淋板外牆、雙斜屋頂，還有利用高地砌成的三層石牆台地，走近看很有氣勢。"},{"who":"R","text":"三層台地，這到底是辦公室還是城堡啊？"},{"who":"A","text":"算是林業界的小城堡！目前修復中不開放，請在外面找找洗石子彎手台階，由下往上拍一張。"}],"clues":["我曾是巒大山林場和巒大林區管理處的辦公處","我坐在三層砌石牆的高台上，外牆是雨淋板","我是水里林業工作站的木造老辦公室"],"quiz":[{"q":"這棟木造廳舍原本屬於哪一個林場？","options":["八仙山林場","阿里山林場","巒大山林場","太平山林場"],"answer":2,"explain":"原為巒大山林場建物，後為巒大林區管理處。"},{"q":"建築利用水里坑高地砌出了幾層石牆台地？","options":["3層","2層","4層","5層"],"answer":0,"explain":"利用高亢地勢作三層台地砌石牆。"}],"images":[]},{"id":"guoxing-xiangnangangcunlin","name":"國姓鄉南港村–林屋伙房","short":"南港村林屋伙房","category":"歷史建築","level":"","town":"國姓鄉","types":["宅第"],"lat":23.943868,"lng":120.865725,"address":"南投縣國姓鄉國姓鄉南港村16鄰南港路40-1號","announced":"2009-04-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20090423000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-09-02/4e67a07d-0064-4cfe-830a-f3618aa06819/國姓鄉南港村–林屋伙房.jpg","year":1911,"yearText":"1911年林家遷居拓墾（日治明治44年，建築年代未詳）","era":"japan","themes":["宅第家族","宗祠公廳"],"yearUnknown":false,"summary":"國姓保存最完整的客家伙房與養鹿聚落","intro":"位於國姓鄉南港村南港路一帶。1911年，林鼎華與妻子林劉番婆妹帶著兒孫近20人，從新竹北埔南遷到此定居，起初開墾荒地、捕鹿、販賣山產與獸皮，後來改為養鹿、販賣鹿茸，養鹿事業遠近聞名，不少政軍名人曾來訪，伙房內掛滿歷年受贈的匾額。聚落由四座三合院背山一字排開，加上養鹿園區與公共廣場，是相當完整的客家聚落；林屋伙房以土埆、磚與竹建造，是國姓地區保存最完整的客家伙房。早年經永安橋聯外，橋的遺跡仍可見。2009年登錄為歷史建築，至今仍有林家後代居住，左橫屋作為客家文化展示空間。","highlights":["土埆、磚、竹構成的客家瓦房三合院","伙房內歷年受贈的匾額","四座三合院背山一字排開的聚落景觀"],"funFact":"林家從捕鹿起家，後來改養鹿、賣鹿茸，讓南港村的養鹿事業遠近馳名。","photoSpot":"從聚落前拍一字排開的三合院","visitMin":25,"openNote":"私人宅第，林家後代仍居住於國姓鄉南港村南港路一帶。官方資料註明須提前來電預約，請洽南投縣政府文化局；未預約請在外觀參觀，勿擅自進入。山區道路颱風、豪雨後常有坍方管制，出發前查詢公路局最新路況。","dialogue":[{"who":"A","text":"阿拉蕾，猜猜看，國姓這戶客家人家當年是靠什麼起家的？"},{"who":"R","text":"種田？還是上山採竹筍？南投的山裡好像什麼都有。"},{"who":"A","text":"答案是鹿！林家1911年從新竹北埔搬來，一開始捕鹿、賣獸皮，後來改成養鹿賣鹿茸。"},{"who":"R","text":"養鹿？那這裡是鹿界的五星級飯店嗎？"},{"who":"A","text":"可以這麼說，養鹿事業讓林家遠近馳名，伙房裡還掛滿了歷年受贈的匾額。"},{"who":"R","text":"那房子本身有什麼特別的地方？除了鹿以外我都想知道。"},{"who":"A","text":"四座三合院背著山一字排開，用土埆、磚和竹子蓋成，是國姓保存最完整的客家伙房。"},{"who":"R","text":"一字排開，好像一排在山腳下列隊的客家阿伯。"},{"who":"A","text":"這裡還有人住，請在外面參觀。找找已經不用的永安橋遺跡，想像當年怎麼進出聚落。"}],"clues":["我的家族在1911年從新竹北埔南遷而來","我們曾靠捕鹿、養鹿與鹿茸聞名","我是國姓保存最完整的客家伙房"],"quiz":[{"q":"林家祖先是從哪裡南遷到國姓定居？","options":["苗栗銅鑼","桃園龍潭","新竹北埔","屏東內埔"],"answer":2,"explain":"林鼎華夫婦於1911年從新竹北埔南遷到此。"},{"q":"林家後來以什麼事業聞名？","options":["養鹿與販賣鹿茸","燒窯製陶","種茶製茶","伐木製材"],"answer":0,"explain":"由捕鹿改為養鹿、販賣鹿茸，聞名遐邇。"}],"images":[]},{"id":"puli-guolizhongxingda","name":"國立中興大學實驗林管理處埔里連絡站(原北海道帝國大學農學部附屬台灣演習林辦公室)","short":"埔里演習林辦公室","category":"歷史建築","level":"","town":"埔里鎮","types":["其他設施"],"lat":23.958271,"lng":120.968026,"address":"南投縣埔里鎮埔里鎮隆生路86 號","announced":"2011-04-15","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20110415000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-09-13/f249ef7e-cf0d-47a0-91f8-f4fe90f6673a/國立中興大學實驗林管理處埔里連絡站(原北海道帝國大學農學部附屬台灣演習林辦公室).jpg","year":1917,"yearText":"1917年（日治大正6年，另有1918年之說）","era":"japan","themes":["日式建築","林業樟腦","教育設施"],"yearUnknown":false,"summary":"屋頂鋪北海道金屬菱形瓦的日式木造辦公室","intro":"位於埔里鎮隆生路，今為國立中興大學實驗林管理處埔里連絡站。1916年北海道帝國大學農學部在今仁愛鄉惠蓀林場一帶設立附屬臺灣演習林，作為師生實習場所；1917年在埔里設演習林派出所，並興建這棟辦公廳舍（另有資料記為1918年）。日式木造，屋頂用北海道金屬菱形瓦，與常見的黑瓦截然不同，入口有車寄，牆面為雨淋板、內牆為編竹夾泥。戰後改隸林務局，1949年撥交省立農林學院，1950年在此設實驗林管理處，1954年遷往臺中後改為植物標本園。921大地震時主結構傾斜、局部毀壞，已修復。2011年登錄為歷史建築。","highlights":["北海道金屬菱形瓦屋頂","入口的車寄構造","周邊的植物標本園"],"funFact":"屋頂不是常見的日式黑瓦，而是北海道金屬菱形瓦，正好呼應它北海道帝大的出身。","photoSpot":"在車寄前拍菱形瓦屋頂","visitMin":20,"openNote":"官方資料開放時間為上午8:00至下午5:00；建物目前閒置，由中興大學實驗林管理處管理，可否入內以現場公告為準。位於埔里鎮隆生路，可搭客運到埔里。","dialogue":[{"who":"R","text":"Allan，這棟木造房子的屋頂亮亮的，跟一般日式房子的黑瓦不一樣耶！"},{"who":"A","text":"好眼力！那是北海道金屬菱形瓦，因為它當年的主人是北海道帝國大學。"},{"who":"R","text":"北海道的大學跑到埔里做什麼？難道是來找熊？"},{"who":"A","text":"是來做森林實習啦。1916年他們在今天惠蓀林場一帶設演習林，隔年在埔里設辦公處。"},{"who":"R","text":"原來是大學生森林教室的總部，上課地點是整座山，太羨慕了。"},{"who":"A","text":"戰後交給省立農林學院，也就是中興大學的前身，1954年處本部遷走後變成植物標本園。"},{"who":"R","text":"木造老房子最怕地震，那921大地震的時候，它還好嗎？"},{"who":"A","text":"主結構傾斜、局部毀壞，後來修好了。去的時候找找入口的車寄，再抬頭數數菱形瓦的排列。"}],"clues":["我的屋頂鋪著北國風格的金屬菱形瓦","我原是一所日本帝國大學臺灣演習林的辦公處","我在埔里，今天屬於中興大學實驗林"],"quiz":[{"q":"這棟辦公室的屋頂用的是哪一種瓦？","options":["日式黑色水泥瓦","閩南紅色板瓦","原住民石板瓦","北海道金屬菱形瓦"],"answer":3,"explain":"屋簷使用北海道金屬菱形瓦，與日式黑瓦不同。"},{"q":"北海道帝大的臺灣演習林設在今天哪裡一帶？","options":["溪頭","惠蓀林場","阿里山","太平山"],"answer":1,"explain":"1916年設於今仁愛鄉惠蓀林場一帶。"}],"images":[{"file":"原北海道帝國大學農學部附屬台灣演習林辦公室.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/%E5%8E%9F%E5%8C%97%E6%B5%B7%E9%81%93%E5%B8%9D%E5%9C%8B%E5%A4%A7%E5%AD%B8%E8%BE%B2%E5%AD%B8%E9%83%A8%E9%99%84%E5%B1%AC%E5%8F%B0%E7%81%A3%E6%BC%94%E7%BF%92%E6%9E%97%E8%BE%A6%E5%85%AC%E5%AE%A4.JPG/960px-%E5%8E%9F%E5%8C%97%E6%B5%B7%E9%81%93%E5%B8%9D%E5%9C%8B%E5%A4%A7%E5%AD%B8%E8%BE%B2%E5%AD%B8%E9%83%A8%E9%99%84%E5%B1%AC%E5%8F%B0%E7%81%A3%E6%BC%94%E7%BF%92%E6%9E%97%E8%BE%A6%E5%85%AC%E5%AE%A4.JPG","page":"https://commons.wikimedia.org/wiki/File:%E5%8E%9F%E5%8C%97%E6%B5%B7%E9%81%93%E5%B8%9D%E5%9C%8B%E5%A4%A7%E5%AD%B8%E8%BE%B2%E5%AD%B8%E9%83%A8%E9%99%84%E5%B1%AC%E5%8F%B0%E7%81%A3%E6%BC%94%E7%BF%92%E6%9E%97%E8%BE%A6%E5%85%AC%E5%AE%A4.JPG","artist":"Fcuk1203","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/puli-guolizhongxingda-0.webp","small":"img/puli-guolizhongxingda-0-s.webp"}]},{"id":"puli-huangzhai","name":"埔里黃宅","short":"埔里黃宅","category":"歷史建築","level":"","town":"埔里鎮","types":["宅第"],"lat":23.976554,"lng":120.938722,"address":"南投縣埔里鎮鐵山里鐵山路1 巷5 號","announced":"2002-08-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020801000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-12-16/646fe9a2-46ee-43e8-af4a-f76b37ea219a/埔里黃宅(整體建築正面外觀) jpg.jpg","year":1918,"yearText":"1918年重建（日治大正7年）；原宅建於清光緒年間","era":"japan","themes":["宅第家族","震災重建"],"yearUnknown":false,"summary":"三度與地震交手的埔里閩式莊園三合院","intro":"位於埔里鎮鐵山里鐵山路一帶。原宅建於清光緒年間，官方說明記載由清代總兵吳光亮堪輿後興建。1917年埔里大地震震塌原宅，次年入贅的女婿黃敦仁以原址為正身，聘請石岡匠師劉然等人建成閩式三合院。正身七開間，木料就地取材，磚瓦由草屯以板車或挑夫運入；彩繪、雕刻與泥塑結合閩式、日式與原住民圖案。1935年新竹臺中大地震後，在正身後方增建木構防震屋。1999年921大地震時正身傾斜、護龍與門樓坍塌，家族依傳統格局修護正身、門樓與內牆，護龍則調整重建，分三期歷時五年完成。2002年登錄為歷史建築。","highlights":["結合閩式、日式與原住民圖案的彩繪雕塑","七開間的正身","門樓兩旁土角牆加台灣瓦的圍牆"],"funFact":"這座宅第歷經1917年、1935年與1999年三次大地震，每次都修復重生。","photoSpot":"在宅外拍門樓與土角圍牆","visitMin":15,"openNote":"私人宅第，位於埔里鎮鐵山里鐵山路一帶。官方資料註明須提前來電預約，請洽南投縣政府文化局；未預約請在外觀參觀，勿擅自進入。","dialogue":[{"who":"R","text":"Allan，聽說這棟三合院的故事，跟地震特別有緣？"},{"who":"A","text":"緣分深到不行！1917年埔里大地震把原宅震塌，隔年才重建成現在的閩式三合院。"},{"who":"R","text":"震一次就很慘了，該不會還有第二集、第三集吧？"},{"who":"A","text":"有喔，1935年又一次大地震，他們乾脆在正身後面加蓋木構的防震屋。"},{"who":"R","text":"自己加蓋防震屋，這家人的危機意識滿分！"},{"who":"A","text":"結果1999年921大地震，正身還是傾斜，護龍和門樓也倒了，家族花了五年才修好。"},{"who":"R","text":"歷經三次大地震還站著，真是老房子界的不倒翁。那屋子裡的裝飾還在嗎？"},{"who":"A","text":"還在，彩繪雕刻混合了閩式、日式和原住民圖案。這是私人宅第，請在外面看，找找門樓兩旁的土角牆。"}],"clues":["1917年的一場地震把我的前身震塌了","我的彩繪混合了閩式、日式和原住民圖案","我是埔里鐵山里的七開間閩式三合院"],"quiz":[{"q":"1935年大地震後，這座宅第增建了什麼？","options":["西式洋樓","防空壕","二層碉樓","木構防震屋"],"answer":3,"explain":"1935年地震後於正身後側增建木架構防震屋六間。"},{"q":"重建時所用的磚瓦是從哪裡運進埔里？","options":["鹿港","草屯","臺南","基隆"],"answer":1,"explain":"磚瓦自草屯以板車或挑夫運入。"}],"images":[]},{"id":"caotun-guominxiaoxueli","name":"草屯國民小學禮堂","short":"草屯國小禮堂","category":"歷史建築","level":"","town":"草屯鎮","types":["其他設施"],"lat":23.98178,"lng":120.687271,"address":"南投縣草屯鎮玉峰里玉屏路210 號","announced":"2002-08-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020801000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-05-09/c201cf23-bbe7-4b19-b413-bf359eb1d935/草屯國小禮堂整體外觀及周邊環境.jpg","year":1921,"yearText":"1921年（大正10年）","era":"japan","themes":["教育設施","日式建築","震災重建"],"yearUnknown":false,"summary":"日治時期草屯最大的集會場所","intro":"草屯國民小學禮堂位於草屯鎮玉峰里草屯國小校園內。學校源自1899年洪玉麟、李昌期等人設置的南投公學校草鞋墩分校，最早借敦和宮上課，1900年獨立為草鞋墩公學校。禮堂1920年動工、1921年3月完工，當時稱「講堂」，是草屯地區最大的集會場所；禮堂左側在日治時期是神社鳥居所在。1964年依原有尺度增建室內舞台，1978年草屯鎮公所曾借作臨時辦公處。921大地震牆體受損，後經補助整修，2004年完成修繕。","highlights":["切角式屋架與瓦片屋頂","紅磁磚與水泥外牆搭配木構窗","1964年依原尺度增建的舞台"],"funFact":"1978年草屯鎮公所曾借這座禮堂當臨時辦公處，小學禮堂當過鎮公所。","photoSpot":"經校方同意後，斜角拍禮堂屋頂與窗列","visitMin":15,"openNote":"位於草屯鎮玉峰里草屯國小校園內，上課時間請勿進入，開放情形以學校公告為準。","dialogue":[{"who":"A","text":"阿拉蕾，100多年前草屯要開大會，妳猜大家擠在哪裡？"},{"who":"R","text":"廟口吧？草屯廟那麼多，廟埕又大又寬。"},{"who":"A","text":"也是一個選項，不過1921年完工的草屯國小講堂，是當時草屯最大的集會場所。"},{"who":"R","text":"國小禮堂竟然是全鎮最大？那時候學校也很早就有了嗎？"},{"who":"A","text":"1899年就成立了，一開始還借敦和宮上課。禮堂左邊以前是神社鳥居的位置。"},{"who":"R","text":"聽說它還當過鎮公所？這也太跨界了吧！"},{"who":"A","text":"1978年鎮公所借來當臨時辦公處。小朋友開朝會，隔壁在辦戶口，畫面應該很熱鬧。"},{"who":"R","text":"那921大地震之後，它受傷嚴重嗎？"},{"who":"A","text":"牆體受損，後來整修完成繼續使用。有機會進校園，看看它的木構窗和屋頂線條，拍一張。"}],"clues":["1978年我曾借給鎮公所當臨時辦公處","日治時期我叫講堂，是地方最大的集會場所","我在草屯玉峰里的國小裡，1921年完工"],"quiz":[{"q":"草屯國小禮堂在日治時期被稱為什麼？","options":["講堂","公會堂","武德殿","演武場"],"answer":0,"explain":"1921年完工時稱為「講堂」。"},{"q":"1978年曾借用這座禮堂辦公的是哪個單位？","options":["南投縣政府","草屯鎮公所","臺灣省政府","草屯鎮農會"],"answer":1,"explain":"民國67年草屯鎮公所曾借用為臨時辦公處。"}],"images":[{"file":"草屯國小禮堂.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9f/%E8%8D%89%E5%B1%AF%E5%9C%8B%E5%B0%8F%E7%A6%AE%E5%A0%82.JPG/960px-%E8%8D%89%E5%B1%AF%E5%9C%8B%E5%B0%8F%E7%A6%AE%E5%A0%82.JPG","page":"https://commons.wikimedia.org/wiki/File:%E8%8D%89%E5%B1%AF%E5%9C%8B%E5%B0%8F%E7%A6%AE%E5%A0%82.JPG","artist":"Pbdragonwang","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/caotun-guominxiaoxueli-0.webp","small":"img/caotun-guominxiaoxueli-0-s.webp"}]},{"id":"caotun-chongshantang","name":"崇善堂","short":"崇善堂","category":"歷史建築","level":"","town":"草屯鎮","types":["宅第"],"lat":23.956509,"lng":120.67411,"address":"南投縣草屯鎮草溪路168 號","announced":"2002-01-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020129000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-09-11/73d79ecd-2eee-4fd2-9b67-6e21432fcdcc/崇善堂.jpg","year":1922,"yearText":"1922年（大正11年）創立","era":"japan","themes":["宗教信仰","宅第家族","震災重建"],"yearUnknown":false,"summary":"林姓家族的齋教龍華派齋堂","intro":"崇善堂位於草屯鎮上林里，地方俗稱「頭前厝齋堂」，後改名崇德堂。1922年創立，屬齋教（在家佛教）龍華派，緣起於林姓族人林輝燎持齋，在公廳內設置齋堂。建築由彰化社頭的匠師施作，建材取自濁水溪漂流木，後因白蟻問題遷到對面現址重建。格局為傳統三合院，正身前加一座歇山頂拜亭，佛青色彩繪醒目。戰後歷經八七水災、韋恩颱風與921大地震受損，管理人出資整修保存，2002年登錄為歷史建築，目前作為家族祭祀與居住空間。","highlights":["正身前歇山頂拜亭與佛青色彩繪","清光緒年間古匾「功奏南天」","偏廳梁上少見的民宅鼓與昭和年間吊鐘"],"funFact":"偏廳梁上那口昭和年間的吊鐘，相傳二戰末期曾被拿來當空襲警報的鐘聲。","photoSpot":"在路旁外觀拍拜亭與三合院正身","visitMin":10,"openNote":"位於草屯鎮上林里，官方資料標示為私人空間，兩側護龍仍有人居住。私人宅第，請在外觀參觀，勿擅自進入。","dialogue":[{"who":"R","text":"Allan，齋堂是什麼？是賣素食的地方嗎？"},{"who":"A","text":"差一點點。齋教又叫在家佛教，信徒在家持齋修行，齋堂就是他們的修行和聚會所。"},{"who":"R","text":"那崇善堂是怎麼來的？誰在這裡持齋修行？"},{"who":"A","text":"1922年，林家一位族人一直沒有子嗣，開始持齋，後來就在公廳裡設了齋堂。"},{"who":"R","text":"聽說蓋房子的木頭是從濁水溪撿來的？"},{"who":"A","text":"官方記載是取自濁水溪漂流木。不過原址白蟻太多，後來只好搬到對面重建。"},{"who":"R","text":"白蟻也太會吃了吧，比 Allan 吃肉圓還兇。"},{"who":"A","text":"我吃草屯肉圓至少會配一碗湯。這裡還是私人家族空間，有人住，我們在外面看就好。"},{"who":"R","text":"那我在路邊找找正身前那座拜亭，看它的佛青色彩繪有多醒目，再拍一張！"}],"clues":["我梁上的吊鐘，相傳曾當過空襲警報","我是齋教龍華派的齋堂，地方叫我頭前厝齋堂","我在草屯上林里，後來改名崇德堂"],"quiz":[{"q":"崇善堂屬於哪一種宗教團體的建築？","options":["基督長老教會","一貫道","齋教龍華派","日本淨土宗"],"answer":2,"explain":"崇善堂是齋教，也就是在家佛教龍華派的齋堂。"},{"q":"崇善堂當年的建材來自哪裡？","options":["阿里山檜木","福杉進口","八仙山林場","濁水溪漂流木"],"answer":3,"explain":"由社頭匠師施作，建材取自濁水溪漂流木。"}],"images":[{"file":"草屯崇善堂.jpg","thumb":"https://upload.wikimedia.org/wikipedia/commons/c/c4/%E8%8D%89%E5%B1%AF%E5%B4%87%E5%96%84%E5%A0%82.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%8D%89%E5%B1%AF%E5%B4%87%E5%96%84%E5%A0%82.jpg","artist":"Pbdragonwang","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0"}]},{"id":"nantou-shizhongshangong","name":"南投市中山公園「聚芳館」","short":"聚芳館","category":"歷史建築","level":"","town":"南投市","types":["其他設施"],"lat":23.911059,"lng":120.688224,"address":"南投縣南投市龍泉里民生街2號","announced":"2004-12-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20041221000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-05-15/96fce3d3-8518-479f-84a8-567049c97b39/南投市中山公園聚芳館.jpg","year":1922,"yearText":"1922年（大正11年）","era":"japan","themes":["公共建築","產業遺產","震災重建"],"yearUnknown":false,"summary":"南投公園裡的日治物產陳列館","intro":"聚芳館位於南投市龍泉里中山公園內。中山公園日治時期稱「南投公園」，1912年開始闢建，園內有池塘、操場、忠魂碑與南投神社等。1922年興建聚芳館，作為「南投郡物產陳列館」，推廣在地土產與手工藝，其中又以「南投燒」陶器最為風光。建築為和洋混合的折衷主義平房，斜屋頂兩側山牆與入口三角頂都設有通氣設計，四周有圓形拱柱採光。戰後曾作縣衛生院、縣立圖書館與托兒所等，921大地震嚴重受損，2001年修繕完成。","highlights":["入口三角頂與山牆下的通氣設計","四周的圓形拱柱","綠蔭扶疏的中山公園環境"],"funFact":"聚芳館當過陳列館、酒家、衛生院、圖書館、托兒所和路燈管理所辦公室，身分多到數不完。","photoSpot":"在中山公園綠樹間拍拱柱與三角頂","visitMin":15,"openNote":"位於南投市龍泉里中山公園內，由南投市公所管理，官方資料標示目前為閒置空間，可在公園內外觀參觀。可搭客運到南投市區後步行前往。","dialogue":[{"who":"R","text":"Allan，公園裡怎麼有一棟長得像小洋房的老建築？好有歐風！"},{"who":"A","text":"這是聚芳館，1922年蓋的南投郡物產陳列館，算是日治時期的在地名產展示中心。"},{"who":"R","text":"那時候南投最有名的名產是什麼？是意麵嗎？我好想吃。"},{"who":"A","text":"妳一講吃就精神來了。官方資料說當時最風光的是「南投燒」，也就是南投陶。"},{"who":"R","text":"原來是陶器！那它後來一直當展示館嗎？還是換了工作？"},{"who":"A","text":"沒有，它換過的工作比我還多，當過酒家、衛生院、圖書館，還有托兒所。"},{"who":"R","text":"這履歷也太豐富了吧！921大地震的時候還撐得住嗎？"},{"who":"A","text":"嚴重受損，後來用震災復建經費修好。到現場繞一圈，找找屋頂下藏著的通氣口，拍下來吧！"}],"clues":["我當過酒家、衛生院、圖書館和托兒所","日治時期我展示南投燒等地方物產","我在南投市中山公園裡，1922年興建"],"quiz":[{"q":"聚芳館最初的用途是什麼？","options":["公學校教室","神社社務所","郡物產陳列館","郡守官邸"],"answer":2,"explain":"1922年興建作為南投郡物產陳列館。"},{"q":"當時陳列品中最風光的南投名產是什麼？","options":["凍頂烏龍茶","樟腦","竹編工藝品","南投燒陶器"],"answer":3,"explain":"陳列物品中以南投燒，也就是南投陶最為風光。"}],"images":[{"file":"JufangHall.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/JufangHall.JPG/960px-JufangHall.JPG","page":"https://commons.wikimedia.org/wiki/File:JufangHall.JPG","artist":"Shxpeng","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/nantou-shizhongshangong-0.webp","small":"img/nantou-shizhongshangong-0-s.webp"}]},{"id":"zhushan-chenshanshulaozhai","name":"陳善述老宅","short":"陳善述老宅","category":"歷史建築","level":"","town":"竹山鎮","types":["宅第"],"lat":23.812771,"lng":120.73242,"address":"南投縣竹山鎮集山路一段1135巷25號","announced":"2021-08-17","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20210908000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-06-07/291e46b6-5c91-41f2-bd46-3bd8d1ba7fbd/陳善述老宅.jpg","year":1925,"yearText":"1925年動工、1927年完工（日治大正14年至昭和2年）","era":"japan","themes":["宅第家族"],"yearUnknown":false,"summary":"彩繪名師柯煥章妙筆的竹山仁醫故居","intro":"位於竹山鎮中央里集山路一段旁。由陳善述的養父陳獻章出資，1925年起備料興建、1927年完工，是正身五間起加左護龍的單伸手閩南民宅，穿斗式木構，以檜木榫卯接合。正廳與簷口的彩繪出自彰化伸港彩繪名師柯煥章，多為全彩；屋內還有西式彩色磁磚、洗石子廊柱、彩繪玻璃和日式紙拉門。陳善述生於1907年，是武秀才陳獻瑞之子、過繼給叔父陳獻章，1939年赴青島東亞醫科大學就讀，戰後回鄉開設「樂生醫院」，民眾沒錢也照樣看診，照護鄉里約30年。2021年登錄為歷史建築。","highlights":["柯煥章的全彩彩繪門扉與簷廊","瓜筒、垂花、斗栱等精美木雕","西式磁磚、彩繪玻璃與日式紙拉門混搭"],"funFact":"主人的生父是同一條巷子裡陳家古厝的武秀才陳獻瑞，他後來過繼給叔叔陳獻章。","photoSpot":"在宅外拍正身簷口的彩繪與木雕","visitMin":20,"openNote":"私人宅第，位於竹山鎮中央里集山路一段旁，目前無人居住、由後代管理。官方資料註明須提前預約，請洽南投縣政府文化局；未預約請在外觀參觀，勿擅自進入。","dialogue":[{"who":"A","text":"這棟閩南合院的主人是一位醫生，戰後在竹山開了樂生醫院，照顧鄉親大約30年。"},{"who":"R","text":"醫生的家應該很新潮吧？會不會是一棟洋樓？"},{"who":"A","text":"外表是傳統合院，裡面卻很混搭，有西式彩色磁磚、彩繪玻璃，還有日式紙拉門。"},{"who":"R","text":"中西日一起上桌，這房子根本是建築界的綜合果汁！"},{"who":"A","text":"形容得好！正廳和簷廊的彩繪，請的是彰化伸港的彩繪名師柯煥章，大多是全彩。"},{"who":"R","text":"那這位醫生本人，又有什麼故事呢？"},{"who":"A","text":"陳善述是武秀才陳獻瑞的兒子，過繼給叔叔，到青島讀醫科，回鄉後病人沒錢也照樣看診。"},{"who":"R","text":"這樣的醫德，比房子的彩繪還要漂亮。"},{"who":"A","text":"這是私人宅第，請在外面欣賞。找找簷下的瓜筒和垂花木雕，看看雕了什麼圖案。"}],"clues":["我的主人戰後開了一間名叫樂生的醫院","我的彩繪出自彰化伸港名師柯煥章","我是竹山中央里一位仁醫的閩南合院故居"],"quiz":[{"q":"這棟老宅的正廳與簷口彩繪出自哪位名師？","options":["潘麗水","陳玉峰","郭新林","柯煥章"],"answer":3,"explain":"彩繪由彰化伸港彩繪名師柯煥章施作。"},{"q":"陳善述戰後在竹山開設的醫院叫什麼名字？","options":["仁愛醫院","樂生醫院","博愛醫院","濟世醫院"],"answer":1,"explain":"他在後埔仔街上開設樂生醫院行醫。"}],"images":[]},{"id":"caotun-furongtang","name":"敷榮堂","short":"敷榮堂","category":"歷史建築","level":"","town":"草屯鎮","types":["宅第"],"lat":23.996047,"lng":120.664998,"address":"南投縣草屯鎮新庄里芬草路二段752號","announced":"2002-01-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020129000006","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-05-16/d1c27fb3-07d3-4a6a-862c-a0e6394c5384/敷榮堂.jpg","year":1928,"yearText":"1928年（昭和3年）","era":"japan","themes":["宅第家族"],"yearUnknown":false,"summary":"門樓題「秀聚東南」的洪家中西合璧宅第","intro":"敷榮堂位於草屯鎮新庄里芬草路旁，屬草屯洪氏陽明派。清同治年間廩生洪聯魁曾禮聘鹿港秀才洪月樵擔任登瀛書院山長，日治時期任南投辦務署參事與頂茄荖庄區長。其子洪得中於1928年從田厝仔分出，在新庄興建敷榮堂，是以紅磚、木樑柱、薄瓦構成的中西合璧三合院，有內外埕、門樓，門前有月眉池。洪得中曾任明治製糖南投工場原料委員，並長年擔任燉倫堂管理人。921大地震後，後代擬修復作為地方文教活動空間。","highlights":["門樓題字「秀聚東南」與磚砌鏤空牆","牆身上紅磚、下浮雕花磚的搭配","門前月眉池與三合院整體配置"],"funFact":"洪得中的子女多旅居美國行醫，三代從事醫業的有二十多位，被稱為醫學世家。","photoSpot":"在路旁外觀拍門樓「秀聚東南」題字","visitMin":10,"openNote":"位於草屯鎮新庄里芬草路旁，官方資料標示為私人空間。私人宅第，請在外觀參觀，勿擅自進入。","dialogue":[{"who":"A","text":"阿拉蕾，抬頭看那座門樓，上面寫了哪四個字？"},{"who":"R","text":"「秀聚東南」！聽起來很有氣勢，是說這裡風水很好嗎？"},{"who":"A","text":"有讚美人才聚集的意思。這是洪得中在1928年蓋的敷榮堂，洪家在草屯是讀書人家。"},{"who":"R","text":"怎麼說？他們家有人考上功名嗎？還是出了大官？"},{"who":"A","text":"他父親洪聯魁是清代廩生，還親自到鹿港請秀才洪月樵來當登瀛書院的山長。"},{"who":"R","text":"哇，自己的書院自己請校長！那後代呢？"},{"who":"A","text":"後代很多到美國行醫，三代二十多位醫生，門口那句「秀聚東南」真的很靈驗。"},{"who":"R","text":"這比我的考運符還有效！不過這裡是私人住宅吧？"},{"who":"A","text":"對，請在外面欣賞。妳可以觀察牆面，上半是紅磚，下半是浮雕花磚，拍一張比較看看。"}],"clues":["我的門樓題著「秀聚東南」四個字","我是紅磚中西合璧的三合院，門前有月眉池","我是洪得中在1928年於草屯新庄建的宅第"],"quiz":[{"q":"敷榮堂門樓上題的是哪四個字？","options":["秀聚東南","紫氣東來","積善餘慶","耕讀傳家"],"answer":0,"explain":"門樓上題「秀聚東南」四字。"},{"q":"洪聯魁曾禮聘誰擔任登瀛書院山長？","options":["簡化成","洪月樵","莊文蔚","林錫爵"],"answer":1,"explain":"洪聯魁親赴鹿港敦聘秀才洪月樵為山長。"}],"images":[{"file":"草屯敷榮堂.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/98/%E8%8D%89%E5%B1%AF%E6%95%B7%E6%A6%AE%E5%A0%82.JPG/960px-%E8%8D%89%E5%B1%AF%E6%95%B7%E6%A6%AE%E5%A0%82.JPG","page":"https://commons.wikimedia.org/wiki/File:%E8%8D%89%E5%B1%AF%E6%95%B7%E6%A6%AE%E5%A0%82.JPG","artist":"Pbdragonwang","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/caotun-furongtang-0.webp","small":"img/caotun-furongtang-0-s.webp"}]},{"id":"shuili-laijiagucuo","name":"賴家古厝","short":"水里賴家古厝","category":"歷史建築","level":"","town":"水里鄉","types":["宅第"],"lat":23.783229,"lng":120.864029,"address":"南投縣水里鄉永興村林朋巷141、142、143 號","announced":"2002-01-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020129000008","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-12-16/2a1dede7-802a-4b35-a930-3acacf91c2e5/賴家古厝(三合院整體建築外觀) (1).jpg","year":1928,"yearText":"1928年動工、1930年竣工（日治昭和3至5年）","era":"japan","themes":["宅第家族","震災重建"],"yearUnknown":false,"summary":"左護龍用歇山頂的近百年漢式三合院","intro":"位於水里鄉永興村林朋巷一帶。1928年動工、1930年竣工，是坐東南向西北的傳統漢式三合院木造建築，由正身、左右護龍與約1970年增建的右外護龍組成。正身與護龍的簷廊出簷構件雕飾精美，左護龍採用歇山式屋頂，是最大的特色。約1955年更換部分本島瓦，約1990年再翻修，除左護龍外多改為水泥瓦。1999年921大地震時，左護龍牆身被震得傾斜，經緊急加固後保存下來。整體仍大致維持原貌，見證水里從日治時期到今天的發展。2002年登錄為歷史建築。","highlights":["左護龍的歇山式屋頂","簷廊出簷構件的精美雕飾","921震後緊急加固保存的左護龍"],"funFact":"一般三合院護龍屋頂較簡單，這裡的左護龍特別採用歇山式屋頂，是最搶眼的特色。","photoSpot":"從宅外比較左右護龍的屋頂","visitMin":15,"openNote":"私人宅第，位於水里鄉永興村林朋巷一帶。官方資料註明須提前預約，請洽南投縣政府文化局；未預約請在外觀參觀，勿擅自進入。山區道路颱風、豪雨後常有坍方管制，出發前查詢公路局最新路況。","dialogue":[{"who":"R","text":"Allan，三合院不是都長得差不多嗎？紅瓦、正身、兩條護龍，收工！"},{"who":"A","text":"那你看看水里這座的左護龍，屋頂是歇山式，跟其他屋頂長得不一樣。"},{"who":"R","text":"一邊穿西裝、一邊穿拖鞋，這三合院很有個性喔！"},{"who":"A","text":"哈哈，可以這樣說。它1928年動工、1930年完工，到現在快要一百年了。"},{"who":"R","text":"南投在921大地震受創很重，那時候它有沒有受傷？"},{"who":"A","text":"有，偏偏就是最有特色的左護龍，牆身被震到傾斜，經過緊急加固才保存下來。"},{"who":"R","text":"好險，不然最有個性的那一邊就沒了，三合院會變成二合院。"},{"who":"A","text":"這是私人宅第，請在外面參觀。找一找簷廊下雕得最細的出簷構件，再比較左右兩邊屋頂的差別。"}],"clues":["我在1930年完工，至今將近百年","921地震時我的一側護龍牆身被震歪","我是水里永興村左護龍有歇山頂的三合院"],"quiz":[{"q":"這座古厝的左護龍採用哪一種屋頂形式？","options":["硬山式","懸山式","歇山式","捲棚式"],"answer":2,"explain":"左護龍屋頂採用歇山式，是建築特色之一。"},{"q":"921大地震時，古厝哪一部分牆身傾斜？","options":["左護龍","正身","右外護龍","門樓"],"answer":0,"explain":"左護龍牆身受地震外力傾斜，經緊急加固保存。"}],"images":[]},{"id":"caotun-xinzhuangguoxiaoli","name":"新庄國小禮堂","short":"新庄國小禮堂","category":"歷史建築","level":"","town":"草屯鎮","types":["其他設施"],"lat":23.995265,"lng":120.66744,"address":"南投縣草屯鎮芬草路219號","announced":"2004-12-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20041221000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-09-09/14f98ec9-4253-451a-a80e-a24bb672dea1/新庄國小禮堂.jpg","year":1931,"yearText":"1931年（昭和6年）","era":"japan","themes":["教育設施","日式建築","震災重建"],"yearUnknown":false,"summary":"與碧峰國小「平分經費」的日式禮堂","intro":"新庄國小禮堂位於草屯鎮新庄國小校園內，興建於1931年。當時草屯地區只編列一間禮堂的經費，經新庄、碧峰兩校地方人士協調，由新庄蓋前段、碧峰蓋後段化解爭議。戰後因空間不足，1964年仿照原設計擴建成今貌。禮堂以紅磚砌牆，正門仿日式「車寄」構造，大門上方有山牆裝飾。921大地震主結構受損，原本要拆除重建，經專家會勘認為具保存價值，在紅十字會資助下依原貌補強修復，2002年完成。","highlights":["正門仿日式車寄的入口構造","大門上方的山牆裝飾","紅磚牆身與切角式屋架"],"funFact":"1931年只有一間禮堂的預算，新庄和碧峰兩校協調後，一校蓋前段、一校蓋後段。","photoSpot":"經校方同意後，正面拍車寄入口與山牆","visitMin":15,"openNote":"位於草屯鎮新庄國小校園內，上課時間請勿進入，開放情形以學校公告為準。","dialogue":[{"who":"A","text":"阿拉蕾，如果有兩間學校只有一份預算，妳會怎麼分？"},{"who":"R","text":"猜拳啊！贏的人蓋禮堂，輸的人負責掃地。"},{"who":"A","text":"1931年草屯人比較有智慧，新庄國小蓋禮堂前段，碧峰國小蓋後段，誰也不吃虧。"},{"who":"R","text":"一棟禮堂切成兩半？這樣的分法太有創意了，我第一次聽到！"},{"who":"A","text":"是預算分兩半啦。戰後1964年新庄這棟又擴建，外型還是照日治時期的設計。"},{"who":"R","text":"921大地震的時候它也受傷了嗎？草屯震得很嚴重吧。"},{"who":"A","text":"主結構受損，原本要拆，專家說值得留，後來紅十字會資助，依原貌補強修好。"},{"who":"R","text":"幸好沒拆！那它最特別的地方在哪裡？"},{"who":"A","text":"正門仿日式車寄，以前讓車子停靠下客用。到現場找找門上方的山牆裝飾吧！"}],"clues":["我的正門仿照日式車寄的構造","1931年我和另一所學校分著用一份蓋禮堂的經費","我在草屯新庄里一所國小裡，921後依原貌修復"],"quiz":[{"q":"1931年新庄、碧峰兩校如何解決禮堂經費問題？","options":["一校蓋前段一校蓋後段","輪流使用一年","抽籤決定給誰","兩校合併成一校"],"answer":0,"explain":"協調後新庄蓋前段，碧峰蓋後段。"},{"q":"921震後新庄國小禮堂主要由誰資助修復？","options":["日本交流協會","中華民國紅十字會","臺灣省政府","地方廟宇"],"answer":1,"explain":"在中華民國紅十字會認養資助下補強修復。"}],"images":[{"file":"草屯新庄國小禮堂.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c4/%E8%8D%89%E5%B1%AF%E6%96%B0%E5%BA%84%E5%9C%8B%E5%B0%8F%E7%A6%AE%E5%A0%82.JPG/960px-%E8%8D%89%E5%B1%AF%E6%96%B0%E5%BA%84%E5%9C%8B%E5%B0%8F%E7%A6%AE%E5%A0%82.JPG","page":"https://commons.wikimedia.org/wiki/File:%E8%8D%89%E5%B1%AF%E6%96%B0%E5%BA%84%E5%9C%8B%E5%B0%8F%E7%A6%AE%E5%A0%82.JPG","artist":"Pbdragonwang","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/caotun-xinzhuangguoxiaoli-0.webp","small":"img/caotun-xinzhuangguoxiaoli-0-s.webp"}]},{"id":"caotun-bifengguominxiao","name":"碧峰國民小學禮堂","short":"碧峰國小禮堂","category":"歷史建築","level":"","town":"草屯鎮","types":["其他設施"],"lat":23.969371,"lng":120.66609,"address":"南投縣草屯鎮立人路439 號","announced":"2002-08-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020801000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-09-12/89490ee4-9283-4ebd-b475-5a26fd7f709c/碧峰國小禮堂.jpg","year":1931,"yearText":"1931年（昭和6年）","era":"japan","themes":["教育設施","日式建築","震災重建"],"yearUnknown":false,"summary":"藏著巴洛克舞台的校園禮堂","intro":"碧峰國民小學禮堂位於草屯鎮碧峰國小校園內。學校源自1920年借北投埔林姓家廟上課的草鞋墩公學校分校，1922年獨立為碧峰公學校。禮堂建於1931年，當時草屯只編列一間禮堂經費，與新庄國小協調後由碧峰蓋後段；今天禮堂內的舞台部分就是日治時期所建。戰後1964年補建完成整棟禮堂。建築為混凝土與磚造，內部有華麗的巴洛克式舞台，兩側弧線流暢的鑄鐵簷廊是最大特色。921大地震一度被判定危樓，後確認主體尚完整，獲教育部經費補強修復。","highlights":["禮堂內日治時期的巴洛克式舞台","兩側弧線流暢的鑄鐵簷廊","白色正門與紅磚後身的對比"],"funFact":"921地震後這座禮堂一度被鑑定為危樓，再次勘察才確定主體還能補強修復，逃過拆除。","photoSpot":"經校方同意後，在側面拍鑄鐵簷廊弧線","visitMin":15,"openNote":"位於草屯鎮碧峰國小校園內，上課時間請勿進入，開放情形以學校公告為準。","dialogue":[{"who":"R","text":"Allan，國小禮堂裡面有巴洛克舞台？你沒有搞錯吧？"},{"who":"A","text":"沒搞錯。碧峰國小禮堂的舞台是1931年日治時期蓋的，裝飾華麗，形式很精緻。"},{"who":"R","text":"那外面呢？會不會跟歐洲宮殿一樣金光閃閃？"},{"who":"A","text":"外面比較低調，正門白色、後身紅磚。最搶眼的是兩側鑄鐵簷廊，弧線很漂亮。"},{"who":"R","text":"聽說它跟新庄國小有一段分預算的故事？"},{"who":"A","text":"對，當年一份經費兩校分，碧峰蓋後段，所以舞台這部分正是當年的成果。"},{"who":"R","text":"那921大地震的時候，它還好嗎？"},{"who":"A","text":"一度被判定危樓，差點要拆。後來確認主體還行，教育部撥款修好，算是大難不死。"},{"who":"R","text":"如果有機會進去，我要站在舞台前，拍一張像在歐洲劇院謝幕的照片！"}],"clues":["我的室內藏著一座巴洛克式華麗舞台","我兩側有弧線流暢的鑄鐵簷廊","我在草屯碧峰里的國小裡，921後曾被判定危樓"],"quiz":[{"q":"碧峰國小禮堂外部最大的特色是什麼？","options":["石雕龍柱","八角形鐘樓","兩側鑄鐵簷廊","琉璃瓦屋頂"],"answer":2,"explain":"兩側有弧線流暢的鑄鐵簷廊，是最大特色。"},{"q":"禮堂內哪一部分是日治時期所建？","options":["廁所","觀眾席座椅","大門玄關","舞台"],"answer":3,"explain":"目前禮堂內舞台部分即為日治時期所建。"}],"images":[{"file":"草屯碧峰國小禮堂.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/%E8%8D%89%E5%B1%AF%E7%A2%A7%E5%B3%B0%E5%9C%8B%E5%B0%8F%E7%A6%AE%E5%A0%82.JPG/960px-%E8%8D%89%E5%B1%AF%E7%A2%A7%E5%B3%B0%E5%9C%8B%E5%B0%8F%E7%A6%AE%E5%A0%82.JPG","page":"https://commons.wikimedia.org/wiki/File:%E8%8D%89%E5%B1%AF%E7%A2%A7%E5%B3%B0%E5%9C%8B%E5%B0%8F%E7%A6%AE%E5%A0%82.JPG","artist":"Pbdragonwang","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/caotun-bifengguominxiao-0.webp","small":"img/caotun-bifengguominxiao-0-s.webp"}]},{"id":"caotun-caoxiedunyashe","name":"草鞋墩雅舍","short":"草鞋墩雅舍","category":"歷史建築","level":"","town":"草屯鎮","types":["其他設施"],"lat":23.979278,"lng":120.688929,"address":"南投縣草屯鎮中正路579-3、579-4號","announced":"2022-03-15","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20220322000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-10-01/e1b1b190-521e-48f9-a942-671f175f21b6/草鞋墩雅舍.jpg","year":1931,"yearText":"1931年（昭和6年）","era":"japan","themes":["日式建築","林業樟腦"],"yearUnknown":false,"summary":"草屯少見的日式木造林務宿舍","intro":"草鞋墩雅舍位於草屯鎮中正路，國立臺灣工藝研究發展中心附近，創建於1931年，由兩棟日式木造建築組成。外牆為雨淋板，屋頂鋪日式黑色甕根瓦，曾作為林務相關業務的員工宿舍，後來已無林務單位員工居住。整體結構除內部破損外，外觀與牆堵保存尚好，是草屯地區少數留存、細部構造優雅的日式木構造建築，2022年登錄為歷史建築。「草鞋墩」正是草屯的舊地名。","highlights":["屋頂的日式黑色甕根瓦","一片片疊合的雨淋板外牆","兩棟並列的日式木構宿舍"],"funFact":"草屯舊名「草鞋墩」，雅舍的名字就把這個老地名留了下來。","photoSpot":"在中正路旁外觀拍黑瓦屋頂與雨淋板","visitMin":10,"openNote":"位於草屯鎮中正路，官方資料標示整修中，目前僅能外觀參觀，請勿進入施工範圍。可順遊附近的工藝研究發展中心。","dialogue":[{"who":"R","text":"Allan，草鞋墩是什麼？是放草鞋的地方嗎？"},{"who":"A","text":"草鞋墩是草屯的舊地名。這兩棟日式木屋取名草鞋墩雅舍，把老地名留了下來。"},{"who":"R","text":"名字好文青！它以前是誰住的？是作家嗎？"},{"who":"A","text":"1931年蓋的，曾經是林務相關業務的員工宿舍，跟森林、木材的工作有關。"},{"who":"R","text":"那屋頂黑黑亮亮的瓦片，是什麼特別的瓦嗎？看起來好有質感。"},{"who":"A","text":"那叫日式黑色甕根瓦，配上一片片雨淋板外牆，這種木造日式建築在草屯已經很少見了。"},{"who":"R","text":"我可以進去喝杯茶、吟首詩，當一下雅士嗎？"},{"who":"A","text":"目前還在整修，只能在外面當雅士。妳可以順便去隔壁工藝中心逛逛，看看陳列館。"},{"who":"R","text":"那我在路邊拍一張黑瓦屋頂，再數數看雨淋板疊了幾層！"}],"clues":["我屋頂鋪著日式黑色甕根瓦","我曾經是林務相關業務的員工宿舍","我的名字裡藏著草屯的舊地名"],"quiz":[{"q":"「草鞋墩」是哪個地方的舊地名？","options":["埔里","竹山","草屯","集集"],"answer":2,"explain":"草鞋墩是草屯的舊地名。"},{"q":"草鞋墩雅舍過去是什麼用途？","options":["神社社務所","郵便局","糖廠招待所","林務業務員工宿舍"],"answer":3,"explain":"曾作為林務相關業務宿舍。"}],"images":[]},{"id":"jiji-huochezhan","name":"集集火車站","short":"集集火車站","category":"歷史建築","level":"","town":"集集鎮","types":["車站"],"lat":23.826538,"lng":120.784885,"address":"南投縣集集鎮集集鎮民生路75號","announced":"2004-12-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20041221000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-10-02/d1f846f6-8fad-49a5-9a7b-94d1fda8f35d/集集火車站.jpg","year":1933,"yearText":"1933年（昭和8年）改建，2001年依原貌重建","era":"japan","themes":["鐵道交通","日式建築","震災重建"],"yearUnknown":false,"summary":"921震後依原貌重建的檜木車站","intro":"集集火車站位於集集鎮民生路，是臺鐵集集線上的車站。集集線原由臺灣電力株式會社為興建日月潭發電廠運送材料而建，1922年1月通車，從二水經源泉、濁水、龍泉、集集、水里到車埕，全長29.7公里，後來兼營客貨運，帶動沿線發展；1930年前後集集香蕉外銷興盛，鄰近地區的香蕉都集中到這裡轉運。官方資料記載1933年因舊站簡陋，改建為檜木站房。1980年代臺鐵曾有意停駛並拆除集集線，因地方反對而保留。1999年921大地震時站房嚴重傾斜受損，成為重建的象徵，2001年依原貌重建完成。","highlights":["檜木屋架與簡潔線條的日式站房","921震後整修換上的黑瓦屋頂","站前廣場的銅製小火車頭"],"funFact":"集集線最初是為了替日月潭發電廠運送材料而建，通車後才開始載客。","photoSpot":"在站前廣場拍檜木站房正面","visitMin":30,"openNote":"位於集集鎮民生路，臺鐵集集線集集站，車站全日開放，人員售票與諮詢服務時間8:00至17:00，其他時間可上車購票。可從臺鐵二水站轉乘集集線；集集線近年曾因隧道與邊坡工程部分區間停駛、改以公路接駁，出發前請查詢臺鐵最新公告。","dialogue":[{"who":"A","text":"集集線小火車進站囉！眼前這座木造站房，就是很多人旅行照片裡的集集火車站。"},{"who":"R","text":"Allan，它看起來好溫柔喔，可是我聽說它經歷過大地震？"},{"who":"A","text":"對，1999年921大地震集集離震央很近，站房嚴重傾斜受損，2001年依原貌重建完成。"},{"who":"R","text":"原來我們現在看到的是重生版！那最早蓋鐵路是為了載觀光客嗎？"},{"who":"A","text":"不是喔，集集線原本是為了興建日月潭發電廠運材料，1922年通車，後來才載客載貨。"},{"who":"R","text":"先當工程車再當觀光列車，轉職很成功耶！"},{"who":"A","text":"而且1930年前後集集香蕉外銷很興盛，附近的香蕉都要送來這裡轉運。"},{"who":"R","text":"難怪集集到處都買得到香蕉和山蕉冰！"},{"who":"A","text":"等一下先去吃根香蕉，再回來抬頭看看站房的黑瓦，那是震後整修換上的。"}],"clues":["我原本是為了運送發電廠工程材料而設的車站","大地震讓我嚴重傾斜，兩年後我依原貌重生","我是集集線上最有名的檜木站房"],"quiz":[{"q":"集集線鐵路最初是為了什麼而興建？","options":["載運觀光客","運送軍隊","運送日月潭發電廠材料","運送樟腦"],"answer":2,"explain":"臺灣電力株式會社為興建日月潭發電廠運材料而建。"},{"q":"921大地震後，集集火車站在哪一年依原貌重建完成？","options":["1999年","2001年","2004年","2010年"],"answer":1,"explain":"站房震後嚴重傾斜，2001年依原貌重建完成。"}],"images":[{"file":"Jiji station.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/Jiji_station.JPG/960px-Jiji_station.JPG","page":"https://commons.wikimedia.org/wiki/File:Jiji_station.JPG","artist":"Takoradee~commonswiki","license":"CC BY 2.5","licenseUrl":"https://creativecommons.org/licenses/by/2.5","local":"img/jiji-huochezhan-0.webp","small":"img/jiji-huochezhan-0-s.webp"}]},{"id":"jiji-zhangnaochuzhang","name":"集集樟腦出張所建築群","short":"集集樟腦出張所","category":"歷史建築","level":"","town":"集集鎮","types":["產業"],"lat":23.829135,"lng":120.786779,"address":"南投縣集集鎮集集鎮民生路57號","announced":"2019-01-02","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20190122000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-09-09/5454f9d9-78ec-4b58-ab88-bab0958d8911/集集樟腦出張所.jpg","year":1934,"yearText":"1934年（昭和9年）設立，1942年移築完成","era":"japan","themes":["林業樟腦","日式建築","產業遺產"],"yearUnknown":false,"summary":"見證樟腦專賣興衰的日式建築群","intro":"集集樟腦出張所建築群位於集集鎮民生路，靠近集集火車站。1934年臺灣總督府解散臺灣製腦株式會社，樟腦製造改為專賣局官營，在臺中支局下設「專賣局集集出張所」，管理25個製腦地、634個腦灶。因舊房舍老舊狹小，陸續移築到現址，主要廳舍宿舍在1942年完成。戰後歷經臺灣樟腦公司、臺灣省樟腦局，以及林務局巒大林區管理處員工宿舍等使用，直到2007年人員全部遷出。建築群共11棟，多為日式木造，有水泥瓦、編竹夾泥牆與雨淋板，是臺灣樟腦產業興衰與濁水溪中游林業的縮影。","highlights":["編竹夾泥牆與雨淋板的日式木造廳舍","洋小屋與和小屋兩種屋架並存","從集集火車站步行可達的產業聚落"],"funFact":"出張所當年管理25個製腦地、634個腦灶，可見集集山區曾是重要的樟腦產地。","photoSpot":"在民生路拍日式木造廳舍與雨淋板","visitMin":30,"openNote":"位於集集鎮民生路，離集集火車站很近。官方資料記載建築群目前閒置，由集集鎮公所管理並推動修復工程；開放情形以鎮公所公告為準，未開放時請在外觀參觀。","dialogue":[{"who":"R","text":"Allan，集集的集有聚集的意思，以前大家都聚來這裡做什麼生意？"},{"who":"A","text":"除了香蕉，還有一樣很香的東西，就是樟腦。這裡就是集集樟腦出張所建築群。"},{"who":"R","text":"樟腦？就是衣櫃裡防蟲的那種白色小球嗎？"},{"who":"A","text":"對，以前樟腦可是重要的經濟產品。1934年改由專賣局官營，在集集設了出張所。"},{"who":"R","text":"那這個出張所管的範圍到底有多大？"},{"who":"A","text":"管理25個製腦地、634個腦灶，規模很大。主要廳舍宿舍到1942年才移築完成。"},{"who":"R","text":"後來樟腦沒落了，這些房子怎麼辦？"},{"who":"A","text":"戰後轉給樟腦公司和樟腦局，最後成了林務局員工宿舍，2007年人員才全部搬走。"},{"who":"R","text":"我的任務是在外面找出雨淋板一片片疊起來的木牆，拍給大家看！"}],"clues":["我曾管理634個腦灶","樟腦沒落後，我變成林務局員工的宿舍","我是集集火車站附近一群樟腦專賣的日式建築"],"quiz":[{"q":"集集出張所隸屬哪一個機關？","options":["鐵道部","營林所","臺灣銀行","專賣局"],"answer":3,"explain":"1934年樟腦改為專賣局官營，在臺中支局下設出張所。"},{"q":"集集出張所管理大約多少個腦灶？","options":["63個","248個","634個","1500個"],"answer":2,"explain":"管理25個製腦地、634個腦灶。"}],"images":[]},{"id":"zhushan-sheliaogucang","name":"社寮穀倉","short":"社寮穀倉","category":"歷史建築","level":"","town":"竹山鎮","types":["產業"],"lat":23.813796,"lng":120.722362,"address":"南投縣竹山鎮竹山鎮社寮里集山路一段1762巷2號","announced":"2005-10-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20110415000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-09-07/9d780279-a914-4e98-b06f-254f814b3ff8/社寮穀倉.jpg","year":1935,"yearText":"1935年（昭和10年）","era":"japan","themes":["產業遺產","茶業農業"],"yearUnknown":false,"summary":"防潮防鼠的日治農業倉庫","intro":"社寮穀倉位於竹山鎮社寮里集山路一段旁巷內。依1935年出版的《竹山郡管內概況》記載，1914年12月26日社寮仕紳黃起奏與地方人士發起組織「社寮信用購買販賣利用組合」，也就是今天農會的前身，提供農民購買農業資材、販售農產品以及存放款等服務。1935年組合興建這座農業倉庫，用來貯存稻穀。穀倉為水泥磚造平房，兩坡式屋頂原蓋水泥瓦，近年改為鋼浪板；牆面為了防潮防鼠，設有多層充填材料的隔間，是相當講究的穀倉設計。2005年登錄為歷史建築。","highlights":["為防潮防鼠設計的多層牆面隔間","兩坡式屋頂的水泥磚造平房","與敬聖亭、紫南宮相鄰的社寮街區"],"funFact":"興建這座穀倉的是社寮信用購買販賣利用組合，也就是今天農會的前身。","photoSpot":"在巷口拍穀倉兩坡屋頂與牆面","visitMin":15,"openNote":"位於竹山鎮社寮里集山路一段旁巷內，官方資料記載開放時間8:00至17:00，實際開放情形以管理單位為準。附近有社寮敬聖亭與紫南宮，可一起散步參觀。","dialogue":[{"who":"A","text":"社寮這裡除了敬聖亭，還有一座守護稻米的老倉庫，社寮穀倉。"},{"who":"R","text":"Allan，穀倉不就是放稻子的地方嗎？有什麼好看？"},{"who":"A","text":"它可講究了！牆面做了多層充填材料隔間，就是為了防潮又防老鼠。"},{"who":"R","text":"老鼠聽了一定很傷心，好不容易找到吃到飽餐廳，結果門都進不去。"},{"who":"A","text":"哈哈，沒錯！它是1935年由社寮信用購買販賣利用組合興建的。"},{"who":"R","text":"這名字好長，像一口氣念不完的繞口令。"},{"who":"A","text":"簡單說就是今天農會的前身，1914年由仕紳黃起奏和地方人士發起，幫農民買賣和存錢。"},{"who":"R","text":"原來這就是農會的阿公阿嬤版本！"},{"who":"A","text":"到現場看看兩坡式屋頂，原本的水泥瓦已經換成鋼浪板，找找新舊材料的差別。"}],"clues":["我的牆裡有好幾層隔間，專門擋濕氣和老鼠","興建我的單位，是今天農會的前身","我是社寮一座日治時期存放稻穀的倉庫"],"quiz":[{"q":"這座穀倉牆面設計多層隔間的主要目的是什麼？","options":["隔音","防火","防潮防鼠","保暖"],"answer":2,"explain":"牆面為防潮防鼠設有多層充填材料隔間。"},{"q":"興建這座穀倉的組合，是今天哪個單位的前身？","options":["鎮公所","農會","郵局","水利會"],"answer":1,"explain":"社寮信用購買販賣利用組合即今農會前身。"}],"images":[{"file":"社寮穀倉.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/99/%E7%A4%BE%E5%AF%AE%E7%A9%80%E5%80%89.jpg/960px-%E7%A4%BE%E5%AF%AE%E7%A9%80%E5%80%89.jpg","page":"https://commons.wikimedia.org/wiki/File:%E7%A4%BE%E5%AF%AE%E7%A9%80%E5%80%89.jpg","artist":"Pbdragonwang","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/zhushan-sheliaogucang-0.webp","small":"img/zhushan-sheliaogucang-0-s.webp"}]},{"id":"nantou-shinonghui","name":"南投市農會","short":"南投市農會","category":"歷史建築","level":"","town":"南投市","types":["其他設施"],"lat":23.908147,"lng":120.687008,"address":"南投縣南投市龍井街62 號","announced":"2002-01-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020129000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-09/188dc563-571c-4f9b-9b78-5e381afe5931/南投市農會.jpg","year":1936,"yearText":"1936年（昭和11年）","era":"japan","themes":["公共建築","茶業農業"],"yearUnknown":false,"summary":"貼滿國防磚的日治農會大樓","intro":"南投市農會位於南投市龍井街，主體建築完成於1936年，前身是1914年成立的有限責任南投信用組合，戰後1949年改組為南投鎮農會，1981年配合縣轄市改制改名南投市農會。建築為坐北朝南、U字形配置的二層加強磚造，外牆貼1930年代流行的13溝面磚，俗稱「國防磚」，增建部分以洗石子修飾，屋頂覆日本文化瓦。立面簡樸，上下樓層細長窗形成垂直線條，受現代主義影響，是南投市現存規模較大且完整的近代建築，目前仍是農會信用部營業場所。","highlights":["外牆淺色13溝面磚，俗稱國防磚","上下樓層細長窗的垂直線條","開口與水平線條的洗石子裝飾"],"funFact":"13溝面磚表面有約13道溝痕，俗稱國防磚，是1930年代流行的面磚，現在已少見。","photoSpot":"在對街拍正面立面與溝面磚","visitMin":10,"openNote":"位於南投市龍井街，目前仍為南投市農會信用部營業使用，依官方資料信用部營業到16:00；請以外觀參觀為主，入內洽公勿打擾業務。","dialogue":[{"who":"A","text":"阿拉蕾，靠近那面牆，用手指輕輕摸一下，有什麼感覺？"},{"who":"R","text":"刮刮的！磚頭上有一條一條的溝，是被貓抓過嗎？"},{"who":"A","text":"不是貓，是13溝面磚，俗稱國防磚，1930年代很流行。這棟南投市農會1936年就蓋好了。"},{"who":"R","text":"快90年的老房子，現在還在營業嗎？"},{"who":"A","text":"還在，現在是農會信用部，每天有人來存錢、辦貸款，是很認真工作的古蹟前輩。"},{"who":"R","text":"那它最早就是農會嗎？還是做別的事？"},{"who":"A","text":"前身是1914年成立的南投信用組合，戰後才改組成農會。從存錢筒變成大銀行的概念。"},{"who":"R","text":"那我去的時候可以進去領錢順便參觀嗎？"},{"who":"A","text":"洽公可以，參觀請別打擾人家上班。在對面數數看，一塊磚上是不是真的有13道溝！"}],"clues":["我外牆貼著俗稱國防磚的溝面磚","我的前身是1914年成立的信用組合","我在南投市龍井街，今天還在辦存放款業務"],"quiz":[{"q":"南投市農會外牆的13溝面磚俗稱什麼？","options":["國防磚","紅毛磚","清水磚","馬約利卡磚"],"answer":0,"explain":"13溝面磚約有13道溝痕，亦稱國防磚。"},{"q":"南投市農會的前身是什麼組織？","options":["南投水利組合","南投信用組合","南投青果合作社","南投商工會"],"answer":1,"explain":"前身為1914年成立的有限責任南投信用組合。"}],"images":[{"file":"NantouCityFarmersAssociation.png","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/NantouCityFarmersAssociation.png/960px-NantouCityFarmersAssociation.png","page":"https://commons.wikimedia.org/wiki/File:NantouCityFarmersAssociation.png","artist":"Shxpeng","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/nantou-shinonghui-0.webp","small":"img/nantou-shinonghui-0-s.webp"}]},{"id":"nantou-shuiwuchuzhangsuo","name":"南投稅務出張所","short":"南投稅務出張所","category":"歷史建築","level":"","town":"南投市","types":["其他設施"],"lat":23.910756,"lng":120.684303,"address":"南投縣南投市南投市康壽里中山街260號","announced":"2009-04-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20190509000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-08-18/3a432922-365f-42d1-a9e0-7327e5d70521/南投稅務出張所.jpg","year":1936,"yearText":"1936年（昭和11年）","era":"japan","themes":["公共建築","日式建築"],"yearUnknown":false,"summary":"臺中州第一個稅務出張所，今為文創空間","intro":"南投稅務出張所位於南投市康壽里中山街，是日治時期臺中州第一個設立的稅務出張所，1936年起辦理南投郡的稅務。原建築由兩層樓的中央主體與左右兩翼平房組成，呈L形對稱，入口玄關為圓弧造型，中央牆體較厚以凸顯官署的權威感。戰後改為臺中縣稅捐處南投分處，1950年南投設縣後成為南投縣稅捐稽徵處；因屋頂漏水改成斜屋頂，兩翼也加蓋二樓，成為今天的外觀。2018年以ROT方式委外經營，轉型為文創空間。","highlights":["圓弧造型的入口玄關","樓梯間高達352公分的大窗","樓梯扶手鏤空波浪紋鐵件"],"funFact":"經營團隊以貓作吉祥物，取名「蘿西家族」，就是「貓羅溪」的諧音。","photoSpot":"在中山街對面拍圓弧玄關與立面","visitMin":30,"openNote":"位於南投市康壽里中山街，以ROT方式委外經營，依官方資料週一、週二未營業，其他營業時間以經營業者公告為準。可搭客運到南投市區後步行前往。","dialogue":[{"who":"R","text":"Allan，以前的稅務所，現在為什麼到處都是貓咪圖案？"},{"who":"A","text":"因為經營團隊用貓當吉祥物，叫「蘿西家族」，就是南投貓羅溪的諧音。"},{"who":"R","text":"哈哈，稅務所變成貓咪家族，這樣繳稅好像也沒那麼可怕了。"},{"who":"A","text":"這裡是日治時期臺中州第一個稅務出張所，1936年開始辦理南投郡的稅務。"},{"who":"R","text":"那以前是誰在這裡上班？大家怎麼分工？"},{"who":"A","text":"一樓分股辦直接稅、土地稅、地方稅，二樓是會議室，左翼最外側是所長辦公室。"},{"who":"R","text":"那外觀一直都長這樣嗎？還是有整形過？"},{"who":"A","text":"戰後屋頂漏水，平頂改成斜屋頂，兩翼也加蓋二樓，才變成現在的樣子。"},{"who":"R","text":"到現場我要找樓梯間那扇超高的大窗，看看陽光怎麼灑進來，再拍一張！"}],"clues":["我的吉祥物是貓，名字來自一條溪的諧音","我入口玄關是圓弧造型，樓梯間有一扇超高大窗","我是日治時期臺中州第一個稅務出張所"],"quiz":[{"q":"南投稅務出張所的吉祥物「蘿西家族」是哪條溪的諧音？","options":["濁水溪","烏溪","貓羅溪","陳有蘭溪"],"answer":2,"explain":"以貓為吉祥物，蘿西家族是貓羅溪的諧音。"},{"q":"南投稅務出張所在日治時期有什麼特殊地位？","options":["全臺最大稅務所","南投第一座洋樓","臺灣最早的郵局","臺中州第一個稅務出張所"],"answer":3,"explain":"是日治時期臺中州第一個設立的稅務出張所。"}],"images":[{"file":"NantouTaxoffice.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/eb/NantouTaxoffice.JPG/960px-NantouTaxoffice.JPG","page":"https://commons.wikimedia.org/wiki/File:NantouTaxoffice.JPG","artist":"Shxpeng","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/nantou-shuiwuchuzhangsuo-0.webp","small":"img/nantou-shuiwuchuzhangsuo-0-s.webp"}]},{"id":"nantou-wudedianjiqifushu","name":"武德殿及其附屬建築群","short":"南投武德殿","category":"歷史建築","level":"","town":"南投市","types":["其他設施"],"lat":23.909416,"lng":120.683986,"address":"南投縣南投市彰南路2 段65 號","announced":"2002-01-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020129000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-25/9e47c142-d707-4f3e-8e89-31aeb0e11a46/武德殿及其附屬建築群.jpg","year":1937,"yearText":"1937年（昭和12年）","era":"japan","themes":["日式建築","公共建築","震災重建"],"yearUnknown":false,"summary":"鬼瓦上刻「武」字的道場，今為縣史館","intro":"南投武德殿及其附屬建築群位於南投市彰南路二段，1937年由大日本武德會南投支所興建，供軍警與學生練習柔道、劍道。棟札記載由鈴木金吉設計、森脇岩夫施作。建築為仿唐式和風的入母屋造，也就是捲棚歇山式，基座架高成兩段，需沿台階步步登上；屋脊經卷型鬼瓦中央有「武」字，山牆有木製懸魚與通氣格柵。戰後曾作縣警察局等辦公處，1997年成為縣史館，921大地震嚴重損毀，2001年修復再啟用，2022年再完成第二期修復。","highlights":["屋脊鬼瓦中央的「武」字","山牆的木製懸魚與通氣格柵","架高兩段式基座與入口台階"],"funFact":"武德殿的建造資訊寫在棟札上，連設計者、施工匠師和監造人的名字都留了下來。","photoSpot":"在台階前仰拍屋脊「武」字鬼瓦","visitMin":40,"openNote":"位於南投市彰南路二段，現為南投縣文化園區，設有縣史館、藝術家資料館與南投陶展示館，依官方資料09:00至17:00開放，休館日以文化局公告為準。可搭客運到南投市區。","dialogue":[{"who":"R","text":"Allan，屋頂上那個大大的字是「武」嗎？好有氣勢！"},{"who":"A","text":"沒錯，那是經卷型鬼瓦，中央刻「武」，代表武道精神。這裡是1937年蓋的南投武德殿。"},{"who":"R","text":"武德殿是練武功的地方嗎？像武俠小說那樣飛來飛去？"},{"who":"A","text":"比較接近體育館。當時軍警和學生在這裡練柔道、劍道，可惜沒有輕功課程。"},{"who":"R","text":"為什麼要走那麼多台階才能進去？"},{"who":"A","text":"基座架高兩段，一步步往上走，有參拜的莊嚴感，也比較通風防潮。"},{"who":"R","text":"那它現在還有人在這裡練劍道嗎？"},{"who":"A","text":"現在是南投縣文化園區，有縣史館和南投陶展示。921震損後修好，2022年又完成修復。"},{"who":"R","text":"到現場我要站在台階下面，抬頭把武字鬼瓦和懸魚一起拍進來！"}],"clues":["我的屋脊鬼瓦中央刻著一個武字","我是捲棚歇山式和風建築，要爬台階才能進門","我在南投市彰南路，今天是縣史館所在的文化園區"],"quiz":[{"q":"武德殿屋脊鬼瓦中央刻著什麼字？","options":["武","德","忠","道"],"answer":0,"explain":"經卷型鬼瓦正中央標示「武」字，象徵武道精神。"},{"q":"南投武德殿現在作為什麼用途？","options":["警察局辦公室","南投縣文化園區","劍道社團會館","福利品供應中心"],"answer":1,"explain":"現為南投縣文化園區，設有縣史館等展示空間。"}],"images":[]},{"id":"caotun-xinzhuangguoxiaori","name":"新庄國小日治宿舍","short":"新庄國小宿舍","category":"歷史建築","level":"","town":"草屯鎮","types":["其他設施"],"lat":23.995361,"lng":120.668955,"address":"南投縣草屯鎮草屯鎮新庄里新庄三路32號","announced":"2009-04-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20090423000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-09-08/adc16334-e343-4bc6-8d34-9fbbaf4068bf/新庄國小日治宿舍.jpg","year":1938,"yearText":"1938年（昭和13年）B棟竣工","era":"japan","themes":["日式建築","教育設施"],"yearUnknown":false,"summary":"校園側門旁兩排日式教師宿舍","intro":"新庄國小日治宿舍位於草屯鎮新庄里新庄國小校園側門旁。新庄國小源自1914年借洪姓家廟上課的草鞋墩公學校新庄分校，1920年獨立為新庄公學校。校園保留兩排昭和時期的日式木造教師宿舍，B棟1938年竣工、A棟1940年竣工，目前僅存五戶，兩排南北相向，中間隔著馬路。建築有磚造基座與通氣格柵，牆身為編竹夾泥牆與雨淋板，屋頂有切妻式與入母屋式，室內保有玄關、座敷、緣側、炊事場等日式空間配置。","highlights":["基座上的通氣格柵","雨淋板外牆與日式瓦屋頂","外凸窗台與左右拉窗"],"funFact":"新庄國小剛創立時沒有校舍，是借洪姓家廟燉煌堂上課的。","photoSpot":"在校外道路拍宿舍雨淋板與屋頂","visitMin":15,"openNote":"位於草屯鎮新庄里新庄國小校園內，上課時間請勿進入，開放情形以學校公告為準。部分宿舍仍有眷屬居住，請勿打擾。","dialogue":[{"who":"R","text":"Allan，這兩排木頭房子好像日劇裡的場景！"},{"who":"A","text":"眼光不錯，這是新庄國小的日治教師宿舍，1938年和1940年先後完工。"},{"who":"R","text":"那老師們以前住在這裡，上班只要走幾步路？"},{"who":"A","text":"對，標準的走路上班族。我每天塞車的時候都很羨慕這種通勤距離。"},{"who":"R","text":"房子下面那些小格子是什麼？是給貓咪進出的門嗎？"},{"who":"A","text":"那是基座的通氣格柵，讓地板下空氣流通，防潮又防蟲，是日式住宅的小智慧。"},{"who":"R","text":"裡面的格局也跟日本房子一樣嗎？有沒有榻榻米？"},{"who":"A","text":"有玄關、座敷、緣側和炊事場。現在只剩五戶，還有一戶有人住，要保持安靜。"},{"who":"R","text":"那我在外面找找看，雨淋板一片一片疊起來，像不像魚鱗？順便拍下來！"}],"clues":["我的基座下有通氣格柵，牆面是一片片雨淋板","我是兩排南北相向的日式木造教師宿舍","我在草屯一所國小的側門旁，建於昭和時期"],"quiz":[{"q":"宿舍基座上的通氣格柵主要功能是什麼？","options":["裝飾門面","排放炊煙","讓地板下通風防潮","當作信箱"],"answer":2,"explain":"基座設通氣格柵，讓地板下空氣流通。"},{"q":"新庄國小剛創立時借用哪裡上課？","options":["媽祖廟","製糖會社","庄役場","洪姓家廟"],"answer":3,"explain":"1914年新庄分校借洪姓家廟上課。"}],"images":[{"file":"草屯新庄國小日式宿舍.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3a/%E8%8D%89%E5%B1%AF%E6%96%B0%E5%BA%84%E5%9C%8B%E5%B0%8F%E6%97%A5%E5%BC%8F%E5%AE%BF%E8%88%8D.JPG/960px-%E8%8D%89%E5%B1%AF%E6%96%B0%E5%BA%84%E5%9C%8B%E5%B0%8F%E6%97%A5%E5%BC%8F%E5%AE%BF%E8%88%8D.JPG","page":"https://commons.wikimedia.org/wiki/File:%E8%8D%89%E5%B1%AF%E6%96%B0%E5%BA%84%E5%9C%8B%E5%B0%8F%E6%97%A5%E5%BC%8F%E5%AE%BF%E8%88%8D.JPG","artist":"Pbdragonwang","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/caotun-xinzhuangguoxiaori-0.webp","small":"img/caotun-xinzhuangguoxiaori-0-s.webp"}]},{"id":"zhushan-shensheniaojujizhu","name":"竹山神社鳥居及竹山神社附屬設施","short":"竹山神社鳥居","category":"歷史建築","level":"","town":"竹山鎮","types":["牌坊"],"lat":23.757863,"lng":120.671699,"address":"南投縣竹山鎮竹山鎮公所路100號","announced":"2018-06-06","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20190502000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-09-01/e4981612-f594-47f4-ae38-7e70620db2f4/竹山神社及其附屬設施.jpg","year":1938,"yearText":"1938年（昭和13年）","era":"japan","themes":["宗教信仰","紀念地景"],"yearUnknown":false,"summary":"竹山公園入口僅存的神社鳥居","intro":"竹山神社鳥居及附屬設施位於竹山鎮竹山公園內、鎮公所旁。竹山神社創建於1938年，屬日本國家神道，社格為鄉社，參道兩旁原設有成對的石燈籠與二葉松，並建有三座鳥居。戰後改為忠烈祠；1975年鎮公所遷到現址，神社因公園與公所用地需要，大部分建物被拆除，只留神主宿舍充作鎮長宿舍。1982年原神社區域改建為竹山公園，1992年興建古典迴廊時，把狛犬與未損毀的石燈籠移到迴廊前。1999年921大地震後，神主宿舍因破損不堪而拆除。如今只剩入口處一座鳥居，2018年與附屬設施一起登錄為歷史建築。","highlights":["入口處僅存的一座鳥居","移到古典迴廊前的狛犬與石燈籠","公園入口僅存的一棵二葉松"],"funFact":"神社原本有三座鳥居，分別在入口、洗手槽和神殿前，如今只剩入口那一座。","photoSpot":"從鳥居下方往公園內取景","visitMin":20,"openNote":"位於竹山鎮竹山公園內，鄰近竹山鎮公所，公園為戶外空間，可自由散步參觀；請勿攀爬鳥居與石燈籠。可搭客運到竹山。","dialogue":[{"who":"R","text":"Allan，這座兩根柱子加上橫樑的大門，就是日本神社的鳥居吧？"},{"who":"A","text":"答對！竹山神社1938年創建，原本有三座鳥居，現在只剩入口這一座。"},{"who":"R","text":"那另外兩座鳥居後來都跑去哪裡了？"},{"who":"A","text":"戰後神社改成忠烈祠，1975年鎮公所搬來、1982年改建公園，很多建物都被拆掉了。"},{"who":"R","text":"那它真的是一個孤單的倖存者耶。"},{"who":"A","text":"它還有夥伴喔！1992年蓋古典迴廊時，把狛犬和沒壞的石燈籠移到了迴廊前面。"},{"who":"R","text":"狛犬就是那種長得像獅子的守護犬嗎？"},{"who":"A","text":"對，可以想成神社的保全。神主宿舍原本也還在，921大地震後破損才拆除。"},{"who":"R","text":"我的任務是在公園入口找到那棵留下來的二葉松，跟它說聲辛苦了！"}],"clues":["我原本有兩個兄弟，現在只剩我守在入口","我身後的狛犬和石燈籠被搬到了古典迴廊前","我是竹山公園入口那座日治神社的大門"],"quiz":[{"q":"竹山神社創建於哪一年？","options":["1922年","1938年","1945年","1975年"],"answer":1,"explain":"竹山神社創建於1938年。"},{"q":"竹山神社原本建有幾座鳥居？","options":["一座","兩座","三座","四座"],"answer":2,"explain":"原有入口、洗手槽與神殿前三座鳥居。"}],"images":[{"file":"竹山神社鳥居.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a1/%E7%AB%B9%E5%B1%B1%E7%A5%9E%E7%A4%BE%E9%B3%A5%E5%B1%85.jpg/960px-%E7%AB%B9%E5%B1%B1%E7%A5%9E%E7%A4%BE%E9%B3%A5%E5%B1%85.jpg","page":"https://commons.wikimedia.org/wiki/File:%E7%AB%B9%E5%B1%B1%E7%A5%9E%E7%A4%BE%E9%B3%A5%E5%B1%85.jpg","artist":"Pbdragonwang","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/zhushan-shensheniaojujizhu-0.webp","small":"img/zhushan-shensheniaojujizhu-0-s.webp"}]},{"id":"yuchi-xingzhengyuannong","name":"行政院農業委員會茶業改良場魚池分場","short":"魚池茶改場","category":"歷史建築","level":"","town":"魚池鄉","types":["其他設施"],"lat":23.876908,"lng":120.91347,"address":"南投縣魚池鄉魚池鄉水社村中山路270巷13號","announced":"2004-12-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20110415000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-10-02/d765d11a-da1e-4000-96c1-a303e7adfb38/行政院農業委員會茶業改良場魚池分場.jpg","year":1938,"yearText":"1938年（日治昭和13年）製茶工廠落成","era":"japan","themes":["茶業農業","產業遺產"],"yearUnknown":false,"summary":"老銅機仍在運轉的英國傳統式紅茶工廠","intro":"位於魚池鄉水社村，貓欄山東南方。前身是1936年成立的「臺灣總督府中央研究所魚池紅茶試驗支所」，製茶工廠於1938年興建，是大葉種紅茶的研究中心；戰後幾經改制，1999年起為農委會茶業改良場魚池分場。工廠被稱為臺灣碩果僅存的英國傳統式製茶工廠：一樓加強磚造，二、三樓為檜木雨淋板；東西向少開窗以避免日曬，靠南北長邊採光，並用可推拉隔板調節溫度與通風。第一代銅製機具至今仍能運轉。分場在1999年育成台茶18號，茶農稱為「森林紅茶」。921大地震後，工廠與日式宿舍一同登錄為歷史建築。","highlights":["一樓磚造、上層檜木雨淋板的製茶工廠","仍能運轉的第一代銅製製茶機具","東西少窗、南北採光的溫控設計"],"funFact":"台茶18號帶有天然肉桂香與薄荷味，茶農稱它「森林紅茶」。","photoSpot":"在外圍拍檜木雨淋板的工廠立面","visitMin":20,"openNote":"官方資料註明為工作區域，不開放參觀，請在外觀參觀並遵守場方公告。位於魚池鄉水社村，可搭往日月潭的客運到魚池一帶。","dialogue":[{"who":"A","text":"阿拉蕾，日月潭除了湖景，還有一樣東西很有名，就是魚池的紅茶。"},{"who":"R","text":"我知道！紅茶配總統魚，一口湖鮮一口茶。"},{"who":"A","text":"搭配很有創意。這裡日治時期是魚池紅茶試驗支所，1938年蓋了這座製茶工廠。"},{"who":"R","text":"工廠有什麼好看的？不就是一堆機器嗎？"},{"who":"A","text":"這可是被稱為臺灣碩果僅存的英國傳統式製茶工廠，第一代銅製機具到現在還能運轉。"},{"who":"R","text":"快九十歲的機器還在上班，比我還勤勞耶！"},{"who":"A","text":"建築也很聰明，東西兩側少開窗避免日曬，用推拉隔板調整通風和溫度。這裡還育成了台茶18號。"},{"who":"R","text":"台茶18號，就是聽說有肉桂香的那款嗎？"},{"who":"A","text":"對，茶農叫它森林紅茶。工廠是工作區，請在外面看，數數二樓雨淋板牆上有幾扇窗。"}],"clues":["我前身是日治時期的紅茶試驗支所","我的第一代銅製機器至今仍能運轉","我在日月潭附近，育成了被稱為森林紅茶的品種"],"quiz":[{"q":"魚池分場的製茶工廠興建於哪一年？","options":["1916年","1955年","1973年","1938年"],"answer":3,"explain":"製茶工廠興建於日治昭和13年，即1938年。"},{"q":"台茶18號被茶農稱為什麼？","options":["東方美人","森林紅茶","凍頂烏龍","蜜香紅茶"],"answer":1,"explain":"台茶18號具肉桂香與薄荷味，茶農稱森林紅茶。"}],"images":[]},{"id":"zhushan-taizhongyanyechang","name":"台中菸葉場竹山輔導站(原專賣局臺中支局竹山葉煙草收納場)","short":"竹山菸葉輔導站","category":"歷史建築","level":"","town":"竹山鎮","types":["產業"],"lat":23.757352,"lng":120.685849,"address":"南投縣竹山鎮竹山鎮竹山里祖師街32號","announced":"2005-10-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20190502000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-15/453d6fe1-45b4-4562-876e-85bb33f6af56/台中菸葉場竹山輔導站.jpg","year":1941,"yearText":"1941年（昭和16年）","era":"japan","themes":["產業遺產","日式建築"],"yearUnknown":false,"summary":"竹山菸草盛世的收購倉庫","intro":"台中菸葉場竹山輔導站位於竹山鎮竹山里祖師街，原為專賣局臺中支局竹山葉煙草收納場。日治時期竹山是菸草種植重鎮，這裡在每年菸葉盛產期負責集中收購與倉儲。建築為L型配置，1941年完工時已具備目前雛型，1957年增建打包場與走廊，1978年增建貨車雨棚。木造平房下方為磚造，外牆上方是雨淋板，屋頂採中柱式屋架並覆黑土瓦。戰後改稱公賣局台中菸葉場竹山輔導站，業務縮減後由國有財產局收回；921震災災後重建推動委員會函請登錄，2005年登錄歷史建築，之後交由竹山鎮公所管理並修復，現部分作餐廳、部分為藝文展覽空間。","highlights":["L型配置的菸草收納場","下方磚造、上方雨淋板的外牆","中柱式屋架與黑土瓦屋頂"],"funFact":"這裡能被登錄，是921震災災後重建推動委員會在2002年發函建議依程序申請登錄。","photoSpot":"在祖師街側拍L型倉庫與黑瓦","visitMin":30,"openNote":"位於竹山鎮竹山里祖師街，現由竹山鎮公所委外經營，部分為餐廳、部分為藝文展覽空間；官方資料記載週二未營業，其餘日11:00至20:30，實際以現場公告為準。可搭客運到竹山。","dialogue":[{"who":"A","text":"阿拉蕾，猜猜看，這間長長的老倉庫以前裝的是什麼？"},{"who":"R","text":"竹山出竹筍和番薯，所以是裝竹筍？還是番薯？"},{"who":"A","text":"都不是，答案是菸葉！日治時期竹山是菸草種植重鎮，這裡就是專賣局的葉煙草收納場。"},{"who":"R","text":"原來是菸葉的大倉庫，那農民都把菸葉送來這裡嗎？"},{"who":"A","text":"對，每年盛產期在這裡集中收購和倉儲。1941年完工時就有現在的這種轉角形狀。"},{"who":"R","text":"外牆上半部那一片片木板好眼熟，好像在集集也看過。"},{"who":"A","text":"沒錯，那叫雨淋板，下面是磚造，屋頂是黑土瓦，標準的老倉庫穿搭。"},{"who":"R","text":"那現在這間倉庫裡裝的是什麼呢？"},{"who":"A","text":"現在由鎮公所委外經營，有餐廳也有藝文展覽空間。請妳找找看，後來增建的貨車雨棚在哪一側。"}],"clues":["我是一棟L型的老倉庫，屋頂蓋著黑土瓦","每到收成季，農民就把曬好的葉子送來給我","我是竹山祖師街上的日治菸葉收納場"],"quiz":[{"q":"這座收納場原本用來收購與倉儲什麼？","options":["稻米","樟腦","茶葉","菸葉"],"answer":3,"explain":"日治時期竹山是菸草種植重鎮。"},{"q":"這棟建築的平面配置是什麼形狀？","options":["L型","口字型","圓形","一字型"],"answer":0,"explain":"屬於L型的菸草收納場空間配置。"}],"images":[{"file":"原專賣局臺中支局竹山葉煙草收納場.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bc/%E5%8E%9F%E5%B0%88%E8%B3%A3%E5%B1%80%E8%87%BA%E4%B8%AD%E6%94%AF%E5%B1%80%E7%AB%B9%E5%B1%B1%E8%91%89%E7%85%99%E8%8D%89%E6%94%B6%E7%B4%8D%E5%A0%B4.jpg/960px-%E5%8E%9F%E5%B0%88%E8%B3%A3%E5%B1%80%E8%87%BA%E4%B8%AD%E6%94%AF%E5%B1%80%E7%AB%B9%E5%B1%B1%E8%91%89%E7%85%99%E8%8D%89%E6%94%B6%E7%B4%8D%E5%A0%B4.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%8E%9F%E5%B0%88%E8%B3%A3%E5%B1%80%E8%87%BA%E4%B8%AD%E6%94%AF%E5%B1%80%E7%AB%B9%E5%B1%B1%E8%91%89%E7%85%99%E8%8D%89%E6%94%B6%E7%B4%8D%E5%A0%B4.jpg","artist":"Pbdragonwang","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/zhushan-taizhongyanyechang-0.webp","small":"img/zhushan-taizhongyanyechang-0-s.webp"}]},{"id":"zhushan-junyisuozuozhanzhi","name":"竹山郡役所作戰指揮所(防空壕)","short":"竹山郡役所防空壕","category":"歷史建築","level":"","town":"竹山鎮","types":["其他設施"],"lat":23.757801,"lng":120.682102,"address":"南投縣竹山鎮竹山里大禮路12巷1號旁","announced":"2019-04-17","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20190424000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-08-30/302e92a2-c268-4fee-8aab-da6dfd4f2422/竹山郡役所作戰指揮所(防空壕)入口.jpg","year":1944,"yearText":"約1944年（日治昭和19年）","era":"japan","themes":["軍事遺構","公共建築"],"yearUnknown":false,"summary":"有辦公室和水泥桌椅的戰時「五星級」防空壕","intro":"位於竹山鎮竹山里大禮路巷內，在舊警察局長官舍前、郡守官舍後方不遠處。依1944年1月1日出版的〈台灣總督府官報〉告示，依都市計畫令在全台興建36座防空壕，竹山這座是其中之一。它是半地下式的鋼筋混凝土構造，內有走道和兩間「辦公室」，混凝土長桌、長椅俱全，面積約148平方公尺，推測是郡守戰時指揮與避難之用。竹山位在美軍轟炸集集線鐵路與日月潭電力設施的要道上，這座防空壕見證了戰爭末期的地方行政與警察體制。2019年登錄為歷史建築，現況保存良好。","highlights":["半地下式鋼筋混凝土構造的入口","內部兩間「辦公室」與混凝土長桌長椅","周邊仍留存的日治時期宿舍群"],"funFact":"官方說明形容它比現存多數防空壕都氣派，堪稱戰時的「五星級」防空壕。","photoSpot":"在入口拍半地下式的混凝土結構","visitMin":20,"openNote":"官方資料標示24小時，位於竹山鎮竹山里大禮路巷內，目前閒置、由南投縣政府警察局管理維護，內部是否開放以現場公告為準。可從高鐵臺中站或臺鐵二水站轉搭客運到竹山市區。","dialogue":[{"who":"A","text":"阿拉蕾，今天我們不逛廟，要往地底下鑽，去看一座戰爭時期的防空壕。"},{"who":"R","text":"防空壕？不就是一個黑漆漆的土洞嗎？有什麼好看的？"},{"who":"A","text":"這座可不一樣，裡面有走道和兩間辦公室，連混凝土做的長桌長椅都有，被形容成五星級防空壕。"},{"who":"R","text":"五星級？那有沒有附早餐和客房服務啊？"},{"who":"A","text":"早餐沒有，空襲警報倒是有。1944年官報公告要在全台蓋36座防空壕，竹山這座就是其中之一。"},{"who":"R","text":"為什麼連竹山這樣的小鎮也要蓋？"},{"who":"A","text":"因為竹山在美軍要轟炸的集集線鐵路和日月潭電力設施的要道上，推測這裡是郡守指揮和避難的地方。"},{"who":"R","text":"原來躲警報的時候，長官還要在地底下開會，真辛苦。"},{"who":"A","text":"到現場請找找入口的半地下式結構，想像當年空襲警報響起時，大家往下跑的心情。"}],"clues":["我是依戰爭末期官報公告興建的36座之一","我半埋在地下，裡面有混凝土長桌和兩間辦公室","我在竹山郡守官舍附近，被稱為戰時的五星級避難所"],"quiz":[{"q":"依1944年官報告示，全台要依都市計畫令興建幾座這類防空壕？","options":["18座","24座","36座","48座"],"answer":2,"explain":"官報告示指定在全台興建36座防空壕。"},{"q":"這座防空壕內部有什麼特別的設施？","options":["混凝土長桌與長椅","地下水井與廚房","鐵軌與運煤車","神龕與石燈籠"],"answer":0,"explain":"內有走道、兩間辦公室與混凝土長桌長椅。"}],"images":[{"file":"竹山防空壕.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/87/%E7%AB%B9%E5%B1%B1%E9%98%B2%E7%A9%BA%E5%A3%95.jpg/960px-%E7%AB%B9%E5%B1%B1%E9%98%B2%E7%A9%BA%E5%A3%95.jpg","page":"https://commons.wikimedia.org/wiki/File:%E7%AB%B9%E5%B1%B1%E9%98%B2%E7%A9%BA%E5%A3%95.jpg","artist":"Pbdragonwang","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/zhushan-junyisuozuozhanzhi-0.webp","small":"img/zhushan-junyisuozuozhanzhi-0-s.webp"}]},{"id":"jiji-guan","name":"集集館","short":"集集館","category":"歷史建築","level":"","town":"集集鎮","types":["宅第"],"lat":23.827906,"lng":120.781231,"address":"南投縣集集鎮集集鎮和平里8鄰集集街142號","announced":"2017-10-18","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20181004000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-20/7219994c-b29c-4ccd-963f-0e2d1e6750b7/集集館.jpg","year":1950,"yearText":"日治昭和年間創建，1950年改建完成","era":"postwar","themes":["宅第家族","日式建築"],"yearUnknown":false,"summary":"旅社改建的和洋混合庭園洋房","intro":"集集館位於集集鎮集集街，原是日治昭和年間由日本人江川氏興建的「集集館」旅社。戰後由集集鎮公所接收，1946年地方人士購得作為私人住宅，1948年聘請竹山水底寮的木工師傅，參考當時流行的現代日式風格改建為和洋混合的建築，並保留日治末期的浴室，1950年落成。宅院有假山、拱橋、流水、蓮池與幽徑，後臨清水溪；建築本體少裝飾，兼具日式建築的古典美與現代主義風格。1999年921大地震受損，修復後曾被中原大學命名為「清水花園」。2017年登錄歷史建築，仍屬私有，目前閒置待整修。","highlights":["和洋混合、少裝飾的近代住宅外觀","連接屋內外庭園的外廊","大門兩側修復過的門柱"],"funFact":"名字叫集集館，是因為它的前身是日治時期的旅社，戰後才變成住家。","photoSpot":"在集集街上拍建築外觀與門柱","visitMin":10,"openNote":"位於集集鎮集集街，屬私有歷史建築，目前閒置待整修、不對外開放；請在外觀參觀，勿擅自進入。可從集集火車站步行前往。","dialogue":[{"who":"R","text":"Allan，集集館聽起來像旅館，我們今晚要住這裡嗎？"},{"who":"A","text":"可惜不行。它以前真的是旅社，是日治昭和年間日本人江川氏開的集集館。"},{"who":"R","text":"那後來呢？旅社老闆回日本了嗎？"},{"who":"A","text":"戰後被鎮公所接收，1946年地方人士買下當住家，還請竹山水底寮的木工師傅來改建。"},{"who":"R","text":"那他們把房子改成了什麼風格呢？"},{"who":"A","text":"和洋混合，日式骨架配上現代主義的簡潔，1950年落成，還保留了日治末期的浴室。"},{"who":"R","text":"連浴室都留下來，原來老房子也有泡澡情懷。"},{"who":"A","text":"院子以前有假山、拱橋和蓮池。921大地震受損後，現在閒置等待整修，而且還是私人產業。"},{"who":"R","text":"那我們就在門外欣賞，我的任務是拍下大門兩側修復過的門柱。"}],"clues":["我的前身是讓旅人過夜的地方","竹山水底寮的木工師傅把我改成和洋混合的樣子","我是集集街上一棟以鎮名為名的日式洋房"],"quiz":[{"q":"集集館的前身是什麼？","options":["公學校","郵便局","製腦所","旅社"],"answer":3,"explain":"原是日治昭和年間江川氏興建的旅社。"},{"q":"1948年改建集集館的木工師傅來自哪裡？","options":["竹山水底寮","鹿港","大溪","埔里"],"answer":0,"explain":"聘請竹山水底寮的木工師傅改建。"}],"images":[{"file":"陳慶仁故居 01.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/de/%E9%99%B3%E6%85%B6%E4%BB%81%E6%95%85%E5%B1%85_01.jpg/960px-%E9%99%B3%E6%85%B6%E4%BB%81%E6%95%85%E5%B1%85_01.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%99%B3%E6%85%B6%E4%BB%81%E6%95%85%E5%B1%85_01.jpg","artist":"Pbdragonwang","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jiji-guan-0.webp","small":"img/jiji-guan-0-s.webp"}]},{"id":"jiji-tianxingyaojiqifu","name":"添興窯及其附屬設施","short":"添興窯","category":"歷史建築","level":"","town":"集集鎮","types":["產業"],"lat":23.832878,"lng":120.755274,"address":"南投縣集集鎮集集鎮田寮里楓林巷10號","announced":"2009-07-10","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20090710000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-08-21/b0184cea-f1ea-41e8-8e59-8d8740a2cb6b/添興窯及其附屬設施(蛇窯內部空間).jpg","year":1955,"yearText":"1955年（民國44年）","era":"postwar","themes":["產業遺產","震災重建"],"yearUnknown":false,"summary":"震後重生、仍在柴燒的老蛇窯","intro":"添興窯位於集集鎮田寮里，1955年由林陳梅女士率子創立，初期專做水缸、酒甕等實用粗陶與琉璃瓦。1963年購置大型練土機提升品質；1980年代塑膠與玻璃製品普及，粗陶競爭力下降，窯場逐步轉向生活陶藝，並開設陶藝教室。登錄的蛇窯是創窯時建的第一座，依15度斜坡砌築，總長95台尺，左右共有50個窯窗。1999年921大地震時窯體幾乎全毀，2000年8月3日修復完成，官方資料記載是臺灣現存仍實際燒窯的最老蛇窯。一同登錄的老事務所與人力沖床，見證戰後臺灣陶業的發展。","highlights":["沿15度斜坡砌築、左右共50個窯窗的蛇窯","不燒窯時可走進窯內看燒窯痕跡","創窯時用來印製琉璃瓦的人力沖床"],"funFact":"燒一窯要3萬到4萬台斤薪柴；為了讓老窯長壽，平常只裝三分之一，其餘空燒。","photoSpot":"在窯頭往上拍長長的蛇窯窯身","visitMin":60,"openNote":"位於集集鎮田寮里，官方資料記載週四休息，其餘每日9:00至17:30；陶藝體驗等活動以窯場公告為準。可搭臺鐵集集線到集集站，再轉乘或騎單車前往。","dialogue":[{"who":"R","text":"Allan，這座窯長長地趴在山坡上，好像一條在曬太陽的大蛇！"},{"who":"A","text":"所以叫蛇窯啊！添興窯1955年創立，這座就是創窯時蓋的第一座蛇窯。"},{"who":"R","text":"七十歲的老蛇，現在還能工作嗎？"},{"who":"A","text":"可以！它沿15度斜坡砌築，總長95台尺，左右各有25個窯窗，至今還會柴燒。"},{"who":"R","text":"那921大地震的時候，它沒有被嚇壞吧？"},{"who":"A","text":"被震得幾乎全毀，窯場一家人克服重重困難，2000年8月終於修好，重新點火。"},{"who":"R","text":"好感人！那燒一次窯要用掉多少柴？"},{"who":"A","text":"大約3萬到4萬台斤，比我一輩子吃的集集香蕉還重好幾倍。"},{"who":"R","text":"聽說不燒窯的時候可以走進窯裡面，我要好好找找窯壁上七十年燒窯留下的痕跡！"}],"clues":["我身長95台尺，左右兩邊共有50扇小窗","大地震把我震得幾乎全毀，隔年夏天我又重新點火","我是集集一座仍在柴燒的老蛇窯"],"quiz":[{"q":"這座蛇窯在哪一次災害後修復重生？","options":["八七水災","921大地震","莫拉克颱風","桃芝颱風"],"answer":1,"explain":"921地震幾乎全毀，2000年8月修復完成。"},{"q":"這座蛇窯左右共有幾個窯窗？","options":["12個","25個","50個","80個"],"answer":2,"explain":"左右窯窗各25個，共50個。"}],"images":[]},{"id":"nantou-jiaotongbujiaotong","name":"交通部交通事業管理小組(原臺灣省政府交通處)","short":"原省府交通處","category":"歷史建築","level":"","town":"南投市","types":["辦公廳舍"],"lat":23.957484,"lng":120.686142,"address":"南投縣南投市南投市中興新村省府路6號","announced":"2011-04-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20190507000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-09-13/9af2cd7f-1089-49e3-8511-3b9a9e0feae6/交通部交通事業管理小組(原臺灣省政府交通處).jpg","year":1956,"yearText":"約1950年代中後期（中興新村初期，確切竣工年未載）","era":"postwar","themes":["省府中興新村","公共建築","鐵道交通"],"yearUnknown":false,"summary":"掌管全省交通的轉折型辦公廳","intro":"交通部交通事業管理小組（原臺灣省政府交通處）位於南投市中興新村省府路，由有巢建築師事務所虞曰鎮建築師設計，是省府時代的核心廳舍之一。建築屬類國際式樣現代建築，配合基地採轉折型平面，主入口設在短向轉折處；水平的橫開窗、梁線、窗台與遮陽板強調水平感，垂直遮陽板與柱列又形成重複韻律。1999年配合精省改制為交通部中部辦公室，2002年更名交通事業管理小組，2023年組織調整後又稱交通部中部辦公室。2020至2022年完成耐震補強。","highlights":["轉折型平面與設在轉角的主入口","水平橫開窗與遮陽板的線條","垂直遮陽板與柱列的重複韻律"],"funFact":"這棟樓的機關名稱從交通處、中部辦公室、交通事業管理小組，最後又回到中部辦公室。","photoSpot":"在省府路旁拍轉角主入口與遮陽板","visitMin":10,"openNote":"位於南投市中興新村省府路，目前為機關辦公使用，請在外觀參觀，開放情形以交通部公告為準。可搭客運到中興新村，與臺灣省政府大樓一起散步參觀。","dialogue":[{"who":"R","text":"Allan，這棟樓的招牌名字也太長了吧，我念到一半就斷氣了。"},{"who":"A","text":"它的名字還換過好幾次。原本是臺灣省政府交通處，負責全省的交通事務。"},{"who":"R","text":"換過名字？那後來又改成什麼了？"},{"who":"A","text":"1999年精省後改成交通部中部辦公室，2002年叫交通事業管理小組，2023年又叫回中部辦公室。"},{"who":"R","text":"繞了一大圈回到原點，好像搭公車坐過站又坐回來！"},{"who":"A","text":"管交通的單位，名字也跟著繞圓環，這樣講是不是很合理？"},{"who":"R","text":"名字聽懂了，那建築本身有什麼看頭？"},{"who":"A","text":"它配合基地轉了個彎，主入口就在轉角處，外牆有一條條水平窗帶和遮陽板。"},{"who":"R","text":"那我到現場先找轉角的大門，再拍一張遮陽板排排站的照片！"}],"clues":["我的名字換來換去，最後又回到中部辦公室","我的平面轉了個彎，主入口就在轉角","我在中興新村省府路，以前管全省交通"],"quiz":[{"q":"這棟建築的主入口設在哪裡？","options":["短向轉折處","正中央","建築背面","二樓天橋"],"answer":0,"explain":"配合基地採轉折型平面，主入口設於短向轉折處。"},{"q":"這棟建築的設計者是誰？","options":["楊卓成建築師","虞曰鎮建築師","彭蔭宣建築師","鈴木金吉"],"answer":1,"explain":"由有巢建築師事務所虞曰鎮建築師設計。"}],"images":[]},{"id":"nantou-jingjibuzhongbuban","name":"經濟部中部辦公室(原臺灣省政府建設廳)","short":"原省府建設廳","category":"歷史建築","level":"","town":"南投市","types":["辦公廳舍"],"lat":23.957884,"lng":120.686261,"address":"南投縣南投市54003南投市省府路４號","announced":"2011-04-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20110413000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-22/8fee4264-ddab-4153-818e-3de3039f6772/經濟部中部辦公室.jpg","year":1956,"yearText":"1956年（民國45年）前後，中興新村初期","era":"postwar","themes":["省府中興新村","公共建築","產業遺產"],"yearUnknown":false,"summary":"從水庫管到攤販的原省府建設廳","intro":"經濟部中部辦公室（原臺灣省政府建設廳）位於南投市中興新村省府路，由有巢建築師事務所虞曰鎮建築師設計，是類國際式樣的現代建築，配合基地採轉折型平面，主入口設在短向轉折處，以橫開窗、梁線、遮陽板強調水平感，垂直遮陽板與柱列形成韻律。建設廳1947年由行政長官公署工礦處改設，掌理工業、商業、礦業、都市計畫、手工業輔導與零售市場攤販管理等，並督導水利局、石門水庫管理局等機關。1999年7月改設經濟部中部辦公室，2021年完成耐震補強。","highlights":["橫開窗與遮陽板構成的水平線條","垂直遮陽板與柱列的重複韻律","轉折型平面與轉角主入口"],"funFact":"建設廳的業務從石門水庫、礦業一路管到零售市場和攤販，連草屯的手工業研究所也是它的附屬機關。","photoSpot":"在省府路旁拍遮陽板與窗帶","visitMin":10,"openNote":"位於南投市中興新村省府路，目前為機關辦公使用，請在外觀參觀，開放情形以經濟部公告為準。可搭客運到中興新村，與省府大樓、原交通處一起步行參觀。","dialogue":[{"who":"A","text":"阿拉蕾，給妳一份工作清單：工業、商業、礦業、都市計畫、水庫，還有夜市攤販。"},{"who":"R","text":"這是什麼超人的工作？一個人做得完嗎？"},{"who":"A","text":"不是一個人，是一個廳。這就是臺灣省政府建設廳，1947年成立，管的範圍超大。"},{"who":"R","text":"連攤販都要管，那它是不是也管雞排要多大塊？"},{"who":"A","text":"那倒沒有。不過草屯的手工業研究所，就是它的附屬機關，我們前面才去過它的陳列館。"},{"who":"R","text":"原來有這層關係！那精省之後呢？"},{"who":"A","text":"1999年7月改設經濟部中部辦公室，現在還在這裡辦公，所以只能在外面看。"},{"who":"R","text":"那建築本身有什麼看頭？跟交通處像嗎？"},{"who":"A","text":"外牆一排排遮陽板很有節奏。到現場數數看，橫的遮陽板和直的柱子各有幾排吧！"}],"clues":["我以前從水庫、礦業一路管到攤販","我的立面有一排排水平窗帶與遮陽板","我在中興新村省府路，精省前是省府的一個廳"],"quiz":[{"q":"下列哪一個曾是省府建設廳的附屬機關？","options":["臺灣省手工業研究所","臺灣省立博物館","臺灣省交響樂團","臺灣省氣象局"],"answer":0,"explain":"手工業研究所、水利局等都是建設廳附屬機關。"},{"q":"原建設廳在1999年7月後改設為什麼單位？","options":["交通部中部辦公室","經濟部中部辦公室","內政部營建署","國家發展委員會"],"answer":1,"explain":"依暫行條例，建設廳裁併改設經濟部中部辦公室。"}],"images":[]},{"id":"nantou-xingzhengyuanren","name":"行政院人事行政局地方人事行政處(原臺灣省政府人事處)","short":"原省府人事處","category":"歷史建築","level":"","town":"南投市","types":["辦公廳舍"],"lat":23.958294,"lng":120.686402,"address":"南投縣南投市南投市中興新村省府路2號","announced":"2011-04-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20110413000011","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-22/b99a32b1-afd5-49cc-afd8-8a19e9807fc4/行政院人事行政局地方人事行政處(原臺灣省政府人事處).jpg","year":1957,"yearText":"年代不詳（省府時期興建）","era":"postwar","themes":["省府中興新村","公共建築"],"yearUnknown":true,"summary":"虞曰鎮設計的類國際式樣辦公廳舍","intro":"位於南投市中興新村省府路，前身是臺灣省政府人事處，由有巢建築師事務所的虞曰鎮建築師設計。建築屬「類國際式樣」的現代建築，是單邊走廊的教室型辦公廳舍，配合基地採轉折型平面，主入口設在短向轉折處；水平的橫開窗、樑線與遮陽板強調水平感，垂直遮陽板與柱列則形成重複的韻律，內部有中庭造景，明亮通風。1999年省府改制後，更名為行政院人事行政局地方人事行政處；2023年3月起改由內政部役政相關單位進駐使用，目前仍為機關辦公廳舍。","highlights":["轉折型平面與設在轉角的主入口","水平橫窗與垂直遮陽板交織的立面","省府路行政軸線上的省府時期廳舍"],"funFact":"中興新村的人事處、建設廳、農林廳等廳舍，都出自有巢建築師事務所虞曰鎮之手。","photoSpot":"在省府路側拍轉折立面與遮陽板","visitMin":10,"openNote":"位於南投市中興新村省府路，目前為機關辦公使用，請在外觀參觀；開放情形以各機關公告為準。可搭客運到中興新村，再步行串連省府路一帶廳舍。","dialogue":[{"who":"R","text":"Allan，這棟樓在中間轉了一個彎，好像在跟路人揮手打招呼。"},{"who":"A","text":"妳觀察很細喔！這是原臺灣省政府人事處，平面配合基地做成轉折型，主入口就在轉角。"},{"who":"R","text":"外牆一條一條橫線，看起來好整齊。"},{"who":"A","text":"那是水平橫窗、樑線和遮陽板，再配上垂直遮陽板和柱列，這種風格叫類國際式樣。"},{"who":"R","text":"聽起來像在說：我很現代，但是我很守規矩。"},{"who":"A","text":"形容得太好了！設計師是有巢建築師事務所的虞曰鎮，中興新村好幾棟廳舍都出自他手。"},{"who":"R","text":"那現在這裡還是人事處在使用嗎？"},{"who":"A","text":"1999年精省後改為地方人事行政處，2023年起由內政部役政相關單位使用，還在辦公。"},{"who":"R","text":"那我們不要進去打擾，在外面數一數立面上的垂直遮陽板有幾片就好。"}],"clues":["我的平面配合基地轉了一個彎，大門就開在轉角","我屬於類國際式樣，橫窗與遮陽板排得整整齊齊","省府時期，管理全省公務人員的單位在我這裡辦公"],"quiz":[{"q":"這棟原省府人事處廳舍由哪位建築師設計？","options":["修澤蘭","王大閎","沈祖海","虞曰鎮"],"answer":3,"explain":"由有巢建築師事務所虞曰鎮建築師設計。"},{"q":"這棟廳舍的主入口設在哪裡？","options":["中庭正中央","短向的轉折處","建築最北端","屋頂平台"],"answer":1,"explain":"配合轉折型平面，主入口設在短向轉折處。"}],"images":[]},{"id":"nantou-xingzhengyuannong2","name":"行政院農業委員會農糧署(原臺灣省政府農林廳)","short":"原省府農林廳","category":"歷史建築","level":"","town":"南投市","types":["辦公廳舍"],"lat":23.95515,"lng":120.687772,"address":"南投縣南投市中興新村光華路8號","announced":"2011-04-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20110413000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-22/20b49c92-2a20-4f24-b192-66855b007627/行政院農業委員會農糧署.jpg","year":1957,"yearText":"年代不詳（省府時期興建）","era":"postwar","themes":["省府中興新村","公共建築"],"yearUnknown":true,"summary":"原省府農林廳，今為農糧署辦公廳舍","intro":"位於南投市中興新村光華路，前身為臺灣省政府農林廳，由有巢建築師事務所虞曰鎮建築師設計，同樣是「類國際式樣」的現代建築，以單邊走廊的教室型辦公空間、轉折型平面及水平橫窗、遮陽板構成立面。1999年依「臺灣省政府功能業務與組織調整暫行條例」，原農林廳與糧食處裁併為農委會中部辦公室及第二辦公室，使中央與地方農政事權統一。2004年再整併成立農委會農糧署，2023年起為農業部農糧署。建物保存良好、持續使用，2018年曾進行屋頂與地坪防水修繕。","highlights":["虞曰鎮設計的類國際式樣立面","單邊走廊的教室型辦公廳舍","從省府農政中心到農糧署的轉變"],"funFact":"今天的農糧署，是由原省府農林廳和糧食處等單位一路整併而來。","photoSpot":"拍廳舍立面的水平窗帶與柱列","visitMin":10,"openNote":"位於南投市中興新村光華路，目前為機關辦公使用，請在外觀參觀；開放情形以各機關公告為準。可搭客運到中興新村。","dialogue":[{"who":"R","text":"Allan，你一路上都在講吃的，這棟建築總該跟吃沒關係了吧？"},{"who":"A","text":"關係可大了！這裡是原臺灣省政府農林廳，現在是農業部農糧署，管的就是大家的飯碗。"},{"who":"R","text":"原來是全臺灣便當的總部！那它怎麼變成農糧署的？"},{"who":"A","text":"1999年精省後，農林廳和糧食處裁併成農委會的中部辦公室和第二辦公室。"},{"who":"R","text":"兩個單位合體，好像機器人變身。"},{"who":"A","text":"2004年再整併成立農糧署，2023年農委會升格農業部，就成了現在的農業部農糧署。"},{"who":"R","text":"它跟隔壁的水保局長得好像兄弟。"},{"who":"A","text":"都是虞曰鎮設計的類國際式樣，單邊走廊像學校教室，橫窗和遮陽板排得整整齊齊。"},{"who":"R","text":"我的任務是在外面比一比，它和水保局的立面到底哪裡不一樣。"}],"clues":["我和糧食處的業務後來被整併在一起","我的設計者也設計了隔壁的水保局","省府時期全臺灣的農林政策從我這裡發出"],"quiz":[{"q":"原省府農林廳精省後和哪個單位一起裁併？","options":["建設廳","交通處","人事處","糧食處"],"answer":3,"explain":"農林廳與糧食處裁併為農委會中部及第二辦公室。"},{"q":"農糧署在哪一年整併成立？","options":["1999年","2001年","2004年","2023年"],"answer":2,"explain":"2004年整併成立農委會農糧署。"}],"images":[]},{"id":"nantou-zhonghuadianxin","name":"中華電信中興服務中心","short":"中興電信局","category":"歷史建築","level":"","town":"南投市","types":["其他設施"],"lat":23.956271,"lng":120.688212,"address":"南投縣南投市南投市中興新村光華路7號","announced":"2011-04-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20110413000009","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-15/7795f278-f9a5-4ca6-a5d4-5bd9a6da0f45/中華電信中興服務中心.jpg","year":1958,"yearText":"1958年（民國47年）","era":"postwar","themes":["省府中興新村","公共建築","震災重建"],"yearUnknown":false,"summary":"省府時代的電報電話與104查號台","intro":"中華電信中興服務中心位於南投市中興新村光華路。1955年交通部中興新村電信局成立，先借省建設廳一間辦公室臨時辦公，1958年完成這棟建築，1960年通話系統完工啟用。一樓後半部設步進式機房，前半部為營業廳，受理電報與電話業務；二樓設104查號台與108長途台話房，1983年撤銷併入南投。建築接近U字形平面，北向立面由花格磚與清水混凝土柱梁組成，外觀以灰色洗石子為主。加強磚造牆厚約1尺2，經歷921大地震仍屹立，2011年登錄為歷史建築。","highlights":["北向立面的花格磚牆","灰色洗石子外牆與細長比例","原木手工製作的窗戶"],"funFact":"二樓曾設104查號台和108長途台，接線生在這裡幫省府人打電話。","photoSpot":"從光華路拍北向花格磚立面","visitMin":10,"openNote":"位於南投市中興新村光華路，目前仍為電信營業與辦公使用，請在外觀參觀，營業時間以中華電信公告為準。","dialogue":[{"who":"A","text":"阿拉蕾，妳知道以前要查電話號碼，要打幾號嗎？"},{"who":"R","text":"我都直接上網查就好啦。以前沒有網路，要打幾號？"},{"who":"A","text":"打104。中興新村電信局二樓，就曾經設有104查號台和108長途台。"},{"who":"R","text":"所以這棟樓以前是省府人打電話的總機中心？"},{"who":"A","text":"可以這樣說。1958年蓋好，一樓前面是營業廳辦電報電話，後面是步進式機房，1960年通話系統完工。"},{"who":"R","text":"步進式機房？聽起來像會走路的機器人，好可愛。"},{"who":"A","text":"是靠機械一步一步轉動接通電話的交換機，運作起來喀喀作響，很有節奏感。"},{"who":"R","text":"那它在921大地震的時候有沒有斷線？房子還好嗎？"},{"who":"A","text":"房子牆壁厚1尺2，地震後仍屹立不搖。到現場看看北面的花格磚牆，拍一張吧！"}],"clues":["我的二樓曾設有104查號台和108長途台","我的北面是花格磚加清水混凝土柱梁","我是中興新村1958年完成的電信局"],"quiz":[{"q":"電信局二樓曾設置哪一種服務？","options":["郵政儲金","廣播電台","104查號台","電報學校"],"answer":2,"explain":"二樓設置104查號台及108長途台話房。"},{"q":"這棟電信建築的牆壁約有多厚？","options":["約3寸","約6寸","約1尺2","約3尺"],"answer":2,"explain":"加強磚造，牆壁厚1尺2，歷經921仍屹立。"}],"images":[{"file":"中華電信中興服務中心.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/%E4%B8%AD%E8%8F%AF%E9%9B%BB%E4%BF%A1%E4%B8%AD%E8%88%88%E6%9C%8D%E5%8B%99%E4%B8%AD%E5%BF%83.JPG/960px-%E4%B8%AD%E8%8F%AF%E9%9B%BB%E4%BF%A1%E4%B8%AD%E8%88%88%E6%9C%8D%E5%8B%99%E4%B8%AD%E5%BF%83.JPG","page":"https://commons.wikimedia.org/wiki/File:%E4%B8%AD%E8%8F%AF%E9%9B%BB%E4%BF%A1%E4%B8%AD%E8%88%88%E6%9C%8D%E5%8B%99%E4%B8%AD%E5%BF%83.JPG","artist":"Pbdragonwang","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/nantou-zhonghuadianxin-0.webp","small":"img/nantou-zhonghuadianxin-0-s.webp"}]},{"id":"nantou-taiwanyinxingzhong","name":"臺灣銀行中興新村分行","short":"臺銀中興分行","category":"歷史建築","level":"","town":"南投市","types":["銀行"],"lat":23.955808,"lng":120.688508,"address":"南投縣南投市南投市中興新村光華路11號","announced":"2011-04-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20110413000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-15/69da4bb1-2aaf-42a6-b49c-6c7bc8decbf8/台灣銀行中興新村分行.jpg","year":1958,"yearText":"1958年（民國47年）","era":"postwar","themes":["省府中興新村","公共建築"],"yearUnknown":false,"summary":"1958年開業、服務省府員工的銀行","intro":"位於南投市中興新村光華路，1958年12月正式開業，當年員工58人，並設招待所供員工住宿。除了沒有外匯業務，營業項目涵蓋省政府總公庫存款、存放款、國內匯兌與各種代理業務，為省府員工與附近民眾提供金融便利，也帶動中興地區與鄰近腹地的經濟發展。建築入口以帶雕刻的石柱支撐並裝飾，大廳外立面的長形開窗與柱列相互融合，牆面以洗石子與花格磚裝飾，整體細長簡約又不失優雅。建物定期修繕，2021年完成屋頂防水與廁所整修，至今仍是營業中的分行。","highlights":["入口帶雕刻裝飾的石柱","長形開窗與柱列交織的大廳立面","洗石子與花格磚裝飾的牆體"],"funFact":"開業時除了外匯業務以外幾乎樣樣都辦，連省政府總公庫存款也在這裡。","photoSpot":"在光華路對面拍石柱與長窗立面","visitMin":15,"openNote":"位於南投市中興新村光華路，目前仍為銀行營業使用，營業時間9:00至15:30；非洽公民眾請在外觀參觀，勿打擾辦理業務的客戶。可搭客運到中興新村。","dialogue":[{"who":"R","text":"Allan，古蹟巡禮怎麼走到銀行了？你是要來領零用錢嗎？"},{"who":"A","text":"我是來領知識的啦！臺灣銀行中興新村分行1958年12月開業，到現在還在營業。"},{"who":"R","text":"六十幾年的老銀行還天天上班，比我還勤勞！當年主要服務誰？"},{"who":"A","text":"主要是省府員工和附近居民。開業時員工就有58人，還辦理省政府總公庫存款。"},{"who":"R","text":"那它根本就是省政府的大錢包耶！"},{"who":"A","text":"對，而且除了外匯幾乎都辦，金融方便了，中興地區的商業也跟著熱鬧起來。"},{"who":"R","text":"那這棟建築本身又有什麼看頭呢？"},{"who":"A","text":"入口石柱有雕刻，大廳外牆是長窗配柱列，還用了洗石子和花格磚，簡約又有氣質。"},{"who":"R","text":"收到！我的任務是在外面安靜觀察，找出花格磚藏在牆面的哪個位置。"}],"clues":["我開業時有58位員工，還有自己的招待所","省政府的總公庫存款曾經放在我這裡","我是中興新村裡至今仍在營業的老銀行"],"quiz":[{"q":"這家分行在哪一年正式開業？","options":["1953年","1958年","1963年","1971年"],"answer":1,"explain":"1958年12月正式開業。"},{"q":"開業時這家分行沒有辦理哪一項業務？","options":["國內匯兌","存放款","外匯業務","代理業務"],"answer":2,"explain":"官方說明它除外匯業務外都有辦理。"}],"images":[{"file":"臺灣銀行中興新村分行.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6e/%E8%87%BA%E7%81%A3%E9%8A%80%E8%A1%8C%E4%B8%AD%E8%88%88%E6%96%B0%E6%9D%91%E5%88%86%E8%A1%8C.JPG/960px-%E8%87%BA%E7%81%A3%E9%8A%80%E8%A1%8C%E4%B8%AD%E8%88%88%E6%96%B0%E6%9D%91%E5%88%86%E8%A1%8C.JPG","page":"https://commons.wikimedia.org/wiki/File:%E8%87%BA%E7%81%A3%E9%8A%80%E8%A1%8C%E4%B8%AD%E8%88%88%E6%96%B0%E6%9D%91%E5%88%86%E8%A1%8C.JPG","artist":"Pbdragonwang","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/nantou-taiwanyinxingzhong-0.webp","small":"img/nantou-taiwanyinxingzhong-0-s.webp"}]},{"id":"nantou-zhongxinghuitang","name":"中興會堂","short":"中興會堂","category":"歷史建築","level":"","town":"南投市","types":["集會堂"],"lat":23.949206,"lng":120.696204,"address":"南投縣南投市南投市中興新村光榮北路1號","announced":"2011-04-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20110413000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-08-19/a78938fa-30d1-4a82-8151-a11302e4a19d/中興會堂.jpg","year":1959,"yearText":"1959年（民國48年）","era":"postwar","themes":["省府中興新村","公共建築"],"yearUnknown":false,"summary":"省府時代集會與放電影的「小白宮」","intro":"中興會堂位於南投市中興新村光榮北路，由和睦建築師事務所楊卓成建築師設計，1959年建成，是省府行政區內最宏偉的建築，用來召開動員月會、接待外賓，也借給中興高中辦週會，晚上還放映票價低廉的電影。建築屬西方古典樣式，強調中軸對稱，門廊有圓拱、柱廊與山牆，白色外觀被稱為「小白宮」。1997年曾作消防處辦公室，精省後一度閒置，2007年轉型為NGO會議中心，2009年整修後重新開幕，2011年登錄為歷史建築。","highlights":["中軸對稱的白色古典立面","入口門廊的圓拱與柱廊","會堂前方的廣場與看台"],"funFact":"省府時代會堂晚上會放電影，票價極低廉；1995年重新開放後，還曾每週兩次免費。","photoSpot":"從前方廣場正面拍白色門廊與山牆","visitMin":20,"openNote":"位於南投市中興新村光榮北路，現由國家發展委員會管理，作為會議、展演場地並對外租借，兩側廂房有機關辦公使用；近年進行修復與耐震補強，開放情形以管理機關公告為準。可搭客運到中興新村。","dialogue":[{"who":"R","text":"Allan，這棟白色建築好像美國總統住的地方！"},{"who":"A","text":"所以大家叫它「小白宮」。這是1959年完工的中興會堂，省府時代最宏偉的建築。"},{"who":"R","text":"那它是拿來做什麼的？總統會住在這裡嗎？"},{"who":"A","text":"沒有人住啦。省府在這裡開動員月會、接待外賓，中興高中也來借場地開週會。"},{"who":"R","text":"開會、接待外賓，聽起來都很嚴肅耶。"},{"who":"A","text":"晚上就不嚴肅了，會堂會放電影，票價很便宜，是中興新村居民的週末娛樂。"},{"who":"R","text":"白天開會，晚上看電影，這棟樓根本是斜槓青年！"},{"who":"A","text":"斜槓老青年。1997年它當過消防處辦公室，精省後一度閒置，後來改成會議中心再出發。"},{"who":"R","text":"到現場我要站在前面廣場上，數數看門廊有幾個圓拱，再拍一張！"}],"clues":["我白天開會、晚上曾放電影給居民看","我是白色古典樣式，被暱稱為小白宮","我是中興新村1959年完工的集會建築"],"quiz":[{"q":"中興會堂的設計者是哪一位建築師？","options":["楊卓成","王大閎","貝聿銘","陳其寬"],"answer":0,"explain":"由和睦建築師事務所楊卓成建築師設計。"},{"q":"中興會堂被暱稱為什麼？","options":["小凡爾賽","小白宮","白色巨塔","中部國會"],"answer":1,"explain":"白色古典建築，期望回復當年「小白宮」風華。"}],"images":[{"file":"中興會館.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/%E4%B8%AD%E8%88%88%E6%9C%83%E9%A4%A8.JPG/960px-%E4%B8%AD%E8%88%88%E6%9C%83%E9%A4%A8.JPG","page":"https://commons.wikimedia.org/wiki/File:%E4%B8%AD%E8%88%88%E6%9C%83%E9%A4%A8.JPG","artist":"Pbdragonwang","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/nantou-zhongxinghuitang-0.webp","small":"img/nantou-zhongxinghuitang-0-s.webp"}]},{"id":"shuili-zhenchangxingyegu","name":"振昌興業股份有限公司建築群","short":"車埕振昌木業","category":"歷史建築","level":"","town":"水里鄉","types":["產業"],"lat":23.834842,"lng":120.86554,"address":"南投縣水里鄉車埕村民權巷36號、34號、101號","announced":"2005-10-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20051021000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-05-10/f2bdda68-c94d-411d-8249-6a7aec17d090/振昌興業股份有限公司建築群.jpg","year":1959,"yearText":"1959年（民國48年）","era":"postwar","themes":["林業樟腦","產業遺產"],"yearUnknown":false,"summary":"車埕伐木黃金年代留下的木造建築群","intro":"位於水里鄉車埕村，集集線終點車埕站一帶。1959年，孫海創立的振昌木業標得中央山脈丹大林區的採伐權，把工廠設在車埕，還開了一條通往丹大林區的運材卡車道路。全盛時期員工600多人，幾乎整個車埕都靠振昌維生；1985年因政府森林政策改變，結束了在車埕二十多年的伐木事業。建築群包括和洋混合木構的辦公室，下半磚牆、上半雨淋板；以臺灣檜木建造的二層宿舍；以及紅磚圍牆的獨立平房宿舍。其中二層宿舍因災害毀損，現址為停車場；辦公室與平房宿舍目前閒置。2005年登錄為歷史建築。","highlights":["下磚上木、雨淋板水平線條的辦公室","平房宿舍的紅磚四角柱與刀花磚通風口","車埕木業聚落與集集線終點站風景"],"funFact":"全盛時期振昌有600多名員工，幾乎整個車埕的居民都靠它維持生計。","photoSpot":"在辦公室前拍雨淋板的水平線條","visitMin":30,"openNote":"官方資料開放時間為上午8:00至下午5:00，建物目前閒置或加固中，請在外觀參觀。可搭臺鐵集集線到終點車埕站，步行可達。山區道路颱風、豪雨後常有坍方管制，出發前查詢公路局最新路況。","dialogue":[{"who":"A","text":"搭集集線小火車坐到底就是車埕。阿拉蕾，你有沒有聞到空氣裡淡淡的木頭香？"},{"who":"R","text":"有耶！難道整個村子都是檜木做的？"},{"who":"A","text":"差不多！1959年振昌木業標到丹大林區的採伐權，工廠就設在車埕，還開了一條運木頭的卡車路。"},{"who":"R","text":"那時候這裡一定很熱鬧吧？街上應該全是穿工作服的伐木工人。"},{"who":"A","text":"全盛時期員工600多人，幾乎整個車埕都靠振昌吃飯。"},{"who":"R","text":"那後來怎麼安靜下來了？是樹被砍完了嗎？"},{"who":"A","text":"1985年政府森林政策改變，振昌就結束了在車埕二十多年的伐木事業。"},{"who":"R","text":"原來這些老房子，是伐木年代留下來的時光膠囊。"},{"who":"A","text":"辦公室下半是磚、上半是雨淋板。請你數數看一面牆有幾條雨淋板的水平線，再拍一張。"}],"clues":["我的老闆在1959年標到丹大林區的採伐權","全盛時期我有600多名員工，養活整個村子","我是集集線終點站旁的伐木公司建築群"],"quiz":[{"q":"振昌木業在1985年結束車埕伐木事業的原因是什麼？","options":["921地震震毀工廠","集集線鐵路停駛","公司遷往花蓮","政府森林政策改變"],"answer":3,"explain":"1985年因政府森林政策改變而結束伐木事業。"},{"q":"振昌木業全盛時期大約有多少名員工？","options":["60多人","600多人","200多人","1500多人"],"answer":1,"explain":"全盛時期員工600多人，幾乎整個車埕都靠它維生。"}],"images":[]},{"id":"nantou-xingzhengyuannong","name":"行政院農業委員會水土保持局(原臺灣省政府水土保持局)","short":"原省府水保局","category":"歷史建築","level":"","town":"南投市","types":["辦公廳舍"],"lat":23.955586,"lng":120.687365,"address":"南投縣南投市南投市中興新村光華路 6 號","announced":"2011-04-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20110413000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-15/2da88a62-9d09-45a9-9a78-aef76e5eb610/行政院農業委員會水土保持局.jpg","year":1961,"yearText":"年代不詳（省府時期興建）","era":"postwar","themes":["省府中興新村","公共建築"],"yearUnknown":true,"summary":"見證山地農牧到水土保持的機關廳舍","intro":"位於南投市中興新村光華路，由有巢建築師事務所虞曰鎮建築師設計，是「類國際式樣」的現代辦公廳舍：單邊走廊的教室型平面、配合基地的轉折型配置，立面以水平橫窗、樑線與垂直遮陽板構成規律節奏。使用機關的歷史從1961年成立、隸屬省府農林廳的山地農牧局開始，1989年改制為臺灣省政府農林廳水土保持局。1998年底「臺灣省政府功能業務與組織調整暫行條例」生效後，1999年7月改隸行政院農業委員會；2023年農委會升格為農業部，今為農業部農村發展及水土保持署。","highlights":["類國際式樣的水平橫窗與遮陽板","轉折型平面與短向主入口","從山地農牧局到水保署的機關沿革"],"funFact":"這個機關1961年成立時叫山地農牧局，1989年才改制為水土保持局，名字跟著任務轉彎。","photoSpot":"在光華路側拍廳舍的水平線條","visitMin":10,"openNote":"位於南投市中興新村光華路，目前為機關辦公使用，請在外觀參觀；開放情形以各機關公告為準。可搭客運到中興新村。","dialogue":[{"who":"A","text":"南投是全臺灣唯一不靠海的縣，山多坡陡，管水土保持的機關就住在這裡。"},{"who":"R","text":"等等，不靠海的地方也要管水喔？"},{"who":"A","text":"當然！山坡地的雨水和土石，都靠水土保持。這棟廳舍就是原臺灣省政府水土保持局。"},{"who":"R","text":"那它一成立的時候就叫水土保持局嗎？"},{"who":"A","text":"不是喔，1961年成立時叫山地農牧局，1989年才改制為水土保持局。"},{"who":"R","text":"從照顧山上的田和牧場，變成照顧整片山坡，業務升級了！"},{"who":"A","text":"精省後1999年改隸農委會，現在是農業部農村發展及水土保持署，還在這裡辦公。"},{"who":"R","text":"那這棟建築長什麼樣子呢？跟隔壁像嗎？"},{"who":"A","text":"也是虞曰鎮設計的類國際式樣，請在外面欣賞，找找主入口藏在哪個轉折處。"}],"clues":["我服務的機關最早叫山地農牧局","精省後我的主人改隸中央的農業主管機關","我在中興新村守護全臺灣的山坡地與水土"],"quiz":[{"q":"這個水土保持機關的前身叫什麼？","options":["山地農牧局","林務局","糧食局","建設廳"],"answer":0,"explain":"1961年成立時為山地農牧局。"},{"q":"這個機關在哪一年改隸行政院農業委員會？","options":["1989年","1995年","1999年","2004年"],"answer":2,"explain":"1999年7月1日改隸農委會。"}],"images":[]},{"id":"nantou-taiwanxinshengbao","name":"臺灣新生報中興新村辦事處(原館)","short":"新生報中興辦事處","category":"歷史建築","level":"","town":"南投市","types":["其他設施"],"lat":23.950185,"lng":120.693662,"address":"南投縣南投市南投市中興新村光華路121號","announced":"2011-04-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20110413000006","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-09/1ab017fb-1a29-4739-a979-15d199b14163/台灣新生報辦事處(原館).jpg","year":1963,"yearText":"1963年（民國52年）","era":"postwar","themes":["省府中興新村"],"yearUnknown":false,"summary":"女建築師修澤蘭設計的中興新村最美建築","intro":"位於南投市中興新村光華路，前身是1963年興建的臺灣新生報報館，由有「臺灣第一女建築師」之稱的修澤蘭設計，之後曾作為第一銀行辦事處。建築正面為紅磚，前後牆面是向內凹的鋼筋混凝土曲面牆，搭配圓形木窗，在早期中興新村相當前衛，號稱中興新村最美建築。建物產權屬私人、土地為國有，曾在921大地震中受損，新屋主委請歷史建築修復建築師整修。2018年再度歇業修復，2019年10月完成外牆整修並開放，現為商業及展演空間，二樓收藏兩幅修澤蘭設計手稿。","highlights":["前後向內凹的曲面牆與紅磚正立面","搭配牆面的圓形木窗","二樓收藏的修澤蘭建築設計手稿"],"funFact":"整棟建築主要由前後兩道曲面牆與兩側牆面共四道牆承重，結構和造型一樣大膽。","photoSpot":"在光華路對面拍曲面牆與圓形木窗","visitMin":30,"openNote":"位於南投市中興新村光華路，現由業者經營為商業及展演空間；官方資料記載週二公休，其餘日9:30至17:30，實際以現場公告為準。可搭客運到中興新村。","dialogue":[{"who":"R","text":"Allan，這棟房子的牆怎麼像被人從中間輕輕按下去，凹成一個弧形？"},{"who":"A","text":"好眼力！這是1963年的臺灣新生報報館，牆面是向內凹的混凝土曲面牆，號稱中興新村最美建築。"},{"who":"R","text":"誰這麼敢設計？六十幾年前這樣蓋應該超前衛吧！"},{"who":"A","text":"設計師是修澤蘭，有臺灣第一女建築師之稱。前後兩道曲面牆加上兩側牆，一起扛起整棟房子。"},{"who":"R","text":"所以這棟房子是靠四面牆在練核心肌群喔？"},{"who":"A","text":"哈哈，可以這麼說。它後來當過銀行辦事處，921大地震時受損，私人買下後請建築師修復。"},{"who":"R","text":"那現在一般遊客可以進去參觀嗎？"},{"who":"A","text":"2019年外牆整修完成，現在是商業和展演空間，二樓還收藏兩幅修澤蘭的設計手稿。"},{"who":"R","text":"好，我的任務是先數一數牆上有幾扇圓形木窗，數完再上樓看手稿！"}],"clues":["我的前後兩面牆向內彎，像被輕輕按了一下","我當過報館，也當過銀行辦事處","有臺灣第一女建築師之稱的修澤蘭設計了我"],"quiz":[{"q":"這棟前身為報館的建築由哪位建築師設計？","options":["王大閎","沈祖海","關頌聲","修澤蘭"],"answer":3,"explain":"修澤蘭有臺灣第一女建築師之稱。"},{"q":"這棟建築前後牆面的最大特色是什麼？","options":["向內凹的曲面牆","斜屋頂雨淋板","洗石子拱廊","紅磚圓頂"],"answer":0,"explain":"前後牆為向內凹的鋼筋混凝土曲面牆。"}],"images":[{"file":"臺灣新生報中興新村辦事處.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8a/%E8%87%BA%E7%81%A3%E6%96%B0%E7%94%9F%E5%A0%B1%E4%B8%AD%E8%88%88%E6%96%B0%E6%9D%91%E8%BE%A6%E4%BA%8B%E8%99%95.JPG/960px-%E8%87%BA%E7%81%A3%E6%96%B0%E7%94%9F%E5%A0%B1%E4%B8%AD%E8%88%88%E6%96%B0%E6%9D%91%E8%BE%A6%E4%BA%8B%E8%99%95.JPG","page":"https://commons.wikimedia.org/wiki/File:%E8%87%BA%E7%81%A3%E6%96%B0%E7%94%9F%E5%A0%B1%E4%B8%AD%E8%88%88%E6%96%B0%E6%9D%91%E8%BE%A6%E4%BA%8B%E8%99%95.JPG","artist":"Pbdragonwang","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/nantou-taiwanxinshengbao-0.webp","small":"img/nantou-taiwanxinshengbao-0-s.webp"}]},{"id":"nantou-taiwanshengzhengzi","name":"臺灣省政資料館(舊館及貴賓招待所)","short":"省政資料館","category":"歷史建築","level":"","town":"南投市","types":["博物館"],"lat":23.955807,"lng":120.686381,"address":"南投縣南投市南投市中興新村中正路2號","announced":"2011-04-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20110413000007","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-05-20/9f48e48d-590e-4321-a709-0a613e730f90/台灣省政資料館正面.jpg","year":1965,"yearText":"1965年（民國54年）","era":"postwar","themes":["省府中興新村","公共建築"],"yearUnknown":false,"summary":"從省府圖表室長成的省政展示館","intro":"位於南投市中興新村中正路，由沈祖海建築師設計。前身是省政府圖表室，以統計圖表向來訪外賓簡介省政；因外賓日多、場地不敷使用，1965年10月25日正式建館，兼作接待來賓與會議場所。1989年擴建會議廳、宴會廳及貴賓招待所「荷園」，1991年啟用。建築簡約，偏向現代主義；荷園以出簷平屋頂搭配樑頭微突的懸挑樑，簡化表現傳統大屋頂下的空間感。精省後資料館併入省府資料室，持續提供參觀導覽；2021年完成耐震補強，2025年7月起改由國家發展委員會管理。","highlights":["一樓臺灣史蹟文物與古蹟模型陳列區","二樓臺灣省歷任主席陳列室","荷園出簷平屋頂與懸挑樑的設計"],"funFact":"資料館的前身只是省府裡的一間圖表室，專門用統計圖表向外賓介紹省政。","photoSpot":"在荷園外拍出簷平屋頂與懸挑樑","visitMin":45,"openNote":"位於南投市中興新村中正路，官方資料記載週一及國定假日不開放，其餘日9:00至17:00，團體參觀請於7天前預約；2025年7月起由國家發展委員會管理，開放情形以管理機關公告為準。可搭客運到中興新村。","dialogue":[{"who":"A","text":"走進中興新村，想一口氣搞懂省政府以前在忙什麼，來省政資料館就對了。"},{"who":"R","text":"Allan，資料館聽起來好嚴肅，裡面該不會都是密密麻麻的報表吧？"},{"who":"A","text":"妳猜對一半！它的前身就是省府圖表室，專門用統計圖表向外賓簡介省政。"},{"who":"R","text":"原來是用圖表做簡報的元祖！那什麼時候變成資料館？"},{"who":"A","text":"1965年10月25日正式建館，1989年又擴建會議廳、宴會廳和貴賓招待所荷園，1991年啟用。"},{"who":"R","text":"那裡面有什麼好看的展覽可以逛呢？"},{"who":"A","text":"一樓有臺灣史蹟文物和古蹟模型，二樓有臺灣省歷任主席陳列室，逛一圈像在翻省政相簿。"},{"who":"R","text":"那我們來比賽誰先認出最多位主席，輸的人請喝魚池紅茶！"},{"who":"A","text":"成交！離開前記得繞到荷園外面，找找出簷平屋頂下那一排微微突出的樑頭。"}],"clues":["我的前身只是一間專門畫統計圖表的辦公室","我有一座叫荷園的貴賓招待所","我在中興新村展示臺灣省歷任主席與省政建設"],"quiz":[{"q":"臺灣省政資料館的前身是什麼？","options":["省府圖書館","省議會會館","省府圖表室","省府新聞處"],"answer":2,"explain":"前身是以統計圖表簡介省政的省府圖表室。"},{"q":"2025年7月起，省政資料館改由哪個機關管理？","options":["文化部","內政部","南投縣政府","國家發展委員會"],"answer":3,"explain":"2025年7月1日起由國家發展委員會管理。"}],"images":[{"file":"臺灣省政資料館.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5b/%E8%87%BA%E7%81%A3%E7%9C%81%E6%94%BF%E8%B3%87%E6%96%99%E9%A4%A8.JPG/960px-%E8%87%BA%E7%81%A3%E7%9C%81%E6%94%BF%E8%B3%87%E6%96%99%E9%A4%A8.JPG","page":"https://commons.wikimedia.org/wiki/File:%E8%87%BA%E7%81%A3%E7%9C%81%E6%94%BF%E8%B3%87%E6%96%99%E9%A4%A8.JPG","artist":"Pbdragonwang","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/nantou-taiwanshengzhengzi-0.webp","small":"img/nantou-taiwanshengzhengzi-0-s.webp"}]},{"id":"nantou-guojiawenguanxue","name":"國家文官學院中區培訓中心中正堂(原臺灣省政府訓練團中正堂)","short":"中興中正堂","category":"歷史建築","level":"","town":"南投市","types":["其他設施"],"lat":23.937548,"lng":120.702446,"address":"南投縣南投市南投市中興新村光明路1號","announced":"2011-04-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20110413000010","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-03-14/09d21320-da35-47f4-b913-3117dd8f339a/國家文官學院中區培訓中心中正堂.jpg","year":1966,"yearText":"約1966年（臺灣省訓練團1965年遷入中興新村）","era":"postwar","themes":["省府中興新村","公共建築","教育設施"],"yearUnknown":false,"summary":"公務員受訓園區裡的紅磚禮堂","intro":"國家文官學院中區培訓中心中正堂位於南投市中興新村光明路，原為臺灣省政府訓練團的禮堂。臺灣省訓練團1965年遷到中興新村，1997年改制為臺灣省政府公務人力培訓處，1999年配合精省改隸行政院人事行政局，更名地方行政研習中心；2010年園區內成立國家文官學院中區培訓中心，負責新進公務人員的訓練。中正堂為兩層鋼筋混凝土加強磚造，紅磚牆配上白色長形開窗與柱列，正面入口刻有「中正堂」，在以白色建築為主的中興新村中相當特別。","highlights":["紅磚牆搭配白色長窗與柱列","正面入口刻的「中正堂」三字","水平橫開窗與梁線的現代線條"],"funFact":"新考上的公務人員會來這裡接受3到5週的訓練，可以說是公務員的新生訓練營。","photoSpot":"在禮堂正前方拍紅磚立面與題字","visitMin":10,"openNote":"位於南投市中興新村光明路的機關訓練園區內，目前為機關使用，請在外觀參觀，開放情形以國家文官學院公告為準。","dialogue":[{"who":"R","text":"Allan，中興新村大部分建築都白白的，這棟怎麼是紅磚？"},{"who":"A","text":"好眼力！這是中正堂，紅磚牆配白色長窗，在中興新村很少見，算是園區裡的異類。"},{"who":"R","text":"那它以前是做什麼用的？也是會堂嗎？"},{"who":"A","text":"原本是臺灣省訓練團的禮堂。省訓團1965年搬來中興新村，專門訓練公務人員。"},{"who":"R","text":"公務員考上了以後，還要回來上學啊？"},{"who":"A","text":"當然。現在這裡是國家文官學院中區培訓中心，新考上的公務員要來受訓3到5週。"},{"who":"R","text":"所以這是公務員的新生訓練營！會不會也要早上跑操場？"},{"who":"A","text":"那要問學員了。我只知道受訓期間，大家吃飯時間都特別準時，排隊也很整齊。"},{"who":"R","text":"到現場我要站在正門前，把刻著中正堂的那三個字拍清楚！"}],"clues":["新考上的公務員會來我這裡受訓幾週","我是紅磚牆配白色長窗，在白色建築群中很特別","我原本是臺灣省訓練團在中興新村的禮堂"],"quiz":[{"q":"中正堂的外觀和中興新村其他建築最大不同是什麼？","options":["紅磚牆體","琉璃瓦屋頂","全玻璃帷幕","木造雨淋板"],"answer":0,"explain":"紅磚牆配白色長窗與柱列，在中興新村格外特別。"},{"q":"文官學院中區培訓中心主要訓練哪些人？","options":["國軍新兵","新進公務人員","國小學生","外籍移工"],"answer":1,"explain":"針對剛通過考試任職的公務人員進行訓練。"}],"images":[]},{"id":"nantou-lantianyashe","name":"藍田雅舍","short":"藍田雅舍","category":"歷史建築","level":"","town":"南投市","types":["其他設施"],"lat":23.909961,"lng":120.683638,"address":"南投縣南投市南投市彰南路2段83號","announced":"2020-07-17","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20201020000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-10-11/2f1a1237-afe0-4407-aff3-d7399d31dcb2/藍田雅舍建築主體.jpg","year":1971,"yearText":"1971年（民國60年）","era":"postwar","themes":["日式建築","公共建築"],"yearUnknown":false,"summary":"南投縣府興建的仿日式木造員工宿舍","intro":"位於南投市彰南路二段，靠近藍田街口，是南投縣政府在1971年8月完工、提供員工及眷屬居住的宿舍。建築為磚木混合的仿日式平房，外牆是雨淋板，原本為兩坡式水泥瓦屋頂，晚近改為鋼浪板。雖然興建於戰後，但外型典雅、木結構保存良好，是南投市內少數完整保存的早期日式風格建築。2020年登錄為歷史建築，文化局依所在位置命名為「藍田雅舍」，希望與附近的藍田書院、武德殿及其附屬建築群、稅務出張所串成文化圈。目前閒置，由南投縣政府文化局管理。","highlights":["一片片橫向疊起的雨淋板外牆","兩坡式屋頂的獨棟平房造型","與藍田書院、武德殿串成的散步路線"],"funFact":"它其實是1971年戰後才蓋的，不是日治時期建築，只是用了仿日式的木造做法。","photoSpot":"在彰南路側拍雨淋板外牆全景","visitMin":15,"openNote":"位於南投市彰南路二段，平時不開放，可事先向南投縣政府文化局洽詢預約；未預約請在外觀參觀。可與附近藍田書院、武德殿一起散步參觀。","dialogue":[{"who":"A","text":"考考妳，這棟木造平房看起來像不像日治時期的老宿舍？"},{"who":"R","text":"像！外牆一條一條的木板，屋頂兩邊斜斜的，我猜它至少一百歲。"},{"who":"A","text":"嗶，答錯！它是南投縣政府1971年8月蓋好的員工宿舍，是戰後的仿日式建築。"},{"who":"R","text":"原來是穿著和服的民國房子，也太會偽裝了吧！"},{"who":"A","text":"外牆那種疊起來的木板叫雨淋板。原本屋頂蓋水泥瓦，後來換成了鋼浪板。"},{"who":"R","text":"那為什麼叫藍田雅舍？聽起來好文青。"},{"who":"A","text":"因為它在藍田街和彰南路口附近，2020年登錄歷史建築時，文化局就幫它取了這個名字。"},{"who":"R","text":"附近還有藍田書院和武德殿，剛好可以串成一條散步路線。"},{"who":"A","text":"沒錯！它平常不開放，請在外面欣賞，找找鋼浪板屋頂和雨淋板外牆的交接處再出發。"}],"clues":["我看起來像日治老屋，其實是戰後才出生","我原本是縣政府員工和眷屬的宿舍","我的名字來自附近一條街和一座書院的名稱"],"quiz":[{"q":"藍田雅舍是哪一年完工的？","options":["1938年","1951年","1971年","1985年"],"answer":2,"explain":"南投縣政府於1971年8月興建完成。"},{"q":"藍田雅舍的外牆是哪一種做法？","options":["雨淋板","洗石子","紅磚清水牆","土角牆"],"answer":0,"explain":"外牆為一片片橫疊的雨淋板。"}],"images":[]},{"id":"zhushan-linpigongmu","name":"林圮公墓","short":"林圮公墓","category":"紀念建築","level":"","town":"竹山鎮","types":["墓葬"],"lat":23.755756,"lng":120.67959,"address":"南投縣竹山鎮竹山鎮育英路33號","announced":"2018-04-25","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/commemorativeBuilding/20181003000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-05-09/16db7fd3-d36b-4918-987f-3b15bdcbc5c4/林圮公墓.jpg","year":1668,"yearText":"約1668年（明永曆22年，依傳統記載）；1940年改建","era":"zheng","themes":["墓葬碑碣","紀念地景"],"yearUnknown":false,"summary":"竹山舊名「林圮埔」的由來，也是土地易主的記憶","intro":"位於竹山鎮市區育英路，鄰近竹山老街與連興宮，是竹山發展的起點。依官方說明，林圮是福建同安人、明鄭部將，率部眾由斗六門一帶拓墾到水沙連，在竹圍仔庄築柵屯墾。這片土地原是原住民族生活與狩獵的領域，墾殖引發衝突，原住民族反擊，林圮與許多部眾身亡，傳統記載為1668年，細節說法不一。居民將殉難者合葬於此，並稱此地為「林圮埔」。墓原以一棵橄欖樹為記，1940年改建為水泥墓園並立花崗石碑，1988年再整修。2018年登錄為紀念建築，由林姓宗親林崇本堂祭祀。認識開墾故事時，也別忘了原住民族因此失去家園的那一面。","highlights":["墓碑「明代開闢水沙連功授右弼參軍林圮公墓」","1940年改建、1988年整修的墓園","周邊竹山老街與連興宮的老街區"],"funFact":"墓園起初沒有墓碑，只用一棵橄欖樹當標記，到1940年才改建成水泥墓園。","photoSpot":"在墓前拍花崗石墓碑與墓園全景","visitMin":15,"openNote":"官方資料標示24小時開放，位於竹山鎮市區育英路，可順遊竹山老街與連興宮。墓園是祭祀場所，請保持肅靜。可從高鐵臺中站或臺鐵二水站轉搭客運到竹山市區。","dialogue":[{"who":"A","text":"阿拉蕾，你知道竹山以前叫什麼嗎？叫做林圮埔，名字就來自這座墓的主人。"},{"who":"R","text":"林圮是誰？聽名字好像很會種田的人。"},{"who":"A","text":"他是明鄭時期的部將，帶著部眾從斗六門一帶開墾到水沙連，在這附近築柵屯墾。"},{"who":"R","text":"那這裡原本是一片沒人的空地嗎？"},{"who":"A","text":"不是喔，這裡本來是原住民族生活和狩獵的土地。開墾的人一進來，雙方就爆發衝突。"},{"who":"R","text":"所以對開墾的人來說是英雄，對原本住在這裡的人，卻是家園被占走了。"},{"who":"A","text":"說得很中肯。依傳統記載，林圮和許多部眾在衝突中身亡，細節說法不一，後人把他們合葬在這裡。"},{"who":"R","text":"歷史果然像銅板，要翻到兩面都看過，才不會只聽到一半的故事。"},{"who":"A","text":"到墓前請安靜致意，找找墓碑上水沙連三個字，想一想這片土地最早的主人是誰。"}],"clues":["我所在的小鎮，舊名就是用我的主人命名的","我起初沒有墓碑，只有一棵橄欖樹做記號","我是明鄭參軍和部眾的合葬墓，在竹山市區"],"quiz":[{"q":"竹山舊名「林圮埔」是怎麼來的？","options":["當地盛產林木與竹子","清代知縣的姓名","日治時期的行政區名","紀念率眾墾殖的明鄭部將"],"answer":3,"explain":"居民將林圮與部眾合葬，並以其名稱此地。"},{"q":"林圮公墓最早用什麼當作標記？","options":["一塊花崗石碑","一棵橄欖樹","一座土地公祠","一根旗杆"],"answer":1,"explain":"原本沒有墓碑，以橄欖樹為記，1940年才改建。"}],"images":[{"file":"Linpi's tomb.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a9/Linpi%27s_tomb.JPG/960px-Linpi%27s_tomb.JPG","page":"https://commons.wikimedia.org/wiki/File:Linpi%27s_tomb.JPG","artist":"Yiken","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/zhushan-linpigongmu-0.webp","small":"img/zhushan-linpigongmu-0-s.webp"}]},{"id":"yuchi-linyuanshitoucuo","name":"林淵石頭厝","short":"林淵石頭厝","category":"紀念建築","level":"","town":"魚池鄉","types":["宅第"],"lat":23.899556,"lng":120.976016,"address":"南投縣魚池鄉魚池鄉共和村中興巷6號","announced":"2018-05-03","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/commemorativeBuilding/20181004000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-02-29/e4a9fb81-f61c-40b9-919c-236abd844077/林淵石頭厝.jpg","year":1977,"yearText":"年代不詳（林淵約65歲起在此創作）","era":"unknown","themes":["紀念地景","震災重建"],"yearUnknown":true,"summary":"樸素藝術家林淵的創作基地與紀念館","intro":"位於魚池鄉共和村內加道社區。林淵（1912–1991）只讀過兩個月小學，一生務農，65歲起以退休老農身分拿起鑿子雕刻石頭，到79歲過世，不到15年間創作石雕、油漆繪畫、刺繡、木雕與拼裝藝術近萬件，作品充滿鄉野生活的故事，是臺灣樸素藝術的重要先驅，與北部的吳李玉哥、南部的洪通並列。石頭厝是兩層樓磚造建築，木構屋頂覆瓦，內部保存大量壁畫與作品。921大地震後由文建會補助整建，2003年內加道社區成為社區營造點，石頭厝改為林淵樸素藝術紀念館。2018年登錄為紀念建築，由新故鄉文教基金會管理。","highlights":["林淵的石雕、刺繡與拼裝藝術","屋內保存的大量壁畫","內加道社區的鄉村景致"],"funFact":"林淵65歲才開始雕石頭，不到15年就創作了近萬件作品。","photoSpot":"在屋外拍石雕作品與石頭厝","visitMin":30,"openNote":"官方未載開放時間，目前作為社區活動與藝術參觀空間，由新故鄉文教基金會管理，參觀前請先洽詢管理單位。位於魚池鄉共和村，可搭客運到埔里或魚池再轉乘。","dialogue":[{"who":"R","text":"Allan，你說要帶我去看藝術大師，結果這裡是鄉下的田邊耶。"},{"who":"A","text":"大師就在田邊！林淵當了一輩子農夫，小學只讀兩個月，65歲以後才拿起鑿子雕石頭。"},{"who":"R","text":"65歲才開始？那他應該只雕了幾件吧？"},{"who":"A","text":"你猜錯了，到79歲過世，不到15年做了將近一萬件，有石雕、繪畫、刺繡，還有拼裝藝術。"},{"who":"R","text":"一年差不多七百件，這產量比便利商店的茶葉蛋還驚人！"},{"who":"A","text":"他的作品講的都是鄉下生活的故事，被看作臺灣樸素藝術的重要先驅。"},{"who":"R","text":"那這棟石頭厝後來怎麼了？921地震的時候有受影響嗎？"},{"who":"A","text":"921地震後整建，2003年起變成林淵樸素藝術紀念館。去之前先聯絡管理單位，到現場找一件你覺得最好笑的石雕。"}],"clues":["我的主人只讀過兩個月小學，65歲才開始創作","我收藏石雕、刺繡與滿牆壁畫","我在魚池內加道，是樸素藝術大師的工作室"],"quiz":[{"q":"林淵大約幾歲開始雕刻石頭？","options":["45歲","55歲","65歲","75歲"],"answer":2,"explain":"林淵65歲退休後開始拿鑿子雕刻石頭。"},{"q":"林淵常與哪兩位並列為臺灣樸素藝術代表？","options":["洪通與吳李玉哥","朱銘與楊英風","李梅樹與陳澄波","席德進與劉其偉"],"answer":0,"explain":"北吳李玉哥、中林淵、南洪通為樸素藝術指標。"}],"images":[]},{"id":"renai-qubingkaoguyizhi","name":"曲冰考古遺址","short":"曲冰考古遺址","category":"考古遺址","level":"國定考古遺址","town":"仁愛鄉","types":[],"lat":23.95505,"lng":121.079631,"address":"南投縣仁愛鄉萬豐村，土名稱Qais的河階地上。","announced":"2019-05-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/archaeologicalSite/20190522000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-03-18/ed81bb7d-a6de-43b8-b817-5e8c6700246a/曲冰遺址現況.jpg","year":-2000,"yearText":"距今約4000年前起","era":"prehistoric","themes":["考古遺址"],"yearUnknown":false,"summary":"臺灣高山唯一完整保存的史前聚落遺址","intro":"位於仁愛鄉萬豐村濁水溪上游的河階地，土名Qais。1981年中央研究院調查濁水溪上游時發現，陳仲玉至1987年間三度發掘，面積3700平方公尺，出土石器29000多件、陶片8萬多片，並發現至少48處房屋基址與171座石板棺。下文化層距今約4000年，主要居住期在距今約3000至2300年與1300至1000年。製玉遺留與花蓮的遺址相似，顯示史前人群跨越中央山脈往來。這裡是臺灣高山地區目前唯一完整且保存良好的史前聚落遺址。2006年公告為縣定遺址，2019年升格為國定考古遺址；發掘坑已回填保護。","highlights":["高山地區罕見的完整史前聚落","171座石板棺與房屋基址","與花蓮相似的製玉遺留"],"funFact":"曲冰的發現顯示山區早在數千年前就有人定居，挑戰了原住民是後來才被趕上山的舊說法。","photoSpot":"從遺址旁眺望濁水溪峽谷","visitMin":20,"openNote":"官方未載開放資訊，發掘坑已回填保護並設有圍籬，請在圍籬外參觀，勿進入或挖掘。位於仁愛鄉萬豐村，進入部落請尊重族人。山區道路颱風、豪雨後常有坍方管制，出發前查詢公路局最新路況。","dialogue":[{"who":"R","text":"Allan，這裡已經是濁水溪上游的深山了，史前人真的會住這麼高嗎？"},{"who":"A","text":"曲冰就是最好的答案！考古學家在這片河階挖到一整個史前聚落，最早距今約4000年。"},{"who":"R","text":"一整個聚落？那到底有多少房子和墳墓？"},{"who":"A","text":"至少48處房屋基址，還有171座石板棺，光是石器就出土29000多件。"},{"who":"R","text":"29000多件！這是史前人的大賣場吧？"},{"who":"A","text":"哈，差不多是大型生活圈。這裡還有製玉遺留，和花蓮的遺址很像，表示人們曾翻越中央山脈往來。"},{"who":"R","text":"原來高山不是阻隔，是史前人的高速公路。"},{"who":"A","text":"這也說明山區很早就有人定居。遺址現在已回填保護，請在圍籬外參觀。"},{"who":"A","text":"到現場找找濁水溪在階地邊轉彎的地方，想像幾千年前的人怎麼在那裡取水捕魚。"}],"clues":["我在濁水溪上游的高山河階上","我有171座石板棺和至少48處房屋基址","我是臺灣高山唯一完整的史前聚落遺址"],"quiz":[{"q":"曲冰遺址共發現了多少座石板棺？","options":["71座","121座","171座","271座"],"answer":2,"explain":"發掘出至少48處房屋基址及171座石板棺。"},{"q":"曲冰遺址在2019年升格為哪一種文化資產？","options":["國定考古遺址","縣定考古遺址","國定古蹟","重要文化景觀"],"answer":0,"explain":"2019年5月13日升格為國定考古遺址。"}],"images":[]},{"id":"puli-fudingjinkaoguyi","name":"覆鼎金考古遺址","short":"覆鼎金考古遺址","category":"考古遺址","level":"縣(市)定考古遺址","town":"埔里鎮","types":[],"lat":23.951336,"lng":120.965114,"address":"南投縣埔里鎮隆生路111巷76號對面","announced":"2021-11-12","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/archaeologicalSite/20211216000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-12-14/ba154819-25a1-4b88-8723-786ffe58b9a3/覆鼎金考古遺址.jpeg","year":-1500,"yearText":"多文化層：繩紋陶文化、大馬璘文化到19世紀埔社，確切年代不詳","era":"prehistoric","themes":["考古遺址","原住民族文化"],"yearUnknown":true,"summary":"疊著史前文化與埔社最後足跡的小丘","intro":"位於埔里鎮水頭里一帶的小丘，目前仍是埔里鎮第一公墓。2002年由簡史朗調查發現；2018年公墓遷葬施工時，地方文化協會通報發現史前遺物，縣府依法要求停工並調查試掘。遺址屬多文化層：下層是可能早於大馬璘文化的繩紋陶文化，其上有大馬璘文化層，最上層則是歷史時期埔社的文化層。出土一件保存完整的喇叭型玉環，也有玉料與切鋸工具，見證東西部交換。調查確認清末埔社人居住在覆鼎金小山周邊；1815年郭百年事件後埔社死傷慘重，土地逐漸流失，到1900年鳥居龍藏調查時族人僅剩5人。2021年公告為縣定考古遺址。","highlights":["繩紋陶、大馬璘與埔社的三層文化","保存完整的喇叭型玉環","埔社族人最後聚居地的歷史記憶"],"funFact":"清道光年間北路理番同知鄧傳安來到埔里社，當時埔社聚落就在覆鼎金山下。","photoSpot":"在小丘外圍遠拍，勿進入墓區拍照","visitMin":15,"openNote":"官方未載開放資訊，遺址目前仍是埔里鎮第一公墓，請尊重墓區、保持肅靜，勿挖掘或撿拾遺物。","dialogue":[{"who":"A","text":"這座小丘現在是公墓，但地底下其實疊了好幾層歷史，就像一本被埋起來的千層書。"},{"who":"R","text":"千層書？那最上面那一頁寫的是什麼？"},{"who":"A","text":"最上層是埔社人的生活痕跡。埔社是埔里盆地原本的原住民族聚落，曾經擁有盆地大半土地。"},{"who":"R","text":"曾經？聽起來不太妙，後來發生了什麼事？"},{"who":"A","text":"1815年郭百年事件，埔社死傷慘重。後來雖引進平埔族群共抗漢人，人口懸殊下土地還是逐漸流失。"},{"who":"R","text":"好令人難過，那埔社的人後來怎麼了？"},{"who":"A","text":"1900年鳥居龍藏調查時只剩5人。考古學家確認，清末埔社最後就住在覆鼎金一帶。"},{"who":"R","text":"原來這座小丘，是一個族群最後的家。"},{"who":"A","text":"這裡仍是墓區，請保持安靜。到現場時，在丘邊停下來一分鐘，想想曾經住在這裡的人。"}],"clues":["我在一座現在仍是公墓的小丘下","我出土一件保存完整的喇叭型玉環","我是埔社人最後聚居地所在的考古遺址"],"quiz":[{"q":"這處遺址出土了哪一件保存完整的玉器？","options":["人獸形玉玦","玉鈴","喇叭型玉環","玉璧"],"answer":2,"explain":"出土保存完整的喇叭型玉環，證明東西交換體系。"},{"q":"1900年鳥居龍藏調查時，埔社族人大約只剩幾人？","options":["5人","50人","150人","500人"],"answer":0,"explain":"據鳥居龍藏調查，埔番當時只剩五人。"}],"images":[]},{"id":"puli-damalinkaoguyizhi","name":"大馬璘考古遺址","short":"大馬璘考古遺址","category":"考古遺址","level":"縣(市)定考古遺址","town":"埔里鎮","types":[],"lat":23.96915,"lng":120.944872,"address":"南投縣埔里鎮埔里鎮愛蘭里，位於烏牛欄聚落南側，醒靈寺西側，南港溪右岸階崖上方","announced":"2018-11-20","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/archaeologicalSite/20091030000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-09-15/2cfdcc30-f355-4145-aed4-864a2ec7c2f3/大馬璘考古遺址入口.jpeg","year":-1300,"yearText":"距今約3300至1700年前（大馬璘文化）","era":"prehistoric","themes":["考古遺址"],"yearUnknown":false,"summary":"埔里盆地史前大聚落，大馬璘文化命名地","intro":"位於埔里鎮愛蘭里的愛蘭台地，烏牛欄聚落南側、南港溪右岸階崖上方。1900年鳥居龍藏調查埔里社時，就在烏牛欄高丘發現石器時代遺物；1949年中央研究院歷史語言研究所與臺大組隊發掘，找到大量石器、陶器，以及石板棺、砌石牆等遺跡。此後歷經多次調查與搶救發掘，學界以此命名「大馬璘文化」，可分早、中、晚與末期。早期有半地穴式住居，中期起出現密集的長方形石板棺與地面式住居，可見東部史前文化要素大量進入，顯示史前人群跨越中央山脈往來交流。2009年公告為縣定遺址，2018年公告為縣定考古遺址。","highlights":["大馬璘文化的命名遺址","長方形石板棺與砌石住居遺跡","東西部史前文化交流的證據"],"funFact":"早在1900年，日本學者鳥居龍藏就在這片台地發現了石器時代遺物。","photoSpot":"在愛蘭台地邊緣眺望埔里盆地","visitMin":20,"openNote":"官方未載開放資訊，遺址位於埔里鎮愛蘭里台地，地下文化層受法律保護，請勿挖掘或撿拾遺物，也勿進入管制區或私人土地。","dialogue":[{"who":"A","text":"阿拉蕾，我們腳下這片愛蘭台地，地底下藏著好幾千年前的大聚落。"},{"who":"R","text":"好幾千年？那時候埔里也有米粉可以吃嗎？"},{"who":"A","text":"米粉沒有，石器和陶器倒是一大堆。考古學家還用這裡的地名，把一整支文化取名叫大馬璘文化。"},{"who":"R","text":"能用地名當文化的名字，代表這裡很有代表性吧？"},{"who":"A","text":"沒錯。1900年鳥居龍藏就在這裡發現石器，1949年中研院和臺大正式發掘，挖出石板棺和砌石牆。"},{"who":"R","text":"石板棺是什麼？用石頭做的棺材嗎？"},{"who":"A","text":"對，用石板拼成長方形的棺。這種葬法在東部很常見，表示史前人群曾翻越中央山脈往來。"},{"who":"R","text":"史前人翻山越嶺，比我們開車還要拚。"},{"who":"A","text":"遺址受法律保護，請別亂挖。站在台地邊緣看看南港溪，想想史前人為什麼選這裡住。"}],"clues":["1900年一位日本人類學者就在我這裡發現石器","有一支史前文化用我的地名命名","我在埔里愛蘭台地，地底有長方形石板棺"],"quiz":[{"q":"1900年在這片台地發現石器時代遺物的日本學者是誰？","options":["森丑之助","伊能嘉矩","鳥居龍藏","鹿野忠雄"],"answer":2,"explain":"1900年鳥居龍藏調查埔里社時發現遺物。"},{"q":"大馬璘出土的哪一種葬具，顯示和東部史前文化有關？","options":["長方形石板棺","陶甕棺","獨木舟形木棺","竹編棺"],"answer":0,"explain":"中期起出現密集的長方形石板棺，可見東部文化要素。"}],"images":[{"file":"大馬璘遺址文化園區.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/83/%E5%A4%A7%E9%A6%AC%E7%92%98%E9%81%BA%E5%9D%80%E6%96%87%E5%8C%96%E5%9C%92%E5%8D%80.jpg/960px-%E5%A4%A7%E9%A6%AC%E7%92%98%E9%81%BA%E5%9D%80%E6%96%87%E5%8C%96%E5%9C%92%E5%8D%80.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%A4%A7%E9%A6%AC%E7%92%98%E9%81%BA%E5%9D%80%E6%96%87%E5%8C%96%E5%9C%92%E5%8D%80.jpg","artist":"Pbdragonwang","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/puli-damalinkaoguyizhi-0.webp","small":"img/puli-damalinkaoguyizhi-0-s.webp"}]},{"id":"puli-shuiwakukaoguyizhi","name":"水蛙窟考古遺址","short":"水蛙窟考古遺址","category":"考古遺址","level":"縣(市)定考古遺址","town":"埔里鎮","types":[],"lat":23.999306,"lng":120.952669,"address":"南投縣埔里鎮埔里鎮史港里史港坑段","announced":"2018-11-20","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/archaeologicalSite/20030307000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-10-02/aa345f62-8124-49e7-8501-7d083724a1a8/水蛙窟考古遺址.jpg","year":-1000,"yearText":"新石器時代中、晚期，確切年代不詳","era":"prehistoric","themes":["考古遺址"],"yearUnknown":true,"summary":"俯瞰埔里盆地、出土大量玉器的史前聚落","intro":"位於埔里鎮史港里，史港溪與眉溪匯流處北側的紅土緩坡台地，可俯瞰埔里盆地。1970年代「濁大計劃」中，由考古學者尹因印調查發現並試掘。遺址範圍廣大，地表遺物分布東西寬約400公尺、南北長800公尺以上。1997年自然科學博物館試掘，發現豐富遺物與8座石板棺墓葬。文化層呈現新石器時代中、晚期的發展過程，出土大量玉器與製玉遺物，是研究營埔文化與東部卑南文化互動、東西交換體系的關鍵遺址，也是「水蛙堀時期」的命名遺址。土地屬台糖公司，現出租以保土生態園藝栽培方式利用。2018年公告為縣定考古遺址。","highlights":["大量玉器與製玉遺物","石板棺墓葬","俯瞰埔里盆地與溪流匯流的景觀"],"funFact":"「水蛙」是臺語的青蛙，官方資料中也有「水蛙堀」的寫法。","photoSpot":"從台地邊緣遠眺埔里盆地","visitMin":15,"openNote":"官方未載開放資訊，土地屬台糖公司並出租耕作，請勿進入農地、挖掘或撿拾遺物，可在周邊道路眺望。","dialogue":[{"who":"R","text":"Allan，水蛙窟？這裡是青蛙開派對的地方嗎？"},{"who":"A","text":"水蛙是臺語的青蛙沒錯，不過這裡最熱鬧的時候，是史前人群在這裡做玉器的年代。"},{"who":"R","text":"史前人也會做玉器？那不就是石器時代的珠寶店！"},{"who":"A","text":"真的很像！這裡出土大量玉器和製玉遺物，證明埔里曾是臺灣東西部交換物品的中繼站。"},{"who":"R","text":"那是誰最先發現這個遺址的？是挖地的農夫嗎？"},{"who":"A","text":"1970年代濁大計劃的考古學者尹因印調查時發現，1997年科博館又試掘出8座石板棺。"},{"who":"R","text":"那現在這裡變成什麼樣子了？有蓋成遺址公園或博物館嗎？"},{"who":"A","text":"土地屬於台糖，租給農民做保土園藝栽培。請在路邊遠眺，看看史港溪和眉溪在哪裡會合。"}],"clues":["我的名字裡藏著臺語的一種兩棲動物","我出土大量玉器和製玉遺物","我是埔里史港里俯瞰盆地的史前聚落"],"quiz":[{"q":"這處遺址最早是在哪一個研究計畫中被發現？","options":["十大建設","臺灣堡圖調查","南迴鐵路搶救發掘","濁大計劃"],"answer":3,"explain":"1970年代濁大計劃中由尹因印調查發現。"},{"q":"1997年科博館試掘時，發現了幾座石板棺墓葬？","options":["3座","8座","5座","12座"],"answer":1,"explain":"試掘探坑六處，發現八處石板棺墓葬。"}],"images":[]},{"id":"renai-taiyaminzuqiyuandi","name":"Sbayan泰雅民族起源地","short":"Sbayan起源地","category":"文化景觀","level":"重要文化景觀","town":"仁愛鄉","types":["神話傳說之場域"],"lat":24.116489,"lng":121.155874,"address":"南投縣仁愛鄉瑞岩段第1524地號","announced":"2025-07-14","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/culturalLandscape/20250725000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-07-30/2056887f-774f-47b6-9834-acd3f4625943/1.jpeg","year":1700,"yearText":"年代不詳（泰雅族口傳起源地）","era":"unknown","themes":["原住民族文化","紀念地景"],"yearUnknown":true,"summary":"泰雅族口傳中祖先由巨石走出的共同之根","intro":"位於仁愛鄉發祥村瑞岩部落下方的台地，泰雅語Sbayan意為「分開」，是賽考列克語群口傳的發源地。口傳說，太古時名為Pinsbkan的聖石裂開，走出祖先；人口增加後，頭目在Sbayan台地的石頭上宣布遷徙，族人沿著山稜與流域分散到今天臺中、苗栗、新竹、桃園、宜蘭、臺北等地建立部落。台地上的巨石是起源與遷徙的象徵，族人視這裡為「泰雅族共同的根」。2016年南投縣登錄為文化景觀，2025年文化部登錄為重要文化景觀，兩次都在瑞岩段1524地號。921大地震後瑞岩部落遷到新址，台地邊坡也有崩塌待維護。","highlights":["台地上矗立的巨石，泰雅起源與遷徙的象徵","2012年設置的地標與解說牌","瑞岩溪流保護區的山林溪景"],"funFact":"Sbayan在泰雅語是「分開」的意思，相傳族人就是從這裡分開，遷往北部各地。","photoSpot":"在解說牌旁遠拍台地，勿攀爬聖石","visitMin":30,"openNote":"官方未載開放資訊。這裡是泰雅族的聖地，請遵守部落規範、保持安靜，不要攀爬、觸摸或移動聖石與石頭，前往前可先向瑞岩部落詢問。台地邊坡有崩塌，請勿靠近邊緣。位於仁愛鄉發祥村，山區道路颱風、豪雨後常有坍方管制，出發前查詢公路局最新路況。","dialogue":[{"who":"A","text":"阿拉蕾，今天放輕腳步，我們來到仁愛鄉瑞岩部落下方的斯巴揚台地，這裡是泰雅族口傳的起源地。"},{"who":"R","text":"起源地？那族人的傳說是怎麼說的呢？"},{"who":"A","text":"口傳說，太古時一塊聖石裂開，走出了祖先。後來人口多了，頭目在台地的石頭上宣布遷徙。"},{"who":"R","text":"所以斯巴揚就是大家分開出發的地方？"},{"who":"A","text":"沒錯，斯巴揚在泰雅語就是分開的意思。族人往北部各地建立部落，祖訓叮嚀不能忘記這裡。"},{"who":"R","text":"難怪族人說這裡是泰雅族共同的根，像一棵大樹的樹根一樣。這裡有被正式保護嗎？"},{"who":"A","text":"有，2016年南投縣登錄為文化景觀，2025年文化部再登錄為重要文化景觀。"},{"who":"R","text":"那我可以爬上大石頭，拍一張很帥的照片嗎？"},{"who":"A","text":"絕對不行！請遵守部落規範，保持安靜，不攀爬、不觸摸、不移動石頭，在解說牌前靜靜讀完傳說就好。"}],"clues":["我的名字在原住民族語中是分開的意思","口傳中，祖先從一塊裂開的聖石走出","我是仁愛鄉瑞岩部落下方，泰雅族視為共同之根的台地"],"quiz":[{"q":"Sbayan在泰雅語是什麼意思？","options":["聖石","祖先","太陽","分開"],"answer":3,"explain":"Sbayan意為分開，族人由此分散遷徙各地。"},{"q":"2025年文化部將這裡登錄為哪一種文化資產？","options":["國定古蹟","重要文化景觀","國家公園","縣定考古遺址"],"answer":1,"explain":"2016年縣登錄文化景觀，2025年登錄為重要文化景觀。"}],"images":[],"extraLinks":[{"title":"文資局官方資料（2016 年南投縣登錄文化景觀）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/culturalLandscape/20160818000001"}]},{"id":"yuchi-tousheguritanfu","name":"頭社古日潭浮田文化景觀","short":"頭社古日潭浮田","category":"文化景觀","level":"文化景觀","town":"魚池鄉","types":["其他人類與自然互動而形成之景觀"],"lat":23.828536,"lng":120.902638,"address":"南投縣魚池鄉魚池鄉平和段791、804、806及807等地號","announced":"2020-02-05","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/culturalLandscape/20200205000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-12-16/99bace6c-45d0-48c3-b54b-78e12cb282a5/頭社古日潭浮田文化景觀.jpg","year":1920,"yearText":"年代不詳（浮田耕作起源未詳，頭社大排建於日治時期）","era":"unknown","themes":["茶業農業","水利設施"],"yearUnknown":true,"summary":"踩上去會彈跳的「活盆地」浮田","intro":"位於魚池鄉頭社盆地。依官方說明，頭社盆地原是古代的「日潭」，約1700年前逐漸乾枯，植物腐化成泥，形成深達數十公尺的草泥炭沼澤，被稱為「活盆地」，也是臺灣古氣候研究的重要地點。早期村民以草莖纏繞木頭承載泥土，在沼澤上打造浮田種稻；人走在上面，整片地面會跟著彈跳。居民又在田埂與水道岸邊種植臺灣特有種水社柳固岸。日治時期地方自力興建頭社大排（原名頭社圳），以不易腐爛的木頭插入泥炭土作為水門基礎，讓看天田變成灌溉良田。邵族傳說中，頭社盆地就是當年的日潭。2020年登錄為文化景觀。","highlights":["草泥炭濕地上的浮田","臺灣特有種水社柳","頭社大排的木樁水門"],"funFact":"走在活盆地上，整片地面會跟著彈跳震動，卻不會陷下去。","photoSpot":"在田邊道路拍水社柳與稻田","visitMin":30,"openNote":"官方未載開放資訊，範圍內多為私人農地與水利用地，請走公共道路觀賞，勿踩踏田地。位於魚池鄉頭社，可搭往日月潭的客運再轉乘。","dialogue":[{"who":"A","text":"阿拉蕾，頭社這片稻田有個綽號，叫做活盆地，你猜為什麼？"},{"who":"R","text":"難道田會自己長腳跑掉？還是會跟著音樂跳舞？"},{"who":"A","text":"差一點！地底下是很深的草泥炭沼澤，人走上去，整片地面會跟著彈跳。"},{"who":"R","text":"原來是天然的彈簧床！那在上面要怎麼種稻？"},{"who":"A","text":"早期村民用草莖纏著木頭，承載泥土做成浮田，等於在沼澤上鋪一張會浮的田。"},{"who":"R","text":"這根本是古早版的浮動農場，太有創意了！"},{"who":"A","text":"田埂旁還種了臺灣特有種水社柳固岸。日治時期村民又挖了頭社大排，用不會爛的木頭當水門基礎。"},{"who":"R","text":"我還聽說，這裡以前叫做日潭，是真的嗎？"},{"who":"A","text":"傳說這裡就是古日潭，後來淤積成盆地。請走公共道路，別踩田，找找水社柳長在哪裡。"}],"clues":["我腳下是深厚的草泥炭沼澤，被稱為活盆地","我的田埂邊種著臺灣特有種的柳樹","傳說我曾是日月潭中的日潭"],"quiz":[{"q":"居民在浮田田埂與河岸種植哪一種樹來固岸？","options":["苦楝","相思樹","木麻黃","水社柳"],"answer":3,"explain":"居民種植臺灣特有種水社柳固岸護土。"},{"q":"頭社大排的水門基礎是用什麼做成的？","options":["鋼筋混凝土樁","插入泥炭土的木頭","廢棄鐵軌","糯米石灰砌石"],"answer":1,"explain":"以不易腐爛的木頭插入泥炭土底層作水門基底。"}],"images":[{"file":"View across rural landscape to Toushe, Yunchi.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/da/View_across_rural_landscape_to_Toushe%2C_Yunchi.jpg/960px-View_across_rural_landscape_to_Toushe%2C_Yunchi.jpg","page":"https://commons.wikimedia.org/wiki/File:View_across_rural_landscape_to_Toushe,_Yunchi.jpg","artist":"Ken Marshall","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","local":"img/yuchi-tousheguritanfu-0.webp","small":"img/yuchi-tousheguritanfu-0-s.webp"}]},{"id":"nantou-zhongxingxincunwen","name":"中興新村文化景觀","short":"中興新村","category":"文化景觀","level":"文化景觀","town":"南投市","types":["歷史事件場所"],"lat":23.946566,"lng":120.693783,"address":"南投縣南投市位於南投市中興新村都市計畫區內，北鄰草屯鎮界；東鄰虎山山麓；西鄰中正路、省府路與東閔路；南至南內轆地區","announced":"2011-04-12","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/culturalLandscape/20110412000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-04-22/09773a8c-28cf-4523-a5d7-ae66f75c445a/中興新村文化景觀.jpg","year":1956,"yearText":"1956年（民國45年）","era":"postwar","themes":["省府中興新村","公共建築"],"yearUnknown":false,"summary":"臺灣第一個花園城市式的行政新市鎮","intro":"中興新村位於南投市北側，北鄰草屯鎮界、東倚虎山山麓。1950年代因應臺海緊張局勢與防空疏散需求，臺灣省政府推動疏遷計畫，1956年起在此興建並陸續遷入，這裡成為省政府所在地四十多年。它是中華民國政府在臺灣實施的第一個都市計畫，引進英國「花園城市」與「鄰里單元」概念，以小學、市場或公園為鄰里中心，住宅低矮、有前庭後院，並有囊底路、馬蹄形與放射狀街廓。1998年底起推動臺灣省政府功能業務與組織調整（精省），省府組織精簡，許多廳舍改由中央機關使用。2011年登錄為文化景觀，範圍內有古蹟臺灣省政府與11處歷史建築。","highlights":["省府路荷花池、牌樓到圓環的行政軸線","鄰里單元裡的囊底路與前庭後院宿舍","王大閎、修澤蘭等建築師設計的廳舍"],"funFact":"第一鄰里單元以小學為中心，用步行距離決定範圍，讓孩子走路就能上學。","photoSpot":"在省府路荷花池邊拍向牌樓與圓環","visitMin":120,"openNote":"位於南投市中興新村，街道與公園可自由散步；範圍內許多廳舍目前為機關辦公使用，請在外觀參觀，開放情形以各機關公告為準，宿舍區請勿打擾住戶。縣內沒有高鐵站，可從高鐵臺中站轉搭往南投的客運。","dialogue":[{"who":"R","text":"Allan，這裡樹好多、房子好矮，路還常常走到底就沒了，我們迷路了嗎？"},{"who":"A","text":"沒迷路啦，那是故意設計的囊底路！歡迎來到中興新村，臺灣省政府住了四十多年的地方。"},{"who":"R","text":"省政府為什麼會搬到南投的山腳下？"},{"who":"A","text":"1950年代臺海局勢緊張，為了防空疏散，省府推動疏遷計畫，在這裡蓋了一座新市鎮。"},{"who":"R","text":"一座城說蓋就蓋，好像在玩城市模擬遊戲。"},{"who":"A","text":"而且是照英國花園城市的概念，以小學、市場或公園當鄰里中心，住宅都有前庭後院。"},{"who":"R","text":"難怪走起來像在逛大公園。那現在省政府還在嗎？"},{"who":"A","text":"1998年底精省後組織精簡，很多廳舍改由中央機關使用，2011年整區登錄為文化景觀。"},{"who":"R","text":"那我的任務是從荷花池走到圓環，數數沿路經過幾棟歷史建築！"}],"clues":["我的巷子常常走到底就沒路，那是故意設計的","我是中華民國政府在臺灣實施的第一個都市計畫","臺灣省政府在我這裡辦公了四十多年"],"quiz":[{"q":"中興新村的整體規劃引進了哪一種概念？","options":["巴洛克放射城","日式棋盤街廓","美式摩天市中心","英國花園城市"],"answer":3,"explain":"引進英式花園城市與鄰里單元概念。"},{"q":"中興新村第一鄰里單元以什麼作為鄰里中心？","options":["小學","廟宇","火車站","工廠"],"answer":0,"explain":"以小學為中心，用步行距離決定範圍。"}],"images":[{"file":"Taiwan JhongSing Village Paifang.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/Taiwan_JhongSing_Village_Paifang.JPG/960px-Taiwan_JhongSing_Village_Paifang.JPG","page":"https://commons.wikimedia.org/wiki/File:Taiwan_JhongSing_Village_Paifang.JPG","artist":"vegafish, vegafish in zh-wikipedia","license":"CC BY-SA 2.5","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.5","local":"img/nantou-zhongxingxincunwen-0.webp","small":"img/nantou-zhongxingxincunwen-0-s.webp"}]}],"eras":[{"id":"dutch","name":"原住民族社會（荷西時期）","range":"約1624–1662","cityName":"南投社、北投社與水沙連內山各族","title":"山與湖之間的原住民族家園","summary":"17世紀荷蘭東印度公司在大員經營時，今天的南投仍是原住民族的家園。日月潭一帶是邵族的生活領域；埔里盆地以眉溪為界，北邊是泰雅族、南邊是布農族的生活地域；霧社山區有賽德克族，竹山、信義一帶的丘陵與山區則有鄒族與布農族。西邊丘陵平原上是洪雅族阿立昆群的南投社與北投社，荷蘭文獻把北投社記作 Tausa Mato、南投社記作 Tausa Talakey，「南投」這個地名就由此而來。巴布薩、拍瀑拉等平埔族群當時住在西部平原，要到清代才遷入埔里。更早以前，仁愛鄉曲冰、埔里大馬璘等遺址顯示這片山地很早就有人居住。","population":"","events":[{"year":"史前","text":"仁愛鄉曲冰遺址經碳十四測定，約二千七百多年前到一千年前就有人在濁水溪上游河階定居"},{"year":"傳說","text":"泰雅族賽考列克群傳說祖先從聖石 Pinsbkan 誕生，後來在 Sbayan 台地分開，向北遷徙建立新部落"},{"year":"1624","text":"荷蘭東印度公司在大員（今臺南安平）建立據點，南投內山仍由各族自主生活"},{"year":"17世紀","text":"荷蘭文獻記下洪雅族北投社（Tausa Mato）與南投社（Tausa Talakey）的社名"},{"year":"1662","text":"荷蘭人離開臺灣，南投各族的生活仍以部落為中心"}],"landmarks":[{"name":"南投社推定位置（今南投市）","lat":23.90996,"lng":120.68371,"note":"洪雅族阿立昆群南投社，南投地名由來；標示點為南投市區","approx":true},{"name":"北投社推定位置（今草屯鎮北投里）","lat":23.98511,"lng":120.66017,"note":"洪雅族阿立昆群北投社，標示點為北投里","approx":true},{"name":"拉魯島（日月潭）","lat":23.85569,"lng":120.91128,"note":"日月潭中的小島，邵族生活領域的中心","approx":false},{"name":"Sbayan泰雅民族起源地","lat":24.11649,"lng":121.15587,"note":"仁愛鄉發祥村瑞岩部落下方台地，泰雅族共同的根","approx":false},{"name":"曲冰考古遺址","lat":23.95505,"lng":121.07963,"note":"仁愛鄉萬豐村，臺灣規模最大的高山考古研究","approx":false},{"name":"大馬璘考古遺址","lat":23.96915,"lng":120.94487,"note":"埔里盆地的史前遺址，出土大量石器與陶器","approx":false},{"name":"久美部落（信義鄉）","lat":23.61722,"lng":120.88472,"note":"鄒族楠仔腳蔓社所在，社名出自鄒語「肥沃平原」","approx":true},{"name":"東埔（信義鄉）","lat":23.56169,"lng":120.92628,"note":"今天的布農族部落，玉山山腳下","approx":true}],"view":{"lat":23.84,"lng":120.91,"zoom":10},"dialogue":[{"who":"R","text":"Allan，荷西時期的南投地圖上只有山和湖，荷蘭人沒有來這裡嗎？"},{"who":"A","text":"南投是臺灣唯一不靠海的縣，荷蘭人的船開不進來，這裡仍是原住民族自己的家園。"},{"who":"R","text":"那時候住在這片山裡的是哪些族群？"},{"who":"A","text":"日月潭有邵族，埔里盆地北邊是泰雅族、南邊是布農族，霧社山區有賽德克族，信義山區還有鄒族和布農族。"},{"who":"R","text":"好多族群！那南投這個名字是從哪裡來的？"},{"who":"A","text":"來自洪雅族的南投社。荷蘭文獻已經記下它和北投社的社名，算是南投最早的書面簽到紀錄。"},{"who":"R","text":"簽到紀錄？Allan，你把荷蘭人當成點名老師了嗎？"},{"who":"A","text":"差不多啦！老師點完名就走，族人照樣過自己的生活。巴布薩、拍瀑拉等平埔族群，要到清代才搬進埔里。"},{"who":"R","text":"那更早以前，這片山裡就有人住了嗎？"},{"who":"A","text":"有！仁愛鄉曲冰遺址顯示兩千多年前就有人定居。小任務：到日月潭找找拉魯島，想想它在邵族心中的分量。"}],"quiz":[{"q":"「南投」這個地名來自哪一個社？","options":["洪雅族南投社","邵族水社","布農族東埔社","泰雅族瑞岩社"],"answer":0,"explain":"南投社屬洪雅族阿立昆群，荷蘭文獻記作 Tausa Talakey。"},{"q":"仁愛鄉瑞岩部落下方的 Sbayan，是哪一族的起源地？","options":["邵族","鄒族","泰雅族","布農族"],"answer":2,"explain":"Sbayan 是泰雅族賽考列克群的發源地，族人視為共同的根。"}],"sources":[{"title":"南投縣（中文維基百科）","url":"https://zh.wikipedia.org/wiki/南投縣"},{"title":"洪雅族（中文維基百科）","url":"https://zh.wikipedia.org/wiki/洪雅族"},{"title":"埔里鎮（中文維基百科）","url":"https://zh.wikipedia.org/wiki/埔里鎮"},{"title":"邵族（中文維基百科）","url":"https://zh.wikipedia.org/wiki/邵族"},{"title":"曲冰考古遺址（文化部文化資產局國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/archaeologicalSite/20190522000002"},{"title":"Sbayan泰雅民族起源地（文化部文化資產局國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/culturalLandscape/20250725000003"}]},{"id":"zheng","name":"明鄭時期（林圮埔開墾）","range":"1661–1683","cityName":"林圮埔（今竹山）與斗六門以東","title":"林圮埔：開墾與失去土地","summary":"1661年鄭成功來臺，林圮隨軍而來，官至參軍。鄭經主政時推行屯田，依中文維基百科與文化部資料，1665年林圮率屯丁從斗六門向東入墾，進入今天竹山一帶，在竹圍仔庄築柵居住。對漢人移民來說這是開墾的起點；對當地原住民族來說，則是武裝的外來者占據了獵場與家園。維基百科記載這一帶原居民是鄒族魯富都人。1668年10月，原住民夜襲竹圍仔，林圮與部眾多人遇害；之後明鄭援軍驅逐原住民，族人失去清水溪與濁水溪流域的丘陵地，被迫往山區遷徙。後人把這裡稱為林圮埔，就是竹山的舊名。明鄭時期南投先屬天興縣，後屬北路安撫司。","population":"","events":[{"year":"1661","text":"鄭成功率軍來臺，林圮隨軍來臺"},{"year":"1665","text":"鄭經推行屯田，林圮率屯丁由斗六門向東入墾今竹山一帶，在竹圍仔庄築柵居住"},{"year":"1668","text":"10月原住民夜襲竹圍仔，林圮與部眾多人遇害；之後援軍驅逐原住民，族人失去清水溪、濁水溪流域丘陵地"},{"year":"明鄭時期","text":"南投一帶先屬天興縣，後屬北路安撫司"},{"year":"1683","text":"清廷領有臺灣；林圮埔之名在清初文獻已有記載"}],"landmarks":[{"name":"林圮公墓（竹山鎮）","lat":23.75576,"lng":120.67959,"note":"林圮與殉難部眾合葬處，位於竹山鎮中心；1940年改建為水泥墓園","approx":false},{"name":"林圮埔推定位置（今竹山市區）","lat":23.75797,"lng":120.67277,"note":"林圮埔就是竹山舊名，標示點為竹山鎮","approx":true},{"name":"斗六門推定位置（今雲林縣斗六市）","lat":23.70505,"lng":120.53725,"note":"林圮率屯丁向東入墾的出發地，標示點為斗六市","approx":true},{"name":"南投社推定位置（今南投市）","lat":23.90996,"lng":120.68371,"note":"洪雅族南投社，當時仍是平埔族群的聚落","approx":true},{"name":"北投社推定位置（今草屯鎮北投里）","lat":23.98511,"lng":120.66017,"note":"洪雅族北投社","approx":true},{"name":"拉魯島（日月潭）","lat":23.85569,"lng":120.91128,"note":"日月潭一帶仍是邵族的生活領域","approx":false}],"view":{"lat":23.82,"lng":120.72,"zoom":10},"dialogue":[{"who":"R","text":"竹山的舊名叫林圮埔，林圮是一個人的名字嗎？"},{"who":"A","text":"對，他是鄭成功的部將，官至參軍。鄭經推行屯田時，他帶著屯丁從斗六門往東開墾。"},{"who":"R","text":"這樣聽起來，他就是開墾竹山的大英雄囉？"},{"who":"A","text":"換個角度看就不一樣了。對住在這裡的鄒族魯富都人來說，帶著武器的外來者占了他們的獵場和家園。"},{"who":"R","text":"那麼後來，雙方之間發生了什麼事？"},{"who":"A","text":"1668年10月，原住民夜襲竹圍仔，林圮和部眾多人遇害，之後明鄭援軍又把原住民趕走。"},{"who":"R","text":"一邊有人犧牲，一邊有人失去家園，這段歷史好沉重。"},{"who":"A","text":"族人失去清水溪、濁水溪一帶的丘陵地，被迫往山裡遷移。後人為了紀念林圮，把這裡叫做林圮埔。"},{"who":"R","text":"原來一個地名裡，藏著兩種完全不同的記憶。"},{"who":"A","text":"小任務：到竹山林圮公墓讀讀墓碑上的字，再想想被迫離開的族人，會怎麼講這個故事。"}],"quiz":[{"q":"竹山鎮的舊名是什麼？","options":["林圮埔","草鞋墩","半路店","營盤口"],"answer":0,"explain":"後人為紀念林圮，把他開墾的地方稱為林圮埔，1920年改稱竹山。"},{"q":"林圮率領屯丁從哪裡向東入墾？","options":["斗六門","鹿港","打狗","雞籠"],"answer":0,"explain":"鄭經推行屯田時，林圮率屯丁由斗六門入墾。"}],"sources":[{"title":"林圮（中文維基百科）","url":"https://zh.wikipedia.org/wiki/林圮"},{"title":"竹山鎮 (台灣)（中文維基百科）","url":"https://zh.wikipedia.org/wiki/竹山鎮_(台灣)"},{"title":"南投縣（中文維基百科）","url":"https://zh.wikipedia.org/wiki/南投縣"},{"title":"林圮公墓（文化部文化資產局國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/commemorativeBuilding/20181003000001"}]},{"id":"qing","name":"清朝","range":"1683–1895","cityName":"彰化縣南投縣丞、埔里社廳與林圮埔","title":"書院、古道與開山撫番","summary":"清代南投先屬諸羅縣，1723年改屬彰化縣，1759年在南投設縣丞。漢人沿濁水溪、烏溪向內山入墾，1758年的古文書已有「草鞋墩」地名，集集在1771年後陸續成庄。士紳興學，1831年建藍田書院，1848年登瀛書院竣工。1814年郭百年事件後清廷一度封禁水沙連，1823年起洪雅、拍瀑拉、道卡斯、巴布薩、巴宰五族十四社受邀遷入埔里。1874年牡丹社事件後推動開山撫番，1875年吳光亮開闢八通關古道並設埔里社廳。這對清廷是開發後山，對布農族等原住民族卻是軍隊進入傳統領域、失去土地。","population":"","events":[{"year":"1759","text":"彰化縣在南投設縣丞，是南投有政教之始"},{"year":"1814–1817","text":"郭百年事件，漢人侵入埔里焚殺族人；清廷驅逐佃人，並在集集、烏溪二口立禁碑"},{"year":"1823","text":"洪雅、拍瀑拉、道卡斯、巴布薩、巴宰等五族十四社受邀遷入埔里盆地"},{"year":"1831","text":"南投縣丞朱懋倡建藍田書院"},{"year":"1848","text":"草屯士紳募建的登瀛書院竣工"},{"year":"1875","text":"吳光亮率兵開闢八通關古道，從林圮埔到璞石閣；同年設埔里社廳"},{"year":"1878","text":"集集樟腦業興起，洋商進入集集街開設腦館"},{"year":"1887","text":"劉銘傳設埔裏社撫墾局；楠仔腳蔓社設立番學堂，不到一年就荒廢"}],"landmarks":[{"name":"藍田書院（南投市）","lat":23.90723,"lng":120.68473,"note":"1831年創建，1917年在現址重建","approx":false},{"name":"登瀛書院（草屯鎮）","lat":23.98876,"lng":120.66748,"note":"1847年募建、1848年竣工","approx":false},{"name":"明新書院（集集鎮）","lat":23.82757,"lng":120.79952,"note":"集集士紳興學，1885年遷建完成","approx":false},{"name":"萬年亨衢石碣（鳳凰谷鳥園內）","lat":23.72913,"lng":120.79198,"note":"八通關古道沿線石碣，標示點為鹿谷鄉鳳凰谷鳥園","approx":true},{"name":"開闢鴻荒石碣（集集鎮林尾里）","lat":23.82004,"lng":120.76339,"note":"濁水溪畔與八通關古道相關的石碣","approx":false},{"name":"林圮埔（八通關古道西端起點一帶）","lat":23.75797,"lng":120.67277,"note":"古道從林圮埔出發，東端在花蓮玉里；標示點為竹山鎮","approx":true},{"name":"埔里（埔里社廳、大埔城一帶）","lat":23.96667,"lng":120.96915,"note":"1875年設埔里社廳，1877年建大埔城；標示點為埔里鎮","approx":true},{"name":"楠仔腳蔓社學堂遺蹟（信義鄉）","lat":23.61797,"lng":120.8842,"note":"1887年為鄒族孩童設的番學堂遺址","approx":false}],"view":{"lat":23.8,"lng":120.82,"zoom":10},"dialogue":[{"who":"R","text":"Allan，清代南投的地圖上多了好多街庄，漢人是從哪裡進來的？"},{"who":"A","text":"沿著濁水溪、烏溪往內山走。草屯在1758年的古文書裡就叫草鞋墩，集集到1771年後才陸續成庄。"},{"who":"R","text":"草鞋墩，是換草鞋換到堆成一座小山嗎？"},{"who":"A","text":"傳說有好幾種，可是古文書比傳說還早，所以答案是：沒人說得準。倒是士紳很愛讀書，1831年就蓋了藍田書院。"},{"who":"R","text":"那埔里呢？我記得那裡住了很多平埔族群。"},{"who":"A","text":"1814年郭百年事件，漢人侵入埔里焚殺族人。1823年起，洪雅、巴布薩、拍瀑拉等五族十四社受邀遷入埔里。"},{"who":"R","text":"八通關古道也是這個時期開的吧？"},{"who":"A","text":"對，1875年吳光亮帶兵從林圮埔開路到璞石閣。對清廷是開發後山，對布農族卻是軍隊走進祖先的獵場。"},{"who":"R","text":"同一條路，兩邊看到的風景完全不一樣。古道的東端在哪裡？"},{"who":"A","text":"在花蓮玉里，詳見花蓮縣篇。小任務：到鹿谷鳳凰谷鳥園找「萬年亨衢」石碣，拍下碑上的四個大字。"}],"quiz":[{"q":"1875年吳光亮開闢的八通關古道，是從哪裡通到哪裡？","options":["林圮埔到璞石閣","草鞋墩到埔里","集集到水里","鹿港到南投"],"answer":0,"explain":"八通關古道從林圮埔（今竹山）越過中央山脈到璞石閣（今花蓮玉里）。"},{"q":"1823年起受邀遷入埔里盆地的是哪些族群？","options":["中部平埔族群五族十四社","噶瑪蘭族","西拉雅族","阿美族"],"answer":0,"explain":"洪雅、拍瀑拉、道卡斯、巴布薩、巴宰等五族十四社遷入埔里。"}],"sources":[{"title":"南投縣（中文維基百科）","url":"https://zh.wikipedia.org/wiki/南投縣"},{"title":"八通關古道（中文維基百科）","url":"https://zh.wikipedia.org/wiki/八通關古道"},{"title":"開山撫番（中文維基百科）","url":"https://zh.wikipedia.org/wiki/開山撫番"},{"title":"郭百年事件（中文維基百科）","url":"https://zh.wikipedia.org/wiki/郭百年事件"},{"title":"埔里鎮（中文維基百科）","url":"https://zh.wikipedia.org/wiki/埔里鎮"},{"title":"埔里社廳（中文維基百科）","url":"https://zh.wikipedia.org/wiki/埔里社廳"},{"title":"草屯鎮（中文維基百科）","url":"https://zh.wikipedia.org/wiki/草屯鎮"},{"title":"藍田書院 (臺灣)（中文維基百科）","url":"https://zh.wikipedia.org/wiki/藍田書院_(臺灣)"},{"title":"登瀛書院（中文維基百科）","url":"https://zh.wikipedia.org/wiki/登瀛書院"},{"title":"明新書院（文化部文化資產局國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19851127000033"},{"title":"楠仔腳蔓社學堂遺蹟（文化部文化資產局國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19880226000001"},{"title":"八通關古道（文化部文化資產局國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19870417000001"}]},{"id":"japan","name":"日治時期","range":"1895–1945","cityName":"南投廳（1901）、臺中州南投郡、竹山郡、新高郡、能高郡（1920）","title":"鐵道、電廠與霧社事件","summary":"1901年設南投廳，1920年改屬臺中州，分成南投、竹山、新高、能高四郡，草鞋墩改名草屯、林圮埔改名竹山。為了日月潭水力發電工程，臺灣電力株式會社鋪設集集線，1922年1月通車；電廠1934年6月完工，日月潭湖面從4.55擴大到7.73平方公里，邵族部分傳統聚落被迫遷移。山區有樟腦與林業開發，1934年起集集設專賣局出張所管理製腦。總督府以理蕃政策控制山地，1919至1921年修築八通關越嶺道。1930年10月27日，莫那魯道等賽德克族六社族人在霧社起事抗日，遭軍警、飛機與火砲鎮壓；1931年5月，倖存的298人被強制遷往川中島（今清流部落）。","population":"","events":[{"year":"1901","text":"設南投廳"},{"year":"1919","text":"日月潭水力發電工程大舉施工；6月八通關越嶺道動工，1921年1月完工"},{"year":"1920","text":"改屬臺中州，分南投、竹山、新高、能高四郡；草鞋墩改名草屯、林圮埔改名竹山"},{"year":"1922","text":"集集線1月通車，原本為運送電廠工程材料而建"},{"year":"1930","text":"10月27日霧社事件，賽德克族德克達雅群六社族人在霧社公學校運動會起事抗日"},{"year":"1931","text":"4月25日第二次霧社事件；5月6日起六社遺族被強制遷往川中島，不得返回原鄉"},{"year":"1934","text":"日月潭第一發電所6月完工，湖面擴大；樟腦改為專賣局官營，集集設出張所"},{"year":"1936","text":"魚池紅茶試驗支所成立，今天的茶業改良場魚池分場"}],"landmarks":[{"name":"集集火車站","lat":23.82654,"lng":120.78489,"note":"集集線的中心站，1933年改建為檜木站房","approx":false},{"name":"車埕車站（水里鄉）","lat":23.83256,"lng":120.86574,"note":"集集線終點站","approx":false},{"name":"大觀發電廠（原日月潭第一發電所）","lat":23.85146,"lng":120.8695,"note":"1934年啟用，引用日月潭的水發電","approx":false},{"name":"集集樟腦出張所建築群","lat":23.82914,"lng":120.78678,"note":"1934年起專賣局集集出張所，管理樟腦製造","approx":false},{"name":"莫那魯道紀念碑（霧社）","lat":24.02057,"lng":121.1323,"note":"仁愛鄉霧社的霧社事件紀念地","approx":false},{"name":"清流部落（原川中島社）","lat":24.06922,"lng":120.95344,"note":"1931年霧社事件遺族被強制遷居之地","approx":true},{"name":"東埔（八通關越嶺道西段一帶）","lat":23.56318,"lng":120.93144,"note":"今天登山客從東埔走的多半是日治越嶺道","approx":true},{"name":"茶業改良場魚池分場","lat":23.87691,"lng":120.91347,"note":"1936年成立紅茶試驗支所，製茶工廠建於1938年","approx":false}],"view":{"lat":23.82,"lng":120.95,"zoom":10},"dialogue":[{"who":"R","text":"集集線小火車好可愛，它一開始就是載觀光客的嗎？"},{"who":"A","text":"才不是！它是為了日月潭水力發電工程載材料蓋的，1922年1月通車，終點就在水里車埕。"},{"who":"R","text":"電廠蓋好以後，日月潭有什麼改變？"},{"who":"A","text":"1934年電廠完工，湖面從4點55平方公里擴大到7點73平方公里，邵族部分傳統聚落被迫遷移。"},{"who":"R","text":"原來漂亮的湖景背後，有族人搬家的故事。那山上呢？"},{"who":"A","text":"總督府用理蕃政策控制山地，1919到1921年修築八通關越嶺道，沿線設了許多駐在所。"},{"who":"R","text":"我聽過霧社事件，是發生在這個時期嗎？"},{"who":"A","text":"1930年10月27日，莫那魯道等賽德克族六社族人在霧社公學校運動會起事抗日。日方動用軍警、飛機與火砲鎮壓。"},{"who":"R","text":"好沉重。那後來倖存的族人怎麼了？"},{"who":"A","text":"1931年5月，倖存的298人被強制遷到川中島，就是今天的清流部落。小任務：到霧社紀念碑前靜默一分鐘，向這段歷史致意。"}],"quiz":[{"q":"集集線最初是為了什麼而興建？","options":["運送日月潭水力發電工程材料","運送香蕉外銷","載觀光客遊日月潭","運送八通關古道物資"],"answer":0,"explain":"集集線由臺灣電力株式會社興建，為日月潭水力發電工程運送材料。"},{"q":"霧社事件後，倖存族人被強制遷往的川中島，今天叫什麼？","options":["清流部落","伊達邵","瑞岩部落","久美部落"],"answer":0,"explain":"1931年5月，六社遺族被遷往北港溪與眉原溪交會處的川中島，今清流部落。"}],"sources":[{"title":"南投縣（中文維基百科）","url":"https://zh.wikipedia.org/wiki/南投縣"},{"title":"集集線（中文維基百科）","url":"https://zh.wikipedia.org/wiki/集集線"},{"title":"日月潭（中文維基百科）","url":"https://zh.wikipedia.org/wiki/日月潭"},{"title":"大觀發電廠（中文維基百科）","url":"https://zh.wikipedia.org/wiki/大觀發電廠"},{"title":"霧社事件（中文維基百科）","url":"https://zh.wikipedia.org/wiki/霧社事件"},{"title":"清流部落（中文維基百科）","url":"https://zh.wikipedia.org/wiki/清流部落"},{"title":"八通關古道（中文維基百科）","url":"https://zh.wikipedia.org/wiki/八通關古道"},{"title":"集集樟腦出張所建築群（文化部文化資產局國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20190122000002"},{"title":"集集火車站（文化部文化資產局國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20041221000003"},{"title":"行政院農業委員會茶業改良場魚池分場（文化部文化資產局國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20110415000002"}]},{"id":"early-roc","name":"民國初年","range":"1945–1950年代","cityName":"臺中縣（1945–1950）→ 南投縣（1950年設縣）","title":"設縣與省府疏遷營盤口","summary":"戰後南投各地先劃入臺中縣。1950年10月南投從臺中縣劃出單獨設縣，10月21日設立縣政府，縣治在南投鎮（今南投市），成為臺灣唯一不靠海的縣。1954年7月，源自竹山竹材工藝傳習所的工藝研究單位遷到草屯，成立南投縣工藝研究班，由顏水龍主持。1949年中央政府遷臺後，為防範空襲使行政中樞癱瘓，臺灣省政府推動疏散遷移，1956年起在南投營盤口興建中興新村。這是中華民國政府在臺灣實施的第一個都市計畫，引進英式「花園城市」概念，以鄰里單元與低密度開發規劃，辦公與住宅合一。1957年年中省府遷入，1959年中興會堂落成。","population":"","events":[{"year":"1945–1946","text":"戰後南投各地劃入臺中縣，日治的郡改為區"},{"year":"1950","text":"10月南投縣從臺中縣劃出設縣，10月21日設立縣政府，縣治在南投鎮"},{"year":"1954","text":"7月南投縣工藝研究班在草屯成立，由顏水龍擔任主任"},{"year":"1956","text":"臺灣省政府因防空疏遷，開始在營盤口興建中興新村；7月7日中部橫貫公路開工"},{"year":"1957","text":"年中臺灣省政府遷入中興新村（各史料記載日期略有不同）"},{"year":"1959","text":"中興會堂建成啟用；振昌木業標得丹大林區採伐權，工廠設在車埕"}],"landmarks":[{"name":"南投縣政府（南投市）","lat":23.90238,"lng":120.69012,"note":"1950年設縣，縣治在南投鎮","approx":false},{"name":"南投稅務出張所","lat":23.91076,"lng":120.6843,"note":"戰後改為臺中縣稅捐處南投分處，1950年設縣後成為南投縣稅捐稽徵處","approx":false},{"name":"武德殿（南投市）","lat":23.90942,"lng":120.68399,"note":"戰後由警察單位接收，作為南投縣警察局辦公地點","approx":false},{"name":"原手工業品陳列館（草屯鎮）","lat":23.98004,"lng":120.69217,"note":"1954年南投縣工藝研究班在此成立，今國立臺灣工藝研究發展中心","approx":false},{"name":"臺灣省政府（中興新村）","lat":23.95832,"lng":120.68728,"note":"1957年省府遷入，今為縣定古蹟","approx":false},{"name":"中興新村文化景觀","lat":23.94657,"lng":120.69378,"note":"參考英式花園城市規劃的行政特區","approx":false},{"name":"中興會堂","lat":23.94921,"lng":120.6962,"note":"1959年建成啟用，中興新村最宏偉的建築","approx":false}],"view":{"lat":23.94,"lng":120.69,"zoom":12},"dialogue":[{"who":"R","text":"Allan，南投縣是什麼時候才有的？"},{"who":"A","text":"1950年10月，南投從臺中縣劃出來單獨設縣，縣政府設在南投鎮，就是今天的南投市。"},{"who":"R","text":"臺灣唯一不靠海的縣，夏天想看海要開好遠喔！"},{"who":"A","text":"沒關係，我們有日月潭可以看湖。這時期最大的新聞，是臺灣省政府要搬來南投。"},{"who":"R","text":"省政府為什麼要從臺北搬到這裡？"},{"who":"A","text":"1949年中央政府遷臺後，為了防範空襲讓行政中樞一起癱瘓，省府推動疏散遷移，1956年起在營盤口興建中興新村。"},{"who":"R","text":"營盤口，聽起來好像軍營的名字。"},{"who":"A","text":"沒錯，地名來自清代的駐軍營地。中興新村參考英式花園城市，用鄰里單元和低密度來規劃。"},{"who":"R","text":"上班和回家都在同一座公園裡，通勤時間大概只要五分鐘！"},{"who":"A","text":"這就是工作和生活合一的理念。小任務：到中興新村走一圈，數數看一條巷子裡有幾戶前院種著大樹。"}],"quiz":[{"q":"南投縣是哪一年從臺中縣劃出設縣的？","options":["1950年","1945年","1957年","1998年"],"answer":0,"explain":"1950年10月南投縣設縣，10月21日設立縣政府。"},{"q":"中興新村的規劃參考了哪一種理念？","options":["英式花園城市","巴洛克放射城市","棋盤式城池","日式神社參道"],"answer":0,"explain":"中興新村引進英式花園城市概念，以鄰里單元、低密度開發規劃。"}],"sources":[{"title":"南投縣（中文維基百科）","url":"https://zh.wikipedia.org/wiki/南投縣"},{"title":"中興新村（中文維基百科）","url":"https://zh.wikipedia.org/wiki/中興新村"},{"title":"臺灣省政府（中文維基百科）","url":"https://zh.wikipedia.org/wiki/臺灣省政府"},{"title":"國立臺灣工藝研究發展中心（中文維基百科）","url":"https://zh.wikipedia.org/wiki/國立臺灣工藝研究發展中心"},{"title":"中興新村文化景觀（文化部文化資產局國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/culturalLandscape/20110412000002"},{"title":"原手工業品陳列館（文化部文化資產局國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20220223000001"}]},{"id":"roc60","name":"民國60年前後","range":"約1957–1981","cityName":"南投縣（臺灣省政府所在地）","title":"省府時代：公路、林業與茶香","summary":"1957年臺灣省政府遷入中興新村後，南投成為省政中心所在。區內辦公廳舍與宿舍多數興建於民國60年代以前，由王大閎、修澤蘭、關頌聲、沈祖海等建築師設計；1965年10月臺灣省政資料館建館。1960年5月9日中部橫貫公路通車，1萬多位榮民投入興建，霧社支線（台14甲線）經過仁愛鄉清境、合歡山。山區林業興盛，振昌木業以車埕為基地，全盛時期員工600多人。工藝與茶業也在這時發展：1973年臺灣省手工業研究所成立，1977年6月草屯的陳列館啟用；1976年鹿谷舉辦第一屆凍頂優良茶比賽，凍頂烏龍茶名號大開。","population":"","events":[{"year":"1957","text":"臺灣省政府遷入中興新村，南投成為省政中心所在"},{"year":"1960","text":"5月9日中部橫貫公路通車，1萬多位榮民參與興建"},{"year":"1965","text":"10月臺灣省政資料館建館，用來簡介省政、接待來賓"},{"year":"1973","text":"臺灣省手工業研究所成立；魚池分場命名台茶七號、八號紅茶品種"},{"year":"1976","text":"5月2日鹿谷國小舉辦第一屆凍頂優良茶比賽"},{"year":"1977","text":"6月手工業研究所陳列館在草屯啟用，成為中潭公路上的地標"}],"landmarks":[{"name":"臺灣省政府（中興新村）","lat":23.95832,"lng":120.68728,"note":"省府在此辦公四十多年","approx":false},{"name":"臺灣省政資料館","lat":23.95581,"lng":120.68638,"note":"1965年建館，沈祖海建築師設計","approx":false},{"name":"原手工業品陳列館（草屯鎮）","lat":23.98004,"lng":120.69217,"note":"1977年啟用，楊英風擔任總設計師","approx":false},{"name":"振昌興業建築群（水里鄉車埕）","lat":23.83484,"lng":120.86554,"note":"1959年起以車埕為基地採伐丹大林區，1985年結束","approx":false},{"name":"南投林區管理處水里工作站木造辦公廳舍","lat":23.81265,"lng":120.85641,"note":"1968到1993年為水里工作站辦公廳舍","approx":false},{"name":"凍頂山（鹿谷鄉）","lat":23.75061,"lng":120.76542,"note":"凍頂烏龍茶的產區","approx":false},{"name":"茶業改良場魚池分場","lat":23.87691,"lng":120.91347,"note":"1968年改組為台灣省茶葉改良場魚池分場","approx":false},{"name":"合歡山（中橫霧社支線經過）","lat":24.14261,"lng":121.2712,"note":"台14甲線經過清境、合歡山，到大禹嶺接中橫主線","approx":false}],"view":{"lat":23.95,"lng":120.97,"zoom":10},"dialogue":[{"who":"R","text":"省政府搬進中興新村以後，南投變成什麼樣子？"},{"who":"A","text":"這裡成了省政中心，辦公廳舍和宿舍一棟棟蓋起來，1965年還成立了臺灣省政資料館。"},{"who":"R","text":"那山上的生活，有沒有跟著改變？"},{"who":"A","text":"1960年5月9日中部橫貫公路通車，1萬多位榮民參與開路，霧社支線一路經過清境、合歡山。"},{"who":"R","text":"1萬多人一起開山，光是便當就要準備好幾卡車吧！"},{"who":"A","text":"你的重點永遠是便當。山裡還有林業，振昌木業以車埕為基地採伐丹大林區，全盛時期員工600多人。"},{"who":"R","text":"那茶呢？我聽說鹿谷的凍頂烏龍茶很有名。"},{"who":"A","text":"1976年鹿谷國小舉辦第一屆凍頂優良茶比賽，冠軍茶喊價很高，凍頂烏龍茶的名號就傳開了。"},{"who":"R","text":"草屯好像也有一棟造型很特別的大建築？"},{"who":"A","text":"那是1977年啟用的手工業研究所陳列館。小任務：到車埕看看振昌留下的檜木宿舍，找找雨淋板的橫線。"}],"quiz":[{"q":"中部橫貫公路是哪一年通車的？","options":["1960年","1950年","1957年","1999年"],"answer":0,"explain":"中橫1956年7月7日開工，1960年5月9日通車。"},{"q":"1976年鹿谷舉辦第一屆比賽，讓哪一種茶聲名大開？","options":["凍頂烏龍茶","阿薩姆紅茶","東方美人茶","碧螺春"],"answer":0,"explain":"1976年5月2日在鹿谷國小舉辦凍頂優良茶比賽，凍頂烏龍茶從此出名。"}],"sources":[{"title":"臺灣省政府（中文維基百科）","url":"https://zh.wikipedia.org/wiki/臺灣省政府"},{"title":"中部橫貫公路（中文維基百科）","url":"https://zh.wikipedia.org/wiki/中部橫貫公路"},{"title":"凍頂烏龍茶（中文維基百科）","url":"https://zh.wikipedia.org/wiki/凍頂烏龍茶"},{"title":"國立臺灣工藝研究發展中心（中文維基百科）","url":"https://zh.wikipedia.org/wiki/國立臺灣工藝研究發展中心"},{"title":"中興新村文化景觀（文化部文化資產局國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/culturalLandscape/20110412000002"},{"title":"臺灣省政資料館（文化部文化資產局國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20110413000007"},{"title":"振昌興業股份有限公司建築群（文化部文化資產局國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20051021000001"}]},{"id":"now","name":"現在","range":"1982–今","cityName":"南投縣","title":"精省、921與重建","summary":"1998年修憲與相關法律調整後，同年12月起實施臺灣省政府功能業務與組織調整（精省），省府成為行政院的派出機關，許多原屬省府的廳處改制或裁撤，中興新村的廳舍多改由中央機關的中部辦公室使用；2018年7月起省府業務移交國家發展委員會。1999年9月21日凌晨1點47分，震央在集集的芮氏規模7.3地震重創南投，各縣市災損統計南投縣死亡886人；中興新村5個廳處大樓全倒，集集武昌宮整座倒塌，九份二山大規模崩塌形成堰塞湖。災後重建中，集集線2001年1月復駛，集集車站依原貌重建。2000年1月日月潭國家風景區管理處成立，2001年8月邵族正名，2011年中興新村登錄為文化景觀。","population":"","events":[{"year":"1998","text":"12月實施精省，臺灣省政府成為行政院派出機關，多數廳處改制或裁撤"},{"year":"1999","text":"9月21日凌晨1點47分大地震，震央在集集，南投是重災區"},{"year":"2000","text":"1月24日日月潭國家風景區管理處成立"},{"year":"2001","text":"1月21日集集線復駛，集集車站依原貌重建；8月8日政府正式承認邵族為原住民族"},{"year":"2011","text":"4月中興新村登錄為文化景觀，臺灣省政府大樓指定為古蹟"},{"year":"2018","text":"7月起臺灣省政府業務移交國家發展委員會"}],"landmarks":[{"name":"集集火車站","lat":23.82654,"lng":120.78489,"note":"921地震中嚴重受損，依原貌重建","approx":false},{"name":"集集武昌宮","lat":23.8309,"lng":120.79205,"note":"921地震中整座倒塌","approx":false},{"name":"九份二山（國姓鄉）","lat":23.93459,"lng":120.84163,"note":"921地震時大規模崩塌，形成堰塞湖；標示點為山頂","approx":true},{"name":"臺灣省政府（中興新村）","lat":23.95832,"lng":120.68728,"note":"精省後仍有機關辦公，請在外觀參觀","approx":false},{"name":"武德殿（南投市）","lat":23.90942,"lng":120.68399,"note":"921地震嚴重毀損，2001年修復再啟用","approx":false},{"name":"埔里酒廠","lat":23.96879,"lng":120.96017,"note":"921地震中部分廠房倒塌","approx":false},{"name":"伊達邵（魚池鄉）","lat":23.8471,"lng":120.93368,"note":"今天邵族的主要聚落，舊稱德化社","approx":false},{"name":"水社碼頭（日月潭）","lat":23.86439,"lng":120.91195,"note":"日月潭觀光的主要碼頭","approx":false}],"view":{"lat":23.89,"lng":120.83,"zoom":11},"dialogue":[{"who":"R","text":"Allan，中興新村現在還是省政府嗎？"},{"who":"A","text":"1998年12月起實施精省，省府組織精簡，許多廳舍改由中央機關的中部辦公室使用。"},{"who":"R","text":"那些省府建築，現在可以進去參觀嗎？"},{"who":"A","text":"有些目前仍是機關辦公使用，請在外觀參觀，開放情形以各機關公告為準。"},{"who":"R","text":"921大地震的震央就在南投，對吧？"},{"who":"A","text":"對，1999年9月21日凌晨1點47分，震央在集集，南投縣死亡886人，是最嚴重的災區之一。"},{"who":"R","text":"好多熟悉的地方都受傷了，有哪些呢？"},{"who":"A","text":"中興新村5個廳處大樓全倒，集集武昌宮整座倒塌，國姓九份二山整片山坡崩落，形成堰塞湖。"},{"who":"R","text":"後來大家怎麼重新站起來？現在週末的集集，人多到要排隊買香蕉冰耶！"},{"who":"A","text":"集集線2001年1月復駛，車站依原貌重建。小任務：到集集車站拍一張檜木站房，再和921前的老照片比比看。"}],"quiz":[{"q":"1999年921大地震的震央在南投縣哪一個鄉鎮？","options":["集集鎮","埔里鎮","竹山鎮","草屯鎮"],"answer":0,"explain":"921大地震震央在南投縣集集鎮，震源深度8公里。"},{"q":"精省後，中興新村許多原省府廳舍改由誰使用？","options":["各部會的中部辦公室","南投縣政府","民間飯店","大學校區"],"answer":0,"explain":"精省後原屬省府的廳處改制或撤銷，多數廳舍轉為各部會中部辦公室使用。"}],"sources":[{"title":"九二一大地震（中文維基百科）","url":"https://zh.wikipedia.org/wiki/九二一大地震"},{"title":"臺灣省政府（中文維基百科）","url":"https://zh.wikipedia.org/wiki/臺灣省政府"},{"title":"中興新村（中文維基百科）","url":"https://zh.wikipedia.org/wiki/中興新村"},{"title":"九份二山（中文維基百科）","url":"https://zh.wikipedia.org/wiki/九份二山"},{"title":"日月潭國家風景區（中文維基百科）","url":"https://zh.wikipedia.org/wiki/日月潭國家風景區"},{"title":"邵族（中文維基百科）","url":"https://zh.wikipedia.org/wiki/邵族"},{"title":"集集線（中文維基百科）","url":"https://zh.wikipedia.org/wiki/集集線"},{"title":"集集火車站（文化部文化資產局國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20041221000003"},{"title":"武德殿及其附屬建築群（文化部文化資產局國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020129000004"}]}],"qingCity":null,"ich":{"items":[{"id":"ich-shoutiangong-xiangqi","name":"南投縣名間鄉受天宮玄天上帝香期","type":"民俗","holder":"松柏嶺受天宮","registered":"2012-09-13","summary":"全臺分靈廟回松柏嶺祖廟進香的兩個月香期","intro":"名間鄉松柏嶺上的受天宮奉祀玄天上帝，官方紀錄指出信仰可上溯清代，最初只是地方小廟。清代移民遷徙，信徒把受天宮的香火帶到中部各地的新村落，日治時期已成為中部重要的玄天上帝信仰中心。戰後1953年成立理事會、1957年成立管理委員會，信仰逐漸擴及全臺，截至2009年自受天宮分靈的廟宇已達三千多間。每年從農曆正月底到三月底，各地分靈廟、祭祀團體與家壇陸續回祖廟進香、割火，農曆3月3日玄天上帝誕辰前後更有近百團香陣湧入，這段時間就稱為「香期」。南投縣於2012年登錄。","whereToSee":"松柏嶺受天宮（名間鄉松山村松山街118號）。香期每年從農曆正月底延續到三月底左右，農曆3月3日玄天上帝誕辰前後是高峰，進香團與陣頭最多。各團進香時間由各宮廟自行安排，請以受天宮公告為準。高峰期松柏嶺一帶人車擁擠、鞭炮聲大，請注意安全，並讓出進香隊伍與神轎的路線。","venueId":"venue-f-shoutiangong","dialogue":[{"who":"R","text":"Allan，松柏嶺上怎麼一路都是鑼鼓聲和鞭炮聲？"},{"who":"A","text":"這是受天宮的玄天上帝香期。從農曆正月底到三月底，全臺各地的分靈廟都回來進香割火。"},{"who":"R","text":"整整兩個月？那到底有多少間分靈廟啊？"},{"who":"A","text":"官方紀錄說，到2009年分靈廟宇已經三千多間，回祖廟的進香團多到算不清楚。"},{"who":"R","text":"三千多間！這個家族聚會也太大了吧，祖廟要準備多少椅子？"},{"who":"A","text":"所以說受天宮是玄天上帝信仰的重鎮。農曆3月3日誕辰前後，一天就有近百團香陣上山。"},{"who":"R","text":"人那麼多，Allan你上山會不會被擠成茶葉蛋？"},{"who":"A","text":"松柏嶺本來就是茶鄉，被擠成茶葉蛋也算入境隨俗。記得讓路給神轎和陣頭。"},{"who":"R","text":"小任務：在廟埕數一數，你看到的進香團旗幟來自幾個不同的縣市。"}],"quiz":[{"q":"受天宮玄天上帝香期的高峰，落在哪一天前後？","options":["農曆正月十五","農曆3月3日","農曆3月23日","農曆9月9日"],"answer":1,"explain":"農曆3月3日是玄天上帝誕辰，前後幾天有近百團香陣上松柏嶺進香。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20120913000001"},{"id":"ich-zinangong-dingjiu","name":"竹山社寮紫南宮吃丁酒","type":"民俗","holder":"竹山社寮紫南宮管理委員會","registered":"2009-09-02","summary":"元宵隔天在紫南宮廟埕分享麻油雞的吃福","intro":"「丁」指男丁。竹山社寮自古流傳吃丁酒習俗：過去一年家裡添丁的人家，元宵節以閹雞祭拜紫南宮土地公，新婚的準備豬腳與米酒，生女兒「許千金」的則準備母雞與雞蛋。拜完後廟方取下部分祭品，把雞頭、雞翅、雞腳、雞尾錐這「四點金」加上紅包送還信眾。農曆正月十六日，祭品煮成麻油雞，配上菜飯、滷肉，中午在廟埕請大家「吃福」，分享添丁、娶妻的喜氣。數十年前廟方邀請路過的進香團一起用餐，後來香客越來越多，雞肉得向外採購，2008年預估要準備12000斤雞酒。南投縣於2009年登錄。","whereToSee":"竹山社寮紫南宮（竹山鎮社寮里大公街40號）廟埕。每年農曆正月十六日中午舉行，前一天元宵節是信眾祭拜的日子。當天人潮非常多，交通與停車安排請以紫南宮及竹山鎮公所公告為準。吃福請依工作人員指示排隊，並且珍惜食物。","venueId":"venue-f-zinangong","dialogue":[{"who":"R","text":"Allan，元宵節都過了，紫南宮廟埕怎麼排了這麼長的隊伍？"},{"who":"A","text":"今天是農曆正月十六，社寮的吃丁酒。去年家裡添丁的人家，元宵節拿閹雞來拜土地公。"},{"who":"R","text":"拜完的雞呢？該不會整隻抱回家吧？"},{"who":"A","text":"廟方會把雞頭、雞翅、雞腳、雞尾錐這四點金加上紅包還給信眾，其他的煮成麻油雞請大家吃。"},{"who":"R","text":"所以排這麼長的隊，大家都是來分喜氣的？"},{"who":"A","text":"對，這又叫吃福。以前只有在地信徒吃，後來香客越來越多，雞肉還得向外採購好幾千斤。"},{"who":"R","text":"好幾千斤！土地公請客的預算，比你的年終獎金還大方。"},{"who":"A","text":"別戳我痛處。吃福時請依工作人員指示排隊，吃多少拿多少。"},{"who":"R","text":"小任務：吃完福，到廟前廣場找到永濟義渡碑，看看碑文說當年買了幾段田。"}],"quiz":[{"q":"竹山社寮紫南宮的吃丁酒在每年哪一天舉行？","options":["農曆正月初九","農曆正月十五","農曆正月十六","農曆2月2日"],"answer":2,"explain":"信眾在元宵節祭拜土地公，隔天農曆正月十六日中午把祭品煮成麻油雞，在廟埕請大家吃福。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20090902000002"},{"id":"ich-zinangong-jiejin","name":"竹山社寮紫南宮借金","type":"民俗","holder":"竹山社寮紫南宮管理委員會","registered":"2009-04-23","summary":"向社寮土地公借發財金，賺了再回來還","intro":"紫南宮是竹山社寮的土地公廟，提供信眾向土地公借「福德金」周轉。官方紀錄說，戰後初期民生困苦，紫南宮本著扶助居民的精神，開放社寮居民求取福德金；1960年代到1977年間，只在農曆正月十五、十六日開放給在地居民。後來借金的社寮子弟事業有成，消息傳開，改由社寮里民擔保讓外地信眾也能借。1983年起限額200元，1987年調整為上限600元。借金時先向土地公、土地婆與石頭公稟明姓名、住址與用途再擲筊，越早擲出聖筊能借越多；還金時帶回紅包袋，本金之外隨心意添加。南投縣於2009年登錄。","whereToSee":"竹山社寮紫南宮（竹山鎮社寮里大公街40號），全年都可以借金、還金，農曆正月與新年假期是高峰。官方紀錄寫的借金資格、證件與擲筊金額是登錄當時的做法，實際規定以紫南宮現場公告為準。廟前廣場有縣定古蹟永濟義渡碑，可以順道參觀。","venueId":"venue-f-zinangong","dialogue":[{"who":"R","text":"Allan，聽說紫南宮的土地公會借錢給人，是真的嗎？"},{"who":"A","text":"真的，這叫借金。先向土地公稟明姓名、住址和借錢用途，再擲筊決定能借多少。"},{"who":"R","text":"擲筊決定額度？那我第一次就擲出聖筊會怎樣？"},{"who":"A","text":"依官方紀錄，第一次就聖筊可以借600元，越多次才擲出，能借的就越少。"},{"who":"R","text":"才600元？Allan，這樣連買一箱竹山番薯都不太夠吧。"},{"who":"A","text":"重點不是金額，是土地公給你的好彩頭。賺了錢回來還，本金之外再隨心意添一點。"},{"who":"R","text":"原來是先借好運，再回來報喜，土地公根本是最有人情味的銀行。"},{"who":"A","text":"而且這家銀行不收利息，只收你的誠心。借金規定請以廟方現場公告為準喔。"},{"who":"R","text":"小任務：在廟裡找找那隻金雞，數數看牠身上貼了多少片金箔。"}],"quiz":[{"q":"依官方紀錄，借金時第一次就擲出聖筊，可以借多少錢？","options":["100元","300元","600元","1000元"],"answer":2,"explain":"官方紀錄寫明第一次聖筊可借600元，第二次才聖筊借500元，依此遞減，六次都沒有聖筊就不能借。實際規定以廟方公告為準。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20090423000007"},{"id":"ich-shao-lusan","name":"邵族Tungkariri Lus'an（祖靈祭）","type":"民俗","holder":"南投縣魚池鄉邵族文化發展協會","registered":"2009-04-23","summary":"日月潭邵族迎新年、敬祖靈的年度大祭","intro":"Lus'an是邵族的新年，也是最重要的年度祭儀。南投縣2009年以「邵族年祭」登錄，文化部2015年指定為重要民俗，兩者是同一套祭儀。農曆7月最後一晚，族人在頭目家舂石音，迎接農曆8月初一的新年。先生媽（女祭司Shinshii）為各家祖靈籃祭祀祈福，族人挨家挨戶飲公酒，還有狩獵儀式、甜酒祭與象徵成年的鑿齒儀式。若當年有族人自願擔任主祭，就辦「大過年」，搭建祖靈屋、迎出代表最高祖靈的日月盾牌，夜夜牽田歌舞，祭期近一個月；否則是約5天的「小過年」。邵族世居日月潭，2001年正名為臺灣第十個原住民族。","whereToSee":"日月潭伊達邵（魚池鄉日月村）邵族部落。祭儀從農曆7月最後一晚的舂石音開始，農曆8月初一是新年；當年是大過年或小過年、各項儀式與結束日期，都由部落與長老會議決定，每年不同，請以邵族部落或魚池鄉邵族文化發展協會公告為準。這是部落的祭祖儀式，不是觀光表演：請勿任意闖入祭場或族人家屋，不要觸碰祖靈籃、日月盾牌等祭物，拍照、錄影前先徵得同意，並聽從族人指示。","venueId":"venue-f-itathao","dialogue":[{"who":"R","text":"Allan，伊達邵晚上傳來一陣陣叩叩叩的聲音，是誰在敲東西？"},{"who":"A","text":"那是舂石音。農曆7月最後一晚，邵族族人用杵敲擊石頭，宣告新年就要到了。"},{"who":"R","text":"邵族的新年是農曆8月初一？跟我們過年完全不一樣耶！"},{"who":"A","text":"對，這就是祖靈祭，邵族最重要的年度祭儀。先生媽會為每家的祖靈籃祈福，族人挨家挨戶飲公酒。"},{"who":"R","text":"祖靈籃是什麼？可以打開來看看嗎？"},{"who":"A","text":"千萬不行。籃裡放著祖先的衣物，只有家人和先生媽能碰。日月盾牌也只有邵族男性能觸碰。"},{"who":"R","text":"了解，我的手會乖乖插在口袋裡。那大過年跟小過年差在哪？"},{"who":"A","text":"有族人自願當主祭就是大過年，會搭祖靈屋、夜夜牽田歌舞，祭期將近一個月，比我減肥的毅力還長。"},{"who":"R","text":"小任務：到部落先找一找祭典公告，看清楚哪些地方不能進入、哪些時候不能拍照。"}],"quiz":[{"q":"邵族祖靈祭中，哪一樣祭物只有家人和先生媽可以碰觸？","options":["祖靈籃","杵","麻糬","竹雞掃"],"answer":0,"explain":"祖靈籃（公媽籃仔）裡放著祖先的衣物，代表祖靈的存在，只有親人與先生媽可以碰觸，外人不可任意碰觸。"},{"q":"邵族傳統新年的第一天是哪一天？","options":["農曆正月初一","農曆7月15日","農曆8月初一","農曆9月9日"],"answer":2,"explain":"農曆7月最後一晚舂石音迎新年，農曆8月初一是邵族傳統新年的第一天。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20150326000002"},{"id":"ich-puli-qingjiao","name":"埔里祈安清醮","type":"民俗","holder":"埔里恒吉宮（醮局總壇）","registered":"2022-01-22","summary":"逢子年建醮、卯年三獻的埔里全鎮大醮","intro":"埔里祈安清醮至少有近百年歷史，留有大正13年（1924年）與昭和11年（1936年）的醮壇老照片。依傳統每逢子年建清醮，約12年一科；自1952年起，再於卯年舉行三獻清醮，俗稱醮尾。醮典由地方大廟恒吉宮媽祖廟擔任總壇綜理醮局，下設東、南、西、北四柱醮壇與63座分壇，醮區涵蓋埔里鎮全境與仁愛鄉部分村落，全境240多家宮廟參與。建醮經費主要來自各家戶繳交的丁口錢，2020年庚子科收取率約8成；建醮期間全境茹素也早已約定成俗。內壇斗燈首採世襲傳承，與多數醮典不同。南投縣於2022年登錄。","whereToSee":"埔里恒吉宮（埔里鎮南興街367號）是醮局總壇，醮期另在鎮上設東、南、西、北四柱醮壇與分壇。依慣例逢子年建醮、卯年三獻，上一科清醮在2020年庚子年，依此推算下一科清醮應在2032年，但實際日期、醮壇地點與茹素期間都以醮局及恒吉宮公告為準。醮期請尊重全境茹素的習俗，參觀醮壇時勿碰觸壇內法器與供品。","venueId":"venue-f-hengjigong","dialogue":[{"who":"R","text":"Allan，埔里的朋友說，建醮那幾天全鎮的便當都變成素食？"},{"who":"A","text":"沒錯，埔里祈安清醮期間，全境茹素早就約定成俗，連路邊攤都跟著換菜單。"},{"who":"R","text":"那多久才辦一次？每年都這樣我會想念滷肉飯。"},{"who":"A","text":"依傳統逢子年建醮，大約12年一科，再過三年到卯年，還會辦一場三獻清醮，叫做醮尾。"},{"who":"R","text":"還有醮尾！那誰來負責這麼大的祭典？"},{"who":"A","text":"總壇設在恒吉宮媽祖廟，鎮上再設東南西北四柱醮壇和63座分壇，240多家宮廟一起參與。"},{"who":"R","text":"錢從哪裡來？該不會是Allan你贊助的吧？"},{"who":"A","text":"我只贊助冷笑話。經費主要靠各家戶繳交丁口錢，上一科收取率約八成，可見大家多投入。"},{"who":"R","text":"小任務：到恒吉宮找一找有沒有歷年建醮的紀念照片或匾額，看看最早是哪一年。"}],"quiz":[{"q":"埔里祈安清醮依傳統逢哪一種年份建醮？","options":["午年","子年","酉年","卯年"],"answer":1,"explain":"埔里依傳統逢子年建清醮，約12年一科；再過三年的卯年另辦三獻清醮，俗稱醮尾。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20220302000003"},{"id":"ich-a-pasibutbut","name":"布農族音樂pasibutbut（八部合音、祈禱小米豐收歌）","type":"傳統表演藝術","holder":"南投縣信義鄉布農文化協會","registered":"2009-04-23","summary":"信義鄉布農族祈求小米豐收的祭儀歌","intro":"Pasibutbut常被稱為「布農族八部合音」，是祈禱小米豐收的祭儀歌曲。小米是布農族傳統賴以維生的作物，歲時祭儀以粟作為中心；依官方紀錄，傳統上在一月播種祭到三月除草祭期間演唱，除草祭結束後就不准再唱。歌曲沒有歌詞，以「u」「e」等母音演唱，族人彼此聆聽、不斷修正音程，呈現泛音與完全五度的和聲；演唱者須是「聖潔」的男子，表達對天神的敬畏。目前只有巒社群、郡社群保有完整的祭儀過程。南投縣於2009年登錄，文化部於2010年登錄為重要傳統藝術，保存團體是1986年成立、屬郡社群的南投縣信義鄉布農文化協會。","whereToSee":"流傳於信義鄉布農族部落。這是祭儀歌曲而非一般表演，沒有固定的公開演出時刻，傳統上只在播種祭到除草祭期間演唱；可留意信義鄉與保存團體的文化活動公告。進入部落、錄音錄影前請先徵得同意，並遵守部落禁忌。","venueId":"","dialogue":[{"who":"R","text":"Allan，聽說布農族有一首歌叫八部合音，真的有八個聲部嗎？"},{"who":"A","text":"這個名稱是後來大家叫出來的，它是祈禱小米豐收的歌，重點是大家的聲音互相聆聽、融成一體。"},{"who":"R","text":"為什麼族人要特別為小米唱歌呢？"},{"who":"A","text":"小米是布農族傳統賴以維生的作物，一年中的重要祭儀都繞著小米耕作，唱歌是向天神祈求小米順利長大。"},{"who":"R","text":"所以它不是拿來表演給觀光客聽的？"},{"who":"A","text":"對，它是祭儀的一部分。依官方紀錄，傳統上只在播種祭到除草祭之間唱，除草祭結束就不准再唱。"},{"who":"R","text":"這首歌沒有歌詞，大家要怎麼對準音？"},{"who":"A","text":"靠耳朵！大家一邊唱一邊微調，像一群人一起轉收音機找頻道，對到了，聲音就開始共鳴。"},{"who":"R","text":"小任務：聆聽錄音時，試著找出那種好像多出來的泛音，數數你聽到幾層聲音。"}],"quiz":[{"q":"依官方紀錄，祈禱小米豐收歌傳統上在什麼期間演唱？","options":["收穫祭之後到年底","播種祭到除草祭期間","只在打耳祭當天","一年四季都可以"],"answer":1,"explain":"傳統上在一月播種祭到三月除草祭期間演唱，除草祭結束後就不准再唱。"},{"q":"南投縣登錄的布農族音樂保存團體是哪一個？","options":["賽德克傳統文化藝術團","花蓮縣布農文化教育關懷協會","南投縣信義鄉布農文化協會","邵族文化發展協會"],"answer":2,"explain":"南投縣與文化部登錄的保存團體都是南投縣信義鄉布農文化協會。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalPerformingart/20100618000003"},{"id":"ich-a-uyas-kmeki","name":"賽德克族祭典舞蹈歌（uyas kmeki）","type":"傳統表演藝術","holder":"賽德克傳統文化藝術團","registered":"2013-01-15","summary":"仁愛鄉賽德克族祭典中即興領唱的歌舞","intro":"在賽德克族的觀念裡，「uyas kmeki」不是指某一首歌，而是祭典歌舞的泛稱：由一連串曲調前後銜接，再即興配上歌詞與舞步。過去在農事、狩獵等各種祭典中，歌舞都不可或缺，官方紀錄甚至說祭典的精華就在歌舞。這種複音歌唱的精髓在領唱者的即興領唱與領舞；過去部落間代代傳承領唱人才，如今這套傳承機制已不復存在，有瀕危之虞。保存團體賽德克傳統文化藝術團的成員主要來自仁愛鄉南山溪部落，由高齡耆老Obin Nawi帶領年輕世代傳唱祖先留下的古謠，曲目保存相對完整。南投縣於2013年登錄。","whereToSee":"由仁愛鄉的賽德克傳統文化藝術團傳承，沒有固定的公開演出時刻；可留意仁愛鄉公所與南投縣政府文化局的活動公告。這是祭典歌舞，請以尊重的態度欣賞，錄影前先徵得同意。","venueId":"","dialogue":[{"who":"R","text":"Allan，賽德克族的祭典歌舞，是一首固定的歌嗎？"},{"who":"A","text":"不是喔，它是祭典歌舞的總稱，好幾段曲調接在一起，歌詞和舞步還要即興配上去。"},{"who":"R","text":"即興？那誰來決定下一段唱什麼？"},{"who":"A","text":"靠領唱的人，他一邊領唱一邊領舞，大家跟著回應，所以領唱者可以說是整場歌舞的靈魂。"},{"who":"R","text":"聽起來好難，現在部落裡還有人會嗎？"},{"who":"A","text":"官方紀錄說，過去部落會代代培養領唱的人，現在這套傳承機制已經不在了，所以有瀕危的危機。"},{"who":"R","text":"那現在是誰在努力守住這些古謠？"},{"who":"A","text":"仁愛鄉南山溪部落族人組成的賽德克傳統文化藝術團，由耆老帶著年輕人一起唱祖先的古謠。"},{"who":"R","text":"小任務：如果有機會欣賞，注意聽領唱者一開口，其他人是怎麼接上去的。"}],"quiz":[{"q":"依官方紀錄，賽德克族祭典歌舞的精髓繫於什麼？","options":["固定不變的歌詞","樂器伴奏","領唱者的即興領唱與領舞","華麗的舞台燈光"],"answer":2,"explain":"官方紀錄指出，這種複音歌唱的精髓繫於領唱者的即興領唱與領舞。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalPerformingart/20130115000001"},{"id":"ich-a-qi-wang","name":"漆工藝","type":"傳統工藝","holder":"王清霜、黃麗淑","registered":"2009-10-30","summary":"草屯漆藝，高蒔繪與天然漆傳統工法","intro":"臺灣漆器生產始於日治時期，日本人在臺開設漆器製造所、引種漆樹成功，埔里一帶後來成為天然漆的主要產地之一。天然漆講究溫度與溼度，初學者約五到六成還會因過敏長漆瘡，傳承不易。王清霜被官方紀錄稱為我國赴日研習漆藝第一人，尤擅「高蒔繪」，要經拓稿、堆高、研磨、蒔粉、推光等繁複工序，一件作品往往耗時數月甚至數年。黃麗淑承傳陳火慶藝師技藝，堅持天然漆與傳統工法，投入教學傳習逾20年。南投縣於2009年登錄兩人，文化部於2010年認定王清霜、2020年認定黃麗淑為重要傳統工藝保存者。","whereToSee":"保存者在草屯鎮，工作室不是公開展示場所，請勿自行前往。可到草屯的國立臺灣工藝研究發展中心看工藝展覽，展出內容依檔期而定，請以中心公告為準。","venueId":"venue-a-ntcri","dialogue":[{"who":"R","text":"Allan，漆器不就是刷一層亮亮的油漆嗎？"},{"who":"A","text":"差很多！天然漆是從漆樹割下的汁液，要在固定的溫度溼度下才會乾，還可能讓人過敏。"},{"who":"R","text":"過敏？難道天然漆還會偷偷咬人喔？"},{"who":"A","text":"這叫漆瘡。官方紀錄說初學者約五到六成會碰到，所以很多人學到一半就打退堂鼓。"},{"who":"R","text":"那王清霜藝師最厲害的絕活是什麼？"},{"who":"A","text":"高蒔繪！要一層一層把圖案堆高、研磨，再撒上金粉推光，一件作品常常要好幾個月。"},{"who":"R","text":"那另一位保存者黃麗淑藝師有什麼特色？"},{"who":"A","text":"她堅持用天然漆和傳統工法，投入教學二十多年，文化部在2020年也認定她為重要保存者。"},{"who":"R","text":"小任務：下次看到漆器，斜著看光澤，找找圖案有沒有微微凸起，那可能就是蒔繪。"}],"quiz":[{"q":"王清霜藝師尤其擅長哪一種漆藝技法？","options":["高蒔繪","螺鈿鑲嵌","剪黏","交趾燒"],"answer":0,"explain":"官方紀錄指出王清霜的「高蒔繪」技法無人能及。"},{"q":"漆工藝使用的天然漆來自哪裡？","options":["石油提煉","礦物顏料","松樹的松脂","漆樹的汁液"],"answer":3,"explain":"天然漆是從漆樹割取的汁液，為自然生成的塗料。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20100618000005"},{"id":"ich-a-qiangjin","name":"漆工藝－戧金","type":"傳統工藝","holder":"王賢民","registered":"2011-04-12","summary":"在漆面刻線填金的細膩戧金技法","intro":"戧金又稱沈金、鎗金，是在髹好的漆器上用刀刻出細線與細點，再填入金箔或金粉，讓圖案閃出金色線條的裝飾技法，在臺灣十分少見。工藝者要先有構圖、素描的底子，熟練髹、描、雕、貼、推等基本功，還要懂得養護各式戧金刀，依題材製作平刀、圓刀、鉤刀、斜刀、針刀等刀頭，刻出深淺不同的線條。王賢民藝師融會各種刀法，再加上貼金、摻金、柔推，技法圓熟，題材多為臺灣常見的花、鳥、民俗與吉慶圖騰，也擅長運用身邊材料發展新技法。南投縣於2011年登錄，保存者在草屯鎮。","whereToSee":"保存者在草屯鎮，保存者工作室不是公開展示場所，請勿自行前往。可留意南投縣政府文化局與國立臺灣工藝研究發展中心的漆藝展覽公告，展品依檔期而定。","venueId":"","dialogue":[{"who":"R","text":"Allan，戧金這兩個字我都快不會念了，它到底在做什麼？"},{"who":"A","text":"簡單說，就是在漆器表面用刀刻出細線，再把金箔或金粉填進去，圖案就變成閃亮的金色線條。"},{"who":"R","text":"那不就像是在漆器的身上刺青嗎？"},{"who":"A","text":"這比喻很傳神！而且刀子不只一把，平刀、圓刀、鉤刀、斜刀、針刀，刻出的深淺都不一樣。"},{"who":"R","text":"王賢民藝師平常都喜歡刻些什麼圖案？"},{"who":"A","text":"多半是臺灣常見的花、鳥、民俗和吉慶圖騰，很有在地味，他也很會用身邊的材料發明新技法。"},{"who":"R","text":"萬一不小心刻錯一刀，該怎麼辦？"},{"who":"A","text":"漆面刻下去就回不去了，所以下刀前的構圖最重要。我削蘋果皮都會斷，還是乖乖欣賞就好。"},{"who":"R","text":"小任務：看到戧金作品時，靠近一點，比較粗線和細線的金色亮度有什麼不同。"}],"quiz":[{"q":"戧金技法是怎麼做出金色線條的？","options":["用金色油漆直接畫上去","把金線縫在漆器上","用火把漆面燒成金色","在漆面刻出線條再填入金箔或金粉"],"answer":3,"explain":"戧金是在漆器上刻畫出線條與細點，再以貼金、摻金等方式填入金色。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20110412000005"},{"id":"ich-a-makie","name":"漆工藝－蒔繪","type":"傳統工藝","holder":"王賢志","registered":"2011-04-12","summary":"工序最繁複的漆畫技法，讓平面變立體","intro":"蒔繪被官方紀錄形容為所有漆工藝技法中工序最繁複的一項，取自傳統「平脫」技法的精神再加以精緻、典雅化，可視為漆畫中的文人畫。蒔繪分為平蒔繪、研出蒔繪、高蒔繪，以及綜合運用前三者的肉合蒔繪。工藝者要熟練髹、描、堆、貼、磨、撒、蒔、推、罩等基本功，才能透過陰陽光影的變化，把平面畫作的紋飾立體化。王賢志藝師精通各種漆藝技法，尤以蒔繪見長，作品多取材臺灣本土的花、鳥、民俗與吉慶圖騰，也善於因畫制宜，運用身邊的材料創發新技法。南投縣於2011年登錄，保存者在草屯鎮。","whereToSee":"保存者在草屯鎮，保存者工作室不是公開展示場所，請勿自行前往。可留意南投縣政府文化局與國立臺灣工藝研究發展中心的漆藝展覽公告，展品依檔期而定。","venueId":"","dialogue":[{"who":"R","text":"Allan，蒔繪的蒔，不是蒔花的蒔嗎？跟種花有關？"},{"who":"A","text":"有點像喔！蒔繪是在還沒乾的漆上撒金粉或色粉，像播種一樣，讓圖案慢慢長出光澤。"},{"who":"R","text":"原來是在漆上種金子！那為什麼說它最麻煩？"},{"who":"A","text":"官方紀錄說它是漆藝裡工序最繁複的，要描、堆、貼、磨、撒、推、罩，一道接一道。"},{"who":"R","text":"蒔繪還可以再細分成好幾種類型嗎？"},{"who":"A","text":"有平蒔繪、研出蒔繪、高蒔繪，還有混在一起用的肉合蒔繪，名字愈往後，立體感愈強。"},{"who":"R","text":"那王賢志藝師的作品，最喜歡畫什麼題材？"},{"who":"A","text":"臺灣的花鳥、民俗和吉慶圖案，他還會依畫面需要，拿身邊的材料發明新做法。"},{"who":"R","text":"小任務：欣賞蒔繪作品時，換個角度看看，金色的光會不會跟著你移動。"}],"quiz":[{"q":"下列哪一種不是官方紀錄提到的蒔繪類型？","options":["平蒔繪","高蒔繪","拉坯蒔繪","肉合蒔繪"],"answer":2,"explain":"蒔繪分為平蒔繪、研出蒔繪、高蒔繪與肉合蒔繪；拉坯是製陶的成型方法。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20110412000006"},{"id":"ich-a-zhubian","name":"竹編工藝","type":"傳統工藝","holder":"黃塗山（歿）、黃啟祥、劉興澤、林秀鳳、涂素英、蘇素任、邱錦緞、葉寶蓮、徐暋盛","registered":"2009-04-23","summary":"竹山竹編，黃塗山與弟子們的傳承","intro":"南投竹林資源豐富，日治時期臺灣總督府在竹山等地設立工藝傳習所，奠定竹編發展的基礎；戰後竹材與人才持續培育，1960年代後竹產業更成為出口經濟的重要一環。黃塗山從事竹編五十年，竹工技藝多元、從徒無數，南投縣於2009年登錄，文化部於2010年認定他為重要傳統工藝保存者，官方紀錄註明他已過世。2020年起，南投縣陸續認定黃啟祥、劉興澤、林秀鳳、涂素英、蘇素任、邱錦緞、葉寶蓮、徐暋盛為保存者，其中多位是黃塗山的弟子或傳習計畫藝生，黃啟祥是他的次子；保存者分布在竹山、草屯、鹿谷、埔里等地。","whereToSee":"保存者工作室多為私人場所，請勿自行前往。竹山文化園區的竹博物館展示竹工藝，草屯的國立臺灣工藝研究發展中心也常有竹藝展覽，展出內容與開放時間請以各館公告為準。","venueId":"venue-a-zhushan-park","dialogue":[{"who":"R","text":"Allan，竹山為什麼會變成竹編重鎮？"},{"who":"A","text":"這裡竹林多，日治時期又在竹山設了工藝傳習所，教大家把竹子剖成細篾，編成更精緻的器物。"},{"who":"R","text":"大家常說的人間國寶黃塗山是誰？"},{"who":"A","text":"他從事竹編五十年，徒弟遍布各地，2010年被文化部認定為重要保存者，官方紀錄註明他已過世。"},{"who":"R","text":"師父走了，這門手藝還有人接下去嗎？"},{"who":"A","text":"還在！南投縣後來又認定八位保存者，好幾位是他的弟子或傳習藝生，黃啟祥就是他的次子。"},{"who":"R","text":"一整個竹編家族，好像竹子一節一節往上長。"},{"who":"A","text":"說得好，竹子靠竹節才站得穩，傳承也是一代接一代。可惜我編竹籃，只會編出漏斗。"},{"who":"R","text":"小任務：到竹山看竹編時，觀察籃子的竹篾怎麼一上一下交錯，找出最細的一條。"}],"quiz":[{"q":"依官方紀錄，日治時期在竹山等地設立了什麼，奠定竹編發展的基礎？","options":["工藝傳習所","製糖會社","樟腦出張所","鐵道部工廠"],"answer":0,"explain":"臺灣總督府在竹山等地設立工藝傳習所，施以更精緻的竹工藝教育。"},{"q":"竹編保存者黃啟祥和黃塗山是什麼關係？","options":["師兄弟","同班同學","父子","叔姪"],"answer":2,"explain":"官方紀錄指出黃啟祥是黃塗山藝師的次子，自幼跟隨父親學習。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20100618000006"},{"id":"ich-a-lantai","name":"竹工藝－籃胎漆器","type":"傳統工藝","holder":"李榮烈","registered":"2009-10-30","summary":"竹編為胎、天然漆塗裝的籃胎漆器","intro":"籃胎漆器是先用竹子編出器物的胎體，再以天然漆層層塗裝，竹編經過漆的處理，更顯內斂之美。李榮烈藝師早年受竹編大師黃塗山指導，後來向陳火慶學習漆藝技法，把竹編與漆藝融為一體，成為作品的重要特色；他浸淫竹編超過半世紀，也精通木工，曾獲民族工藝獎、工藝成就獎肯定。官方紀錄提到，南投縣在竹山設竹材專業加工區推動竹產業，1988年又成立以竹藝為主題的竹藝博物館，是全國第一座啟用的地方文物特色館。南投縣於2009年登錄，文化部於2016年認定他為重要傳統工藝保存者。","whereToSee":"保存者工作室不是公開展示場所，請勿自行前往。可留意國立臺灣工藝研究發展中心與南投縣政府文化局的工藝展覽，展品依檔期而定。","venueId":"","dialogue":[{"who":"R","text":"Allan，籃胎漆器到底是竹籃還是漆器？我搞糊塗了。"},{"who":"A","text":"兩個都是！先用竹子編出器物的骨架，再一層一層塗上天然漆，竹編就穿上了一件亮面外套。"},{"who":"R","text":"要會竹編又要會漆藝，等於一個人學兩門功夫？"},{"who":"A","text":"沒錯，李榮烈藝師早年跟黃塗山學竹編，後來又向陳火慶學漆藝，才把兩門手藝合在一起。"},{"who":"R","text":"竹編塗上了漆以後，有什麼不一樣？"},{"who":"A","text":"竹編會變得更沉穩內斂。就像我的光頭，抹了乳液之後，特別有質感。"},{"who":"R","text":"這個比喻我給零分。那他得過什麼肯定？"},{"who":"A","text":"民族工藝獎、工藝成就獎都有，文化部在2016年認定他為重要傳統工藝保存者。"},{"who":"R","text":"小任務：看到籃胎漆器時，找找漆面底下還隱約看得到的竹編紋路。"}],"quiz":[{"q":"籃胎漆器是哪兩種工藝的結合？","options":["陶藝與木雕","竹編與漆藝","刺繡與染布","石雕與彩繪"],"answer":1,"explain":"籃胎漆器以竹編為胎，再以天然漆塗裝，融合竹編與漆藝。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20160504000002"},{"id":"ich-a-seediq-tninun","name":"賽德克族傳統織布工藝（Tninun na Seediq bale／Sediq balay／Seejiq balay）","type":"傳統工藝","holder":"張胡愛妹（歿）、林喜美、高雪珠","registered":"2012-10-01","summary":"織進信仰與族群記憶的賽德克族織布","intro":"在傳統賽德克族社會，織布是婦女必備的技能。擅織的婦女被稱為「mqetin bale」（真正的女人），須勤勞且才德兼備，相傳死後才能順利通過彩虹橋（Hako Utux）與祖靈團聚。織布從栽種苧麻、積麻、捻線、理經、染色、整經到織作，工序繁長；技法依用途分為平織、斜紋織、提花、浮織、緯挑、經挑等。紋樣與用色帶有信仰內涵，具族群識別的功能，承載著族群的神話與信仰。南投縣於2012年登錄並認定張胡愛妹，官方紀錄註明她已過世；2020年再認定仁愛鄉的林喜美、高雪珠為保存者。","whereToSee":"保存者住在仁愛鄉部落，沒有固定的公開展示場所，請勿自行登門。可留意仁愛鄉公所與南投縣政府文化局的織布展演、傳習活動公告；進入部落、拍照前請先徵得同意。","venueId":"","dialogue":[{"who":"R","text":"Allan，賽德克族的織布，跟我們買布做衣服差在哪？"},{"who":"A","text":"差在從頭到尾都自己來！從種苧麻、剝麻、捻線、染色、整經，一路做到織成布。"},{"who":"R","text":"光是聽就手痠了。為什麼織布這麼重要？"},{"who":"A","text":"傳統上，會織布的婦女被尊稱為真正的女人，相傳這樣的人死後才能走過彩虹橋，與祖靈團聚。"},{"who":"R","text":"原來織布跟信仰連在一起，不只是手工藝。"},{"who":"A","text":"對，布上的紋樣和顏色都有意義，還有族群識別的功能，等於把祖先的故事穿在身上。"},{"who":"R","text":"現在是哪些織布者在傳承這門手藝？"},{"who":"A","text":"縣府先認定張胡愛妹，官方紀錄註明她已過世，2020年又認定仁愛鄉的林喜美和高雪珠。"},{"who":"R","text":"小任務：看到賽德克族織品時，找找菱形紋，數數同一排重複了幾次。"}],"quiz":[{"q":"傳統上擅長織布的賽德克族婦女被尊稱為什麼？","options":["頭目","獵人","祭司","真正的女人"],"answer":3,"explain":"擅織的婦女被稱為mqetin bale，意思是真正的女人。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20121001000001"},{"id":"ich-a-seediq-puniri","name":"賽德克族Gaya tminun傳統織布（puniri經挑技法）","type":"傳統工藝","holder":"張鳳英（Seta Bakan）、張貴珠","registered":"2012-10-01","summary":"賽德克族最上乘的經挑織法，母傳女","intro":"puniri（經挑）是賽德克族特有的織布技法，也是傳統織藝中最上乘的禮服織作技術；看到織品上大小菱形紋、豆紋等紋路，就能認出是賽德克族的織布。官方紀錄指出，puniri代表族人織布文化的總成，蘊含母傳女的織布傳承與家徽傳承的歷史意義；從在地種苧麻、製作織具，到剝皮取纖、捻線、染色、整經與織布，都和土地及歲時祭儀相連。南投縣於2012年登錄經挑技法，認定張貴珠、張鳳英母女為保存者；文化部於2021年登錄「賽德克族Gaya tminun傳統織布」為重要傳統工藝，認定張鳳英（Seta Bakan）為保存者。","whereToSee":"保存者住在仁愛鄉部落，沒有固定的公開展示場所，請勿自行登門。官方紀錄提到，賽德克傳統文化藝術團展演歌舞時會穿著傳統服飾；可留意仁愛鄉與南投縣政府文化局的展演公告，拍照前請先徵得同意。","venueId":"","dialogue":[{"who":"R","text":"Allan，經挑是什麼？聽起來像在挑剔經書。"},{"who":"A","text":"哈哈，是挑經線啦！織布時把直向的經線挑起來，織出菱形紋、豆紋這些圖案。"},{"who":"R","text":"一根一根挑？那不是要挑到天荒地老？"},{"who":"A","text":"所以它是賽德克族最上乘的禮服織法，縣府登錄時說，張貴珠、張鳳英母女是碩果僅存的保存者。"},{"who":"R","text":"母女兩代一起傳承，聽起來好溫馨。"},{"who":"A","text":"這正是重點，官方紀錄說經挑技法帶有母傳女的意義，也和家徽的傳承連在一起。"},{"who":"R","text":"後來文化部也有把它登錄起來嗎？"},{"who":"A","text":"2021年登錄為重要傳統工藝，認定張鳳英為保存者，母親教女兒的手藝成了全國級的文化資產。"},{"who":"R","text":"小任務：看到賽德克族禮服時，找找大大小小的菱形紋，比較大菱形和小菱形怎麼排列。"}],"quiz":[{"q":"依官方紀錄，看到織品上哪些紋路，就可知是賽德克族經挑織布的特徵？","options":["雲紋與龍紋","菱形紋與豆紋","百步蛇紋","格子紋"],"answer":1,"explain":"官方紀錄指出，見到菱形紋（大小）、豆紋等紋路，即可知為賽德克族織布的特徵。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20210521000001"},{"id":"ich-a-nantoutao","name":"傳統南投陶工藝","type":"傳統工藝","holder":"林清河、林國隆","registered":"2020-02-26","summary":"兩百多年的南投窯業與柴燒裝飾技法","intro":"依文獻記載，南投窯業始於18世紀末清嘉慶年間，是臺灣陶瓷發展最久的窯區；日治時期「南投燒」更成為臺中州名產。先民就地取用南投黏土，依在地氣候與樹種，以柴燒窯燒成火烘、筷籠、香筒、龍壺、油甕、粿印、大水缸等日用器皿，質樸而裝飾細膩，其中浮雕、透雕、鑲嵌、貼花、化妝土等技法最具代表性。南投縣於2020年登錄，認定集集添興窯第三代窯主林清河，他熟習各種南投陶裝飾技法；2022年再認定水里蛇窯第三代窯主林國隆，他擅長傳統柴燒，能燒出火痕、落灰、結晶等不同風格。","whereToSee":"水里蛇窯陶藝文化園區（水里鄉，需購票入園）與集集添興窯（集集鎮，參觀請先預約）都看得到傳統蛇窯與柴燒陶器；南投市武德殿的南投陶展示館則介紹南投陶的歷史。開放時間請以各場館公告為準。","venueId":"venue-a-shuili-sheyao","dialogue":[{"who":"R","text":"Allan，南投不靠海，怎麼會有這麼有名的陶？"},{"who":"A","text":"就是靠山才有好黏土和柴火啊！南投窯業從清嘉慶年間就開始，是臺灣發展最久的窯區。"},{"who":"R","text":"那早期南投的窯場，都燒些什麼東西？"},{"who":"A","text":"火烘、筷籠、香筒、油甕、粿印、大水缸，全是過日子用得到的東西，實用又耐看。"},{"who":"R","text":"南投陶有哪些招牌的裝飾技法呢？"},{"who":"A","text":"浮雕、透雕、鑲嵌、貼花、化妝土，只靠雕刻工具和不同性質的陶土來裝飾，樸實又細膩。"},{"who":"R","text":"現在是誰在守護這門南投陶手藝？"},{"who":"A","text":"集集添興窯的林清河和水里蛇窯的林國隆，兩位都是自家窯場的第三代窯主，從小在窯邊長大。"},{"who":"R","text":"小任務：到窯場時找一件柴燒陶器，看看表面有沒有火燒留下的火痕或落灰。"}],"quiz":[{"q":"依官方紀錄，南投窯業大約從什麼時候開始？","options":["荷蘭時期","日治昭和年間","戰後初期","清嘉慶年間"],"answer":3,"explain":"依文獻記載，南投窯業始於18世紀末清嘉慶年間。"},{"q":"日治時期成為臺中州名產的是哪一種陶？","options":["南投燒","鶯歌燒","北投燒","苗栗燒"],"answer":0,"explain":"官方紀錄指出，日治時期「南投燒」成為臺中州名產，遠近馳名。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20200421000001"},{"id":"ich-a-shoujipi","name":"傳統南投陶工藝－手擠坯","type":"傳統工藝","holder":"曾樹枝","registered":"2013-02-26","summary":"一節節推擠土條，做出大型陶缸","intro":"手擠坯是傳統南投陶成型法中的「泥條盤築法」：先做好陶器底部，再把搓成條狀的土條一節一節往上推擠，另一手掌配合擋壓，靠雙手力道把土條接合穩固，最後用陶拍拍打結實。因為可以不斷往上加高，手擠坯是南投陶製作大型陶缸的獨門技術，做出的大水缸、醬缸、防空缸，官方紀錄稱「獨步全台」，而擁有這項技術的人已寥寥無幾。曾樹枝作陶年資超過60年，作品饒富傳統藝術氣息，尤其擅長以手擠坯成型大件器物，精熟盤條、整型、拍坯等步驟。南投縣於2013年登錄，保存者在南投市。","whereToSee":"保存者在南投市，工作場所不對外開放，請勿自行前往。南投市武德殿的南投陶展示館介紹南投陶的歷史與器物，開放時間請以南投縣政府文化局公告為準。","venueId":"venue-a-nantoutao","dialogue":[{"who":"R","text":"Allan，手擠坯聽起來好像在擠牙膏？"},{"who":"A","text":"有點像！把土搓成長條，一節一節往上推擠，另一隻手在旁邊擋著，讓土條黏得牢牢的。"},{"who":"R","text":"為什麼不直接用拉坯機轉一轉就好？"},{"who":"A","text":"因為要做的是大水缸！手擠坯可以一直往上加高，拉坯機可轉不出那種大傢伙。"},{"who":"R","text":"大水缸、醬缸，還有防空缸？名字好有年代感。"},{"who":"A","text":"對，官方紀錄說這些大缸獨步全台。最後還要用陶拍拍打，把缸身拍得結結實實。"},{"who":"R","text":"曾樹枝藝師做這一行，已經做了多久？"},{"who":"A","text":"作陶超過60年了。我拍打的經驗只有拍西瓜，聽聲音挑甜的，完全不是同一個等級。"},{"who":"R","text":"小任務：在展示館找一個大陶缸，看看缸身有沒有一圈一圈接起來的痕跡。"}],"quiz":[{"q":"手擠坯技法最適合製作哪一種器物？","options":["小茶杯","薄胎瓷碗","陶笛","大型陶缸"],"answer":3,"explain":"手擠坯可以不斷往上加高，是南投陶製作大型陶缸的獨門技術。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20130226000005"},{"id":"ich-a-tianran-ranse","name":"天然染色","type":"傳統工藝","holder":"陳景林、馬毓秀","registered":"2020-09-08","summary":"復原上百種天然染料配方的染色工藝","intro":"人類染織文化的發展比文字還早，臺灣染作承續華夏文化與在地原住民族文化，近代又受日本與歐美影響。1930至1980年代化學染料取代天然染料，天然染色一度中斷。陳景林、馬毓秀兩位保存者長年田野調查、採集試驗，復原一百多種天然染料配方，累積數以千計的色卡，把天然染色技藝系統化；兩人蠟染、型染、絞染、夾染、繪染等技藝純熟，長期教學推廣，臺灣藍染、柿染、草木染的興起與他們的努力息息相關。官方紀錄也提到南投縣中寮、埔里、信義等地的植物染。南投縣於2020年登錄，保存者在南投市。","whereToSee":"保存者在南投市，保存者工作室不是公開展示場所，請勿自行前往。可留意南投縣政府文化局與國立臺灣工藝研究發展中心的染織展覽、研習公告。","venueId":"","dialogue":[{"who":"R","text":"Allan，天然染色是用什麼染？果汁嗎？"},{"who":"A","text":"植物的根、莖、葉、花、果實都可能派上用場，每一種顏色都有自己的配方。"},{"who":"R","text":"那以前的人，大家都是這樣染布嗎？"},{"who":"A","text":"對，可是1930到1980年代化學染料普及，天然染色一度中斷，很多配方差點失傳。"},{"who":"R","text":"那後來是誰把這些配方一個一個救回來的？"},{"who":"A","text":"陳景林、馬毓秀兩位藝師長年田野調查、反覆試驗，復原了一百多種天然染料配方。"},{"who":"R","text":"一百多種！那色卡一定多到可以鋪滿整面牆。"},{"who":"A","text":"官方紀錄說累積了數以千計的色卡。我的衣服只有黑白兩色，看了真的很慚愧。"},{"who":"R","text":"小任務：散步時撿一片落葉，想想它可能染出什麼顏色，回家再查查看答案。"}],"quiz":[{"q":"依官方紀錄，兩位保存者復原了大約多少種天然染料配方？","options":["10多種","100多種","50多種","1000多種"],"answer":1,"explain":"陳景林、馬毓秀長年田野調查與試驗，復原一百多種天然染料配方。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20210128000002"},{"id":"ich-a-lanran","name":"天然染色－藍染工藝","type":"傳統工藝","holder":"湯文君","registered":"2025-02-20","summary":"從種藍、製靛到型染的臺灣藍染","intro":"臺灣藍染在清領時期隨福建移民帶來的製靛技術興起，1800至1870年間藍靛生產達到頂峰，藍草遍及西部平原與淺山。19世紀末德國合成藍量產，加上20世紀初日本機械印花布普及，產業急速萎縮。1990年代起，臺灣省手工業研究所（今國立臺灣工藝研究發展中心）推動復振，藍染才逐漸復甦。官方紀錄指出，今天臺灣各地的藍草種源幾乎都來自南投，南投也是全臺少數仍兼有山藍與木藍製靛的區域。湯文君師承馬芬妹，完整掌握植藍、採藍、製藍、建藍到染色，尤以型糊染見長。南投縣於2025年登錄，保存者在草屯鎮。","whereToSee":"保存者在草屯鎮，保存者工作室不是公開展示場所，請勿自行前往。草屯的國立臺灣工藝研究發展中心是推動藍染復振的單位，園區常有工藝展覽與研習，內容依檔期而定，請以中心公告為準。","venueId":"venue-a-ntcri","dialogue":[{"who":"R","text":"Allan，藍染的藍色是從哪裡來的？"},{"who":"A","text":"從藍草來！把山藍或木藍做成藍靛，再建一缸染液，布放進去拉出來，接觸空氣就慢慢變藍。"},{"who":"R","text":"臺灣以前真的有很多人做藍染嗎？"},{"who":"A","text":"清代很興盛，1800到1870年間藍靛生產達到頂峰，後來被合成藍和印花布打敗，幾乎消失。"},{"who":"R","text":"那為什麼現在藍染又流行起來了？"},{"who":"A","text":"1990年代起，草屯的工藝研究單位推動復振。官方紀錄還說，現在各地的藍草種源幾乎都來自南投。"},{"who":"R","text":"南投真是藍草的娘家！湯文君藝師擅長什麼？"},{"who":"A","text":"她從種藍、製藍到染色一手包辦，尤其擅長型糊染，表現植物、動物和風景的意象。"},{"who":"R","text":"小任務：看到藍染布時，找找顏色深淺不同的地方，猜猜它在染缸裡泡了幾回。"}],"quiz":[{"q":"依官方紀錄，今天臺灣各地的藍草種源幾乎都來自哪裡？","options":["澎湖","臺東","南投","金門"],"answer":2,"explain":"官方紀錄指出，臺灣各地的藍草種源幾乎都來自南投。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20250301000001"},{"id":"ich-a-yudiao","name":"玉石雕刻","type":"傳統工藝","holder":"陳培澤","registered":"2015-08-06","summary":"隨物賦形、契會自然的玉石雕琢","intro":"臺灣當代玉石工藝在民國50年代萌芽：花蓮豐田一帶產閃玉，中國石礦公司開始開採玉礦，後來又發現藍玉髓（臺灣藍寶），產業在民國60、70年代達到巔峰，之後因加工外移與傾銷而沒落，擁有傳統玉雕技能的藝師逐漸凋零。陳培澤在民國55年進入寶石公司，從學徒學起，秉持玉雕「隨物賦形」「契會自然」的法則，廣泛以各種玉石雕出蟲魚鳥獸、神佛人物、花卉瓜果與器皿禮器，並融入現代藝術思潮，也著力研究本土與原住民題材，作品受到博物館收藏。南投縣於2015年登錄，保存者在竹山鎮。","whereToSee":"保存者在竹山鎮，保存者工作室不是公開展示場所，請勿自行前往。可留意南投縣政府文化局的工藝展覽公告。","venueId":"","dialogue":[{"who":"R","text":"Allan，臺灣自己也有出產玉石嗎？"},{"who":"A","text":"有喔，花蓮豐田一帶產閃玉，民國50年代開始開採，後來還發現了被叫做臺灣藍寶的藍玉髓。"},{"who":"R","text":"那臺灣的玉雕產業，後來發展得怎麼樣？"},{"who":"A","text":"民國60、70年代達到巔峰，之後加工外移，產業衰退，會傳統雕琢的師傅愈來愈少。"},{"who":"R","text":"那陳培澤藝師當初是怎麼入行的？"},{"who":"A","text":"他民國55年進寶石公司當學徒，從頭學起，最講究隨物賦形，順著石頭的樣子決定雕什麼。"},{"who":"R","text":"隨物賦形，就是石頭長怎樣就雕怎樣？"},{"who":"A","text":"對，一塊帶斑點的石頭，可能就變成一隻青蛙。我看到石頭只會想拿來墊桌腳。"},{"who":"R","text":"小任務：看玉雕時，找找作者怎麼把石頭原本的顏色或紋路變成作品的一部分。"}],"quiz":[{"q":"玉雕講究的「隨物賦形」是什麼意思？","options":["一定要雕成圓形","依石材原本的形狀與色澤構思作品","用模具大量複製","只能雕刻神佛像"],"answer":1,"explain":"隨物賦形是順著玉石本身的形狀、色澤與紋理來構思雕琢。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20150806000001"},{"id":"ich-a-zhudiao","name":"竹雕工藝","type":"傳統工藝","holder":"葉基祥","registered":"2022-01-14","summary":"竹山竹雕，荷花與青蛙的生態趣味","intro":"竹雕歷史悠久，臺灣、中國、日本都早有記載，因題材與技法不同衍生出許多門派；傳統竹雕多用來裝飾生活器具，臺灣當代竹雕則更著重個人特色。19世紀末到20世紀，竹材加工是竹山地區重要的經濟產業，竹雕工藝顯著反映當地的生活特色。葉基祥從就讀竹山高中美工科時就專攻竹雕，畢業後師事臺灣竹雕名家陳銘堂，從事竹雕三十多年，深入研究竹材產製，各式雕刻技法操作自如，作品以荷花、青蛙見長，饒富人文意味與生態趣味，也長年擔任竹雕班講師。南投縣於2022年登錄，保存者在竹山鎮。","whereToSee":"保存者在竹山鎮，保存者工作室不是公開展示場所，請勿自行前往。竹山文化園區的竹博物館展示竹工藝，開放時間與展品請以園區公告為準。","venueId":"venue-a-zhushan-park","dialogue":[{"who":"R","text":"Allan，竹子是空心的，要怎麼雕？"},{"who":"A","text":"竹雕會依竹材特性選擇做法，掛屏、立體作品都有，靠的是對竹子的了解和刀上的功夫。"},{"who":"R","text":"竹山跟竹雕之間，到底有什麼樣的淵源？"},{"who":"A","text":"19世紀末到20世紀，竹材加工一直是竹山的重要產業，竹雕就在這樣的生活裡長出來。"},{"who":"R","text":"那葉基祥藝師最拿手的題材是什麼？"},{"who":"A","text":"荷花和青蛙！他從竹山高中美工科就專攻竹雕，後來拜師陳銘堂，到現在已經三十多年。"},{"who":"R","text":"在竹子上雕青蛙，會不會一不小心就跳走？"},{"who":"A","text":"雕得太傳神，確實要小心。我上次盯著看太久，差點伸手去抓。"},{"who":"R","text":"小任務：看竹雕作品時，找找青蛙或荷葉，看看作者怎麼利用竹子的節或表皮顏色。"}],"quiz":[{"q":"葉基祥的竹雕作品以什麼題材見長？","options":["龍鳳呈祥","山水亭臺","人物肖像","荷花與青蛙"],"answer":3,"explain":"官方紀錄指出葉基祥的作品以荷花、青蛙見長，饒富人文與生態趣味。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20220302000002"},{"id":"ich-a-puli-paper","name":"埔里手工紙","type":"傳統工藝","holder":"黃煥彰（歿）","registered":"2020-02-17","summary":"好水孕育的埔里手工造紙","intro":"埔里手工造紙始於19世紀末清領末期，日治時期創立「埔里製紙所」；因為埔里水質純淨，周邊山區又有豐富的野生造紙原料，非常適合造紙。戰後持續發展，民國60年左右進入全盛期，造紙業者增加到50間左右，埔里成為日本及東南亞手工書畫紙最大的供應地。現存技術受日本製紙技術影響，又發展出地方特色，工序為原料處理、打漿、抄紙、壓紙、烘紙；壓好的濕紙疊狀如豆腐，稱為「紙豆腐」，再用檜木取紙棒一張張分離、刷貼在鐵板上烘乾。保存者黃煥彰造紙近50年，帶領廣興紙寮推廣手工紙文化，官方紀錄註明他已過世。南投縣於2020年登錄。","whereToSee":"埔里鎮鐵山里的廣興紙寮是開放參觀的手工造紙觀光工廠，可看造紙流程並參加體驗（體驗另收費）。開放時間請以紙寮公告為準。","venueId":"venue-a-guangxing","dialogue":[{"who":"R","text":"Allan，埔里為什麼會變成造紙重鎮？"},{"who":"A","text":"造紙要用大量的水，日治時期發現埔里水質純淨，周邊山上又有很多野生造紙原料。"},{"who":"R","text":"原來是好山好水的功勞。全盛期有多熱鬧？"},{"who":"A","text":"民國60年左右，埔里造紙業者增加到50間左右，還是日本和東南亞手工書畫紙最大的供應地。"},{"who":"R","text":"我聽說有一道工序叫紙豆腐，可以吃嗎？"},{"who":"A","text":"不能吃啦！那是抄好又壓過水的濕紙疊，看起來像一塊豆腐，要用檜木棒一張一張挑起來烘乾。"},{"who":"R","text":"埔里手工紙登錄的保存者是哪一位？"},{"who":"A","text":"廣興紙寮的黃煥彰，造紙將近50年，官方紀錄註明他已過世，紙寮仍開放大家參觀體驗。"},{"who":"R","text":"小任務：到紙寮時，把一張手工紙對著光看，找找裡面的纖維紋路。"}],"quiz":[{"q":"埔里手工紙工序中的「紙豆腐」是指什麼？","options":["用紙包起來的豆腐","壓過水的濕紙疊","造紙用的黃豆原料","紙做的玩具"],"answer":1,"explain":"抄好的紙張經壓紙排水後狀如豆腐，稱為紙豆腐。"},{"q":"依官方紀錄，埔里為什麼適合造紙？","options":["水質純淨，周邊又有野生造紙原料","靠近港口方便出口","附近有煤礦當燃料","日治時期就有鐵路直達"],"answer":0,"explain":"日治時期發現埔里水質純淨，周邊山地又有無盡的野生造紙原料。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20200417000001"},{"id":"ich-a-bunun-weaving","name":"布農族傳統織布工藝","type":"傳統工藝","holder":"谷秀紅（Cina Savung）","registered":"2022-12-28","summary":"百步蛇紋與12竿織法的布農族織布","intro":"南投縣是布農族五大社群的發源地，織布是布農族婦女代代相傳的工藝。傳統以部落自種的苧麻為原料，用山藍、薯榔、薑黃與黑泥等染出綠、紅、黃、黑色；工作服多以白色為底，禮服則以菱形等幾何紋連續排列，配色鮮豔。圖紋多取自部落傳說與自然，象徵百步蛇的紋樣尤其重要，也代表不同家族與氏族。布農族也有織布禁忌，例如不可跨越整經架、織布時不能吵架。谷秀紅能操作布農族最高竿數的12竿織布技法，熟悉織具製作，是濁水溪沿岸潭南、雙龍、人和、地利4個部落公認的傳統織布代表。南投縣於2022年登錄。","whereToSee":"保存者住在信義鄉部落，沒有固定的公開展示場所，請勿自行登門。可留意信義鄉公所與南投縣政府文化局的織布傳習、展覽公告；進入部落、拍照前請先徵得同意。","venueId":"","dialogue":[{"who":"R","text":"Allan，布農族織布上好多菱形，有什麼意思嗎？"},{"who":"A","text":"很多紋樣和百步蛇有關，布農族流傳著一位祖先照著百步蛇身上的花紋織布的故事。"},{"who":"R","text":"所以在故事裡，百步蛇是朋友，不是可怕的蛇？"},{"who":"A","text":"對，官方紀錄記下這個傳說，族人把百步蛇視為好朋友，紋樣也代表不同的家族與氏族。"},{"who":"R","text":"布農族織布的時候，有什麼禁忌嗎？"},{"who":"A","text":"有喔，不能跨越整經架，織布時也不能吵架，不然要先把線收起來，暫時不做。"},{"who":"R","text":"那我以後要吵架前，先說我在織布，大家就會安靜。"},{"who":"A","text":"好主意。谷秀紅藝師能操作最高竿數的12竿織法，竿數愈多，織出的圖案就愈大。"},{"who":"R","text":"小任務：看布農族織品時，找找像蛇身花紋的連續菱形，數數它重複了幾次。"}],"quiz":[{"q":"依官方紀錄，下列哪一項是布農族的織布禁忌？","options":["不可在白天織布","不可使用紅色線","不可跨越整經架","不可在室內織布"],"answer":2,"explain":"老人家會叮嚀不要跨越整經架，織布時也不能跟人吵架。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20221228000002"},{"id":"ich-a-sheyao-repair","name":"傳統蛇窯修造技術","type":"保存技術","holder":"林國隆、林清河","registered":"2020-02-26","summary":"讓老蛇窯持續燒窯的修窯功夫","intro":"蛇窯順著山坡而建、窯身細長，是製陶工藝實踐不可或缺的設備，每燒一次窯幾乎都要修護。臺灣從清代到戰後存在過的蛇窯不下百座，官方紀錄指出，至今仍完整且運作的只剩三座。水里蛇窯建於1927年（日治昭和2年），是目前能正常運作的蛇窯中年代最久的一座；第三代窯主林國隆精通窯爐設計、建造與修復，921大地震後帶領員工修復窯體，也曾為鶯歌陶瓷博物館搭建兩座傳統蛇窯。集集添興窯創立於1955年，第三代主人林清河在震災後修復自家蛇窯，至今維持每年至少燒窯一次。南投縣於2020年認定林國隆、2022年認定林清河。","whereToSee":"水里蛇窯陶藝文化園區（需購票入園）可看到日治時期的蛇窯；集集添興窯的蛇窯與附屬設施是登錄的歷史建築，參觀請先預約。開放時間請以各窯場公告為準。","venueId":"venue-a-shuili-sheyao","dialogue":[{"who":"R","text":"Allan，蛇窯為什麼叫蛇窯？裡面養蛇嗎？"},{"who":"A","text":"沒有蛇啦！是因為窯身細細長長，順著山坡往上爬，遠遠看像一條趴著的大蛇。"},{"who":"R","text":"窯不是蓋好就能一直用嗎，為什麼還要修？"},{"who":"A","text":"柴燒溫度很高，官方紀錄說每燒一次窯幾乎都要修護，所以修窯本身就是一門專業。"},{"who":"R","text":"現在臺灣各地，還有很多蛇窯在燒嗎？"},{"who":"A","text":"完整而且還在運作的只剩三座，水里蛇窯建於1927年，是其中年代最久的。"},{"who":"R","text":"921大地震的時候，這些老蛇窯都沒事嗎？"},{"who":"A","text":"也有受損！林國隆在震後帶員工修好自家窯體，集集添興窯的林清河也修復了自家蛇窯。"},{"who":"R","text":"小任務：到蛇窯旁邊，從窯頭走到窯尾，數數側邊有幾個投柴孔。"}],"quiz":[{"q":"依官方紀錄，水里蛇窯建於哪一年？","options":["1895年","1927年","1955年","1999年"],"answer":1,"explain":"水里蛇窯建於日治時期昭和2年，也就是1927年。"},{"q":"依官方紀錄，臺灣至今仍完整且運作的蛇窯剩下幾座？","options":["10座","30座","3座","100座"],"answer":2,"explain":"臺灣曾有不下百座蛇窯，至今仍完整且運作的僅存三座。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/ptp/20200421000002"},{"id":"ich-a-furniture-repair","name":"細木作－傳統家具修復","type":"保存技術","holder":"張春能、李建章","registered":"2020-02-21","summary":"修好古蹟裡的案桌、神龕與木櫃","intro":"廟宇、宗祠與故宅裡的案桌、神龕、几、椅、凳、床、櫥、櫃等傳統木造家具，是古蹟與歷史建築不可或缺的重要物件。修復要懂榫卯、雕刻、鑲嵌、墨繪、鎏金、塗漆等技法，還要辨識材料，選用最接近的木料並先做試驗。流程包括表面檢視、判別產地年代與樣式、診斷榫卯結構、鑑定木材、清潔、拆卸、修補或重製損毀構件、塗裝調色，最後處理金屬配件。從事者日漸減少，面臨失傳。張春能師承王漢松，累積數千件修護紀錄；李建章從事家具修復三十多年，精通榫卯、雕刻鑿花、漆金按金等技法。南投縣於2020年登錄，保存者分別在草屯鎮與南投市。","whereToSee":"這是修復古蹟、歷史建築與古物家具的保存技術，沒有固定的公開展示場所；保存者工作室不對外開放，請勿自行前往。可留意南投縣政府文化局的修復成果展或講座公告。","venueId":"","dialogue":[{"who":"R","text":"Allan，古董椅子壞了，拿釘子釘一釘不就好了？"},{"who":"A","text":"千萬不行！傳統家具靠榫卯接合，亂釘釘子反而會傷到結構，修復師最怕看到這種急救。"},{"who":"R","text":"那專業的家具修復，到底要怎麼做？"},{"who":"A","text":"先檢視表面、判斷年代樣式，再診斷榫卯、鑑定木材，接著清潔、拆卸、修補，最後塗裝收尾。"},{"who":"R","text":"聽起來好像醫生看病，先診斷再開刀。"},{"who":"A","text":"完全正確！補上去的木料還要選最接近原來的，先做試驗，免得新舊兩塊木頭吵架。"},{"who":"R","text":"那南投縣登錄的是哪兩位家具醫生？"},{"who":"A","text":"張春能和李建章，一位累積了數千件修護紀錄，一位做了三十多年，都是榫卯高手。"},{"who":"R","text":"小任務：到老廟參拜時，看看供桌的轉角，找找有沒有不用釘子的榫卯接縫。"}],"quiz":[{"q":"傳統木造家具主要靠什麼方式接合？","options":["榫卯","鐵釘","強力膠","螺絲"],"answer":0,"explain":"傳統家具以榫卯接合，修復時要先診斷榫卯及結構。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/ptp/20210126000003"},{"id":"ich-a-natural-lacquer","name":"台灣天然漆產業技術","type":"保存技術","holder":"徐玉富、徐仁樑","registered":"2025-02-25","summary":"從種漆樹、割漆到煉漆的埔里技術","intro":"天然漆是傳統工藝與文物修復不可缺的材料，漆器、家具、建築、彩繪、佛像都用得到，品質好壞決定文物能否永續流傳。臺灣天然漆產業在日治時期因政府推動大規模種植漆樹而興起，延續到民國60、70年代才沒落。這項技術包括漆樹育苗、種植、管理，以及採漆、煉漆、濾漆：臺灣主要種安南漆樹，每棵每年平均只產約250公克漆液，以夏漆品質最佳；濾去雜質的稱「生漆」，再經攪拌、加熱讓水分蒸發，製成「精製漆」。徐玉富把日治時期「臺灣殖漆株式會社」的煉漆技法傳給兒子徐仁樑，父子主持龍南天然漆博物館。南投縣於2025年登錄，保存者在埔里鎮。","whereToSee":"埔里鎮的龍南天然漆博物館由保存者父子主持，展示臺灣天然漆產業的歷史；館址與開放時間各方資料不一，出發前請先向館方確認。","venueId":"venue-a-longnan","dialogue":[{"who":"R","text":"Allan，前面講了好多漆藝，那漆到底是從哪裡來的？"},{"who":"A","text":"從漆樹來！在樹皮上割出刀口，流出來的汁液就是漆，臺灣主要種的是安南漆樹。"},{"who":"R","text":"一棵漆樹一年到底可以割出多少漆？"},{"who":"A","text":"官方紀錄說，每棵每年平均只有約250公克，差不多一杯手搖飲的量，所以天然漆非常珍貴。"},{"who":"R","text":"漆液割下來之後，就能直接用嗎？"},{"who":"A","text":"要先過濾成生漆，再攪拌加熱讓水分蒸發，變成精製漆，還能加顏料調成彩漆。"},{"who":"R","text":"埔里跟天然漆之間，又有什麼關係？"},{"who":"A","text":"埔里曾是天然漆的主要產地之一。徐玉富把日治時期的煉漆技法傳給兒子徐仁樑，父子一起被認定為保存者。"},{"who":"R","text":"小任務：參觀天然漆展示時，找找割漆用的工具，想像漆農怎麼在樹皮上下刀。"}],"quiz":[{"q":"依官方紀錄，臺灣一棵漆樹一年平均可產多少漆液？","options":["約2.5公斤","約25公斤","約25公克","約250公克"],"answer":3,"explain":"臺灣漆樹每棵年產量平均只有約250公克。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/ptp/20250305000001"},{"id":"ich-a-malepa","name":"泰雅族Malepa群口述傳統","type":"口述傳統","holder":"翁進文（歿）","registered":"2018-12-25","summary":"以吟唱傳承的泰雅族遷徙史詩","intro":"傳統泰雅族社會沒有文字，社群的歷史記憶與文化傳承，靠祖先流傳下來的語言，透過口語敘述或歌謠吟唱來進行。仁愛鄉北港溪流域的Malepa（馬烈霸）群口述傳統，記述泰雅族從瑞岩到雪山階段的遷移史詩，內容包括起源遷徙、部落歷史、Gaga（祖訓規範）及其典故，也包含山川地理、動植物與氣候等知識。它以Lmuhuw的宣敘式唱法進行教導傳述、對話申辯與即興吟唱，要用象徵、比喻把詞句串連起來，演說者須熟悉歷史典故與祖訓。保存者翁進文是當地最高齡、最擅長Lmuhuw的耆老，官方紀錄註明他已過世。南投縣於2018年登錄。","whereToSee":"流傳於仁愛鄉北港溪流域的泰雅族部落，沒有固定的公開演出場所。史詩提到的瑞岩一帶有Sbayan泰雅民族起源地，前往請遵守部落規範、保持安靜，不要攀爬、觸摸或移動聖石，並先向部落詢問。","venueId":"","dialogue":[{"who":"R","text":"Allan，泰雅族以前沒有文字，歷史要怎麼記下來？"},{"who":"A","text":"靠語言和記憶！族人用口述或吟唱，把祖先從哪裡來、怎麼遷徙，一代一代傳下去。"},{"who":"R","text":"南投這一支口述傳統，主要在講什麼？"},{"who":"A","text":"主要記述泰雅族從瑞岩遷到雪山的遷移史詩，還有祖訓規範、山川地名和動植物的知識。"},{"who":"R","text":"這些內容是用說的，還是用唱的呢？"},{"who":"A","text":"用一種宣敘式的吟唱，可以教導、對話申辯，也可以即興，還要用很多象徵和比喻。"},{"who":"R","text":"那不只要會唱，還要很懂歷史跟族語。"},{"who":"A","text":"沒錯，保存者翁進文是北港溪流域最高齡、最擅長這種吟唱的耆老，官方紀錄註明他已過世。"},{"who":"R","text":"小任務：聽泰雅族吟唱錄音時，留意有沒有反覆出現的地名，想想祖先走過哪些地方。"}],"quiz":[{"q":"依官方紀錄，這項口述傳統記述泰雅族從哪裡到哪裡的遷移？","options":["從瑞岩到雪山","從日月潭到玉山","從蘭嶼到綠島","從阿里山到墾丁"],"answer":0,"explain":"泰雅族Malepa群口述傳統記述泰雅族從瑞岩至雪山階段的遷移史詩。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/ote/20190201000001"},{"id":"ich-a-puzhong-tea","name":"傳統手工製茶－名間埔中茶","type":"傳統知識與實踐","holder":"陳茂淳（歿）","registered":"2019-01-25","summary":"松柏坑「一眼二頂三埔中」的手工製茶","intro":"名間鄉手工製茶已有百年以上歷史，早期茶園集中在「埔中」一帶，俗稱埔中茶，後來曾稱「松柏長青茶」，今稱「台灣好茶」。清代中南部流傳一句諺語「一眼、二頂、三埔中」，三埔中說的就是名間埔中。松柏坑居民幾乎家家都有簡易製茶設備，早期沒有機械，人力不足時就與家族、鄰里「相伴工」一起完成。手工製茶要經過採菁、萎凋、靜置與攪拌、大浪、堆菁、殺菁、揉捻、初乾、團揉、乾燥、烘存、揀枝、烘焙等工序，每一道都憑製茶者的經驗與技術。保存者陳茂淳曾獲26面茶葉競賽特等獎牌，官方紀錄註明他已過世。南投縣於2019年登錄。","whereToSee":"名間鄉松柏嶺一帶是主要茶區。松柏嶺遊客中心是以茶為主題的旅遊服務中心，有茶文化展示與體驗課程，開放時間與課程請以參山國家風景區管理處公告為準。茶園多為私人產業，請勿任意進入或採摘。","venueId":"venue-a-songboling","dialogue":[{"who":"R","text":"Allan，一眼二頂三埔中，是什麼繞口令？"},{"who":"A","text":"是清代中南部流傳的茶諺，三埔中說的就是名間的埔中茶，可見當時名氣多響亮。"},{"who":"R","text":"那埔中茶到現在，都還叫這個名字嗎？"},{"who":"A","text":"後來曾叫松柏長青茶，現在叫台灣好茶，換過好幾個名字，就像藝人改藝名。"},{"who":"R","text":"以前沒有機器，一家人忙得過來嗎？"},{"who":"A","text":"忙不過來就找親友鄰居相伴工，大家輪流幫忙，做茶也順便交流經驗、聯絡感情。"},{"who":"R","text":"手工製茶的工序，是不是多到數不完？"},{"who":"A","text":"從採菁、萎凋、殺菁、揉捻到團揉、烘焙，十幾道工序全憑經驗。保存者陳茂淳已經過世了。"},{"who":"R","text":"小任務：到松柏嶺泡一杯茶，先聞茶香，再看看泡開的茶葉是不是捲得很緊。"}],"quiz":[{"q":"清代茶諺「一眼、二頂、三埔中」的「埔中」指的是哪裡？","options":["鹿谷凍頂","魚池日月潭","名間埔中","竹山杉林溪"],"answer":2,"explain":"官方紀錄指出，三埔中就是名間埔中。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/tkp/20190418000001"},{"id":"ich-a-lugu-oolong","name":"傳統手工製茶－鹿谷烏龍茶","type":"傳統知識與實踐","holder":"蘇文昭","registered":"2019-01-25","summary":"深夜起灶手炒茶，茶香飄滿凍頂山","intro":"官方紀錄指出，鹿谷鄉是全臺最早也是唯一靠單一作物作為經濟來源的鄉鎮。日治時期鄉內茶樹品種更新為小葉種，開啟凍頂烏龍茶的種植；到民國70年代，鹿谷家戶幾乎都靠茶業改善家中經濟，沒有茶園的人也靠採茶、作茶養家。傳統凍頂烏龍茶製作的關鍵在控制炒菁（殺菁）：茶葉萎凋靜置後，茶農大多在深夜起灶手炒，通常四、五戶鄰居合力輪流翻炒，一刻都不能停，整個凍頂山區飄滿茶香。保存者蘇文昭18歲起就以手炒方式製茶，至今保留全套手炒茶傳統設備，持續以活動傳承傳統製程。南投縣於2019年登錄。","whereToSee":"鹿谷鄉凍頂山一帶是主要茶區；鹿谷鄉農會的茶文化館有茶業展示，開放時間請以農會公告為準。茶園與製茶廠多為私人產業，參觀前請先聯繫。","venueId":"venue-a-lugu-tea","dialogue":[{"who":"R","text":"Allan，凍頂烏龍茶的凍頂，是因為山頂冷到會結凍嗎？"},{"who":"A","text":"名稱由來說法很多，我就不亂講了。可以確定的是，鹿谷是全臺最早只靠一種作物維生的鄉鎮。"},{"who":"R","text":"只靠茶？那全鄉的人都在做茶嗎？"},{"who":"A","text":"民國70年代幾乎家家戶戶都靠茶，沒有茶園的人也靠採茶、作茶養家。"},{"who":"R","text":"傳統做法裡，最關鍵的是哪一個步驟？"},{"who":"A","text":"炒菁！茶農常在深夜起灶手炒，四五戶鄰居輪流翻炒，一刻都不能停，整座山都是茶香。"},{"who":"R","text":"半夜聞到茶香，鄰居應該都睡不著了吧。"},{"who":"A","text":"睡不著就起來一起炒啊。保存者蘇文昭18歲開始手炒茶，到現在還保留全套傳統設備。"},{"who":"R","text":"小任務：到鹿谷喝凍頂烏龍時，細看茶湯的顏色，猜猜這泡茶焙火是輕還是重。"}],"quiz":[{"q":"依官方紀錄，傳統凍頂烏龍茶製作的關鍵工序是什麼？","options":["炒菁","日曬三天","發酵三個月","冷凍保存"],"answer":0,"explain":"傳統凍頂烏龍茶製作的關鍵在控制炒菁（殺菁）這個工序。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/tkp/20220619000001"}],"venues":[{"id":"venue-f-shoutiangong","name":"松柏嶺受天宮","address":"南投縣名間鄉松山村松山街118號","lat":23.8317402,"lng":120.6308849,"relatedSiteId":"","ichIds":["ich-shoutiangong-xiangqi"],"antiquities":[]},{"id":"venue-f-zinangong","name":"竹山社寮紫南宮","address":"南投縣竹山鎮社寮里大公街40號","lat":23.8171483,"lng":120.7225076,"relatedSiteId":"zhushan-xiandinggujiyongji","ichIds":["ich-zinangong-dingjiu","ich-zinangong-jiejin"],"antiquities":[]},{"id":"venue-f-itathao","name":"日月潭伊達邵邵族部落","address":"南投縣魚池鄉日月村（伊達邵）","lat":23.8471039,"lng":120.9336779,"relatedSiteId":"","ichIds":["ich-shao-lusan"],"antiquities":[]},{"id":"venue-f-hengjigong","name":"埔里恒吉宮","address":"南投縣埔里鎮南興街367號","lat":23.9652284,"lng":120.9622264,"relatedSiteId":"","ichIds":["ich-puli-qingjiao"],"antiquities":[{"name":"恒吉宮神昭海表匾額","level":"一般古物","registered":"2025-02-19","note":"大正13年（1924）柯金同敬獻、劉曉邨書、彩繪名師劉沛製作的金地墨字匾，鳳穿牡丹紋飾精美，稱頌媽祖神威遍及埔里"}]},{"id":"venue-a-ntcri","name":"國立臺灣工藝研究發展中心（臺灣工藝文化園區）","address":"南投縣草屯鎮中正路573號","lat":23.980042,"lng":120.69217,"relatedSiteId":"caotun-shougongyepinchen","ichIds":["ich-a-qi-wang","ich-a-zhubian","ich-a-lantai","ich-a-tianran-ranse","ich-a-lanran"],"antiquities":[]},{"id":"venue-a-nantoutao","name":"南投陶展示館（南投武德殿）","address":"南投縣南投市彰南路二段65號","lat":23.9094159841329,"lng":120.683986068675,"relatedSiteId":"nantou-wudedianjiqifushu","ichIds":["ich-a-shoujipi","ich-a-nantoutao"],"antiquities":[{"name":"陶棺","level":"一般古物","registered":"2023-03-23","note":"日治時期南投牛運堀信成陶器工廠製作的陶棺，側面浮雕「福」字、據說立著燒成，是南投陶燒造技術的少見實物"},{"name":"習字磚（含木架）","level":"一般古物","registered":"2020-11-14","note":"日治時期霧峰林家燒製的素燒方磚，用毛筆沾水在上面練字，水乾可重寫，被認為是臺灣唯一現存的早期習字磚"},{"name":"二宮尊德","level":"一般古物","registered":"2020-11-14","note":"日治末期南投陶大師劉樹枝製作的二宮尊德陶塑立像，以背柴苦讀的形象勸學，兼採模型與手工雕塑，見證日治教育文化"}]},{"id":"venue-a-shuili-sheyao","name":"水里蛇窯陶藝文化園區","address":"南投縣水里鄉頂崁村水信路一段512巷21號","lat":23.8008004,"lng":120.8647018,"relatedSiteId":"","ichIds":["ich-a-nantoutao","ich-a-sheyao-repair"],"antiquities":[]},{"id":"venue-a-tianxingyao","name":"集集添興窯","address":"南投縣集集鎮田寮里楓林巷10號","lat":23.8328780423471,"lng":120.755273526438,"relatedSiteId":"jiji-tianxingyaojiqifu","ichIds":["ich-a-nantoutao","ich-a-sheyao-repair"],"antiquities":[]},{"id":"venue-a-guangxing","name":"廣興紙寮","address":"南投縣埔里鎮鐵山里鐵山路310號","lat":23.9755914,"lng":120.9386423,"relatedSiteId":"","ichIds":["ich-a-puli-paper"],"antiquities":[]},{"id":"venue-a-longnan","name":"龍南天然漆博物館","address":"南投縣埔里鎮","lat":null,"lng":null,"relatedSiteId":"","ichIds":["ich-a-natural-lacquer"],"antiquities":[]},{"id":"venue-a-zhushan-park","name":"竹山文化園區（竹博物館）","address":"南投縣竹山鎮建國路742號","lat":23.7473769,"lng":120.6799399,"relatedSiteId":"","ichIds":["ich-a-zhubian","ich-a-zhudiao"],"antiquities":[]},{"id":"venue-a-lugu-tea","name":"鹿谷鄉農會茶文化館","address":"南投縣鹿谷鄉中正路一段（鹿谷鄉農會）","lat":23.7412664,"lng":120.7572603,"relatedSiteId":"","ichIds":["ich-a-lugu-oolong"],"antiquities":[]},{"id":"venue-a-songboling","name":"松柏嶺遊客中心","address":"南投縣名間鄉松山村名松路二段","lat":23.8339034,"lng":120.6361194,"relatedSiteId":"","ichIds":["ich-a-puzhong-tea"],"antiquities":[]},{"id":"venue-g-lantian-shuyuan","name":"藍田書院","address":"南投縣南投市崇文里文昌街140號","lat":23.907231167841,"lng":120.684731579049,"relatedSiteId":"nantou-lantianshuyuan","ichIds":[],"antiquities":[{"name":"「奏凱崇文」匾","level":"一般古物","registered":"2014-10-17","note":"同治4年（1865）兵備道丁曰健平定北勢湳洪欉事件後移師南投所立，取凱旋歸來、崇尚文風之意，雙龍搶珠浮雕"},{"name":"新建藍田書院捐緣姓名碑","level":"一般古物","registered":"2026-07-24","note":"道光13年（1833）書院落成時所立的花崗岩碑，列出官員、仕紳與墾戶的捐款；主碑已佚，是書院創建的少數物證"},{"name":"重修藍田書院碑","level":"一般古物","registered":"2026-07-24","note":"道光27年（1847）立，曾作霖撰文，記載書院1845年遭地震毀損後仕紳募資依原貌重修的經過"}]},{"id":"venue-g-dengying-shuyuan","name":"登瀛書院","address":"南投縣草屯鎮新庄里史館路文昌巷30號","lat":23.9887586151698,"lng":120.66747904754,"relatedSiteId":"caotun-dengyingshuyuan","ichIds":[],"antiquities":[{"name":"登瀛書院文昌帝君神像","level":"一般古物","registered":"2026-07-24","note":"書院稱為開基神像的整塊樟木雕文昌帝君，最晚在昭和2年（1927）前已奉祀，今端坐正殿神龕，粉線安金工藝精細"},{"name":"登瀛書院執事牌組","level":"一般古物","registered":"2026-07-24","note":"春秋二祭與文昌帝君出巡時用的木刻儀牌，刻有玉峰社、萃英社等學社名號，見證草屯「四學社」與書院的文教網絡"},{"name":"登瀛書院洪鍾英功名牌組","level":"一般古物","registered":"2026-07-24","note":"書院倡建者、訓導洪鍾英的「部銓儒學」「欽加五品」「賞戴藍翎」功名牌，清代儀仗留存稀少，今隨文昌帝君出巡"}]},{"id":"venue-g-caotun-chaoyanggong","name":"草屯朝陽宮","address":"南投縣草屯鎮史館路239號","lat":23.983499,"lng":120.663974,"relatedSiteId":"caotun-chaoyanggong","ichIds":[],"antiquities":[{"name":"朝陽宮虎爺石雕香爐","level":"一般古物","registered":"2014-10-17","note":"道光21年（1841）石雕香爐，正面雕龍吐珠，原為媽祖香爐後改祀虎爺；落款「和樂社」暗示廟裡曾有樂團，今置正殿展示櫃"},{"name":"朝陽宮德溥入山匾額","level":"一般古物","registered":"2025-02-06","note":"咸豐7年（1857）總理洪朝功敬獻的紅地金字匾，「入山」指信仰傳入內山北投街，懸於正殿，見證草屯早期媽祖與觀音信仰"}]},{"id":"venue-g-yuemeicuo-longdemiao","name":"月眉厝龍德廟","address":"南投縣草屯鎮碧峰里碧山路1158號","lat":23.9712978294903,"lng":120.65041902094,"relatedSiteId":"caotun-yuemeicuolongde","ichIds":[],"antiquities":[{"name":"月眉厝龍德廟大老爺保生大帝神轎","level":"一般古物","registered":"2026-07-24","note":"清末臺灣櫸與牛樟木雕的四角文轎，四面安金鏤雕，形似縮小的廟宇，昭和8年（1933）曾全面整修上漆"},{"name":"月眉厝龍德廟二老爺保生大帝神轎","level":"一般古物","registered":"2026-07-24","note":"清末楠木框架、牛樟雕板的文轎，曾載保生大帝與廿四庄林祖姑媽祖遶境三個里，今封存在廟後右廂房玻璃櫃中"}]},{"id":"venue-g-zhushan-lianxinggong","name":"竹山連興宮","address":"南投縣竹山鎮竹山里下橫街28號","lat":23.7562743992568,"lng":120.68516819352,"relatedSiteId":"zhushan-lianxinggong","ichIds":[],"antiquities":[{"name":"嚴禁勒索竹排船伕碑","level":"一般古物","registered":"2014-10-17","note":"道光4年（1824）知縣李振青示諭碑，禁止下游攔截勒索運竹排的船伕，改收費充作廟宇香燈，記錄竹山竹業與河運"},{"name":"竹山連興宮長生祿位","level":"一般古物","registered":"2026-07-24","note":"清代樟木透雕雲龍祿位，供奉定長、知縣胡邦翰與李振青，反映百姓感念良吏開發水沙連，今安奉二樓凌霄寶殿"}]},{"id":"venue-g-nantou-peitiangong","name":"南投配天宮","address":"南投縣南投市中山街65號","lat":23.9065316,"lng":120.6858809,"relatedSiteId":"","ichIds":[],"antiquities":[{"name":"配天宮正殿石獅","level":"一般古物","registered":"2014-10-17","note":"道光29年（1849）擴建時所置的一對青斗石獅，公獅踩球、母獅帶小獅；廟經遷徙與921地震重創，僅這對石獅留存"}]},{"id":"venue-g-caotun-qinganggong","name":"草屯慶安宮","address":"南投縣草屯鎮北投里北投路416號","lat":null,"lng":null,"relatedSiteId":"","ichIds":[],"antiquities":[{"name":"慶安宮土地公石雕香爐","level":"一般古物","registered":"2014-10-17","note":"道光21年（1841）蕭英敬獻的長方形石香爐，正面浮雕麒麟，是南投縣已知有年款的石香爐中年代較早的一件"}]},{"id":"venue-g-lugu-zhushengmiao","name":"鹿谷祝生廟","address":"南投縣鹿谷鄉彰雅村中厝巷21號","lat":null,"lng":null,"relatedSiteId":"","ichIds":[],"antiquities":[{"name":"喜捐祝生廟祀田碑","level":"一般古物","registered":"2014-10-17","note":"道光12年（1832）立，記開發大坪頂的業主許廷瑄捐田、以租穀供慚愧祖師香燈，見證鹿谷早期拓墾與信仰"}]}]},"ubike":{"meta":{},"stations":[]},"extra":{"intro":[{"who":"A","text":"嗨，我是 Allan Lo！今天不用看海，因為我們來到臺灣唯一不靠海的縣，南投。"},{"who":"R","text":"我是阿拉蕾！南投我知道，有日月潭、清境，還有喝不完的高山茶！"},{"who":"A","text":"說得好。南投的文化資產一共73處，有國定古蹟、縣定古蹟、歷史建築、紀念建築、考古遺址和文化景觀。"},{"who":"R","text":"國定古蹟是哪一個？"},{"who":"A","text":"就是清代1875年開闢的八通關古道，從竹山一路翻過中央山脈到花蓮玉里。東端在花蓮，西段就在南投。"},{"who":"R","text":"那文資最多在哪裡？"},{"who":"A","text":"南投市有21處，很多在中興新村，那裡曾經是臺灣省政府的所在地；竹山和草屯也各有十幾處，書院和老廟特別多。"},{"who":"R","text":"我還知道，這裡是邵族、布農族、泰雅族、賽德克族的家園，仁愛鄉還有泰雅族的起源地斯巴揚！"},{"who":"A","text":"沒錯。1999年的921大地震，南投是重災區，很多老建築是震後修復或重建的；山區道路颱風豪雨後也常坍方，出發前記得查路況。"},{"who":"R","text":"南投景點分散，建議開車。準備好了嗎？從南投市區出發囉！"}],"timeIntro":[{"who":"R","text":"Allan，南投的時光地圖要看什麼？"},{"who":"A","text":"先看荷西時期，那時南投沒有外來政權，是各族原住民的天地；明鄭時期林圮帶人到竹山開墾，也和原住民發生衝突。"},{"who":"A","text":"清代有書院和八通關古道，日治有集集線、日月潭水力發電和霧社事件，戰後省政府搬到中興新村。清代以後都會疊上當年的老地圖。"},{"who":"R","text":"那我要找找看，日月潭在發電廠蓋好以前，是不是比現在小很多！"},{"who":"A","text":"好，把老地圖的透明度拉一拉，答案就在地圖上！"}],"planIntro":[{"who":"A","text":"南投縣幅員很大，從南投市到仁愛鄉的山區要開兩個多小時，景點分散，建議開車；南投市、中興新村、竹山和集集市區，停好車就可以走路串遊。"},{"who":"R","text":"南投沒有高鐵站，也沒有 YouBike，不過可以從高鐵臺中站轉客運，或搭集集線小火車到集集和車埕！"},{"who":"A","text":"日月潭環湖的自行車是業者出租的，不是 YouBike。山區道路颱風、豪雨後常有坍方管制，出發前請先查詢最新路況。"},{"who":"R","text":"中午記得留肚子給南投意麵、草屯肉圓，還有集集的香蕉冰！"}],"gameIntro":[{"who":"R","text":"山城遊戲場開張！問答王、時光排序、猜猜我是誰、翻翻樂，還有山城擲骰大冒險！"},{"who":"A","text":"題目從藍田書院、中興新村，一路考到集集火車站、車埕和八通關古道，看你能不能全部答對。"},{"who":"R","text":"Allan，這次擲骰子我一定贏你！"},{"who":"A","text":"哈哈，那就從南投市區出發，比比看吧！"}],"reactions":[{"who":"R","text":"答對了！你根本就是南投通！"},{"who":"A","text":"正確答案！給你一個大大的讚。"},{"who":"R","text":"哎呀，答錯了，沒關係，看看解說再挑戰！"},{"who":"A","text":"可惜！差一點點，下次一定行。"},{"who":"R","text":"換我擲骰子囉！看我的！"},{"who":"A","text":"恭喜你贏了！今天的南投意麵和草屯肉圓算我的！"},{"who":"R","text":"耶！這一局是我贏了，要不要再來一局？"},{"who":"A","text":"平手！你們兩個都是文資高手。"},{"who":"R","text":"時光排序完成！你從埔里的史前遺址一路排到今天的中興新村，好厲害！"},{"who":"A","text":"恭喜集到新的護照印章！"},{"who":"R","text":"全部配對成功，記憶力滿分！"},{"who":"A","text":"嗯，這一題我們一起看看解說。"}],"starts":[{"id":"nantou","name":"南投市區（南投縣政府）","lat":23.90238,"lng":120.69012},{"id":"zhongxing","name":"中興新村","lat":23.95612,"lng":120.68508},{"id":"hsr","name":"高鐵臺中站（烏日）","lat":24.11168,"lng":120.61584},{"id":"caotun","name":"草屯市區（草屯鎮公所）","lat":23.97358,"lng":120.68065},{"id":"zhushan","name":"竹山市區（竹山鎮公所）","lat":23.7579,"lng":120.67157},{"id":"jiji","name":"臺鐵集集車站","lat":23.82649,"lng":120.78488},{"id":"checheng","name":"臺鐵車埕車站","lat":23.83256,"lng":120.86574},{"id":"sunmoon","name":"日月潭水社（客運轉運站）","lat":23.86655,"lng":120.91106},{"id":"puli","name":"埔里轉運站","lat":23.96357,"lng":120.96921},{"id":"gps","name":"我的目前位置","lat":null,"lng":null},{"id":"pick","name":"在地圖上點選出發點","lat":null,"lng":null}],"plans":{"1":{"name":"一日：南投市（藍田書院、武德殿）、中興新村與草屯書院老廟","days":[["nantou-lantianshuyuan","nantou-wudedianjiqifushu","nantou-shuiwuchuzhangsuo","nantou-shizhongshangong","nantou-zhongxingxincunwen","nantou-taiwanshengzhengfu","nantou-taiwanshengzhengzi","caotun-shougongyepinchen","caotun-dengyingshuyuan","caotun-chaoyanggong"]]},"2":{"name":"二日：南投市、中興新村、草屯 ＋ 竹山、八通關古道、社寮、集集與車埕","days":[["nantou-lantianshuyuan","nantou-wudedianjiqifushu","nantou-shuiwuchuzhangsuo","nantou-shizhongshangong","nantou-zhongxingxincunwen","nantou-taiwanshengzhengfu","nantou-taiwanshengzhengzi","caotun-shougongyepinchen","caotun-dengyingshuyuan","caotun-chaoyanggong"],["zhushan-linpigongmu","zhushan-lianxinggong","zhushan-shensheniaojujizhu","zhushan-batongguangudao","zhushan-sheliaogucang","zhushan-xiandinggujiyongji","jiji-tianxingyaojiqifu","jiji-huochezhan","jiji-zhangnaochuzhang","shuili-zhenchangxingyegu"]]},"3":{"name":"三日：再加日月潭（頭社、魚池）與埔里、國姓","days":[["nantou-lantianshuyuan","nantou-wudedianjiqifushu","nantou-shuiwuchuzhangsuo","nantou-shizhongshangong","nantou-zhongxingxincunwen","nantou-taiwanshengzhengfu","nantou-taiwanshengzhengzi","caotun-shougongyepinchen","caotun-dengyingshuyuan","caotun-chaoyanggong"],["zhushan-linpigongmu","zhushan-lianxinggong","zhushan-shensheniaojujizhu","zhushan-batongguangudao","zhushan-sheliaogucang","zhushan-xiandinggujiyongji","jiji-tianxingyaojiqifu","jiji-huochezhan","jiji-zhangnaochuzhang","shuili-zhenchangxingyegu"],["yuchi-tousheguritanfu","yuchi-xingzhengyuannong","yuchi-linyuanshitoucuo","puli-fudingjinkaoguyi","puli-guolizhongxingda","puli-damalinkaoguyizhi","puli-nancunyiminci","guoxing-xiangbeigangxishi"]]},"mountain":{"label":"山區：仁愛、信義","name":"山區加碼：仁愛鄉曲冰遺址與斯巴揚起源地、水里與信義鄉楠仔腳蔓","days":[["renai-qubingkaoguyizhi","renai-taiyaminzuqiyuandi"],["shuili-linquguanlichushui","shuili-laijiagucuo","xinyi-nanzaijiaomanshe"]]}},"food":[]}};
